type CharacterRedrawPlacementRect = { x: number; y: number; width: number; height: number };
type CharacterRedrawLayerInput = {
  id: string;
  shotId: string;
  zIndex: number;
  bitmapPath: string;
  maskPath?: string;
  isolatedRgbaPath?: string;
  acceptedCompositePath?: string;
  placementRect?: CharacterRedrawPlacementRect;
  characterGenerationMetadata?: { characterAssetId: string; status: "generated" | "accepted" | "needs_review" };
};

export function planCharacterRedrawSelection<TPass extends { characterAssetId: string }, TLayer extends CharacterRedrawLayerInput>(input: {
  shotId: string;
  characterAssetId: string;
  passes: TPass[];
  layers: TLayer[];
}):
  | { ok: true; passes: [TPass]; targetPass: TPass; targetLayer: TLayer; protectedMaskPaths: string[] }
  | { ok: false; reason: string } {
  const targetPasses = input.passes.filter((pass) => pass.characterAssetId === input.characterAssetId);
  if (targetPasses.length !== 1) return { ok: false, reason: "character_redraw_target_pass_missing" };
  const targetLayers = input.layers.filter(
    (layer) =>
      layer.shotId === input.shotId &&
      layer.characterGenerationMetadata?.characterAssetId === input.characterAssetId
  );
  if (targetLayers.length !== 1) return { ok: false, reason: "character_redraw_target_layer_missing" };
  const targetLayer = targetLayers[0];
  if (!String(targetLayer.maskPath ?? "").trim()) {
    return { ok: false, reason: "character_redraw_target_mask_missing" };
  }
  const protectedLayers = input.layers.filter(
    (layer) =>
      layer.shotId === input.shotId &&
      layer.id !== targetLayer.id &&
      layer.characterGenerationMetadata?.status === "accepted"
  );
  const missingProtectedMask = protectedLayers.find((layer) => !String(layer.maskPath ?? "").trim());
  if (missingProtectedMask) {
    return { ok: false, reason: `character_redraw_protected_mask_missing:${missingProtectedMask.id}` };
  }
  const protectedMaskPaths = protectedLayers.map((layer) => String(layer.maskPath).trim());
  return {
    ok: true,
    passes: [targetPasses[0]],
    targetPass: targetPasses[0],
    targetLayer,
    protectedMaskPaths
  };
}

export function planCharacterRedrawMaskBounds(input: {
  scope: CharacterRedrawScope;
  placementRect: CharacterRedrawPlacementRect;
}): CharacterRedrawPlacementRect {
  const rect = {
    x: Math.max(0, Math.floor(Number(input.placementRect?.x) || 0)),
    y: Math.max(0, Math.floor(Number(input.placementRect?.y) || 0)),
    width: Math.max(1, Math.ceil(Number(input.placementRect?.width) || 0)),
    height: Math.max(1, Math.ceil(Number(input.placementRect?.height) || 0))
  };
  if (input.scope === "face_hair") return { ...rect, height: Math.max(1, Math.ceil(rect.height * 0.35)) };
  if (input.scope === "upper_body") return { ...rect, height: Math.max(1, Math.ceil(rect.height * 0.62)) };
  return rect;
}

export function planCharacterRedrawLayerTransition<TLayer extends { id?: string; maskPath?: string }>(input: {
  layers: TLayer[];
  targetLayerId: string;
  previousShotPath: string;
  outcome:
    | { status: "accepted"; layer: TLayer; shotPath: string }
    | { status: "needs_review" | "failed" | "cancelled"; bestPreviewPath?: string };
}): { layers: TLayer[]; shotPath: string; changed: boolean; bestPreviewPath?: string } {
  if (input.outcome.status !== "accepted") {
    return {
      layers: input.layers,
      shotPath: input.previousShotPath,
      changed: false,
      bestPreviewPath: input.outcome.bestPreviewPath
    };
  }
  const targetLayers = input.layers.filter((layer) => layer?.id === input.targetLayerId);
  const targetCount = targetLayers.length;
  if (targetCount !== 1) {
    return { layers: input.layers, shotPath: input.previousShotPath, changed: false };
  }
  const acceptedOutcome = input.outcome;
  const previousTarget = targetLayers[0];
  const replacementLayer = {
    ...acceptedOutcome.layer,
    maskPath: previousTarget.maskPath
  } as TLayer;
  return {
    layers: input.layers.map((layer) => layer?.id === input.targetLayerId ? replacementLayer : layer),
    shotPath: acceptedOutcome.shotPath,
    changed: true
  };
}
/* CHARACTER_REDRAW_RUNTIME_END */

export type StoryboardGenerationRequest = {
  settings: ComfySettings;
  shot: Shot;
  index?: number;
  allShots?: Shot[];
  assets?: Asset[];
  stageAWorkflowJson?: string;
  stageBWorkflowJson?: string;
  workflowId?: string;
  globalStyle?: string;
  negativePrompt?: string;
  preflight?: () => Promise<void>;
  runStage?: (stage: "stageA" | "stageB" | "fallback", request: StoryboardGenerationRequest) => Promise<StoryboardStagedGenerationResult>;
  batchId?: string;
  characterRedraw?: CharacterRedrawRequest;
  signal?: AbortSignal;
};

export type StoryboardBatchOptions = Partial<Omit<StoryboardGenerationRequest, "shot" | "index">> & {
  batchId?: string;
  preflight?: () => Promise<void>;
  continueOnFailure?: boolean;
};

function storyboardPromptHash(request: StoryboardGenerationRequest): string {
  const shot = request.shot;
  const refs = [...(shot.characterRefs ?? []), shot.sceneRefId ?? "", ...(shot.sourceCharacterNames ?? []), shot.sourceSceneName ?? ""];
  const camera = [shot.cameraYaw, shot.cameraPitch, shot.cameraFov].map((value) => value ?? "").join(",");
  const normalized = [shot.title, shot.storyPrompt, shot.dialogue, shot.notes, ...(shot.tags ?? []), ...refs, camera, request.globalStyle, request.negativePrompt ?? shot.negativePrompt].map((value) => String(value ?? "").trim().replace(/\s+/g, " ")).filter(Boolean).join("\n");
  let hash = 2166136261;
  for (let index = 0; index < normalized.length; index += 1) {
    hash ^= normalized.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function cloneSerializableRetryValue<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

export function createStoryboardRetrySnapshot(request: StoryboardGenerationRequest): StoryboardGenerationRetrySnapshot {
  return cloneSerializableRetryValue({
    version: 1 as const,
    settings: request.settings as unknown as Record<string, unknown>,
    shot: request.shot,
    index: request.index ?? Math.max(0, request.shot.order - 1),
    allShots: request.allShots ?? [request.shot],
    assets: request.assets ?? [],
    stageAWorkflowJson: request.stageAWorkflowJson,
    stageBWorkflowJson: request.stageBWorkflowJson,
    workflowId: request.workflowId,
    globalStyle: request.globalStyle,
    negativePrompt: request.negativePrompt,
    characterRedraw: request.characterRedraw,
    preflightRequired: Boolean(request.preflight),
    customRunnerRequired: Boolean(request.runStage)
  });
}

function generationTask(request: StoryboardGenerationRequest, batchId: string): StoryboardGenerationTask {
  const now = new Date().toISOString();
  return { id: `generation_${batchId}_${request.shot.id}`, batchId, shotId: request.shot.id, workflowId: request.workflowId ?? "storyboard-qwen-stageA", stage: "preflight", status: "queued", promptHash: storyboardPromptHash(request), startedAt: now, retrySnapshot: createStoryboardRetrySnapshot(request) };
}

export async function queueStoryboardShot(request: StoryboardGenerationRequest): Promise<StoryboardGenerationTask> {
  request.signal?.throwIfAborted();
  const batchId = request.batchId ?? `batch_${Date.now()}`;
  const task = generationTask(request, batchId);
  const store = useStoryboardStore.getState();
  store.upsertGenerationTask(task);
  try {
    request.signal?.throwIfAborted();
    if (request.preflight) await request.preflight();
    request.signal?.throwIfAborted();
    const runner = request.runStage ?? (async (_stage, current) => generateStoryboardImageStaged(current.settings, current.shot, current.index ?? 0, current.allShots ?? [current.shot], current.assets ?? [], current.stageAWorkflowJson ?? current.settings.imageWorkflowJson, current.stageBWorkflowJson ?? current.settings.imageWorkflowJson, { signal: current.signal, characterRedraw: current.characterRedraw }));
    request.signal?.throwIfAborted();
    store.upsertGenerationTask({ ...task, stage: "stageA", status: "running" });
    const stageAResult = await runner("stageA", request);
    request.signal?.throwIfAborted();
    if (stageAResult.status === "needs_review") {
      store.markGenerationTaskNeedsReview(task.id, stageAResult.bestPreviewPath, stageAResult.reasons);
      return useStoryboardStore.getState().generationTasks.find((item) => item.id === task.id)!;
    }
    let result: StoryboardStagedGenerationResult = stageAResult;
    if (request.runStage) {
      store.upsertGenerationTask({ ...task, stage: "stageB", status: "running" });
      try {
        result = await runner("stageB", request);
      } catch (stageBError) {
        store.upsertGenerationTask({ ...task, stage: "fallback", status: "running", errorMessage: String(stageBError) });
        result = await runner("fallback", request);
      }
    }
    const transition = planStoryboardOutcomeTransition(result);
    if (transition.action === "needs_review") {
      store.markGenerationTaskNeedsReview(task.id, transition.bestPreviewPath, transition.reasons);
      return useStoryboardStore.getState().generationTasks.find((item) => item.id === task.id)!;
    }
    const output = transition.outputPath;
    if (!output) throw Object.assign(new Error("ComfyUI output is missing"), { errorCode: "output_missing" });
    request.signal?.throwIfAborted();
    store.completeGenerationTask(task.id, output);
    return useStoryboardStore.getState().generationTasks.find((item) => item.id === task.id) ?? { ...task, stage: "completed", status: "completed", outputPath: output };
  } catch (error) {
    const errorDetails = error as {
      errorCode?: string;
      bestPreviewPath?: string;
      reviewReasons?: string[];
      reasons?: string[];
      name?: string;
    };
    const errorCode = String(errorDetails?.errorCode ?? (request.preflight ? "preflight_failed" : "generation_failed"));
    const errorMessage = String(error instanceof Error ? error.message : error);
    const bestPreviewPath = String(errorDetails.bestPreviewPath ?? "").trim() || undefined;
    const reviewReasons = [...new Set(
      [...(errorDetails.reviewReasons ?? errorDetails.reasons ?? [])]
        .map((reason) => String(reason ?? "").trim())
        .filter(Boolean)
    )];
    const cancelled = request.signal?.aborted === true || errorDetails.name === "AbortError" || errorCode === "cancelled";
    if (cancelled) {
      store.markGenerationTaskCancelled(task.id, { bestPreviewPath, reviewReasons, errorMessage });
      return useStoryboardStore.getState().generationTasks.find((item) => item.id === task.id) ?? {
        ...task,
        stage: "cancelled",
        status: "cancelled",
        errorCode: "cancelled",
        errorMessage,
        bestPreviewPath,
        reviewReasons
      };
    }
    store.markGenerationTaskFailed(task.id, { errorCode, errorMessage, bestPreviewPath, reviewReasons });
    return useStoryboardStore.getState().generationTasks.find((item) => item.id === task.id) ?? { ...task, stage: "failed", status: "failed", errorCode, errorMessage, bestPreviewPath, reviewReasons };
  }
}

export async function queueStoryboardBatch(requests: StoryboardGenerationRequest[], options: StoryboardBatchOptions = {}): Promise<StoryboardGenerationTask[]> {
  options.signal?.throwIfAborted();
  const batchId = options.batchId ?? `batch_${Date.now()}`;
  if (options.preflight) {
    try { await options.preflight(); } catch (error) {
      return requests.map((request) => { const task = generationTask(request, batchId); const store = useStoryboardStore.getState(); store.upsertGenerationTask(task); store.markGenerationTaskFailed(task.id, { errorCode: "preflight_failed", errorMessage: String(error instanceof Error ? error.message : error) }); return useStoryboardStore.getState().generationTasks.find((item) => item.id === task.id)!; });
    }
  }
  const results: StoryboardGenerationTask[] = [];
  for (const request of requests) {
    options.signal?.throwIfAborted();
    results.push(await queueStoryboardShot({ ...options, ...request, preflight: undefined, batchId }));
  }
  return results;
}

export async function retryStoryboardTask(taskId: string, _settings?: ComfySettings, overrides: Partial<StoryboardGenerationRequest> = {}): Promise<StoryboardGenerationTask> {
  const task = useStoryboardStore.getState().generationTasks.find((item) => item.id === taskId);
  if (!task) throw new Error(`Unknown storyboard generation task: ${taskId}`);
  const snapshot = task.retrySnapshot;
  if (!snapshot || snapshot.version !== 1) {
    throw Object.assign(new Error(`retry_snapshot_missing:${taskId}`), { errorCode: "retry_snapshot_missing" });
  }
  if (snapshot.preflightRequired && !overrides.preflight) {
    throw Object.assign(new Error(`retry_preflight_unavailable:${taskId}`), { errorCode: "retry_preflight_unavailable" });
  }
  if (snapshot.customRunnerRequired && !overrides.runStage) {
    throw Object.assign(new Error(`retry_runner_unavailable:${taskId}`), { errorCode: "retry_runner_unavailable" });
  }
  const restored = cloneSerializableRetryValue(snapshot);
  return queueStoryboardShot({
    settings: restored.settings as unknown as ComfySettings,
    shot: restored.shot,
    index: restored.index,
    allShots: restored.allShots,
    assets: restored.assets,
    stageAWorkflowJson: restored.stageAWorkflowJson,
    stageBWorkflowJson: restored.stageBWorkflowJson,
    workflowId: restored.workflowId ?? task.workflowId,
    globalStyle: restored.globalStyle,
    negativePrompt: restored.negativePrompt,
    characterRedraw: restored.characterRedraw,
    preflight: overrides.preflight,
    runStage: overrides.runStage,
    batchId: overrides.batchId,
    signal: overrides.signal
  });
}

