function hasDesktopInvoke(): boolean {
  return isDesktopRuntime();
}

async function invokeDesktop<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  if (!hasDesktopInvoke()) {
    throw new Error("未检测到桌面运行环境。请使用 Tauri 桌面版或 Windows Web 启动脚本。");
  }
  return invokeDesktopCommand<T>(cmd, args);
}

function createComfyClient(baseUrl: string): ComfyClient {
  return new ComfyClient({
    baseUrl,
    desktopInvoke: hasDesktopInvoke() ? invokeDesktop : undefined
  });
}

export async function generateLocalTtsAudio(
  request: LocalTtsGenerationRequest
): Promise<LocalTtsGenerationResult> {
  return invokeDesktop<LocalTtsGenerationResult>("generate_tts_audio", {
    ...request
  });
}

export async function deleteGeneratedFileFamilies(sourcePaths: string[], excludePaths: string[] = []) {
  if (!hasDesktopInvoke()) {
    return { deletedPaths: [] };
  }
  const normalizedSourcePaths = sourcePaths
    .map((value) => String(value || "").trim())
    .filter((value): value is string => Boolean(value));
  if (normalizedSourcePaths.length <= 0) {
    return { deletedPaths: [] };
  }
  const normalizedExcludePaths = excludePaths
    .map((value) => String(value || "").trim())
    .filter((value): value is string => Boolean(value));
  return invokeDesktop<DeleteGeneratedFileFamiliesResult>("delete_generated_file_families", {
    sourcePaths: normalizedSourcePaths,
    excludePaths: normalizedExcludePaths
  });
}

function normalizeBaseUrl(raw: string): string {
  return normalizeComfyBaseUrl(raw);
}

async function storyboardSleep(ms: number): Promise<void> {
  const safeMs = Math.max(0, Math.floor(ms));
  await new Promise((resolve) => window.setTimeout(resolve, safeMs));
}

type ComfyMaintenanceAttemptDetail = {
  route: "desktop" | "http";
  path: string;
  statusCode?: number | null;
  ok: boolean;
  message?: string;
};

type ComfyMemoryReliefResult = {
  interruptOk: boolean;
  freeOk: boolean;
  usedDesktopBridge: boolean;
  attempts: ComfyMaintenanceAttemptDetail[];
};

async function invokeComfyMaintenance(
  baseUrl: string,
  path: "/interrupt" | "/free",
  payload?: Record<string, unknown>
): Promise<ComfyMaintenanceResult> {
  if (hasDesktopInvoke()) {
    try {
      const result = await invokeDesktop<ComfyMaintenanceResult>("comfy_maintenance", {
        baseUrl: normalizeBaseUrl(baseUrl),
        path,
        payload: payload ?? null
      });
      return {
        ok: !!result?.ok,
        statusCode: result?.statusCode ?? null,
        message: String(result?.message ?? "")
      };
    } catch (error) {
      return {
        ok: false,
        statusCode: null,
        message: `desktop_invoke_failed:${String(error ?? "unknown")}`.slice(0, 240)
      };
    }
  }
  try {
    const response = await fetch(`${normalizeBaseUrl(baseUrl)}${path}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: payload ? JSON.stringify(payload) : undefined
    });
    return {
      ok: response.ok,
      statusCode: response.status,
      message: response.ok ? `http_${response.status}` : `http_${response.status}`
    };
  } catch (error) {
    return {
      ok: false,
      statusCode: null,
      message: `fetch_failed:${String(error ?? "unknown")}`.slice(0, 240)
    };
  }
}

async function attemptComfyMemoryRelief(baseUrl: string, promptId = ""): Promise<ComfyMemoryReliefResult> {
  const attempts: ComfyMaintenanceAttemptDetail[] = [];
  const usedDesktopBridge = hasDesktopInvoke();
  const trimmedPromptId = String(promptId ?? "").trim();
  const usedTargetedInterruptOnly = trimmedPromptId.length > 0 && /^[0-9a-fA-F-]{24,64}$/.test(trimmedPromptId);

  let interruptOk = false;
  if (usedTargetedInterruptOnly) {
    const targetedInterruptAttempt = await invokeComfyMaintenance(baseUrl, "/interrupt", {
      prompt_id: trimmedPromptId
    });
    attempts.push({
      route: usedDesktopBridge ? "desktop" : "http",
      path: "/interrupt",
      statusCode: targetedInterruptAttempt.statusCode ?? null,
      ok: targetedInterruptAttempt.ok,
      message: `${targetedInterruptAttempt.message ?? ""} prompt_id=${trimmedPromptId}`.trim()
    });
    interruptOk = targetedInterruptAttempt.ok;
  }

  if (!usedTargetedInterruptOnly) {
    const interruptAttempt1 = await invokeComfyMaintenance(baseUrl, "/interrupt", {});
    attempts.push({
      route: usedDesktopBridge ? "desktop" : "http",
      path: "/interrupt",
      statusCode: interruptAttempt1.statusCode ?? null,
      ok: interruptAttempt1.ok,
      message: interruptAttempt1.message
    });
    if (!interruptOk) {
      interruptOk = interruptAttempt1.ok;
    }
    if (!interruptOk) {
      const interruptAttempt2 = await invokeComfyMaintenance(baseUrl, "/interrupt");
      attempts.push({
        route: usedDesktopBridge ? "desktop" : "http",
        path: "/interrupt",
        statusCode: interruptAttempt2.statusCode ?? null,
        ok: interruptAttempt2.ok,
        message: interruptAttempt2.message
      });
      interruptOk = interruptAttempt2.ok;
    }
  }

  const freePayloads: Array<Record<string, unknown> | undefined> = [
    { unload_models: true, free_memory: true },
    { free_memory: true },
    {}
  ];
  let freeOk = false;
  for (const payload of freePayloads) {
    const freeAttempt = await invokeComfyMaintenance(baseUrl, "/free", payload);
    attempts.push({
      route: usedDesktopBridge ? "desktop" : "http",
      path: "/free",
      statusCode: freeAttempt.statusCode ?? null,
      ok: freeAttempt.ok,
      message: freeAttempt.message
    });
    if (freeAttempt.ok) {
      freeOk = true;
      break;
    }
  }

  return {
    interruptOk,
    freeOk,
    usedDesktopBridge,
    attempts
  };
}

function looksLikeSdxlCheckpoint(name: string): boolean {
  const normalized = name.trim().toLowerCase();
  if (!normalized) return false;
  if (/sd[_-]?xl/.test(normalized)) return true;
  if (/animagine[-_]?xl/.test(normalized)) return true;
  if (/juggernautxl/.test(normalized)) return true;
  return /(?:^|[^a-z0-9])xl(?:[^a-z0-9]|$)/.test(normalized);
}

function looksLikeFluxOrSd3Model(name: string): boolean {
  const normalized = name.trim().toLowerCase();
  if (!normalized) return false;
  return /flux|sd3|sd[_ -]?3\.?5|stable[_ -]?diffusion[_ -]?3|xlabs/.test(normalized);
}

function looksLikeControlNetLoRA(name: string): boolean {
  const normalized = basenameModelChoice(name);
  if (!normalized) return false;
  return /control[-_]?lora|rank\d+/.test(normalized);
}

function looksLikeSdxlControlNet(name: string): boolean {
  const normalized = basenameModelChoice(name);
  if (!normalized) return false;
  if (looksLikeFluxOrSd3Model(normalized)) return false;
  return /sd[_-]?xl|openposexl\d*|posexl\d*|cannyxl\d*|depthxl\d*|scribblexl\d*|(?:^|[^a-z0-9])xl\d*(?:[^a-z0-9]|$)|xinsir|mistoline|union|thibaud.*xl|kohya.*xl/.test(normalized);
}

function looksLikeSd15ControlNet(name: string): boolean {
  const normalized = basenameModelChoice(name);
  if (!normalized) return false;
  if (looksLikeFluxOrSd3Model(normalized) || looksLikeSdxlControlNet(normalized)) return false;
  return /sd15|control[_-]?v11|(?:^|[^a-z0-9])v11(?:[^a-z0-9]|$)|11p|11f1|t2i[_-]?adapter/.test(normalized);
}

function preferControlNetOption(
  options: string[],
  matchers: Array<(value: string) => boolean>
): string | null {
  for (const matcher of matchers) {
    const matched = options.find((value) => matcher(value));
    if (matched) return matched;
  }
  return null;
}

function looksLikeOpenPoseControlNet(name: string): boolean {
  const normalized = basenameModelChoice(name);
  if (!normalized) return false;
  return /openpose|posexl|openposexl|dwpose/.test(normalized);
}

function looksLikeDepthControlNet(name: string): boolean {
  const normalized = basenameModelChoice(name);
  if (!normalized) return false;
  return /depth/.test(normalized);
}

type StoryboardControlNetTask = "openpose" | "depth" | "canny";

function storyboardControlNetTaskLabel(task: StoryboardControlNetTask): string {
  if (task === "openpose") return "OpenPose";
  if (task === "depth") return "Depth";
  return "Canny";
}

function storyboardDefaultControlNetName(task: StoryboardControlNetTask, isSdxl: boolean): string {
  if (task === "openpose") {
    return isSdxl ? "OpenPoseXL2.safetensors" : "control_v11p_sd15_openpose_fp16.safetensors";
  }
  if (task === "depth") {
    return isSdxl ? "controlnet-depth-sdxl-1.0.safetensors" : "control_v11f1p_sd15_depth_fp16.safetensors";
  }
  return isSdxl ? "controlnet-canny-sdxl-1.0.safetensors" : "control_v11p_sd15_canny.pth";
}

function storyboardControlNetTaskMatcher(task: StoryboardControlNetTask): (value: string) => boolean {
  if (task === "openpose") return looksLikeOpenPoseControlNet;
  if (task === "depth") return looksLikeDepthControlNet;
  return (value) => /canny/i.test(value);
}

function resolveStoryboardControlNetTaskChoice(
  storyboardModel: string,
  task: StoryboardControlNetTask,
  objectInfo?: Record<string, unknown>
): {
  controlNetName: string | null;
  isMatchedToModelFamily: boolean;
  missingForModelFamily: boolean;
} {
  const isSdxl = looksLikeSdxlCheckpoint(storyboardModel);
  const preferredDefault = storyboardDefaultControlNetName(task, isSdxl);
  const options =
    objectInfo && typeof objectInfo === "object"
      ? extractComboOptionsFromObjectInfo(objectInfo, "ControlNetLoader", "control_net_name")
      : [];
  const taskMatcher = storyboardControlNetTaskMatcher(task);
  const taskOptions = options.filter((value) => taskMatcher(value));

  if (taskOptions.length === 0) {
    return {
      controlNetName: preferredDefault,
      isMatchedToModelFamily: !objectInfo,
      missingForModelFamily: Boolean(objectInfo)
    };
  }

  if (isSdxl) {
    const sdxlChoice = preferControlNetOption(taskOptions, [
      (value) => taskMatcher(value) && looksLikeSdxlControlNet(value) && !looksLikeControlNetLoRA(value) && /\.safetensors$/i.test(value),
      (value) => taskMatcher(value) && looksLikeSdxlControlNet(value) && !looksLikeControlNetLoRA(value),
      (value) => taskMatcher(value) && looksLikeSdxlControlNet(value),
      (value) => taskMatcher(value)
    ]);
    if (sdxlChoice && looksLikeSdxlControlNet(sdxlChoice)) {
      return { controlNetName: sdxlChoice, isMatchedToModelFamily: true, missingForModelFamily: false };
    }
    return {
      controlNetName: sdxlChoice ?? preferredDefault,
      isMatchedToModelFamily: false,
      missingForModelFamily: true
    };
  }

  const sd15Choice = preferControlNetOption(taskOptions, [
    (value) => taskMatcher(value) && looksLikeSd15ControlNet(value) && /\.safetensors$/i.test(value),
    (value) => taskMatcher(value) && looksLikeSd15ControlNet(value),
    (value) => taskMatcher(value) && !looksLikeSdxlControlNet(value) && !looksLikeFluxOrSd3Model(value),
    (value) => taskMatcher(value)
  ]);
  return {
    controlNetName: sd15Choice ?? preferredDefault,
    isMatchedToModelFamily: true,
    missingForModelFamily: false
  };
}

function resolveStoryboardStableControlNetChoice(
  storyboardModel: string,
  objectInfo?: Record<string, unknown>
): {
  openposeControlNetName: string | null;
  depthControlNetName: string | null;
  checkpointOverride: string | null;
  qualityError: string | null;
} {
  const isSdxl = looksLikeSdxlCheckpoint(storyboardModel);
  const openposeChoice = resolveStoryboardControlNetTaskChoice(storyboardModel, "openpose", objectInfo);
  const depthChoice = resolveStoryboardControlNetTaskChoice(storyboardModel, "depth", objectInfo);

  if (isSdxl && objectInfo && (!openposeChoice.isMatchedToModelFamily || !depthChoice.isMatchedToModelFamily)) {
    const missingLabels = [
      !openposeChoice.isMatchedToModelFamily ? storyboardControlNetTaskLabel("openpose") : "",
      !depthChoice.isMatchedToModelFamily ? storyboardControlNetTaskLabel("depth") : ""
    ].filter(Boolean);
    return {
      openposeControlNetName: openposeChoice.controlNetName,
      depthControlNetName: depthChoice.controlNetName,
      checkpointOverride: null,
      qualityError: `当前分镜基模“${storyboardModel}”属于 SDXL，但本机未同时检测到匹配同体系的 ${missingLabels.join(" + ")} ControlNet。为避免再次出现维度不匹配和结构崩坏，请补齐 SDXL 版 OpenPose + Depth ControlNet，再继续使用当前基模。`
    };
  }

  return {
    openposeControlNetName: openposeChoice.controlNetName,
    depthControlNetName: depthChoice.controlNetName,
    checkpointOverride: null,
    qualityError: null
  };
}

function resolveStoryboardControlNetChoice(
  storyboardModel: string,
  usePoseGuide: boolean,
  objectInfo?: Record<string, unknown>
): {
  controlNetName: string | null;
  checkpointOverride: string | null;
  qualityError: string | null;
} {
  const requestedTask = usePoseGuide ? /openpose/i : /canny/i;
  const requestedTaskLabel = usePoseGuide ? "OpenPose" : "Canny";
  const preferredDefault = usePoseGuide ? "control_v11p_sd15_openpose.pth" : "control_v11p_sd15_canny.pth";
  const isSdxl = looksLikeSdxlCheckpoint(storyboardModel);
  const options =
    objectInfo && typeof objectInfo === "object"
      ? extractComboOptionsFromObjectInfo(objectInfo, "ControlNetLoader", "control_net_name")
      : [];
  const taskOptions = options.filter((value) => requestedTask.test(value));

  if (taskOptions.length === 0) {
    return {
      controlNetName: preferredDefault,
      checkpointOverride: isSdxl ? "realisticVisionV60B1_v51VAE.safetensors" : null,
      qualityError:
        isSdxl && objectInfo
          ? `当前分镜基模“${storyboardModel}”属于 SDXL，但 ComfyUI 未检测到任何可用的 ${requestedTaskLabel} ControlNet。为保证最终质量，请先下载 SDXL 版 ${requestedTaskLabel} ControlNet；文件名建议包含 “${usePoseGuide ? "openpose" : "canny"}” 和 “sdxl/xl” 或 “xinsir”。`
          : null
    };
  }

  if (isSdxl) {
    const sdxlChoice = preferControlNetOption(taskOptions, [
      (value) => looksLikeSdxlControlNet(value) && !looksLikeControlNetLoRA(value) && /\.safetensors$/i.test(value),
      (value) => looksLikeSdxlControlNet(value) && !looksLikeControlNetLoRA(value),
      (value) => looksLikeSdxlControlNet(value) && /\.safetensors$/i.test(value),
      (value) => looksLikeSdxlControlNet(value)
    ]);
    if (sdxlChoice) {
      return { controlNetName: sdxlChoice, checkpointOverride: null, qualityError: null };
    }
    const sd15Fallback = preferControlNetOption(taskOptions, [
      (value) => looksLikeSd15ControlNet(value) && /\.safetensors$/i.test(value),
      (value) => looksLikeSd15ControlNet(value),
      () => true
    ]);
    return {
      controlNetName: sd15Fallback,
      checkpointOverride: "realisticVisionV60B1_v51VAE.safetensors",
      qualityError: objectInfo
        ? `当前分镜基模“${storyboardModel}”属于 SDXL，但当前 ComfyUI 里只有 SD1.5 系的 ${requestedTaskLabel} ControlNet（例如：${taskOptions.slice(0, 3).join(" / ")}）。这会导致你刚才看到的维度报错或被迫降级到低质量兜底。要保住 SDXL 质量，请下载 SDXL 版 ${requestedTaskLabel} ControlNet；文件名建议包含 “${usePoseGuide ? "openpose" : "canny"}” 和 “sdxl/xl” 或 “xinsir”。`
        : null
    };
  }

  const sd15Choice = preferControlNetOption(taskOptions, [
    (value) => looksLikeSd15ControlNet(value) && /\.safetensors$/i.test(value),
    (value) => looksLikeSd15ControlNet(value),
    (value) => !looksLikeSdxlControlNet(value) && !looksLikeFluxOrSd3Model(value),
    () => true
  ]);
  return {
    controlNetName: sd15Choice,
    checkpointOverride: null,
    qualityError: null
  };
}

type StoryboardDepthPreprocessorChoice =
  | {
      classType: "DepthAnythingV2Preprocessor";
      defaults: { ckpt_name: string };
    }
  | {
      classType: "DepthAnythingPreprocessor";
      defaults: { ckpt_name: string };
    }
  | {
      classType: "MiDaS-DepthMapPreprocessor";
      defaults: { a: number; bg_threshold: number };
    };

function resolveStoryboardDepthPreprocessorChoice(
  objectInfo?: Record<string, unknown>
): StoryboardDepthPreprocessorChoice | null {
  const hasNode = (name: string) => Boolean(objectInfo && typeof objectInfo === "object" && objectInfo[name]);
  if (!objectInfo) {
    return {
      classType: "DepthAnythingV2Preprocessor",
      defaults: { ckpt_name: "depth_anything_v2_vitl.pth" }
    };
  }
  if (hasNode("DepthAnythingV2Preprocessor")) {
    return {
      classType: "DepthAnythingV2Preprocessor",
      defaults: { ckpt_name: "depth_anything_v2_vitl.pth" }
    };
  }
  if (hasNode("DepthAnythingPreprocessor")) {
    return {
      classType: "DepthAnythingPreprocessor",
      defaults: { ckpt_name: "depth_anything_vitl14.pth" }
    };
  }
  if (hasNode("MiDaS-DepthMapPreprocessor")) {
    return {
      classType: "MiDaS-DepthMapPreprocessor",
      defaults: { a: Math.PI * 2, bg_threshold: 0.1 }
    };
  }
  return null;
}

type StoryboardPosePreprocessorChoice = {
  classType: "OpenposePreprocessor";
  defaults: {
    detect_hand: "enable" | "disable";
    detect_body: "enable" | "disable";
    detect_face: "enable" | "disable";
    resolution: number;
    scale_stick_for_xinsr_cn: "disable" | "enable";
  };
};

function resolveStoryboardPosePreprocessorChoice(
  objectInfo?: Record<string, unknown>,
  resolution = 768
): StoryboardPosePreprocessorChoice | null {
  const normalizedResolution = Math.max(512, Math.min(1024, Math.round(resolution / 64) * 64 || 768));
  if (!objectInfo || (typeof objectInfo === "object" && objectInfo["OpenposePreprocessor"])) {
    return {
      classType: "OpenposePreprocessor",
      defaults: {
        detect_hand: "enable",
        detect_body: "enable",
        detect_face: "enable",
        resolution: normalizedResolution,
        scale_stick_for_xinsr_cn: "disable"
      }
    };
  }
  return null;
}

function snapRenderSize(value: number): number {
  const clamped = Math.max(320, Math.round(value));
  return Math.max(320, Math.round(clamped / 64) * 64);
}

function normalizeStoryboardStillRenderSize(
  settings: ComfySettings,
  width: number,
  height: number
): { width: number; height: number } {
  const storyboardMode = settings.storyboardImageWorkflowMode ?? "builtin_qwen";
  if (storyboardMode !== "mature_asset_guided") {
    return { width: snapRenderSize(width), height: snapRenderSize(height) };
  }
  const modelName = resolveStoryboardImageModel(settings);
  const isSdxl = looksLikeSdxlCheckpoint(modelName);
  const maxSide = isSdxl ? STORYBOARD_SDXL_MAX_SIDE : STORYBOARD_SD15_MAX_SIDE;
  const minSide = isSdxl ? STORYBOARD_SDXL_MIN_SIDE : STORYBOARD_SD15_MIN_SIDE;

  let outWidth = Math.max(320, Math.round(width));
  let outHeight = Math.max(320, Math.round(height));

  const downScale = Math.min(1, maxSide / Math.max(outWidth, outHeight));
  outWidth = Math.round(outWidth * downScale);
  outHeight = Math.round(outHeight * downScale);

  if (Math.min(outWidth, outHeight) < minSide) {
    const upScale = minSide / Math.max(1, Math.min(outWidth, outHeight));
    outWidth = Math.round(outWidth * upScale);
    outHeight = Math.round(outHeight * upScale);
  }

  const finalScale = Math.min(1, maxSide / Math.max(outWidth, outHeight));
  outWidth = snapRenderSize(outWidth * finalScale);
  outHeight = snapRenderSize(outHeight * finalScale);
  return { width: outWidth, height: outHeight };
}

function resolveStoryboardImageModel(
  settings: ComfySettings,
  hasCharacterRefs = false
): string {
  const storyboardMode = settings.storyboardImageWorkflowMode ?? "builtin_qwen";
  const storyboardModel = settings.storyboardImageModelName?.trim() || "";
  const characterModel = settings.characterAssetModelName?.trim() || "";
  const hasExplicitStoryboardModel =
    storyboardModel.length > 0 && storyboardModel.toLowerCase() !== "sd_xl_base_1.0.safetensors";
  if (hasExplicitStoryboardModel) return storyboardModel;
  if (hasCharacterRefs && characterModel) return characterModel;
  if (storyboardMode === "mature_asset_guided" && hasCharacterRefs) {
    return "realisticVisionV60B1_v51VAE.safetensors";
  }
  if (storyboardModel) return storyboardModel;
  if (characterModel) return characterModel;
  return "realisticVisionV60B1_v51VAE.safetensors";
}

const STORYBOARD_RUNTIME_MODEL_PREFERRED_ORDER = [
  "cardosanime_v10.safetensors",
  "animagine-xl-4.0.safetensors",
  "animapencilxl_v100_2.safetensors",
  "anything-v3.0.ckpt",
  "awpainting_v14.safetensors",
  "netayumev35_pretrained_all_in_one.safetensors",
  "realisticvisionv60b1_v51vae.safetensors",
  "sd_xl_base_1.0.safetensors"
];

const STORYBOARD_RUNTIME_MODEL_GENERIC_DEFAULTS = new Set<string>([
  "",
  "realisticvisionv60b1_v51vae.safetensors",
  "sd_xl_base_1.0.safetensors"
]);

function listCheckpointOptionsFromObjectInfo(objectInfo?: Record<string, unknown>): string[] {
  if (!objectInfo || typeof objectInfo !== "object") return [];
  const loader = objectInfo["CheckpointLoaderSimple"];
  if (!loader || typeof loader !== "object" || Array.isArray(loader)) return [];
  const input = (loader as { input?: Record<string, unknown> }).input;
  if (!input || typeof input !== "object" || Array.isArray(input)) return [];
  const required = (input as { required?: Record<string, unknown> }).required;
  if (!required || typeof required !== "object" || Array.isArray(required)) return [];
  return extractStringList((required as Record<string, unknown>).ckpt_name);
}

function resolveStoryboardRuntimeModelChoice(args: {
  currentModel: string;
  objectInfo?: Record<string, unknown>;
  preferAnime: boolean;
}): string {
  const currentModel = String(args.currentModel ?? "").trim();
  const options = listCheckpointOptionsFromObjectInfo(args.objectInfo);
  if (options.length === 0) return currentModel;

  const resolvedCurrent = currentModel
    ? resolveBestModelOption(currentModel, options, "CheckpointLoaderSimple", "ckpt_name")
    : "";
  const currentBase = basenameModelChoice(resolvedCurrent || currentModel);
  const hasCurrentInOptions =
    resolvedCurrent.length > 0 &&
    options.some((option) => normalizeModelChoice(option) === normalizeModelChoice(resolvedCurrent));
  const shouldAutoSwitch =
    !hasCurrentInOptions || STORYBOARD_RUNTIME_MODEL_GENERIC_DEFAULTS.has(currentBase);

  if (!args.preferAnime && hasCurrentInOptions) {
    return resolvedCurrent;
  }
  if (!shouldAutoSwitch && hasCurrentInOptions) {
    return resolvedCurrent;
  }

  const byBase = new Map<string, string>();
  for (const option of options) {
    byBase.set(basenameModelChoice(option), option);
  }
  for (const preferred of STORYBOARD_RUNTIME_MODEL_PREFERRED_ORDER) {
    const hit = byBase.get(basenameModelChoice(preferred));
    if (hit) return hit;
  }

  if (args.preferAnime) {
    const animeSoft =
      options.find((name) => /cardos|animagine|anima|anime|anything|awpainting|neta|yume/i.test(name)) ??
      "";
    if (animeSoft) return animeSoft;
  }

  return resolvedCurrent || options[0] || currentModel;
}

export function defaultVideoGenerationMode(): "comfy" | "local_motion" {
  if (typeof navigator !== "undefined" && /mac/i.test(navigator.platform)) {
    return "local_motion";
  }
  return "comfy";
}

let comfyWsClientId = `storyboard-pro-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
let comfyWsBaseUrl = "";
let comfyWs: WebSocket | null = null;
let comfyWsActivePromptId = "";
const promptProgressById = new Map<string, PromptProgressSnapshot>();
const promptProgressListeners = new Map<string, Set<PromptProgressListener>>();

function toComfyWsUrl(baseUrl: string, clientId: string): string {
  const normalized = normalizeBaseUrl(baseUrl);
  const wsBase = normalized.startsWith("https://")
    ? `wss://${normalized.slice("https://".length)}`
    : `ws://${normalized.slice("http://".length)}`;
  return `${wsBase}/ws?clientId=${encodeURIComponent(clientId)}`;
}

function emitPromptProgress(promptId: string, progress: number, message: string) {
  const safePromptId = promptId.trim();
  if (!safePromptId) return;
  const safeProgress = Math.max(0, Math.min(1, Number.isFinite(progress) ? progress : 0));
  const snapshot: PromptProgressSnapshot = {
    progress: safeProgress,
    message: message.trim() || "执行中"
  };
  promptProgressById.set(safePromptId, snapshot);
  const listeners = promptProgressListeners.get(safePromptId);
  if (!listeners || listeners.size === 0) return;
  for (const listener of listeners) listener(snapshot);
}

function subscribePromptProgress(promptId: string, listener: PromptProgressListener): () => void {
  const safePromptId = promptId.trim();
  if (!safePromptId) return () => undefined;
  const set = promptProgressListeners.get(safePromptId) ?? new Set<PromptProgressListener>();
  set.add(listener);
  promptProgressListeners.set(safePromptId, set);
  const snapshot = promptProgressById.get(safePromptId);
  if (snapshot) listener(snapshot);
  return () => {
    const current = promptProgressListeners.get(safePromptId);
    if (!current) return;
    current.delete(listener);
    if (current.size === 0) promptProgressListeners.delete(safePromptId);
  };
}

function shouldUseComfyProgressSocket(baseUrl: string): boolean {
  if (typeof window === "undefined" || typeof WebSocket === "undefined") return false;
  if (!String(baseUrl ?? "").trim()) return false;
  // In Windows Web Bridge mode, page origin (127.0.0.1:3211) differs from Comfy origin (127.0.0.1:8188).
  // Prefer polling to avoid repeated cross-origin websocket 403 noise and instability.
  if (isWebBridgeRuntime()) return false;
  return true;
}

function ensureComfyProgressSocket(baseUrl: string) {
  if (!shouldUseComfyProgressSocket(baseUrl)) {
    if (comfyWs) {
      try {
        comfyWs.close();
      } catch {
        // ignore close errors
      }
    }
    comfyWs = null;
    comfyWsBaseUrl = "";
    return;
  }
  const normalizedBaseUrl = normalizeBaseUrl(baseUrl);
  const shouldReuse =
    comfyWs &&
    comfyWsBaseUrl === normalizedBaseUrl &&
    (comfyWs.readyState === WebSocket.OPEN || comfyWs.readyState === WebSocket.CONNECTING);
  if (shouldReuse) return;

  if (comfyWs) {
    try {
      comfyWs.close();
    } catch {
      // ignore close errors
    }
    comfyWs = null;
  }

  const ws = new WebSocket(toComfyWsUrl(normalizedBaseUrl, comfyWsClientId));
  comfyWsBaseUrl = normalizedBaseUrl;
  ws.onmessage = (event) => {
    let payload: ComfyProgressMessage | null = null;
    try {
      payload = JSON.parse(String(event.data)) as ComfyProgressMessage;
    } catch {
      return;
    }
    if (!payload || typeof payload !== "object") return;
    const type = String(payload.type ?? "");
    const data = payload.data ?? {};
    const promptIdRaw = String(data.prompt_id ?? "").trim();
    if (promptIdRaw) {
      comfyWsActivePromptId = promptIdRaw;
    }
    const promptId = promptIdRaw || comfyWsActivePromptId;
    if (!promptId) return;

    if (type === "execution_start") {
      emitPromptProgress(promptId, 0.05, "任务已入队");
      return;
    }
    if (type === "executing") {
      if (data.node) {
        emitPromptProgress(promptId, 0.12, `执行节点 ${String(data.node)}`);
      } else {
        emitPromptProgress(promptId, 0.95, "执行完成，等待输出文件");
      }
      return;
    }
    if (type === "progress") {
      const value = Number(data.value);
      const max = Number(data.max);
      if (Number.isFinite(value) && Number.isFinite(max) && max > 0) {
        const ratio = Math.max(0, Math.min(1, value / max));
        emitPromptProgress(promptId, 0.12 + ratio * 0.82, `采样进度 ${Math.round(value)}/${Math.round(max)}`);
      }
      return;
    }
    if (type === "execution_cached") {
      emitPromptProgress(promptId, 0.3, "复用缓存节点");
      return;
    }
    if (type === "execution_success") {
      emitPromptProgress(promptId, 0.97, "执行成功，正在收集输出");
      return;
    }
    if (type === "execution_error") {
      const message = String(data.exception_message ?? "").trim();
      emitPromptProgress(promptId, 1, message ? `执行失败：${message}` : "执行失败");
      return;
    }
    if (type === "status") {
      const remaining = Number(data.queue_remaining);
      if (Number.isFinite(remaining)) {
        emitPromptProgress(promptId, 0.08, `队列剩余 ${Math.max(0, Math.round(remaining))}`);
      }
    }
  };
  ws.onclose = () => {
    if (comfyWs === ws) comfyWs = null;
  };
  ws.onerror = () => {
    // WS is best-effort; polling fallback is still used.
  };
  comfyWs = ws;
}

function inferComfyInputDir(settings: ComfySettings): string {
  const explicit = settings.comfyInputDir.trim().replace(/\/+$/, "");
  if (explicit) return explicit;
  const root = settings.comfyRootDir.trim().replace(/\/+$/, "");
  if (root) return `${root}/input`;
  const output = settings.outputDir.trim().replace(/\/+$/, "");
  if (!output) return "";
  const index = output.lastIndexOf("/");
  if (index <= 0) return "";
  return `${output.slice(0, index)}/input`;
}

function normalizeWorkflowJsonText(raw: string): string {
  return raw.replace(/^\uFEFF/, "").trim();
}

function stripMarkdownJsonFence(raw: string): string {
  const trimmed = raw.trim();
  const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fenced?.[1]?.trim() || trimmed;
}

function extractJsonObjectBody(raw: string): string {
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return raw.slice(firstBrace, lastBrace + 1).trim();
  }
  return raw;
}

function parseWorkflowJsonWithRecovery(raw: string): unknown {
  const attempts: string[] = [];
  const pushAttempt = (value: string) => {
    const next = value.trim();
    if (!next) return;
    if (!attempts.includes(next)) attempts.push(next);
  };

  const normalized = normalizeWorkflowJsonText(raw);
  if (!normalized) {
    throw new Error("工作流内容为空");
  }
  const withoutFence = stripMarkdownJsonFence(normalized);
  const extractedBody = extractJsonObjectBody(withoutFence);

  pushAttempt(normalized);
  pushAttempt(withoutFence);
  pushAttempt(extractedBody);

  let lastError: unknown = null;
  for (const candidate of attempts) {
    try {
      return JSON.parse(candidate) as unknown;
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError ?? new Error("未知 JSON 解析错误");
}

function applyTokenAliases(
  mapping: ComfySettings["tokenMapping"],
  baseTokens: Record<string, string>
): Record<string, string> {
  const mappedTokens: Record<string, string> = { ...baseTokens };
  const aliasPairs: Array<[keyof ComfySettings["tokenMapping"], string]> = [
    ["prompt", baseTokens.PROMPT],
    ["nextScenePrompt", baseTokens.NEXT_SCENE_PROMPT],
    ["videoPrompt", baseTokens.VIDEO_PROMPT],
    ["videoMode", baseTokens.VIDEO_MODE],
    ["negativePrompt", baseTokens.NEGATIVE_PROMPT],
    ["seed", baseTokens.SEED],
    ["title", baseTokens.SHOT_TITLE],
    ["dialogue", baseTokens.DIALOGUE],
    ["speakerName", baseTokens.SPEAKER_NAME],
    ["emotion", baseTokens.EMOTION],
    ["deliveryStyle", baseTokens.DELIVERY_STYLE],
    ["speechRate", baseTokens.SPEECH_RATE],
    ["voiceProfile", baseTokens.VOICE_PROFILE],
    ["characterVoiceProfiles", baseTokens.CHARACTER_VOICE_PROFILES],
    ["durationFrames", baseTokens.DURATION_FRAMES],
    ["durationSec", baseTokens.DURATION_SEC],
    ["characterRefs", baseTokens.CHARACTER_REFS],
    ["sceneRefPath", baseTokens.SCENE_REF_PATH],
    ["sceneRefName", baseTokens.SCENE_REF_NAME],
    ["characterRefPaths", baseTokens.CHARACTER_REF_PATHS],
    ["characterRefNames", baseTokens.CHARACTER_REF_NAMES],
    ["characterFrontPaths", baseTokens.CHARACTER_FRONT_PATHS],
    ["characterSidePaths", baseTokens.CHARACTER_SIDE_PATHS],
    ["characterBackPaths", baseTokens.CHARACTER_BACK_PATHS],
    ["character1Name", baseTokens.CHAR1_NAME],
    ["character1PrimaryPath", baseTokens.CHAR1_PRIMARY_PATH],
    ["character1FrontPath", baseTokens.CHAR1_FRONT_PATH],
    ["character1SidePath", baseTokens.CHAR1_SIDE_PATH],
    ["character1BackPath", baseTokens.CHAR1_BACK_PATH],
    ["character2Name", baseTokens.CHAR2_NAME],
    ["character2PrimaryPath", baseTokens.CHAR2_PRIMARY_PATH],
    ["character2FrontPath", baseTokens.CHAR2_FRONT_PATH],
    ["character2SidePath", baseTokens.CHAR2_SIDE_PATH],
    ["character2BackPath", baseTokens.CHAR2_BACK_PATH],
    ["character3Name", baseTokens.CHAR3_NAME],
    ["character3PrimaryPath", baseTokens.CHAR3_PRIMARY_PATH],
    ["character3FrontPath", baseTokens.CHAR3_FRONT_PATH],
    ["character3SidePath", baseTokens.CHAR3_SIDE_PATH],
    ["character3BackPath", baseTokens.CHAR3_BACK_PATH],
    ["character4Name", baseTokens.CHAR4_NAME],
    ["character4PrimaryPath", baseTokens.CHAR4_PRIMARY_PATH],
    ["character4FrontPath", baseTokens.CHAR4_FRONT_PATH],
    ["character4SidePath", baseTokens.CHAR4_SIDE_PATH],
    ["character4BackPath", baseTokens.CHAR4_BACK_PATH],
    ["frameImagePath", baseTokens.FRAME_IMAGE_PATH],
    ["firstFramePath", baseTokens.FIRST_FRAME_PATH],
    ["lastFramePath", baseTokens.LAST_FRAME_PATH],
    ["dialogueAudioPath", baseTokens.DIALOGUE_AUDIO_PATH],
    ["dialogueAudioPaths", baseTokens.DIALOGUE_AUDIO_PATHS],
    ["dialogueAudioCount", baseTokens.DIALOGUE_AUDIO_COUNT],
    ["hasDialogueAudio", baseTokens.HAS_DIALOGUE_AUDIO]
  ];
  for (const [key, value] of aliasPairs) {
    const alias = mapping[key]?.trim();
    if (!alias) continue;
    mappedTokens[alias] = value;
  }
  return mappedTokens;
}

export function inferComfyRootDir(settings: ComfySettings): string {
  const explicit = settings.comfyRootDir.trim().replace(/\/+$/, "");
  if (explicit) return explicit;
  const output = settings.outputDir.trim().replace(/\/+$/, "");
  if (output.endsWith("/output")) return output.slice(0, -"/output".length);
  const input = settings.comfyInputDir.trim().replace(/\/+$/, "");
  if (input.endsWith("/input")) return input.slice(0, -"/input".length);
  return "";
}

function ensureWorkflowJson(raw: string): Record<string, unknown> {
  let parsed: unknown;
  try {
    parsed = parseWorkflowJsonWithRecovery(raw);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`工作流 JSON 解析失败：${message}。请重新导入完整的 ComfyUI API 工作流 JSON 文件`);
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("工作流 JSON 必须是对象");
  }
  return parsed as Record<string, unknown>;
}

export function validateWorkflowJsonSyntax(workflowJson: string): void {
  void ensureWorkflowJson(workflowJson);
}

function collectTemplateTokens(value: unknown, bucket: Set<string>) {
  if (typeof value === "string") {
    const matches = value.matchAll(/\{\{([A-Z0-9_]+)\}\}/g);
    for (const match of matches) {
      const token = match[1]?.trim();
      if (token) bucket.add(token);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectTemplateTokens(item, bucket);
    return;
  }
  if (value && typeof value === "object") {
    for (const item of Object.values(value as Record<string, unknown>)) {
      collectTemplateTokens(item, bucket);
    }
  }
}

function configuredTokenOrFallback(value: string | undefined, fallback: string): string {
  const trimmed = value?.trim() ?? "";
  return trimmed || fallback;
}

function dialogueAudioPathTokens(mapping: ComfySettings["tokenMapping"]): string[] {
  return [
    configuredTokenOrFallback(mapping.dialogueAudioPath, "DIALOGUE_AUDIO_PATH"),
    configuredTokenOrFallback(mapping.dialogueAudioPaths, "DIALOGUE_AUDIO_PATHS")
  ];
}

function dialogueAudioAuxTokens(mapping: ComfySettings["tokenMapping"]): string[] {
  return [
    configuredTokenOrFallback(mapping.dialogueAudioCount, "DIALOGUE_AUDIO_COUNT"),
    configuredTokenOrFallback(mapping.hasDialogueAudio, "HAS_DIALOGUE_AUDIO")
  ];
}

function inspectWorkflowLipSyncSupportFromObject(
  workflow: Record<string, unknown>,
  mapping: ComfySettings["tokenMapping"]
): VideoWorkflowLipSyncSupport {
  const usedTokens = new Set<string>();
  collectTemplateTokens(workflow, usedTokens);
  const candidatePathTokens = dialogueAudioPathTokens(mapping);
  const candidateAuxTokens = dialogueAudioAuxTokens(mapping);
  const matchedPathTokens = candidatePathTokens.filter((token) => usedTokens.has(token));
  const matchedAuxTokens = candidateAuxTokens.filter((token) => usedTokens.has(token));
  return {
    usesTokenPlaceholders: usedTokens.size > 0,
    usesDialogueAudioPathToken: matchedPathTokens.length > 0,
    matchedPathTokens,
    matchedAuxTokens,
    candidatePathTokens,
    candidateAuxTokens
  };
}

function deepReplaceTokens(value: unknown, tokens: Record<string, string>): unknown {
  if (typeof value === "string") {
    let next = value;
    for (const [key, tokenValue] of Object.entries(tokens)) {
      next = next.split(`{{${key}}}`).join(tokenValue);
    }
    return next;
  }
  if (Array.isArray(value)) {
    return value.map((item) => deepReplaceTokens(item, tokens));
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>).map(([key, item]) => [
      key,
      deepReplaceTokens(item, tokens)
    ]);
    return Object.fromEntries(entries);
  }
  return value;
}

function rewriteWorkflowFilenamePrefixes(
  value: unknown,
  rewrite: (prefix: string) => string
): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => rewriteWorkflowFilenamePrefixes(item, rewrite));
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>).map(([key, item]) => {
      if (key === "filename_prefix" && typeof item === "string") {
        return [key, rewrite(item)] as const;
      }
      return [key, rewriteWorkflowFilenamePrefixes(item, rewrite)] as const;
    });
    return Object.fromEntries(entries);
  }
  return value;
}

function rewriteCharacterAssetFilenamePrefix(prefix: string): string {
  const trimmed = prefix.trim();
  if (!trimmed) return prefix;
  if (trimmed.startsWith(".storyboard-cache/人物/")) return trimmed;
  if (trimmed.startsWith("人物/")) {
    return trimmed.replace(/^人物\//, ".storyboard-cache/人物/");
  }
  if (/character_anchor_cleanup/i.test(trimmed)) {
    return `${CHARACTER_ASSET_OUTPUT_PREFIX_TEMPLATE}/character_anchor_cleanup_{{SHOT_ID}}`;
  }
  if (/character_anchor|character_threeview/i.test(trimmed)) {
    return `${CHARACTER_ASSET_OUTPUT_PREFIX_TEMPLATE}/character_anchor_{{SHOT_ID}}`;
  }
  if (/character_orthoview|character_mv/i.test(trimmed)) {
    return `${CHARACTER_ASSET_OUTPUT_PREFIX_TEMPLATE}/character_orthoview_{{SHOT_ID}}`;
  }
  return prefix;
}

function rewriteSkyboxFilenamePrefix(prefix: string): string {
  const trimmed = prefix.trim();
  if (!trimmed) return prefix;
  if (trimmed.startsWith("场景/")) return trimmed;
  if (/skybox_panorama/i.test(trimmed)) {
    return `${SCENE_ASSET_OUTPUT_PREFIX_TEMPLATE}/skybox_panorama`;
  }
  const face = trimmed.match(/skybox_(front|right|back|left|up|down)/i)?.[1]?.toLowerCase();
  if (face) {
    return `${SCENE_ASSET_OUTPUT_PREFIX_TEMPLATE}/skybox_${face}`;
  }
  if (/skybox/i.test(trimmed)) {
    return `${SCENE_ASSET_OUTPUT_PREFIX_TEMPLATE}/skybox_{{SHOT_ID}}`;
  }
  return prefix;
}

function isComfyNodeReferenceTuple(value: unknown): value is [string, unknown] {
  if (!Array.isArray(value) || value.length !== 2) return false;
  const [nodeId, outputIndex] = value;
  if (typeof nodeId !== "string" || !/^\d+$/.test(nodeId.trim())) return false;
  if (typeof outputIndex === "number") return Number.isFinite(outputIndex);
  return typeof outputIndex === "string" && /^-?\d+$/.test(outputIndex.trim());
}

function coerceWorkflowLiteralValues(value: unknown): unknown {
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed === "true") return true;
    if (trimmed === "false") return false;
    if (/^-?\d+$/.test(trimmed)) {
      const parsed = Number.parseInt(trimmed, 10);
      if (Number.isFinite(parsed)) return parsed;
    }
    if (/^-?(?:\d+\.\d+|\d+e[+-]?\d+|\d+\.\d+e[+-]?\d+)$/i.test(trimmed)) {
      const parsed = Number.parseFloat(trimmed);
      if (Number.isFinite(parsed)) return parsed;
    }
    return value;
  }
  if (Array.isArray(value)) {
    // Preserve Comfy node-link tuples like ["6", 0].
    // If the first item is coerced to number, Comfy prompt validation may fail with KeyError
    // because node IDs in prompt objects are string keys.
    if (
      value.length === 2 &&
      typeof value[0] === "string" &&
      /^\d+$/.test(value[0].trim()) &&
      (typeof value[1] === "number" || (typeof value[1] === "string" && /^-?\d+$/.test(value[1].trim())))
    ) {
      const slot = coerceWorkflowLiteralValues(value[1]);
      return [value[0], slot];
    }
    if (isComfyNodeReferenceTuple(value)) {
      return [value[0], coerceWorkflowLiteralValues(value[1])];
    }
    return value.map((item) => coerceWorkflowLiteralValues(item));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, coerceWorkflowLiteralValues(item)])
    );
  }
  return value;
}

function normalizeLineBreaks(value: string): string {
  return value.replace(/\r\n?/g, "\n");
}

function normalizePromptBody(value: string): string {
  return normalizeLineBreaks(value)
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .join("\n");
}

function appendPromptSection(base: string, sectionTitle: string, sectionBody: string): string {
  const content = normalizePromptBody(base);
  const addition = normalizePromptBody(sectionBody);
  if (!addition) return content;
  return [content, `${sectionTitle}：${addition}`].filter((item) => item.length > 0).join("\n");
}

function appendNegativePrompt(base: string, extra: string): string {
  const primary = normalizePromptBody(base);
  const addition = normalizePromptBody(extra).replace(/\n/g, ", ");
  if (!addition) return primary;
  if (!primary) return addition;
  return `${primary}, ${addition}`;
}

function stableNumericId(value: string): number {
  let hash = 2166136261 >>> 0;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619) >>> 0;
  }
  return Math.max(1, hash % 1_000_000_000);
}

function sanitizeStoryboardNegativePrompt(base: string, hasCharacters: boolean): string {
  const normalized = normalizePromptBody(base);
  if (!normalized || !hasCharacters) return normalized;
  const blocked = [
    /empty\s*scene/i,
    /scenery\s*only/i,
    /landscape\s*only/i,
    /character\s*missing/i,
    /\bno\s+people\b/i,
    /\bno\s+person\b/i,
    /\bno\s+human\b/i,
    /\bwithout\s+people\b/i,
    /\bwithout\s+person\b/i,
    /空镜/,
    /无人/,
    /无人物/,
    /无角色/,
    /纯场景/,
    /仅场景/,
    /只有场景/
  ];
  const parts = normalized
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
  const filtered = parts.filter((item) => !blocked.some((pattern) => pattern.test(item)));
  return filtered.join(", ");
}

function sanitizeCharacterDrivenNegativePrompt(base: string, hasCharacters: boolean): string {
  if (!hasCharacters) return normalizePromptBody(base);
  return sanitizeStoryboardNegativePrompt(base, true);
}

function toNextScenePrompt(value: string): string {
  const compact = normalizePromptBody(value);
  if (!compact) return "Next Scene: empty shot";
  const segments = compact
    .split(/\bNext\s*Scene\b[:：]?\s*/gi)
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
  const shotText = segments[0] ?? compact;
  return `Next Scene: ${shotText}`;
}

function containsAnyKeyword(raw: string, keywords: string[]): boolean {
  const text = raw.toLowerCase();
  return keywords.some((item) => text.includes(item));
}

const LOCAL_MOTION_TOKEN_PATTERN = /\[motion:(auto|still|fade|push_in|push_out|pan_left|pan_right)\]/i;
const FIRST_LAST_ENDPOINT_PATTERNS = [
  /从.+到/,
  /由.+到/,
  /先.+后/,
  /逐渐/,
  /慢慢/,
  /最终/,
  /直到/,
  /一步步/,
  /镜头.+来到/,
  /画面.+转到/
];
const FIRST_LAST_ACTION_KEYWORDS = [
  "走向",
  "走到",
  "走进",
  "走出",
  "跑向",
  "跑到",
  "进入",
  "离开",
  "穿过",
  "经过",
  "越过",
  "跨过",
  "靠近",
  "远离",
  "起身",
  "站起",
  "坐下",
  "跪下",
  "转身",
  "回头",
  "俯身",
  "抬头",
  "低头",
  "伸手",
  "抬手",
  "落手",
  "拿起",
  "放下",
  "放回",
  "推门",
  "开门",
  "关门",
  "拉开",
  "推开",
  "登上",
  "下楼",
  "上楼",
  "绕过",
  "穿越",
  "reveals",
  "reveal",
  "blocking"
];
const SINGLE_FRAME_DIALOGUE_KEYWORDS = [
  "对白",
  "说话",
  "开口",
  "台词",
  "反应",
  "注视",
  "凝视",
  "沉默",
  "停顿",
  "愣住",
  "特写",
  "近景",
  "中近景",
  "肖像",
  "半身"
];
const SINGLE_FRAME_AMBIENCE_KEYWORDS = [
  "轻微",
  "微微",
  "呼吸感",
  "镜头稳定",
  "镜头固定",
  "静止",
  "静帧",
  "风吹",
  "水波",
  "烟雾",
  "火焰",
  "树叶",
  "衣摆轻晃",
  "环境氛围",
  "空镜",
  "插入镜头",
  "道具特写",
  "产品特写"
];

export function extractLocalMotionPresetFromText(raw: string): LocalMotionPreset {
  const matched = LOCAL_MOTION_TOKEN_PATTERN.exec(raw.trim());
  const value = matched?.[1]?.toLowerCase() ?? "";
  if (
    value === "still" ||
    value === "fade" ||
    value === "push_in" ||
    value === "push_out" ||
    value === "pan_left" ||
    value === "pan_right"
  ) {
    return value;
  }
  return "auto";
}

export function stripLocalMotionPresetToken(raw: string): string {
  return raw.replace(LOCAL_MOTION_TOKEN_PATTERN, "").replace(/\n{3,}/g, "\n\n").trim();
}

export function inferStoryboardVideoModeByMatureCase(
  text: string,
  dialogue = "",
  options?: { preferAutoWhenAmbiguous?: boolean }
): StoryboardVideoModeChoice {
  const corpus = `${text} ${dialogue}`.trim();
  if (!corpus) return options?.preferAutoWhenAmbiguous ? "auto" : "single_frame";

  if (FIRST_LAST_ENDPOINT_PATTERNS.some((pattern) => pattern.test(corpus))) {
    return "first_last_frame";
  }
  if (containsAnyKeyword(corpus, FIRST_LAST_ACTION_KEYWORDS)) {
    return "first_last_frame";
  }

  if (dialogue.trim()) return "single_frame";
  if (containsAnyKeyword(corpus, SINGLE_FRAME_DIALOGUE_KEYWORDS)) {
    return "single_frame";
  }
  if (containsAnyKeyword(corpus, SINGLE_FRAME_AMBIENCE_KEYWORDS)) {
    return "single_frame";
  }

  return options?.preferAutoWhenAmbiguous ? "auto" : "single_frame";
}

export function explainStoryboardVideoModeByMatureCase(
  text: string,
  dialogue = "",
  options?: { preferAutoWhenAmbiguous?: boolean }
): { mode: StoryboardVideoModeChoice; reason: string } {
  const corpus = `${text} ${dialogue}`.trim();
  if (!corpus) {
    return {
      mode: options?.preferAutoWhenAmbiguous ? "auto" : "single_frame",
      reason: options?.preferAutoWhenAmbiguous
        ? "文案信息不足，保留自动判断。"
        : "文案信息不足，默认按稳定单帧镜头处理。"
    };
  }

  const matchedEndpoint = FIRST_LAST_ENDPOINT_PATTERNS.find((pattern) => pattern.test(corpus));
  if (matchedEndpoint) {
    return {
      mode: "first_last_frame",
      reason: "检测到明确的起点到终点变化，这类镜头更适合首尾帧控制。"
    };
  }

  const matchedFirstLastKeyword = FIRST_LAST_ACTION_KEYWORDS.find((keyword) => containsAnyKeyword(corpus, [keyword]));
  if (matchedFirstLastKeyword) {
    return {
      mode: "first_last_frame",
      reason: `检测到动作或位移关键词“${matchedFirstLastKeyword}”，更像有明确终点状态的镜头，适合首尾帧。`
    };
  }

  if (dialogue.trim()) {
    return {
      mode: "single_frame",
      reason: "检测到对白镜头，成熟做法通常优先稳定人物和构图，用单帧图生视频更稳。"
    };
  }

  const matchedDialogueKeyword = SINGLE_FRAME_DIALOGUE_KEYWORDS.find((keyword) => containsAnyKeyword(corpus, [keyword]));
  if (matchedDialogueKeyword) {
    return {
      mode: "single_frame",
      reason: `检测到“${matchedDialogueKeyword}”这类反应/特写镜头，通常以稳定表演为主，适合单帧图生视频。`
    };
  }

  const matchedAmbienceKeyword = SINGLE_FRAME_AMBIENCE_KEYWORDS.find((keyword) => containsAnyKeyword(corpus, [keyword]));
  if (matchedAmbienceKeyword) {
    return {
      mode: "single_frame",
      reason: `检测到“${matchedAmbienceKeyword}”这类轻动作或氛围镜头，通常不需要显式终点，适合单帧图生视频。`
    };
  }

  return {
    mode: options?.preferAutoWhenAmbiguous ? "auto" : "single_frame",
    reason: options?.preferAutoWhenAmbiguous
      ? "没有命中明确规则，先保留自动判断。"
      : "没有命中明确规则，默认按稳定单帧镜头处理。"
  };
}

type VisualStyleSettings = Pick<ComfySettings, "globalVisualStylePrompt" | "globalStyleNegativePrompt">;

function resolveVisualStyleSettings(settings?: Partial<VisualStyleSettings>) {
  const positivePrompt = settings
    ? String(settings.globalVisualStylePrompt ?? "").trim()
    : CINEMATIC_3D_DONGHUA_CONTRACT.positivePrompt;
  const negativePrompt = settings
    ? String(settings.globalStyleNegativePrompt ?? "").trim()
    : CINEMATIC_3D_DONGHUA_CONTRACT.negativePrompt;
  return {
    positivePrompt,
    negativePrompt,
    canonical:
      positivePrompt === CINEMATIC_3D_DONGHUA_CONTRACT.positivePrompt &&
      negativePrompt === CINEMATIC_3D_DONGHUA_CONTRACT.negativePrompt
  };
}

function applyUnversionedVisualStyleToTokens(
  tokens: Record<string, string>,
  kind: "image" | "video",
  positivePrompt: string,
  negativePrompt: string
): Record<string, string> {
  const next = { ...tokens };
  delete next.STYLE_CONTRACT_ID;
  delete next.STYLE_CONTRACT_VERSION;
  delete next.STYLE_CONTRACT_DIGEST;
  if (positivePrompt) {
    if (kind === "image") {
      next.PROMPT = appendPromptSection(next.PROMPT ?? "", "Unversioned operator style", positivePrompt);
      next.NEXT_SCENE_PROMPT = appendPromptSection(
        next.NEXT_SCENE_PROMPT ?? "",
        "Unversioned operator style",
        positivePrompt
      );
    } else {
      next.VIDEO_PROMPT = appendPromptSection(next.VIDEO_PROMPT ?? "", "Unversioned operator style", positivePrompt);
    }
    next.GLOBAL_VISUAL_STYLE = positivePrompt;
  }
  if (negativePrompt) {
    next.NEGATIVE_PROMPT = appendNegativePrompt(next.NEGATIVE_PROMPT ?? "", negativePrompt);
    next.GLOBAL_STYLE_NEGATIVE = negativePrompt;
  }
  return next;
}

function applyGlobalStyleToTokens(
  settings: ComfySettings,
  tokens: Record<string, string>,
  kind: "image" | "video" | "audio",
  _scope: "storyboard" | "character_asset" | "scene_asset" = "storyboard"
): Record<string, string> {
  if (kind === "audio") return tokens;
  const style = resolveVisualStyleSettings(settings);
  if (!style.canonical) {
    return applyUnversionedVisualStyleToTokens(tokens, kind, style.positivePrompt, style.negativePrompt);
  }
  return applyCharacterStyleContractToTokens({
    tokens,
    kind,
    contract: CINEMATIC_3D_DONGHUA_CONTRACT
  }) as Record<string, string>;
}

type CharacterStyleRequestCharacter = {
  name: string;
  species: CharacterSpeciesId;
  speciesTraits: string[];
};

function resolveCharacterStyleRequestCharacters(
  shot: Shot,
  assets: Asset[],
  assetOutputContext: AssetOutputContext | null
): CharacterStyleRequestCharacter[] {
  let matchedAssets: Asset[];
  if (assetOutputContext?.kind === "character") {
    matchedAssets = assets.filter(
      (asset) =>
        asset.type === "character" &&
        sanitizeOutputAssetFolderName(asset.name, "character") === assetOutputContext.assetName
    );
    if (matchedAssets.length === 0) {
      throw new Error(
        `character_asset_identity_missing_persisted asset=${assetOutputContext.assetName} action=save_character_identity_before_generation`
      );
    }
    if (matchedAssets.length > 1) {
      throw new Error(
        `character_asset_identity_ambiguous_persisted asset=${assetOutputContext.assetName} count=${matchedAssets.length} action=deduplicate_character_assets`
      );
    }
  } else {
    matchedAssets = [];
    for (const rawRefId of shot.characterRefs ?? []) {
      const refId = String(rawRefId ?? "").trim();
      if (!refId) continue;
      const matches = assets.filter((asset) => asset.type === "character" && asset.id === refId);
      if (matches.length !== 1) {
        throw new Error(`character_reference_validation_failed id=${refId} count=${matches.length}`);
      }
      if (!matchedAssets.some((asset) => asset.id === matches[0]!.id)) matchedAssets.push(matches[0]!);
    }
  }

  return matchedAssets.map((asset) => {
    const resolution = resolveCharacterSpecies({
      identitySpecies: asset.characterIdentityPack?.species,
      explicitLabels: shot.tags ?? []
    });
    if (!resolution.ok) throw new Error(resolution.reason);
    return {
      name: asset.name.trim(),
      species: resolution.species,
      speciesTraits: asset.characterIdentityPack?.speciesTraits ?? []
    };
  });
}

export function applyCharacterStyleContractForRequest(input: {
  tokens: Record<string, string>;
  kind: "image" | "video" | "audio";
  shot: Shot;
  assets?: Asset[];
  settings?: Partial<VisualStyleSettings>;
}): Record<string, string> {
  if (input.kind === "audio") return { ...input.tokens };
  const characters = resolveCharacterStyleRequestCharacters(
    input.shot,
    input.assets ?? [],
    inferAssetOutputContextFromShot(input.shot)
  );
  const humanClauses = characters
    .filter((character) => character.species === "human")
    .map((character) => `${character.name}, human ears only`)
    .join(", ");
  const nonHumanCharacters = characters.filter((character) => character.species !== "human");
  const tokens = humanClauses
    ? {
        ...input.tokens,
        PROMPT:
          input.kind === "image"
            ? appendPromptSection(input.tokens.PROMPT ?? "", "Character species", humanClauses)
            : input.tokens.PROMPT,
        NEXT_SCENE_PROMPT:
          input.kind === "image"
            ? appendPromptSection(input.tokens.NEXT_SCENE_PROMPT ?? "", "Character species", humanClauses)
            : input.tokens.NEXT_SCENE_PROMPT,
        VIDEO_PROMPT:
          input.kind === "video"
            ? appendPromptSection(input.tokens.VIDEO_PROMPT ?? "", "Character species", humanClauses)
            : input.tokens.VIDEO_PROMPT
      }
    : input.tokens;
  const style = resolveVisualStyleSettings(input.settings);
  let styled: Record<string, string | undefined>;
  if (style.canonical) {
    styled = applyCharacterStyleContractToTokens({
      tokens,
      kind: input.kind,
      characters: nonHumanCharacters,
      contract: CINEMATIC_3D_DONGHUA_CONTRACT
    });
  } else {
    styled = applyUnversionedVisualStyleToTokens(tokens, input.kind, style.positivePrompt, style.negativePrompt);
    const nonHumanClauses = nonHumanCharacters
      .map((character) => {
        const anatomy = buildCharacterSpeciesClauses({
          ok: true,
          species: character.species,
          source: "identity"
        }).positive;
        return [character.name, anatomy, ...character.speciesTraits].filter(Boolean).join(", ");
      })
      .filter(Boolean)
      .join(", ");
    if (nonHumanClauses) {
      if (input.kind === "image") {
        styled.PROMPT = appendPromptSection(styled.PROMPT ?? "", "Character species", nonHumanClauses);
        styled.NEXT_SCENE_PROMPT = appendPromptSection(
          styled.NEXT_SCENE_PROMPT ?? "",
          "Character species",
          nonHumanClauses
        );
      } else {
        styled.VIDEO_PROMPT = appendPromptSection(styled.VIDEO_PROMPT ?? "", "Character species", nonHumanClauses);
      }
    }
  }
  if (humanClauses && nonHumanCharacters.length === 0) {
    const humanExclusions = characters
      .filter((character) => character.species === "human")
      .map(
        (character) =>
          `${character.name}: human ears only, no animal ears, no tail, no horns, no animal muzzle`
      )
      .join(", ");
    styled.NEGATIVE_PROMPT = appendNegativePrompt(styled.NEGATIVE_PROMPT ?? "", humanExclusions);
  }
  return Object.fromEntries(
    Object.entries(styled).map(([key, value]) => [key, typeof value === "string" ? value : ""])
  );
}

function parseComfyViewPath(path: string): string {
  const trimmed = path.trim();
  if (!trimmed) return "";
  if (!trimmed.includes("/view?")) return trimmed;
  try {
    const url = new URL(trimmed);
    const filename = url.searchParams.get("filename")?.trim() ?? "";
    const subfolder = url.searchParams.get("subfolder")?.trim() ?? "";
    if (!filename) return trimmed;
    const cleanSubfolder = subfolder.replace(/^\/+|\/+$/g, "");
    return cleanSubfolder ? `${cleanSubfolder}/${filename}` : filename;
  } catch {
    return trimmed;
  }
}

function toComfyViewDownloadUrl(source: string, fallbackBaseUrl: string): string {
  const trimmed = source.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) return trimmed;
  const filename = parseComfyViewPath(trimmed);
  if (!filename) return "";
  const params = new URLSearchParams();
  params.set("filename", filename.split("/").pop() ?? filename);
  if (filename.includes("/")) {
    params.set("subfolder", filename.slice(0, filename.lastIndexOf("/")));
  } else {
    params.set("subfolder", "");
  }
  params.set("type", "output");
  return `${normalizeBaseUrl(fallbackBaseUrl)}/view?${params.toString()}`;
}

function fileExtensionFromSource(source: string): string {
  const clean = source.split("?")[0].trim();
  const idx = clean.lastIndexOf(".");
  if (idx < 0) return "png";
  const ext = clean.slice(idx + 1).toLowerCase();
  if (!/^[a-z0-9]{1,6}$/.test(ext)) return "png";
  return ext;
}

function isAbsoluteLocalPath(path: string): boolean {
  if (path.startsWith("/")) return true;
  if (path.startsWith("~/")) return true;
  return /^[a-zA-Z]:[\\/]/.test(path);
}

function isWindowsStyleAbsolutePath(path: string): boolean {
  return /^[a-zA-Z]:[\\/]/.test(path.trim());
}

function runtimeUsesWindowsPaths(): boolean {
  if (typeof navigator === "undefined") return false;
  const fingerprint = `${navigator.userAgent ?? ""} ${navigator.platform ?? ""}`.toLowerCase();
  return fingerprint.includes("win");
}

function canUseAbsoluteLocalPath(path: string): boolean {
  const trimmed = path.trim();
  if (!trimmed || !isAbsoluteLocalPath(trimmed)) return false;
  if (isWindowsStyleAbsolutePath(trimmed)) return runtimeUsesWindowsPaths();
  return !runtimeUsesWindowsPaths();
}

function normalizeComparablePath(path: string): string {
  return path.trim().replace(/\\/g, "/").replace(/\/+/g, "/").replace(/\/+$/, "");
}

function inferComfyOutputDownloadSource(source: string, outputDir = ""): string {
  const normalized = parseComfyViewPath(source).trim();
  if (!normalized) return "";
  if (!isAbsoluteLocalPath(normalized)) return normalized;

  const normalizedSource = normalizeComparablePath(normalized);
  const normalizedOutput = normalizeComparablePath(outputDir);
  if (normalizedOutput) {
    const sourceLower = normalizedSource.toLowerCase();
    const outputLower = normalizedOutput.toLowerCase();
    const prefix = `${outputLower}/`;
    if (sourceLower.startsWith(prefix)) {
      return normalizedSource.slice(normalizedOutput.length + 1);
    }
  }

  return normalizedSource.split("/").pop() ?? "";
}

async function stageSourceFileToComfyInput(
  source: string,
  targetPath: string,
  baseUrl: string,
  outputDir = ""
): Promise<string> {
  const trimmed = source.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://") || trimmed.includes("/view?")) {
    const url = toComfyViewDownloadUrl(trimmed, baseUrl);
    const base64 = await createComfyClient(baseUrl).fetchViewBase64(url);
    const result = await createComfyClient(baseUrl).writeBase64File(targetPath, base64);
    return result.filePath;
  }
  let downloadError: unknown = null;
  const downloadSource = inferComfyOutputDownloadSource(trimmed, outputDir);
  // For values like "Batch_00003_.png" or remote absolute output paths, fetch via /view first.
  if (downloadSource && !canUseAbsoluteLocalPath(trimmed)) {
    const viewUrl = toComfyViewDownloadUrl(downloadSource, baseUrl);
    if (viewUrl) {
      try {
        const base64 = await createComfyClient(baseUrl).fetchViewBase64(viewUrl);
        const result = await createComfyClient(baseUrl).writeBase64File(targetPath, base64);
        return result.filePath;
      } catch (error) {
        downloadError = error;
      }
    }
  }
  try {
    const copied = await createComfyClient(baseUrl).copyFile(trimmed, targetPath);
    return copied.filePath;
  } catch (copyError) {
    if (downloadError) {
      throw new Error(`准备输入文件失败：下载 Comfy 输出失败(${String(downloadError)})，本地复制也失败(${String(copyError)})`);
    }
    throw copyError;
  }
}

async function stageVideoFrameTokens(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>
): Promise<Record<string, string>> {
  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) return tokens;

  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const firstSource = tokens.FIRST_FRAME_PATH || tokens.FRAME_IMAGE_PATH;
  const lastSource = tokens.LAST_FRAME_PATH || firstSource;
  const frameSource = tokens.FRAME_IMAGE_PATH || firstSource;
  if (!firstSource && !lastSource && !frameSource) {
    throw new Error(`镜头 ${shot.title} 缺少可用分镜图，无法自动喂给 ComfyUI 视频工作流`);
  }
  const firstExt = fileExtensionFromSource(firstSource || frameSource || "png");
  const lastExt = fileExtensionFromSource(lastSource || frameSource || "png");
  const frameExt = fileExtensionFromSource(frameSource || firstSource || "png");

  const firstTargetAbs = `${inputDir}/shot_${safeShotId}_first.${firstExt}`;
  const lastTargetAbs = `${inputDir}/shot_${safeShotId}_last.${lastExt}`;
  const frameTargetAbs = `${inputDir}/shot_${safeShotId}_frame.${frameExt}`;

  const [firstWritten, lastWritten, frameWritten] = await Promise.all([
    stageSourceFileToComfyInput(firstSource, firstTargetAbs, settings.baseUrl, settings.outputDir),
    stageSourceFileToComfyInput(lastSource, lastTargetAbs, settings.baseUrl, settings.outputDir),
    stageSourceFileToComfyInput(frameSource, frameTargetAbs, settings.baseUrl, settings.outputDir)
  ]);

  const firstName = firstWritten.split("/").pop() ?? `shot_${safeShotId}_first.${firstExt}`;
  const lastName = lastWritten.split("/").pop() ?? `shot_${safeShotId}_last.${lastExt}`;
  const frameName = frameWritten.split("/").pop() ?? `shot_${safeShotId}_frame.${frameExt}`;

  return {
    ...tokens,
    FIRST_FRAME_PATH: firstName,
    LAST_FRAME_PATH: lastName,
    FRAME_IMAGE_PATH: frameName
  };
}

function workflowConsumesVideoFrameTokens(workflow: Record<string, unknown>): boolean {
  const serialized = JSON.stringify(workflow);
  return ["{{FRAME_IMAGE_PATH}}", "{{FIRST_FRAME_PATH}}", "{{LAST_FRAME_PATH}}"].some((token) =>
    serialized.includes(token)
  );
}

async function stageImageFrameToken(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>
): Promise<Record<string, string>> {
  const source = (tokens.FRAME_IMAGE_PATH || "").trim();
  if (!source) return tokens;

  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) {
    throw new Error("图片工作流需要参考图输入，但未检测到 ComfyUI input 目录");
  }

  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const ext = fileExtensionFromSource(source || "png");
  const preserveExplicitFrameSeed = String(tokens.STORYBOARD_PRESERVE_FRAME_IMAGE_PATH ?? "").trim() === "1";
  const explicitFrameSeedName = preserveExplicitFrameSeed
    ? (parseComfyViewPath(source).split(/[\\/]/).pop()?.trim() ?? "")
    : "";
  const stagedFrameName = explicitFrameSeedName || `shot_${safeShotId}_frame.${ext}`;
  const targetAbs = `${inputDir}/${stagedFrameName}`;
  const sourceAbs = resolveInputTokenSourcePath(settings, source);
  const normalizePathForCompare = (value: string): string => value.trim().replace(/\\/g, "/").toLowerCase();
  if (normalizePathForCompare(sourceAbs) === normalizePathForCompare(targetAbs)) {
    return {
      ...tokens,
      FRAME_IMAGE_PATH: stagedFrameName
    };
  }
  let written = "";
  try {
    written = await stageSourceFileToComfyInput(source, targetAbs, settings.baseUrl, settings.outputDir);
  } catch (error) {
    console.warn(`[storyboard] skipping unavailable frame seed: ${String(error)}`);
    return { ...tokens, FRAME_IMAGE_PATH: "" };
  }
  return {
    ...tokens,
    FRAME_IMAGE_PATH: written.split("/").pop() ?? written.split("\\").pop() ?? written
  };
}

const IMAGE_REFERENCE_TOKEN_KEYS = [
  "SCENE_REF_PATH",
  "SCENE_FOREGROUND_MASK_PATH",
  "PREV_SCENE_IMAGE_PATH",
  "PREV_CHARACTER_IMAGE_PATH",
  "CHAR1_FRONT_PATH",
  "CHAR1_SIDE_PATH",
  "CHAR1_BACK_PATH",
  "CHAR1_FACE_REF_PATH",
  "CHAR1_DETAIL_REF_PATH",
  "CHAR2_FRONT_PATH",
  "CHAR2_SIDE_PATH",
  "CHAR2_BACK_PATH",
  "CHAR2_FACE_REF_PATH",
  "CHAR2_DETAIL_REF_PATH",
  "CHAR3_FRONT_PATH",
  "CHAR3_SIDE_PATH",
  "CHAR3_BACK_PATH",
  "CHAR3_FACE_REF_PATH",
  "CHAR3_DETAIL_REF_PATH",
  "CHAR4_FRONT_PATH",
  "CHAR4_SIDE_PATH",
  "CHAR4_BACK_PATH",
  "CHAR4_FACE_REF_PATH",
  "CHAR4_DETAIL_REF_PATH",
  "CHAR1_PRIMARY_PATH",
  "CHAR1_SECONDARY_PATH",
  "CHAR2_PRIMARY_PATH",
  "CHAR2_SECONDARY_PATH"
] as const;

const STAGE_LOCKED_IMAGE_REFERENCE_TOKEN_KEYS = new Set<(typeof IMAGE_REFERENCE_TOKEN_KEYS)[number]>([
  "SCENE_REF_PATH",
  "SCENE_FOREGROUND_MASK_PATH",
  "PREV_SCENE_IMAGE_PATH",
  "CHAR1_FRONT_PATH",
  "CHAR1_SIDE_PATH",
  "CHAR1_BACK_PATH",
  "CHAR1_FACE_REF_PATH",
  "CHAR1_DETAIL_REF_PATH",
  "CHAR1_PRIMARY_PATH",
  "CHAR1_SECONDARY_PATH"
]);

async function stageImageReferenceTokens(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>
): Promise<Record<string, string>> {
  const stagedEntries = IMAGE_REFERENCE_TOKEN_KEYS
    .map((key) => ({ key, source: tokens[key]?.trim() ?? "" }))
    .filter((item) => item.source.length > 0);
  if (stagedEntries.length === 0) return tokens;

  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) {
    throw new Error("图片工作流需要角色/场景参考图输入，但未检测到 ComfyUI input 目录");
  }

  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const nextTokens = { ...tokens };
  const lockStageInputs = String(tokens.STORYBOARD_QWEN_STAGE_LOCK_INPUTS ?? "").trim() === "1";
  const normalizePathForCompare = (value: string): string => value.trim().replace(/\\/g, "/").toLowerCase();
  for (const entry of stagedEntries) {
    const ext = "png";
    const targetAbs = `${inputDir}/shot_${safeShotId}_${entry.key.toLowerCase()}.${ext}`;
    const sourceAbs = resolveInputTokenSourcePath(settings, entry.source);
    const stagedName = targetAbs.split("/").pop() ?? targetAbs;
    if (normalizePathForCompare(sourceAbs) === normalizePathForCompare(targetAbs)) {
      nextTokens[entry.key] = stagedName;
      continue;
    }
    if (lockStageInputs && STAGE_LOCKED_IMAGE_REFERENCE_TOKEN_KEYS.has(entry.key)) {
      nextTokens[entry.key] = stagedName;
      continue;
    }
    const mode = entry.key === "SCENE_REF_PATH" || entry.key === "PREV_SCENE_IMAGE_PATH" ? "scene" : "character";
    try {
      const written = await stagePreparedReferenceImage(settings, entry.source, targetAbs, mode);
      nextTokens[entry.key] = written.split("/").pop() ?? written;
    } catch (error) {
      // Projects can retain asset paths from a removed Comfy installation. A stale
      // optional reference must not prevent text-only storyboard generation.
      console.warn(`[storyboard] skipping unavailable ${entry.key} reference: ${String(error)}`);
      nextTokens[entry.key] = "";
    }
  }
  return nextTokens;
}

async function mixDialogueAudioTracks(
  fps: number,
  tracks: AudioTrack[]
): Promise<string> {
  const orderedTracks = [...tracks]
    .filter((track) => track.filePath.trim().length > 0)
    .sort((left, right) => left.startFrame - right.startFrame || left.id.localeCompare(right.id));
  if (orderedTracks.length === 0) return "";
  if (orderedTracks.length === 1) return orderedTracks[0]!.filePath.trim();
  const result = await invokeDesktop<AudioMixResult>("mix_audio_tracks", {
    fps: Math.max(1, Math.round(fps || 24)),
    audioTracks: orderedTracks
  });
  return result.outputPath.trim();
}

async function stageDialogueAudioTokens(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>,
  dialogueAudioTracks: AudioTrack[],
  fps: number
): Promise<Record<string, string>> {
  const validTracks = [...dialogueAudioTracks]
    .filter((track) => track.filePath.trim().length > 0)
    .sort((left, right) => left.startFrame - right.startFrame || left.id.localeCompare(right.id));
  if (validTracks.length === 0) {
    return {
      ...tokens,
      DIALOGUE_AUDIO_PATH: "",
      DIALOGUE_AUDIO_PATHS: "",
      DIALOGUE_AUDIO_COUNT: "0",
      HAS_DIALOGUE_AUDIO: "0"
    };
  }

  const mixedSourcePath = await mixDialogueAudioTracks(fps, validTracks);
  const segmentSourcePaths = validTracks.map((track) => track.filePath.trim()).filter((value) => value.length > 0);
  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) {
    return {
      ...tokens,
      DIALOGUE_AUDIO_PATH: mixedSourcePath,
      DIALOGUE_AUDIO_PATHS: segmentSourcePaths.join(","),
      DIALOGUE_AUDIO_COUNT: String(segmentSourcePaths.length),
      HAS_DIALOGUE_AUDIO: "1"
    };
  }

  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const mixedExt = fileExtensionFromSource(mixedSourcePath || "wav");
  const mixedTargetAbs = `${inputDir}/shot_${safeShotId}_dialogue.${mixedExt}`;
  const mixedWritten = await stageSourceFileToComfyInput(
    mixedSourcePath,
    mixedTargetAbs,
    settings.baseUrl,
    settings.outputDir
  );

  const stagedSegments = await Promise.all(
    segmentSourcePaths.map(async (source, index) => {
      const ext = fileExtensionFromSource(source || "wav");
      const targetAbs = `${inputDir}/shot_${safeShotId}_dialogue_${index + 1}.${ext}`;
      const written = await stageSourceFileToComfyInput(source, targetAbs, settings.baseUrl, settings.outputDir);
      return written.split("/").pop() ?? written;
    })
  );

  return {
    ...tokens,
    DIALOGUE_AUDIO_PATH: mixedWritten.split("/").pop() ?? mixedWritten,
    DIALOGUE_AUDIO_PATHS: stagedSegments.join(","),
    DIALOGUE_AUDIO_COUNT: String(stagedSegments.length),
    HAS_DIALOGUE_AUDIO: "1"
  };
}

function inferVideoMode(shot: Shot, nextShot?: Shot): VideoMode {
  if (shot.videoMode === "single_frame") return "single_frame";
  if (shot.videoMode === "first_last_frame") return "first_last_frame";
  if (shot.videoStartFramePath?.trim() && shot.videoEndFramePath?.trim()) {
    return "first_last_frame";
  }
  const corpus = [
    shot.storyPrompt ?? "",
    shot.videoPrompt ?? "",
    shot.dialogue ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ].join(" ");
  if (containsAnyKeyword(corpus, ["首尾帧", "首尾", "first_last", "first last", "起始帧", "结束帧"])) {
    return "first_last_frame";
  }
  if (containsAnyKeyword(corpus, ["单帧", "single frame", "图生视频"])) {
    return "single_frame";
  }
  const inferred = inferStoryboardVideoModeByMatureCase(corpus, shot.dialogue ?? "", {
    preferAutoWhenAmbiguous: false
  });
  if (inferred === "first_last_frame" || inferred === "single_frame") {
    return inferred;
  }
  return "single_frame";
}

function resolveVideoFrameSources(shot: Shot, nextShot: Shot | undefined, mode: VideoMode): {
  firstFramePath: string;
  lastFramePath: string;
} {
  const firstFramePath = shot.videoStartFramePath?.trim() || shot.generatedImagePath?.trim() || "";
  const lastFramePath =
    mode === "first_last_frame"
      ? shot.videoEndFramePath?.trim() || nextShot?.generatedImagePath?.trim() || firstFramePath
      : "";
  return { firstFramePath, lastFramePath };
}

function inferLocalMotionPreset(
  shot: Shot,
  mode: VideoMode,
  nextShot?: Shot
): Exclude<LocalMotionPreset, "auto"> {
  const explicit = extractLocalMotionPresetFromText(shot.videoPrompt ?? "");
  if (explicit !== "auto") return explicit;
  const corpus = [
    shot.videoPrompt ?? "",
    shot.storyPrompt ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ]
    .join(" ")
    .toLowerCase();

  if (containsAnyKeyword(corpus, ["静止", "静帧", "still"])) return "still";
  if (containsAnyKeyword(corpus, ["淡入淡出", "淡变", "fade"])) return "fade";
  if (containsAnyKeyword(corpus, ["推近", "推进", "zoom in", "push in"])) return "push_in";
  if (containsAnyKeyword(corpus, ["拉远", "zoom out", "push out"])) return "push_out";
  if (containsAnyKeyword(corpus, ["左移", "向左平移", "pan left"])) return "pan_left";
  if (containsAnyKeyword(corpus, ["右移", "向右平移", "pan right"])) return "pan_right";

  if (mode === "first_last_frame") return "fade";
  if (shot.generatedImagePath?.trim() && nextShot?.generatedImagePath?.trim()) return "fade";
  return "push_in";
}

function inferSkyboxFaceFromShot(shot: Shot): SkyboxFace {
  if (
    shot.skyboxFace === "front" ||
    shot.skyboxFace === "right" ||
    shot.skyboxFace === "back" ||
    shot.skyboxFace === "left" ||
    shot.skyboxFace === "up" ||
    shot.skyboxFace === "down"
  ) {
    return shot.skyboxFace;
  }
  const cameraPitch = typeof shot.cameraPitch === "number" && Number.isFinite(shot.cameraPitch) ? shot.cameraPitch : undefined;
  if (cameraPitch !== undefined) {
    if (cameraPitch >= 55) return "up";
    if (cameraPitch <= -55) return "down";
  }
  const cameraYawRaw = typeof shot.cameraYaw === "number" && Number.isFinite(shot.cameraYaw) ? shot.cameraYaw : undefined;
  if (cameraYawRaw !== undefined) {
    let yaw = cameraYawRaw % 360;
    if (yaw > 180) yaw -= 360;
    if (yaw <= -180) yaw += 360;
    if (yaw >= -45 && yaw < 45) return "front";
    if (yaw >= 45 && yaw < 135) return "right";
    if (yaw >= 135 || yaw < -135) return "back";
    return "left";
  }
  const corpus = [
    shot.title ?? "",
    shot.storyPrompt ?? "",
    shot.videoPrompt ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ]
    .join(" ")
    .toLowerCase();
  if (containsAnyKeyword(corpus, ["右侧", "右边", "right"])) return "right";
  if (containsAnyKeyword(corpus, ["左侧", "左边", "left"])) return "left";
  if (containsAnyKeyword(corpus, ["后方", "背面", "后面", "rear", "back"])) return "back";
  if (containsAnyKeyword(corpus, ["俯视", "高角度", "top", "overhead", "bird"])) return "up";
  if (containsAnyKeyword(corpus, ["仰视", "低角度", "bottom", "low angle"])) return "down";
  return "front";
}

function autoSkyboxAdjacentFaces(face: SkyboxFace): SkyboxFace[] {
  if (face === "front") return ["left", "right"];
  if (face === "back") return ["left", "right"];
  if (face === "left") return ["front", "back"];
  if (face === "right") return ["front", "back"];
  if (face === "up" || face === "down") return ["front"];
  return [];
}

function inferAutoSkyboxProfile(shot: Shot): { faces: SkyboxFace[]; weights: Partial<Record<SkyboxFace, number>> } {
  const primary = inferSkyboxFaceFromShot(shot);
  const cameraYaw = typeof shot.cameraYaw === "number" && Number.isFinite(shot.cameraYaw) ? shot.cameraYaw : undefined;
  const cameraPitch = typeof shot.cameraPitch === "number" && Number.isFinite(shot.cameraPitch) ? shot.cameraPitch : undefined;
  const cameraFov = typeof shot.cameraFov === "number" && Number.isFinite(shot.cameraFov) ? shot.cameraFov : undefined;
  const hasCameraPose = cameraYaw !== undefined || cameraPitch !== undefined || cameraFov !== undefined;
  const corpus = [
    shot.title ?? "",
    shot.storyPrompt ?? "",
    shot.videoPrompt ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ]
    .join(" ")
    .toLowerCase();

  const isCloseShot = containsAnyKeyword(corpus, ["特写", "近景", "中近景", "表情", "反应", "肖像", "半身"]);
  const isWideSpatialShot = containsAnyKeyword(corpus, [
    "全景",
    "大全景",
    "建立",
    "建立镜头",
    "广角",
    "空间",
    "环境",
    "室内",
    "走廊",
    "门厅",
    "房间",
    "客厅",
    "卧室",
    "街道",
    "河边",
    "桥上",
    "庭院",
    "仓库",
    "车内",
    "天台"
  ]);
  const isDiagonalShot = containsAnyKeyword(corpus, ["斜侧", "斜角", "45度", "对角", "偏角度", "过肩", "肩后"]);
  const favorsLeft = containsAnyKeyword(corpus, ["左侧", "左边", "偏左", "向左"]);
  const favorsRight = containsAnyKeyword(corpus, ["右侧", "右边", "偏右", "向右"]);

  const faces: SkyboxFace[] = [primary];
  const weights: Partial<Record<SkyboxFace, number>> = { [primary]: 1 };

  if (hasCameraPose) {
    return { faces, weights };
  }

  if (isCloseShot) {
    return { faces, weights };
  }

  const pushFace = (face: SkyboxFace, weight: number) => {
    if (!faces.includes(face)) faces.push(face);
    weights[face] = Math.max(weights[face] ?? 0, weight);
  };

  if (primary === "up" || primary === "down") {
    pushFace("front", 0.6);
    return { faces, weights };
  }

  if (isWideSpatialShot) {
    for (const face of autoSkyboxAdjacentFaces(primary)) {
      pushFace(face, 0.72);
    }
  } else if (isDiagonalShot) {
    if (favorsLeft) {
      pushFace("left", primary === "left" ? 0.82 : 0.62);
    } else if (favorsRight) {
      pushFace("right", primary === "right" ? 0.82 : 0.62);
    } else {
      const fallback = primary === "left" || primary === "back" ? "front" : "right";
      pushFace(fallback, 0.58);
    }
  } else if (favorsLeft && primary !== "left") {
    pushFace("left", 0.52);
  } else if (favorsRight && primary !== "right") {
    pushFace("right", 0.52);
  }

  return { faces, weights };
}

export function inferSkyboxReferencePlan(shot: Shot): {
  primaryFace: SkyboxFace;
  faces: SkyboxFace[];
  weights: Partial<Record<SkyboxFace, number>>;
  manualFaces: boolean;
  manualWeights: boolean;
} {
  const primaryFace = inferSkyboxFaceFromShot(shot);
  const autoProfile = inferAutoSkyboxProfile(shot);
  const manualFaces = Array.isArray(shot.skyboxFaces) && shot.skyboxFaces.length > 0;
  const manualWeights = Boolean(
    shot.skyboxFaceWeights &&
      Object.values(shot.skyboxFaceWeights).some((value) => typeof value === "number" && Number.isFinite(value))
  );
  const faces = manualFaces ? inferSkyboxFacesFromShot(shot) : autoProfile.faces;
  const weights: Partial<Record<SkyboxFace, number>> = {};
  for (const face of faces) {
    weights[face] = manualWeights
      ? skyboxFaceWeight(shot, face)
      : autoProfile.weights[face] ?? skyboxFaceWeight(shot, face);
  }
  return {
    primaryFace,
    faces,
    weights,
    manualFaces,
    manualWeights
  };
}

function inferSkyboxFacesFromShot(shot: Shot): SkyboxFace[] {
  const manual = (shot.skyboxFaces ?? []).filter(
    (face): face is SkyboxFace =>
      face === "front" ||
      face === "right" ||
      face === "back" ||
      face === "left" ||
      face === "up" ||
      face === "down"
  );
  if (manual.length > 0) return uniquePreserveOrder(manual) as SkyboxFace[];
  return inferAutoSkyboxProfile(shot).faces;
}

function skyboxFaceWeight(shot: Shot, face: SkyboxFace): number {
  const raw = shot.skyboxFaceWeights?.[face];
  if (typeof raw !== "number" || !Number.isFinite(raw)) {
    return inferAutoSkyboxProfile(shot).weights[face] ?? 1;
  }
  return Math.max(0, Math.min(1, raw));
}

function toVideoPrompt(shot: Shot, mode: VideoMode): string {
  const raw = shot.videoPrompt?.trim() || shot.storyPrompt?.trim() || shot.notes?.trim() || shot.title;
  const compact = normalizePromptBody(raw);
  const speakingDirective = shot.dialogue.trim()
    ? "画面中若出现正在说话的角色，口型开合应与对白节奏一致，避免闭口说话、乱张嘴或延迟口型。"
    : "";
  if (mode === "first_last_frame") {
    return ["首尾帧运镜，保持角色与场景连续，平滑过渡。", speakingDirective, compact]
      .filter((item) => item.length > 0)
      .join("");
  }
  return ["单帧图生视频，保持主体稳定并增加自然镜头运动。", speakingDirective, compact]
    .filter((item) => item.length > 0)
    .join("");
}

type WorkflowNode = {
  id?: number;
  type?: string;
  pos?: [number, number];
  order?: number;
  mode?: number;
  size?: [number, number];
  flags?: Record<string, unknown>;
  inputs?: Array<{ name?: string; type?: string; link?: number | null; widget?: Record<string, unknown> }>;
  outputs?: Array<{ name?: string; type?: string; links?: number[] | null }>;
  widgets_values?: unknown;
};

type WeightedImageRef = {
  source: string;
  weight: number;
  priority: number;
  bucket: string;
  label: string;
  role:
    | "scene_primary"
    | "scene_secondary"
    | "character_front"
    | "character_side"
    | "character_back"
    | "continuity_scene"
    | "continuity_character";
};

type CharacterReferenceView = "front" | "side" | "back";

type ShotContinuityPlan = {
  previousSceneShot?: Shot;
  previousCharacterShot?: Shot;
};

function nodeWidgetList(node: WorkflowNode): unknown[] | null {
  return Array.isArray(node.widgets_values) ? node.widgets_values : null;
}

function setNodeWidgetValue(node: WorkflowNode | undefined, index: number, value: string | number | boolean) {
  if (!node) return;
  const widgets = nodeWidgetList(node);
  if (!widgets || index < 0 || index >= widgets.length) return;
  widgets[index] = value;
}

function setNodeWidgetNamedValue(
  node: WorkflowNode | undefined,
  name: string,
  value: string | number | boolean
) {
  if (!node || !node.widgets_values || typeof node.widgets_values !== "object" || Array.isArray(node.widgets_values)) {
    return;
  }
  (node.widgets_values as Record<string, unknown>)[name] = value;
}

function workflowNodeWidgetInputNames(node: WorkflowNode | undefined): string[] {
  if (!node || !Array.isArray(node.inputs)) return [];
  const names: string[] = [];
  for (const rawInput of node.inputs) {
    if (!rawInput || typeof rawInput !== "object") continue;
    const input = rawInput as Record<string, unknown>;
    if (!hasWidgetMeta(input)) continue;
    const name = typeof input.name === "string" ? input.name.trim() : "";
    if (!name) continue;
    names.push(name);
  }
  return names;
}

function kSamplerControlAfterGenerateDeclared(node: WorkflowNode | undefined): boolean | null {
  const widgetInputNames = workflowNodeWidgetInputNames(node);
  if (widgetInputNames.length === 0) return null;
  return widgetInputNames.includes("control_after_generate");
}

function setKSamplerWidgetValues(
  node: WorkflowNode | undefined,
  values: {
    seed: number;
    steps: number;
    cfg: number;
    samplerName: string;
    scheduler: string;
    denoise: number;
    controlAfterGenerate?: "fixed" | "randomize" | "increment" | "decrement";
  }
) {
  const widgets = node ? nodeWidgetList(node) : null;
  if (!widgets || widgets.length === 0) return;
  const controlAfterGenerate = values.controlAfterGenerate ?? "fixed";
  const declaredControlAfterGenerate = kSamplerControlAfterGenerateDeclared(node);
  const hasControlAfterGenerateSlot =
    declaredControlAfterGenerate !== null
      ? declaredControlAfterGenerate
      : widgets.length >= 7 && isKSamplerControlAfterGenerateValue(widgets[1]);
  setNodeWidgetValue(node, 0, values.seed);
  if (hasControlAfterGenerateSlot) {
    setNodeWidgetValue(node, 1, controlAfterGenerate);
    setNodeWidgetValue(node, 2, values.steps);
    setNodeWidgetValue(node, 3, values.cfg);
    setNodeWidgetValue(node, 4, values.samplerName);
    setNodeWidgetValue(node, 5, values.scheduler);
    setNodeWidgetValue(node, 6, values.denoise);
    return;
  }
  setNodeWidgetValue(node, 1, values.steps);
  setNodeWidgetValue(node, 2, values.cfg);
  setNodeWidgetValue(node, 3, values.samplerName);
  setNodeWidgetValue(node, 4, values.scheduler);
  setNodeWidgetValue(node, 5, values.denoise);
}

function setNodeEnabled(node: WorkflowNode | undefined, enabled: boolean) {
  if (!node) return;
  node.mode = enabled ? 0 : 4;
}

function workflowNodeTitle(node: WorkflowNode | undefined): string {
  if (!node || typeof node !== "object") return "";
  const directTitle = (node as Record<string, unknown>).title;
  if (typeof directTitle === "string" && directTitle.trim().length > 0) {
    return directTitle.trim();
  }
  const properties = (node as Record<string, unknown>).properties;
  if (properties && typeof properties === "object" && !Array.isArray(properties)) {
    const nodeName = (properties as Record<string, unknown>)["Node name for S&R"];
    if (typeof nodeName === "string" && nodeName.trim().length > 0) {
      return nodeName.trim();
    }
  }
  return "";
}

function findWorkflowNodeByTitle(nodes: WorkflowNode[], matcher: RegExp): WorkflowNode | undefined {
  for (const node of nodes) {
    if (isNodeDisabled(node)) continue;
    const title = workflowNodeTitle(node);
    if (!title) continue;
    matcher.lastIndex = 0;
    if (matcher.test(title)) return node;
  }
  return undefined;
}

function reconnectImageInputLink(
  workflow: Record<string, unknown>,
  targetNode: WorkflowNode | undefined,
  targetInputIndex: number,
  sourceNode: WorkflowNode | undefined,
  sourceOutputSlot = 0
) {
  if (!targetNode || typeof targetNode.id !== "number") return;
  if (!sourceNode || typeof sourceNode.id !== "number") return;
  removeIncomingLinks(workflow, targetNode.id, [targetInputIndex]);
  ensureWorkflowLink(workflow, sourceNode.id, sourceOutputSlot, targetNode.id, targetInputIndex, "IMAGE");
}

function applyQwenProDualStoryboardBindings(
  workflow: Record<string, unknown>,
  tokens: Record<string, string>,
  kind: "image" | "video" | "audio"
): boolean {
  if (kind !== "image") return false;
  const nodes = workflowNodes(workflow);
  const qwenProNodes = nodes.filter(
    (node) => typeof node.type === "string" && node.type.trim() === "TextEncodeQwenImageEditPlusPro_lrzjason"
  );
  if (qwenProNodes.length < 2) return false;

  const findByTitleOrId = (titlePattern: RegExp, fallbackId: number): WorkflowNode | undefined =>
    findWorkflowNodeByTitle(nodes, titlePattern) ??
    nodes.find((node) => !isNodeDisabled(node) && typeof node.id === "number" && node.id === fallbackId);

  const sceneNode = findByTitleOrId(/clean\s*scene|scene\s*ref/i, 297);
  const charAFrontNode = findByTitleOrId(/character\s*a\s*front/i, 299);
  const charASideNode = findByTitleOrId(/character\s*a\s*side/i, 300);
  const charABackNode = findByTitleOrId(/character\s*a\s*back/i, 302);
  const charALockNode = findByTitleOrId(/character\s*a\s*identity\s*lock/i, 308);
  const charBFrontNode = findByTitleOrId(/character\s*b\s*front/i, 305);
  const charBSideNode = findByTitleOrId(/character\s*b\s*side/i, 306);
  const charBBackNode = findByTitleOrId(/character\s*b\s*back/i, 307);
  const promptANode = findByTitleOrId(/prompt\s*a/i, 298);
  const promptBNode = findByTitleOrId(/prompt\s*b/i, 304);
  const qwenPassANode = findByTitleOrId(/qwen.*pass\s*a|qwen.*character\s*a/i, 303) ?? qwenProNodes[0];
  const qwenPassBNode = findByTitleOrId(/qwen.*pass\s*b|qwen.*add\s*character\s*b/i, 309) ?? qwenProNodes[1];
  const negativeBNode = findByTitleOrId(/negative\s*b/i, 310);
  const samplerANode = findByTitleOrId(/ksampler\s*a/i, 218);
  const samplerBNode = findByTitleOrId(/ksampler\s*b/i, 311);
  const decodeANode = findByTitleOrId(/decode\s*a/i, 217);
  const decodeBNode = findByTitleOrId(/decode\s*b/i, 312);
  const saveFinalNode = findByTitleOrId(/save\s*dual\s*final|save\s*final/i, 283);
  const savePassANode = findByTitleOrId(/save\s*pass\s*a/i, 313);
  const checkpointNode =
    nodes.find((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "CheckpointLoaderSimple") ??
    nodes.find((node) => typeof node.id === "number" && node.id === 277) ??
    undefined;

  const scenePath = String(tokens.SCENE_REF_PATH ?? "").trim();
  const char1PrimaryPath = String(tokens.CHAR1_PRIMARY_PATH ?? tokens.CHAR1_FRONT_PATH ?? "").trim();
  const char1SidePath = String(tokens.CHAR1_SIDE_PATH ?? "").trim() || char1PrimaryPath;
  const char1BackPath = String(tokens.CHAR1_BACK_PATH ?? "").trim() || char1PrimaryPath;
  const char2PrimaryPath = String(tokens.CHAR2_PRIMARY_PATH ?? tokens.CHAR2_FRONT_PATH ?? "").trim();
  const char2SidePath = String(tokens.CHAR2_SIDE_PATH ?? "").trim() || char2PrimaryPath;
  const char2BackPath = String(tokens.CHAR2_BACK_PATH ?? "").trim() || char2PrimaryPath;
  const passBMaskPath = String(tokens.PASS_B_CHARACTER_MASK_PATH ?? tokens.PASS_A_CHARACTER_MASK_PATH ?? "").trim();
  const qwenPromptText = String(tokens.PROMPT || tokens.NEXT_SCENE_PROMPT || "").trim();
  const storyboardModel = String(tokens.STORYBOARD_IMAGE_MODEL ?? "").trim();
  const safeShotId = sanitizePathSegment(String(tokens.SHOT_ID ?? "").trim() || "shot");
  const seed = Number(tokens.SEED);
  const safeSeed = Number.isFinite(seed) ? Math.floor(seed) : undefined;
  const charAName = String(tokens.CHAR1_NAME ?? "").trim() || "Character A";
  const charBName = String(tokens.CHAR2_NAME ?? "").trim() || "Character B";
  const hasCharacterB = char2PrimaryPath.length > 0;
  const promptA = [
    qwenPromptText,
    `Pass A target: render exactly one person only (${charAName}).`,
    "Do not add any second person in this pass.",
    "Keep the clean scene composition, horizon, perspective, and lighting stable.",
    "Human anatomy must be complete and natural: one head, two arms, two legs, clean hands, grounded feet.",
    "No ghost limbs, no duplicate body parts, no silhouette-only person, no collage artifacts."
  ]
    .filter((line) => line.length > 0)
    .join("\n");
  const promptB = [
    qwenPromptText,
    `Pass B target: keep ${charAName} unchanged and inject ${charBName} only in the masked empty region.`,
    `Preserve ${charAName} identity and composition, then add ${charBName} with correct proportion and pose.`,
    "Only update the masked local area; all unmasked pixels must remain unchanged.",
    "Do not add extra crowd or bystanders; final frame must contain exactly two people.",
    "Both people must remain complete and anatomically normal, without extra limbs, duplicate heads, or warped bodies."
  ]
    .filter((line) => line.length > 0)
    .join("\n");
  const passAInstruction = [
    "Picture 1 is a clean scene-only reference.",
    `Pictures 2-4 are ${charAName} front / side / back references.`,
    `Generate exactly one complete person: ${charAName}.`,
    "Maintain consistent face, hairstyle, outfit, and body proportion from references.",
    "No additional people, no missing body parts, no white cutout silhouette, no background dirt/artifacts."
  ].join("\n");
  const passBInstruction = [
    `Picture 1 is the locked base frame containing scene + ${charAName}.`,
    `Picture 2 is ${charAName} identity lock.`,
    `Pictures 3-5 are ${charBName} front / side / back references.`,
    `Add ${charBName} only inside the provided mask region and preserve ${charAName} exactly as-is.`,
    "Do not rewrite the entire image. Outside mask must remain unchanged.",
    "Keep both identities stable and anatomically normal with natural pose and grounded feet.",
    "No extra people, no duplicate limbs, no ghosting, no blurred messy artifacts."
  ].join("\n");

  if (scenePath) setNodeWidgetValue(sceneNode, 0, scenePath);
  if (char1PrimaryPath) {
    setNodeWidgetValue(charAFrontNode, 0, char1PrimaryPath);
    setNodeWidgetValue(charALockNode, 0, char1PrimaryPath);
  }
  if (char1SidePath) setNodeWidgetValue(charASideNode, 0, char1SidePath);
  if (char1BackPath) setNodeWidgetValue(charABackNode, 0, char1BackPath);
  setNodeWidgetValue(promptANode, 0, promptA);
  setNodeWidgetValue(promptBNode, 0, promptB);
  setNodeWidgetValue(qwenPassANode, 7, passAInstruction);
  setNodeWidgetValue(qwenPassBNode, 7, passBInstruction);
  setNodeWidgetValue(saveFinalNode, 0, `Storyboard/image_asset_guided_${safeShotId}`);
  setNodeWidgetValue(savePassANode, 0, `Storyboard/debug_passA_${safeShotId}`);
  if (storyboardModel) {
    setNodeWidgetValue(checkpointNode, 0, storyboardModel);
  }

  const samplerAValues = samplerANode ? buildWidgetValuesByInputName(samplerANode) : {};
  const samplerBValues = samplerBNode ? buildWidgetValuesByInputName(samplerBNode) : {};
  const samplerASamplerName =
    typeof samplerAValues.sampler_name === "string" && samplerAValues.sampler_name.trim().length > 0
      ? samplerAValues.sampler_name.trim()
      : "euler";
  const samplerAScheduler =
    typeof samplerAValues.scheduler === "string" && samplerAValues.scheduler.trim().length > 0
      ? samplerAValues.scheduler.trim()
      : "normal";
  const samplerBSamplerName =
    typeof samplerBValues.sampler_name === "string" && samplerBValues.sampler_name.trim().length > 0
      ? samplerBValues.sampler_name.trim()
      : samplerASamplerName;
  const samplerBScheduler =
    typeof samplerBValues.scheduler === "string" && samplerBValues.scheduler.trim().length > 0
      ? samplerBValues.scheduler.trim()
      : samplerAScheduler;

  setKSamplerWidgetValues(samplerANode, {
    seed: safeSeed !== undefined ? safeSeed : 1234567890123,
    steps: 6,
    cfg: 1.1,
    samplerName: samplerASamplerName,
    scheduler: samplerAScheduler,
    denoise: 1,
    controlAfterGenerate: "fixed"
  });
  setKSamplerWidgetValues(samplerBNode, {
    seed: safeSeed !== undefined ? safeSeed : 1234567891123,
    steps: 8,
    cfg: 1.1,
    samplerName: samplerBSamplerName,
    scheduler: samplerBScheduler,
    denoise: 0.3,
    controlAfterGenerate: "fixed"
  });

  const passBNodes = [
    promptBNode,
    charALockNode,
    charBFrontNode,
    charBSideNode,
    charBBackNode,
    qwenPassBNode,
    negativeBNode,
    samplerBNode,
    decodeBNode
  ];

  if (hasCharacterB) {
    if (!passBMaskPath) {
      throw new Error(`Qwen Pro 双人分镜缺少 PASS_B_CHARACTER_MASK_PATH，无法执行局部注入：${safeShotId}`);
    }
    setNodeWidgetValue(charBFrontNode, 0, char2PrimaryPath);
    setNodeWidgetValue(charBSideNode, 0, char2SidePath);
    setNodeWidgetValue(charBBackNode, 0, char2BackPath);
    reconnectImageInputLink(workflow, qwenPassBNode, 2, decodeANode, 0);
    const samplerPosX = samplerBNode?.pos?.[0] ?? qwenPassBNode?.pos?.[0] ?? 0;
    const samplerPosY = samplerBNode?.pos?.[1] ?? qwenPassBNode?.pos?.[1] ?? 0;
    const passBMaskNode = createLoadImageMaskNode(workflow, passBMaskPath, "red");
    passBMaskNode.pos = [samplerPosX - 740, samplerPosY + 260];
    const passBBaseEncodeNode = createVaeEncodeNode(workflow, samplerPosX - 520, samplerPosY + 180);
    const passBMaskedLatentNode = createSetLatentNoiseMaskNode(workflow, samplerPosX - 300, samplerPosY + 220);
    reconnectImageInputLink(workflow, passBBaseEncodeNode, 0, decodeANode, 0);
    if (
      typeof checkpointNode?.id === "number" &&
      typeof passBBaseEncodeNode.id === "number" &&
      typeof passBMaskedLatentNode.id === "number" &&
      typeof passBMaskNode.id === "number"
    ) {
      removeIncomingLinks(workflow, passBBaseEncodeNode.id, [1]);
      ensureWorkflowLink(workflow, checkpointNode.id, 2, passBBaseEncodeNode.id, 1, "VAE");
      removeIncomingLinks(workflow, passBMaskedLatentNode.id, [0, 1]);
      ensureWorkflowLink(workflow, passBBaseEncodeNode.id, 0, passBMaskedLatentNode.id, 0, "LATENT");
      ensureWorkflowLink(workflow, passBMaskNode.id, 0, passBMaskedLatentNode.id, 1, "MASK");
      if (typeof samplerBNode?.id === "number") {
        removeIncomingLinks(workflow, samplerBNode.id, [3]);
        ensureWorkflowLink(workflow, passBMaskedLatentNode.id, 0, samplerBNode.id, 3, "LATENT");
      }
    }
    for (const node of passBNodes) setNodeEnabled(node, true);
    reconnectImageInputLink(workflow, saveFinalNode, 0, decodeBNode, 0);
  } else {
    for (const node of passBNodes) setNodeEnabled(node, false);
    reconnectImageInputLink(workflow, saveFinalNode, 0, decodeANode, 0);
  }
  reconnectImageInputLink(workflow, savePassANode, 0, decodeANode, 0);

  // Keep pass-A encoder always enabled; pass-B can be disabled for single-character shots.
  setNodeEnabled(qwenPassANode, true);
  setNodeEnabled(samplerANode, true);
  setNodeEnabled(decodeANode, true);

  return true;
}

type StoryboardComposerCharacterSlot = {
  slotIndex: number;
  name: string;
  frontPath: string;
  sidePath: string;
  backPath: string;
  referencePath: string;
  faceRefPath: string;
  detailRefPath: string;
  sideViewDirection: "left" | "right";
  mirrorSideForOpposite: boolean;
};

type NextsceneCharacterSlot = {
  slotIndex: number;
  name: string;
  primaryPath: string;
  secondaryPath: string;
  frontPath: string;
  sidePath: string;
  backPath: string;
  faceRefPath: string;
  detailRefPath: string;
  maskPath: string;
};

function isStoryboardComposerWorkflow(workflow: Record<string, unknown>): boolean {
  return (
    workflowHasNodeType(workflow, "StoryboardSceneNode") &&
    workflowHasNodeType(workflow, "StoryboardCompositeNode") &&
    (workflowHasNodeType(workflow, "StoryboardTurnaroundCharacterNode") ||
      workflowHasNodeType(workflow, "StoryboardCharacterNode"))
  );
}

function isFisherNextsceneWorkflow(workflow: Record<string, unknown>): boolean {
  if (isStoryboardComposerWorkflow(workflow)) return false;
  const nodes = workflowNodes(workflow).filter((node) => !isNodeDisabled(node));
  if (nodes.length === 0) return false;
  const hasQwenAdvance = nodes.some(
    (node) => (node.type ?? "").trim() === "TextEncodeQwenImageEditPlusAdvance_lrzjason"
  );
  if (!hasQwenAdvance) return false;
  const hasKSampler = nodes.some((node) => (node.type ?? "").trim() === "KSampler");
  const hasCheckpoint = nodes.some((node) => (node.type ?? "").trim() === "CheckpointLoaderSimple");
  const hasSaveImage = nodes.some((node) => (node.type ?? "").trim() === "SaveImage");
  if (!hasKSampler || !hasCheckpoint || !hasSaveImage) return false;
  const powerLoraNode = nodes.find((node) =>
    (node.type ?? "").trim().toLowerCase().includes("power lora loader")
  );
  if (!powerLoraNode) return false;
  const loraWidgetText = JSON.stringify(powerLoraNode.widgets_values ?? "").toLowerCase();
  if (loraWidgetText.includes("next-scene") || loraWidgetText.includes("nextscene")) return true;
  return (
    nodes.some((node) => node.id === 21 && (node.type ?? "").trim() === "TextEncodeQwenImageEditPlusAdvance_lrzjason") &&
    nodes.some((node) => node.id === 10 && (node.type ?? "").trim() === "KSampler") &&
    nodes.some((node) => node.id === 89 && (node.type ?? "").trim() === "SaveImage")
  );
}

function workflowNodeTypeCount(workflow: Record<string, unknown>, targetType: string): number {
  const normalizedTarget = targetType.trim();
  if (!normalizedTarget) return 0;
  if (Array.isArray(workflow.nodes)) {
    return workflowNodes(workflow).filter((node) => (node.type ?? "").trim() === normalizedTarget).length;
  }
  let count = 0;
  for (const entry of Object.values(workflow)) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) continue;
    if (String((entry as Record<string, unknown>).class_type ?? "").trim() === normalizedTarget) {
      count += 1;
    }
  }
  return count;
}

function isQwenCustomMaskStoryboardWorkflow(workflow: Record<string, unknown>): boolean {
  return (
    workflowHasNodeType(workflow, "TextEncodeQwenImageEditPlusCustom_lrzjason") &&
    workflowHasNodeType(workflow, "QwenEditConfigPreparer") &&
    workflowHasNodeType(workflow, "KSampler") &&
    workflowHasNodeType(workflow, "SaveImage")
  );
}

function qwenCustomMaskWorkflowSupportsPoseRef(workflow: Record<string, unknown>): boolean {
  return (
    isQwenCustomMaskStoryboardWorkflow(workflow) &&
    workflowHasNodeType(workflow, "LoadImage") &&
    Object.values(workflow).some((entry) => {
      if (!entry || typeof entry !== "object" || Array.isArray(entry)) return false;
      const inputs = (entry as Record<string, unknown>).inputs;
      if (!inputs || typeof inputs !== "object" || Array.isArray(inputs)) return false;
      const imageValue = String((inputs as Record<string, unknown>).image ?? "").trim();
      return imageValue === "{{PASS_A_POSE_GUIDE_PATH}}" || imageValue === "{{PASS_B_POSE_GUIDE_PATH}}";
    })
  );
}

function isQwenProDualStoryboardWorkflow(workflow: Record<string, unknown>): boolean {
  return (
    workflowNodeTypeCount(workflow, "TextEncodeQwenImageEditPlusPro_lrzjason") >= 2 &&
    workflowHasNodeType(workflow, "KSampler") &&
    workflowHasNodeType(workflow, "SaveImage")
  );
}

function normalizeStoryboardComposerSideViewDirection(value: string | undefined): "left" | "right" | undefined {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase();
  if (normalized === "left" || normalized === "right") return normalized;
  return undefined;
}

function parseStoryboardComposerBooleanToken(value: string | undefined): boolean | undefined {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase();
  if (!normalized) return undefined;
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return undefined;
}

function inferStoryboardComposerSideViewDirectionFromPath(path: string): "left" | "right" | undefined {
  const filename = path.split(/[\\/]/).pop()?.toLowerCase() ?? "";
  if (!filename) return undefined;
  const normalized = filename.replace(/[^a-z0-9]+/g, " ").trim();
  if (!normalized) return undefined;
  const leftHints = /\b(left|leftward|lhs)\b/u;
  const rightHints = /\b(right|rightward|rhs)\b/u;
  if (leftHints.test(normalized)) return "left";
  if (rightHints.test(normalized)) return "right";
  return undefined;
}

function resolveStoryboardComposerSideViewDirection(
  tokens: Record<string, string>,
  slotIndex: number,
  sidePath: string
): "left" | "right" {
  const explicit =
    normalizeStoryboardComposerSideViewDirection(tokens[`CHAR${slotIndex}_SIDE_VIEW_DIRECTION`]) ??
    normalizeStoryboardComposerSideViewDirection(tokens[`CHAR${slotIndex}_SIDE_DIRECTION`]) ??
    normalizeStoryboardComposerSideViewDirection(tokens.STORYBOARD_COMPOSER_SIDE_VIEW_DIRECTION);
  if (explicit) return explicit;
  const inferredFromPath = inferStoryboardComposerSideViewDirectionFromPath(sidePath);
  if (inferredFromPath) return inferredFromPath;
  return slotIndex % 2 === 1 ? "right" : "left";
}

function resolveStoryboardComposerMirrorSideForOpposite(
  tokens: Record<string, string>,
  slotIndex: number
): boolean {
  const explicit =
    parseStoryboardComposerBooleanToken(tokens[`CHAR${slotIndex}_MIRROR_SIDE_FOR_OPPOSITE`]) ??
    parseStoryboardComposerBooleanToken(tokens[`CHAR${slotIndex}_MIRROR_SIDE`]) ??
    parseStoryboardComposerBooleanToken(tokens.STORYBOARD_COMPOSER_MIRROR_SIDE_FOR_OPPOSITE);
  return explicit ?? true;
}

function buildNextsceneCharacterSlots(tokens: Record<string, string>): NextsceneCharacterSlot[] {
  const slots: NextsceneCharacterSlot[] = [];
  for (const slotIndex of [1, 2, 3, 4] as const) {
    const name = String(tokens[`CHAR${slotIndex}_NAME`] ?? "").trim() || `character_${slotIndex}`;
    const frontPath = String(tokens[`CHAR${slotIndex}_FRONT_PATH`] ?? "").trim();
    const sidePath = String(tokens[`CHAR${slotIndex}_SIDE_PATH`] ?? "").trim();
    const backPath = String(tokens[`CHAR${slotIndex}_BACK_PATH`] ?? "").trim();
    const faceRefPath = String(tokens[`CHAR${slotIndex}_FACE_REF_PATH`] ?? "").trim();
    const detailRefPath = String(tokens[`CHAR${slotIndex}_DETAIL_REF_PATH`] ?? "").trim();
    const primaryPath =
      String(tokens[`CHAR${slotIndex}_PRIMARY_PATH`] ?? "").trim() ||
      frontPath ||
      sidePath ||
      backPath ||
      detailRefPath ||
      faceRefPath;
    const secondaryPath =
      String(tokens[`CHAR${slotIndex}_SECONDARY_PATH`] ?? "").trim() ||
      sidePath ||
      backPath ||
      detailRefPath ||
      faceRefPath ||
      primaryPath;
    const explicitMaskPath = String(tokens[`CHAR${slotIndex}_MASK_PATH`] ?? "").trim();
    const maskPath =
      explicitMaskPath ||
      (slotIndex === 2
        ? String(tokens.PASS_B_CHARACTER_MASK_PATH ?? tokens.PASS_A_CHARACTER_MASK_PATH ?? "").trim()
        : slotIndex === 1
          ? String(tokens.PASS_A_CHARACTER_MASK_PATH ?? "").trim()
          : "");
    const hasPath = Boolean(primaryPath || secondaryPath || frontPath || sidePath || backPath || faceRefPath || detailRefPath);
    if (!hasPath) continue;
    slots.push({
      slotIndex,
      name,
      primaryPath,
      secondaryPath,
      frontPath,
      sidePath,
      backPath,
      faceRefPath,
      detailRefPath,
      maskPath
    });
  }
  return slots;
}

function buildNextsceneProgressivePrompt(args: {
  basePrompt: string;
  stageIndex: number;
  stageCount: number;
  currentSlot: NextsceneCharacterSlot;
  activeSlots: NextsceneCharacterSlot[];
  hasMask: boolean;
}): string {
  const { basePrompt, stageIndex, stageCount, currentSlot, activeSlots, hasMask } = args;
  const normalizedBase = basePrompt.trim();
  const activeNames = activeSlots.map((slot) => slot.name.trim()).filter((name) => name.length > 0);
  const roleLabel = currentSlot.name.trim() || `character_${currentSlot.slotIndex}`;
  const finalCount = Math.max(1, stageIndex);
  const identityLine =
    activeNames.length > 0
      ? `Identity lock characters: ${activeNames.join(", ")}.`
      : `Identity lock character: ${roleLabel}.`;
  const sharedLines = [
    normalizedBase,
    `Progressive storyboard pass ${stageIndex}/${stageCount}.`,
    identityLine,
    "Human anatomy must be complete and natural: one head, two arms, two legs, complete hands and feet.",
    "No extra crowd, no duplicated limbs, no ghost body, no sticker edge, no collage artifacts."
  ];
  if (stageIndex <= 1) {
    return [
      ...sharedLines,
      `Pass goal: render exactly one visible character only (${roleLabel}).`,
      "Do not draw any second character in this pass.",
      "Keep environment perspective and lighting stable."
    ]
      .filter((line) => line.length > 0)
      .join("\n");
  }
  return [
    ...sharedLines,
    `Pass goal: keep all existing characters and scene unchanged, then add only ${roleLabel}.`,
    `Final frame should contain exactly ${finalCount} visible characters: ${activeNames.join(", ")}.`,
    hasMask
      ? "Local inpaint is enabled: only update the masked area for the new character."
      : "When no explicit mask is available, preserve previous content as much as possible and only introduce the new character."
  ]
    .filter((line) => line.length > 0)
    .join("\n");
}

function buildNextsceneStageImageRefs(args: {
  stageIndex: number;
  currentSlot: NextsceneCharacterSlot;
  stageScenePath: string;
  originalScenePath: string;
}): Array<{ filename: string; weight: number; role: WeightedImageRef["role"]; label: string }> {
  const { stageIndex, currentSlot, stageScenePath, originalScenePath } = args;
  const refs: Array<{ filename: string; weight: number; role: WeightedImageRef["role"]; label: string }> = [];
  const used = new Set<string>();
  const pushRef = (candidate: {
    filename: string;
    weight: number;
    role: WeightedImageRef["role"];
    label: string;
  }) => {
    const filename = candidate.filename.trim();
    if (!filename || used.has(filename)) return;
    used.add(filename);
    refs.push({
      filename,
      weight: Math.max(0, Math.min(1.2, candidate.weight)),
      role: candidate.role,
      label: candidate.label
    });
  };
  if (stageScenePath.trim()) {
    pushRef({
      filename: stageScenePath.trim(),
      weight: 1,
      role: "scene_primary",
      label: stageIndex <= 1 ? "scene:base" : `scene:stage_${stageIndex - 1}`
    });
  }
  if (stageIndex > 1 && originalScenePath.trim() && originalScenePath.trim() !== stageScenePath.trim()) {
    pushRef({
      filename: originalScenePath.trim(),
      weight: 0.42,
      role: "scene_secondary",
      label: "scene:anchor"
    });
  }
  const roleLabel = currentSlot.name.trim() || `character_${currentSlot.slotIndex}`;
  if (currentSlot.primaryPath.trim()) {
    pushRef({
      filename: currentSlot.primaryPath.trim(),
      weight: stageIndex <= 1 ? 0.96 : 0.94,
      role: "character_front",
      label: `${roleLabel}:primary`
    });
  }
  const secondaryPath = currentSlot.secondaryPath.trim();
  if (secondaryPath && secondaryPath !== currentSlot.primaryPath.trim() && refs.length < 3) {
    pushRef({
      filename: secondaryPath,
      weight: stageIndex <= 1 ? 0.62 : 0.68,
      role: "character_side",
      label: `${roleLabel}:secondary`
    });
  }
  if (refs.length < 3 && currentSlot.detailRefPath.trim()) {
    pushRef({
      filename: currentSlot.detailRefPath.trim(),
      weight: 0.5,
      role: "character_back",
      label: `${roleLabel}:detail`
    });
  }
  return refs.slice(0, 3);
}

function applyNextsceneMaskedLatentBindings(
  workflow: Record<string, unknown>,
  maskPath: string
): boolean {
  const normalizedMaskPath = maskPath.trim();
  if (!normalizedMaskPath) return false;
  const nodes = workflowNodes(workflow);
  const qwenNode = nodes.find(
    (node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "TextEncodeQwenImageEditPlusAdvance_lrzjason"
  );
  const samplerNode = nodes.find((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "KSampler");
  if (!qwenNode || typeof qwenNode.id !== "number" || !samplerNode || typeof samplerNode.id !== "number") {
    return false;
  }
  const samplerX = samplerNode.pos?.[0] ?? 0;
  const samplerY = samplerNode.pos?.[1] ?? 0;
  const maskNode = createLoadImageMaskNode(workflow, normalizedMaskPath, "red");
  maskNode.pos = [samplerX - 760, samplerY + 220];
  const maskedLatentNode = createSetLatentNoiseMaskNode(workflow, samplerX - 520, samplerY + 220);
  if (typeof maskNode.id !== "number" || typeof maskedLatentNode.id !== "number") return false;
  removeIncomingLinks(workflow, maskedLatentNode.id, [0, 1]);
  ensureWorkflowLink(workflow, qwenNode.id, 1, maskedLatentNode.id, 0, "LATENT");
  ensureWorkflowLink(workflow, maskNode.id, 0, maskedLatentNode.id, 1, "MASK");
  removeIncomingLinks(workflow, samplerNode.id, [3]);
  ensureWorkflowLink(workflow, maskedLatentNode.id, 0, samplerNode.id, 3, "LATENT");
  return true;
}

function tuneNextsceneStageSampler(
  workflow: Record<string, unknown>,
  stageSeed: number,
  stageIndex: number,
  maskedInpaint: boolean
) {
  const samplerNode = workflowNodes(workflow).find(
    (node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "KSampler"
  );
  if (!samplerNode) return;
  const samplerValues = buildWidgetValuesByInputName(samplerNode);
  const samplerName =
    typeof samplerValues.sampler_name === "string" && samplerValues.sampler_name.trim().length > 0
      ? samplerValues.sampler_name.trim()
      : "sa_solver";
  const scheduler =
    typeof samplerValues.scheduler === "string" && samplerValues.scheduler.trim().length > 0
      ? samplerValues.scheduler.trim()
      : "beta";
  const steps = stageIndex <= 1 ? 4 : maskedInpaint ? 8 : 6;
  const cfg = stageIndex <= 1 ? 1 : maskedInpaint ? 1.18 : 1.08;
  const denoise = stageIndex <= 1 ? 1 : maskedInpaint ? 0.56 : 0.74;
  setKSamplerWidgetValues(samplerNode, {
    seed: Math.abs(Math.floor(stageSeed)),
    steps,
    cfg,
    samplerName,
    scheduler,
    denoise,
    controlAfterGenerate: "fixed"
  });
}

function findWorkflowSourceNodeByInputName(
  targetNode: WorkflowNode | undefined,
  inputName: string,
  byId: Map<number, WorkflowNode>,
  linksById: Map<number, WorkflowLink>
): WorkflowNode | undefined {
  if (!targetNode || typeof targetNode.id !== "number") return undefined;
  if (!Array.isArray(targetNode.inputs)) return undefined;
  const normalizedName = inputName.trim().toLowerCase();
  const input = targetNode.inputs.find((item) => (item?.name ?? "").trim().toLowerCase() === normalizedName);
  if (!input || typeof input.link !== "number") return undefined;
  const link = linksById.get(input.link);
  if (!link) return undefined;
  const sourceNodeId = link[1];
  if (typeof sourceNodeId !== "number") return undefined;
  const sourceNode = byId.get(sourceNodeId);
  if (!sourceNode || isNodeDisabled(sourceNode)) return undefined;
  return sourceNode;
}

function bindStoryboardComposerLoadImageInput(
  targetNode: WorkflowNode | undefined,
  inputName: string,
  path: string,
  byId: Map<number, WorkflowNode>,
  linksById: Map<number, WorkflowLink>
): boolean {
  const normalizedPath = String(path ?? "").trim();
  if (!normalizedPath) return false;
  const sourceNode = findWorkflowSourceNodeByInputName(targetNode, inputName, byId, linksById);
  if (!sourceNode) return false;
  if ((sourceNode.type ?? "").trim() !== "LoadImage") return false;
  setNodeWidgetValue(sourceNode, 0, normalizedPath);
  return true;
}

function inferStoryboardComposerPoseMode(corpus: string, slotIndex: number): string {
  const normalized = corpus.toLowerCase();
  if (/run|running|sprint|chase|奔跑|跑|冲刺|追赶/.test(normalized)) return "run";
  if (/sit|sitting|坐下|坐着/.test(normalized)) return "sit";
  if (/hands?\s*up|raise\s*hands|举手|抬手|投降|惊呼/.test(normalized)) return "hands_up";
  if (/crossed?\s*arms|arms\s*crossed|抱臂|双臂交叉/.test(normalized)) return "crossed_arms";
  if (/walk|walking|步行|走向|慢走|前行/.test(normalized)) {
    return slotIndex % 2 === 0 ? "walk_right" : "walk_left";
  }
  return "stand";
}

function inferStoryboardComposerExpressionMode(corpus: string): string {
  const normalized = corpus.toLowerCase();
  if (/shout|yell|scream|怒吼|大喊/.test(normalized)) return "shouting";
  if (/angry|anger|furious|生气|愤怒/.test(normalized)) return "angry";
  if (/sad|upset|cry|悲伤|难过/.test(normalized)) return "sad";
  if (/surprise|surprised|shock|惊讶|震惊/.test(normalized)) return "surprised";
  if (/happy|smile|开心|高兴|微笑/.test(normalized)) return "happy";
  return "neutral";
}

function inferStoryboardComposerFacingDirection(corpus: string, preferredView: string, slotIndex: number): string {
  const normalized = corpus.toLowerCase();
  if (/back|behind|背影|背对|背面/.test(normalized) || preferredView === "back") return "back";
  if (/left|向左|左侧|左边/.test(normalized)) return "left";
  if (/right|向右|右侧|右边/.test(normalized)) return "right";
  if (preferredView === "side") return slotIndex % 2 === 0 ? "right" : "left";
  return "front";
}

function storyboardComposerPlacementRatios(characterCount: number): number[] {
  if (characterCount <= 1) return [0.5];
  if (characterCount === 2) return [0.36, 0.68];
  if (characterCount === 3) return [0.26, 0.5, 0.74];
  return [0.2, 0.4, 0.6, 0.8];
}

function inferStoryboardComposerShotLayoutSignals(corpus: string): {
  isDialogue: boolean;
  isLocomotion: boolean;
  isCloseShot: boolean;
  isWideShot: boolean;
} {
  const normalized = corpus.toLowerCase();
  const isDialogue = /(?:dialogue|conversation|talk|speak|react|\u5bf9\u8bdd|\u4ea4\u8c08|\u8bf4\u8bdd|\u56de\u5e94|\u5bf9\u7b54|\u70b9\u5934)/u.test(
    normalized
  );
  const isLocomotion = /(?:walk|walking|run|running|\u884c\u8d70|\u6162\u8d70|\u8d70|\u8dd1|\u5954\u8dd1|\u5e76\u80a9|\u524d\u8fdb)/u.test(
    normalized
  );
  const isCloseShot = /(?:close[-\s]?up|cu\b|big close|\u7279\u5199|\u8fd1\u666f|\u534a\u8eab)/u.test(normalized);
  const isWideShot = /(?:wide|establishing|long shot|\u5168\u666f|\u8fdc\u666f|\u7fa4\u50cf)/u.test(normalized);
  return { isDialogue, isLocomotion, isCloseShot, isWideShot };
}

function storyboardComposerPlacementRatiosV2(characterCount: number, corpus: string): number[] {
  if (characterCount <= 1) return [0.5];
  const { isDialogue, isLocomotion, isWideShot } = inferStoryboardComposerShotLayoutSignals(corpus);
  if (characterCount === 2) {
    if (isWideShot) return [0.38, 0.68];
    if (isDialogue || isLocomotion) return [0.46, 0.6];
    return [0.42, 0.64];
  }
  if (characterCount === 3) {
    if (isWideShot) return [0.24, 0.5, 0.76];
    return [0.3, 0.52, 0.74];
  }
  if (isWideShot) return [0.16, 0.36, 0.58, 0.8];
  return [0.2, 0.4, 0.62, 0.82];
}

function inferStoryboardComposerFacingDirectionStrict(corpus: string, preferredView: string, slotIndex: number): string {
  const normalized = corpus.toLowerCase();
  if (/back|behind|back view|rear view/.test(normalized) || preferredView === "back") return "back";
  // Guard against false positives where "left/right" only refers to placement.
  if (
    /(left\s*profile|face\s*left|facing\s*left|turn(?:ed|ing)?\s*left|look(?:ing)?\s*left|profile\s*to\s*left)/.test(normalized)
  ) {
    return "left";
  }
  if (
    /(right\s*profile|face\s*right|facing\s*right|turn(?:ed|ing)?\s*right|look(?:ing)?\s*right|profile\s*to\s*right)/.test(normalized)
  ) {
    return "right";
  }
  if (preferredView === "side") return slotIndex % 2 === 0 ? "right" : "left";
  return "front";
}

function storyboardComposerAutoSceneHeightRatios(characterCount: number): number[] {
  if (characterCount <= 1) return [0.56];
  if (characterCount === 2) return [0.54, 0.5];
  if (characterCount === 3) return [0.52, 0.48, 0.44];
  return [0.5, 0.46, 0.42, 0.38];
}

function storyboardComposerAutoSceneHeightRatiosV2(characterCount: number, corpus: string): number[] {
  const { isDialogue, isLocomotion, isCloseShot, isWideShot } = inferStoryboardComposerShotLayoutSignals(corpus);
  if (characterCount <= 1) {
    if (isCloseShot) return [0.66];
    if (isWideShot) return [0.52];
    return [0.6];
  }
  if (characterCount === 2) {
    if (isCloseShot) return [0.64, 0.62];
    if (isWideShot) return [0.5, 0.48];
    if (isDialogue || isLocomotion) return [0.6, 0.58];
    return [0.56, 0.54];
  }
  if (characterCount === 3) {
    if (isWideShot) return [0.5, 0.46, 0.42];
    return [0.56, 0.52, 0.48];
  }
  if (isWideShot) return [0.48, 0.44, 0.4, 0.36];
  return [0.54, 0.5, 0.46, 0.42];
}

function storyboardComposerGroundYRatio(corpus: string): number {
  const { isCloseShot, isWideShot } = inferStoryboardComposerShotLayoutSignals(corpus);
  if (isCloseShot) return 0.95;
  if (isWideShot) return 0.98;
  return 0.965;
}

function inferStoryboardComposerBlockingTemplate(corpus: string, characterCount: number): string {
  const normalized = corpus.toLowerCase();
  if (characterCount <= 1) return "wide_lineup";
  if (/dialogue|talk|conversation|speak/.test(normalized)) return "dialogue_split";
  if (characterCount >= 3 && /triangle/.test(normalized)) return "triangle_focus";
  if (characterCount >= 3) return "foreground_mid_background";
  return "dialogue_split";
}

function inferStoryboardComposerPoseModeV2(corpus: string, slotIndex: number): string {
  const normalized = corpus.toLowerCase();
  if (/(?:run|running|sprint|chase|\u8dd1|\u5954\u8dd1|\u51b2\u523a|\u8ffd\u8d76)/u.test(normalized)) return "run";
  if (/(?:sit|sitting|seated|\u5750|\u5750\u4e0b|\u5750\u7740)/u.test(normalized)) return "sit";
  if (/(?:hands?\s*up|raise\s*hands|\u4e3e\u624b|\u62ac\u624b|\u60ca\u547c)/u.test(normalized)) return "hands_up";
  if (/(?:crossed?\s*arms|arms\s*crossed|\u62b1\u81c2|\u53cc\u81c2\u4ea4\u53c9)/u.test(normalized)) return "crossed_arms";
  if (/(?:walk|walking|\u8d70|\u884c\u8d70|\u6162\u8d70|\u5e76\u80a9)/u.test(normalized)) {
    return slotIndex % 2 === 0 ? "walk_right" : "walk_left";
  }
  return "stand";
}

function inferStoryboardComposerExpressionModeV2(corpus: string): string {
  const normalized = corpus.toLowerCase();
  if (/(?:shout|yell|scream|\u6012\u558a|\u5927\u558a)/u.test(normalized)) return "shouting";
  if (/(?:angry|anger|furious|\u751f\u6c14|\u6124\u6012)/u.test(normalized)) return "angry";
  if (/(?:sad|upset|cry|\u60b2\u4f24|\u96be\u8fc7)/u.test(normalized)) return "sad";
  if (/(?:surprise|surprised|shock|\u60ca\u8bb6|\u9707\u60ca)/u.test(normalized)) return "surprised";
  if (/(?:happy|smile|\u5f00\u5fc3|\u9ad8\u5174|\u5fae\u7b11)/u.test(normalized)) return "happy";
  return "neutral";
}

function inferStoryboardComposerFacingDirectionStrictV2(
  corpus: string,
  preferredView: string,
  slotIndex: number
): string {
  const normalized = corpus.toLowerCase();
  if (/(?:back|behind|back view|rear view|\u80cc\u5f71|\u80cc\u5bf9|\u80cc\u9762)/u.test(normalized) || preferredView === "back") {
    return "back";
  }
  if (
    /(?:left\s*profile|face\s*left|facing\s*left|turn(?:ed|ing)?\s*left|look(?:ing)?\s*left|profile\s*to\s*left|\u770b\u5411\u5de6|\u9762\u5411\u5de6|\u5de6\u4fa7\u8138|\u5de6\u8f6c)/u.test(
      normalized
    )
  ) {
    return "left";
  }
  if (
    /(?:right\s*profile|face\s*right|facing\s*right|turn(?:ed|ing)?\s*right|look(?:ing)?\s*right|profile\s*to\s*right|\u770b\u5411\u53f3|\u9762\u5411\u53f3|\u53f3\u4fa7\u8138|\u53f3\u8f6c)/u.test(
      normalized
    )
  ) {
    return "right";
  }
  const dialogueFacing = /(?:dialogue|conversation|talk|speak|react|\u5bf9\u8bdd|\u4ea4\u8c08|\u8bf4\u8bdd|\u56de\u5e94|\u5bf9\u7b54|\u70b9\u5934)/u.test(
    normalized
  );
  if (dialogueFacing && preferredView !== "back" && preferredView !== "side") {
    return slotIndex % 2 === 0 ? "right" : "left";
  }
  if (preferredView === "side") return slotIndex % 2 === 0 ? "right" : "left";
  return "front";
}

function inferStoryboardComposerBlockingTemplateV2(corpus: string, characterCount: number): string {
  const normalized = corpus.toLowerCase();
  if (characterCount <= 1) return "wide_lineup";
  if (/(?:dialogue|talk|conversation|speak|\u5bf9\u8bdd|\u4ea4\u8c08|\u8bf4\u8bdd)/u.test(normalized)) {
    return "dialogue_split";
  }
  if (characterCount >= 3 && /(?:triangle|\u4e09\u89d2)/u.test(normalized)) return "triangle_focus";
  if (characterCount >= 3) return "foreground_mid_background";
  return "dialogue_split";
}

function storyboardComposerSemanticPlacementPrompts(characterCount: number): string[] {
  if (characterCount <= 1) return ["center midground, main subject, natural stance"];
  if (characterCount === 2) {
    return [
      "left midground, main subject, natural stance, keep safe margin",
      "right midground, reacting subject, natural stance, keep safe margin"
    ];
  }
  if (characterCount === 3) {
    return [
      "left foreground, main subject, closer to camera",
      "center midground, supporting subject, natural reaction",
      "right background, observing subject, smaller scale"
    ];
  }
  return [
    "left foreground, main subject, closer to camera",
    "left midground, supporting subject",
    "right midground, supporting subject",
    "right background, observing subject"
  ];
}

type StoryboardComposerMaskScope = "all_subjects" | "new_subjects";
type StoryboardComposerQualityMode = "natural" | "strict" | "blend";
type StoryboardComposerQualityProfile = {
  qualityMode: StoryboardComposerQualityMode;
  maskScope: StoryboardComposerMaskScope;
  refineSteps: number;
  refineCfg: number;
  refineDenoise: number;
  maskGrow: number;
  maskFeather: number;
  samplerName: string;
  scheduler: string;
};

function clampStoryboardComposerNumber(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function parseStoryboardComposerNumberToken(
  value: string | undefined,
  min: number,
  max: number
): number | undefined {
  const parsed = Number.parseFloat(String(value ?? "").trim());
  if (!Number.isFinite(parsed)) return undefined;
  return clampStoryboardComposerNumber(parsed, min, max);
}

function parseStoryboardComposerIntToken(
  value: string | undefined,
  min: number,
  max: number
): number | undefined {
  const parsed = Number.parseInt(String(value ?? "").trim(), 10);
  if (!Number.isFinite(parsed)) return undefined;
  return Math.round(clampStoryboardComposerNumber(parsed, min, max));
}

function normalizeStoryboardComposerQualityMode(value: string): StoryboardComposerQualityMode {
  const normalized = value.trim().toLowerCase();
  if (["strict", "identity", "identity_lock", "lock"].includes(normalized)) return "strict";
  if (["blend", "aggressive", "cinematic", "natural_plus"].includes(normalized)) return "blend";
  return "natural";
}

function normalizeStoryboardComposerMaskScope(value: string): StoryboardComposerMaskScope | undefined {
  const normalized = value.trim().toLowerCase();
  if (
    [
      "all",
      "all_subjects",
      "all_characters",
      "all_people",
      "all_roles",
      "union_all"
    ].includes(normalized)
  ) {
    return "all_subjects";
  }
  if (
    [
      "new",
      "new_subjects",
      "secondary_only",
      "new_only",
      "inject_only",
      "new_characters"
    ].includes(normalized)
  ) {
    return "new_subjects";
  }
  return undefined;
}

function resolveStoryboardComposerQualityProfile(args: {
  qualityModeToken: string;
  maskScopeToken: string;
  strictIdentityLock: boolean;
  visibleCount: number;
  corpus: string;
  tokens: Record<string, string>;
}): StoryboardComposerQualityProfile {
  const { qualityModeToken, maskScopeToken, strictIdentityLock, visibleCount, corpus, tokens } = args;
  const qualityMode = normalizeStoryboardComposerQualityMode(qualityModeToken);
  const lowerCorpus = corpus.toLowerCase();
  const isCloseShotV2 = /(?:close[-\s]?up|cu\b|big close|\u7279\u5199|\u8fd1\u666f|\u534a\u8eab)/u.test(lowerCorpus);
  const isWideShotV2 = /(?:wide|establishing|long shot|\u5168\u666f|\u8fdc\u666f|\u7fa4\u50cf)/u.test(lowerCorpus);
  const isCloseShot =
    /close[-\s]?up|cu\b|big close|特写|近景|半身/.test(lowerCorpus);
  const isWideShot =
    /wide|establishing|long shot|全景|远景|群像/.test(lowerCorpus);

  let profile: StoryboardComposerQualityProfile;
  if (qualityMode === "strict") {
    profile = {
      qualityMode,
      maskScope: "all_subjects",
      refineSteps: visibleCount >= 3 ? 16 : 14,
      refineCfg: 4.5,
      refineDenoise: visibleCount > 1 ? 0.18 : 0.16,
      maskGrow: visibleCount >= 3 ? 16 : 14,
      maskFeather: 10,
      samplerName: "euler",
      scheduler: "normal"
    };
  } else if (qualityMode === "blend") {
    profile = {
      qualityMode,
      maskScope: "all_subjects",
      refineSteps: visibleCount >= 3 ? 20 : 18,
      refineCfg: 4.7,
      refineDenoise: 0.24,
      maskGrow: visibleCount >= 3 ? 22 : 20,
      maskFeather: 12,
      samplerName: "euler",
      scheduler: "normal"
    };
  } else {
    profile = {
      qualityMode: "natural",
      maskScope: "all_subjects",
      refineSteps: visibleCount >= 3 ? 24 : 22,
      refineCfg: 4.8,
      refineDenoise: visibleCount >= 3 ? 0.26 : 0.24,
      maskGrow: visibleCount >= 3 ? 26 : 24,
      maskFeather: 14,
      samplerName: "euler",
      scheduler: "normal"
    };
  }

  if (strictIdentityLock && qualityMode !== "blend") {
    profile.refineDenoise = Math.min(profile.refineDenoise, visibleCount > 1 ? 0.26 : 0.2);
    profile.refineCfg = Math.min(profile.refineCfg, 5.2);
  }

  if (isCloseShotV2 || isCloseShot) {
    profile.refineDenoise = Math.max(0.16, profile.refineDenoise - 0.02);
    profile.maskGrow = Math.max(10, profile.maskGrow - 2);
  } else if (isWideShotV2 || isWideShot) {
    profile.refineDenoise = Math.min(0.36, profile.refineDenoise + 0.04);
    profile.maskGrow = Math.min(30, profile.maskGrow + 2);
  }

  const parsedMaskScope = normalizeStoryboardComposerMaskScope(maskScopeToken);
  if (parsedMaskScope) profile.maskScope = parsedMaskScope;

  const overrideSteps = parseStoryboardComposerIntToken(tokens.STORYBOARD_COMPOSER_REFINE_STEPS, 6, 40);
  const overrideCfg = parseStoryboardComposerNumberToken(tokens.STORYBOARD_COMPOSER_REFINE_CFG, 1.5, 12);
  const overrideDenoise = parseStoryboardComposerNumberToken(tokens.STORYBOARD_COMPOSER_REFINE_DENOISE, 0.05, 1);
  const overrideMaskGrow = parseStoryboardComposerIntToken(tokens.STORYBOARD_COMPOSER_MASK_GROW, 2, 64);
  const overrideMaskFeather = parseStoryboardComposerIntToken(tokens.STORYBOARD_COMPOSER_MASK_FEATHER, 0, 64);
  const overrideSampler = String(tokens.STORYBOARD_COMPOSER_REFINE_SAMPLER ?? "").trim();
  const overrideScheduler = String(tokens.STORYBOARD_COMPOSER_REFINE_SCHEDULER ?? "").trim();

  if (overrideSteps !== undefined) profile.refineSteps = overrideSteps;
  if (overrideCfg !== undefined) profile.refineCfg = overrideCfg;
  if (overrideDenoise !== undefined) profile.refineDenoise = overrideDenoise;
  if (overrideMaskGrow !== undefined) profile.maskGrow = overrideMaskGrow;
  if (overrideMaskFeather !== undefined) profile.maskFeather = overrideMaskFeather;
  if (overrideSampler) profile.samplerName = overrideSampler;
  if (overrideScheduler) profile.scheduler = overrideScheduler;

  return profile;
}

function buildStoryboardComposerStructuredPrompt(args: {
  shotTitle: string;
  promptText: string;
  dialogueText: string;
  characterNames: string[];
}): string {
  const { shotTitle, promptText, dialogueText, characterNames } = args;
  const cleanedNames = characterNames
    .map((name) => String(name ?? "").trim())
    .filter((name) => name.length > 0);
  const characterCount = Math.max(1, cleanedNames.length);
  const subjectLine =
    characterCount <= 1
      ? `exactly one visible character: ${cleanedNames[0] ?? "main character"}`
      : `exactly ${characterCount} visible characters: ${cleanedNames.join(", ")}`;
  const sceneHint = [shotTitle, promptText].find((item) => String(item ?? "").trim().length > 0) ?? "riverside cinematic storyboard scene";
  const actionHint = dialogueText.trim().length > 0 ? dialogueText.trim() : promptText.trim() || shotTitle.trim();
  return [
    "Goal: cinematic storyboard keyframe with natural anatomy and clean composition.",
    `Scene: ${sceneHint}.`,
    "Camera: eye-level medium-wide shot, stable perspective, full-body framing for all visible characters.",
    `Subjects: ${subjectLine}.`,
    `Action: ${actionHint || "natural conversational motion with grounded feet and relaxed hands"}.`,
    "Identity lock: preserve each character's face, hairstyle, outfit, and body proportions from turnaround references.",
    "For multi-character shots: keep each character visually distinct and preserve stable relative scale.",
    "Composition: readable faces and hands, clean silhouettes, no body cropping, no floating limbs.",
    "Body integrity: keep each visible character complete from head to toe unless close-up is explicitly requested.",
    "Lighting: coherent scene lighting and contact shadows, no sticker-like white edge.",
    "Rendering: single coherent frame, consistent line quality and shading, avoid pasted cutout artifacts.",
    "Constraints: no extra people, no duplicate heads, no extra arms, no extra legs, no collage artifacts."
  ].join("\n");
}

function buildStoryboardComposerStructuredNegativePrompt(baseNegativePrompt: string): string {
  return [
    baseNegativePrompt.trim(),
    "extra people",
    "duplicate character",
    "extra arms",
    "extra legs",
    "duplicate head",
    "missing hands",
    "missing feet",
    "warped anatomy",
    "cropped body",
    "ghost limbs",
    "face mask",
    "medical mask",
    "double exposure",
    "sticker edge",
    "white halo",
    "collage",
    "dirty artifacts",
    "watermark",
    "text"
  ]
    .filter((item) => item.length > 0)
    .join(", ");
}

function buildStoryboardComposerCharacterSlots(tokens: Record<string, string>): StoryboardComposerCharacterSlot[] {
  const slots: StoryboardComposerCharacterSlot[] = [];
  for (const slotIndex of [1, 2, 3, 4] as const) {
    const name = String(tokens[`CHAR${slotIndex}_NAME`] ?? "").trim();
    const primaryPath = slotIndex <= 2 ? String(tokens[`CHAR${slotIndex}_PRIMARY_PATH`] ?? "").trim() : "";
    const secondaryPath = slotIndex <= 2 ? String(tokens[`CHAR${slotIndex}_SECONDARY_PATH`] ?? "").trim() : "";
    const frontCandidates = [
      String(tokens[`CHAR${slotIndex}_FRONT_PATH`] ?? "").trim(),
      primaryPath,
      secondaryPath,
      String(tokens[`CHAR${slotIndex}_SIDE_PATH`] ?? "").trim(),
      String(tokens[`CHAR${slotIndex}_BACK_PATH`] ?? "").trim()
    ].filter((item) => item.length > 0);
    const frontPath = frontCandidates[0] ?? "";
    const sidePath = String(tokens[`CHAR${slotIndex}_SIDE_PATH`] ?? "").trim() || frontPath;
    const backPath = String(tokens[`CHAR${slotIndex}_BACK_PATH`] ?? "").trim() || frontPath;
    const faceRefPath = String(tokens[`CHAR${slotIndex}_FACE_REF_PATH`] ?? "").trim();
    const detailRefPath = String(tokens[`CHAR${slotIndex}_DETAIL_REF_PATH`] ?? "").trim();
    // Keep reference_image anchored to full-body sources first.
    // Face/detail refs are supplementary and should not drive whole-body warping.
    const referencePath = primaryPath || frontPath || sidePath || backPath || detailRefPath || faceRefPath;
    const sideViewDirection = resolveStoryboardComposerSideViewDirection(tokens, slotIndex, sidePath);
    const mirrorSideForOpposite = resolveStoryboardComposerMirrorSideForOpposite(tokens, slotIndex);
    const hasAnyPath = Boolean(frontPath || sidePath || backPath || referencePath);
    if (!hasAnyPath && !name) continue;
    slots.push({
      slotIndex,
      name: name || `character_${slotIndex}`,
      frontPath,
      sidePath,
      backPath,
      referencePath,
      faceRefPath,
      detailRefPath,
      sideViewDirection,
      mirrorSideForOpposite
    });
  }
  return slots;
}

function applyStoryboardComposerBindings(
  workflow: Record<string, unknown>,
  tokens: Record<string, string>,
  kind: "image" | "video" | "audio"
): boolean {
  if (kind !== "image") return false;
  if (!isStoryboardComposerWorkflow(workflow)) return false;
  const nodes = workflowNodes(workflow);
  if (nodes.length === 0) return false;

  const byId = new Map<number, WorkflowNode>();
  for (const node of nodes) {
    if (typeof node.id === "number") byId.set(node.id, node);
  }
  const linksById = new Map<number, WorkflowLink>();
  for (const link of workflowLinks(workflow)) {
    if (Array.isArray(link) && typeof link[0] === "number") {
      linksById.set(link[0], link);
    }
  }

  const parseRenderToken = (value: string | undefined, fallback: number) => {
    const parsed = Number.parseInt(String(value ?? "").trim(), 10);
    if (!Number.isFinite(parsed)) return fallback;
    return Math.max(256, Math.min(4096, snapRenderSize(parsed)));
  };
  const renderWidth = parseRenderToken(tokens.RENDER_WIDTH, 1280);
  const renderHeight = parseRenderToken(tokens.RENDER_HEIGHT, 720);
  const scenePath = String(tokens.SCENE_REF_PATH ?? "").trim();
  const sceneForegroundMaskPath = String(tokens.SCENE_FOREGROUND_MASK_PATH ?? "").trim();
  const shotTitle = String(tokens.SHOT_TITLE ?? "").trim();
  const promptText = String(tokens.PROMPT || tokens.NEXT_SCENE_PROMPT || "").trim();
  const safeShotId = sanitizePathSegment(String(tokens.SHOT_ID ?? "").trim() || "shot");
  const storyboardModel = String(tokens.STORYBOARD_IMAGE_MODEL ?? "").trim();
  const baseSeed = Number.parseInt(String(tokens.SEED ?? "").trim(), 10);
  const safeSeed = Number.isFinite(baseSeed) ? Math.abs(baseSeed) : Math.abs(stableNumericId(`${safeShotId}|composer_sampling`));
  const dialogueText = String(tokens.DIALOGUE ?? "").trim();
  const preferredView = String(tokens.PREFERRED_CHARACTER_VIEW ?? "").trim().toLowerCase();
  // StoryboardComposer does not rely on legacy clean_pose/openpose staging.
  tokens.POSE_GUIDE_PATH = "";
  tokens.PASS_A_POSE_GUIDE_PATH = "";
  tokens.PASS_B_POSE_GUIDE_PATH = "";
  tokens.STORYBOARD_POSE_GUIDE_MODE = "none";
  tokens.STORYBOARD_ACTION_REF_PATH = "";
  const corpus = compactTextParts(shotTitle, promptText, dialogueText);
  const expressionMode = inferStoryboardComposerExpressionModeV2(corpus);

  const sceneNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardSceneNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const saveNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "SaveImage")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));

  for (const sceneNode of sceneNodes) {
    setNodeWidgetValue(sceneNode, 0, renderWidth);
    setNodeWidgetValue(sceneNode, 1, renderHeight);
    const cameraHint = (shotTitle || promptText || "medium shot, eye-level camera").slice(0, 220);
    setNodeWidgetValue(sceneNode, 3, cameraHint.slice(0, 220));
    if (scenePath) {
      bindStoryboardComposerLoadImageInput(sceneNode, "scene_image", scenePath, byId, linksById);
    }
    if (sceneForegroundMaskPath) {
      bindStoryboardComposerLoadImageInput(sceneNode, "foreground_mask", sceneForegroundMaskPath, byId, linksById);
      setNodeWidgetValue(sceneNode, 4, 8);
      setNodeWidgetValue(sceneNode, 5, 1);
    }
  }

  const imagePrefix = `Storyboard/image_asset_guided_${safeShotId}`;
  saveNodes.forEach((node, index) => {
    setNodeWidgetValue(node, 0, index === 0 ? imagePrefix : `${imagePrefix}_${index + 1}`);
  });

  const characterSlots = buildStoryboardComposerCharacterSlots(tokens);
  for (const slot of characterSlots) {
    tokens[`CHAR${slot.slotIndex}_SIDE_VIEW_DIRECTION`] = slot.sideViewDirection;
    tokens[`CHAR${slot.slotIndex}_MIRROR_SIDE_FOR_OPPOSITE`] = slot.mirrorSideForOpposite ? "1" : "0";
  }
  const allVisibleSlots = characterSlots.filter((slot) => slot.frontPath.length > 0 || slot.referencePath.length > 0);
  const requestedActiveCountRaw = Number.parseInt(String(tokens.STORYBOARD_COMPOSER_ACTIVE_CHAR_COUNT ?? "").trim(), 10);
  const requestedActiveCount = Number.isFinite(requestedActiveCountRaw)
    ? Math.max(1, Math.min(4, requestedActiveCountRaw))
    : 0;
  const visibleSlots =
    requestedActiveCount > 0 ? allVisibleSlots.slice(0, requestedActiveCount) : allVisibleSlots;
  const fallbackSlot = visibleSlots[0] ?? characterSlots[0];
  if (!fallbackSlot) {
    return true;
  }
  const visibleCharacterNames = visibleSlots.map((slot) => slot.name);
  const structuredStoryboardPrompt = buildStoryboardComposerStructuredPrompt({
    shotTitle,
    promptText,
    dialogueText,
    characterNames: visibleCharacterNames
  });
  const structuredNegativePrompt = buildStoryboardComposerStructuredNegativePrompt(
    String(tokens.NEGATIVE_PROMPT ?? "")
  );

  const turnaroundNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardTurnaroundCharacterNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const poseNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardPoseNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const specNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardCharacterSpecNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const renderNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardCharacterRenderNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const conditioningBridgeNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardConditioningBridgeNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const emptyLatentNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "EmptyLatentImage")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const samplerNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "KSampler")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const checkpointNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "CheckpointLoaderSimple")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const vaeDecodeNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "VAEDecode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const maskCompositeNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "MaskComposite")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const growMaskNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "GrowMask")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const featherMaskNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "FeatherMask")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const inpaintConditioningNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "InpaintModelConditioning")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const colorKeyNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardColorKeyMaskNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const autoPlacementNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardAutoPlacementNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const semanticPlacementNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardSemanticPlacementNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const blockingTemplateNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardBlockingTemplateNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const layoutAssistNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "StoryboardLayoutAssistNode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const clipTextEncodeNodes = nodes
    .filter((node) => !isNodeDisabled(node) && (node.type ?? "").trim() === "CLIPTextEncode")
    .sort((left, right) => (left.id ?? 0) - (right.id ?? 0));
  const visibleCount = Math.max(1, Math.min(4, visibleSlots.length || 1));
  const placementRatios = storyboardComposerPlacementRatiosV2(visibleCount, corpus);
  const autoHeightRatios = storyboardComposerAutoSceneHeightRatiosV2(visibleCount, corpus);
  const groundYRatio = storyboardComposerGroundYRatio(corpus);
  const semanticPlacementPrompts = storyboardComposerSemanticPlacementPrompts(visibleCount);
  const blockingTemplate = inferStoryboardComposerBlockingTemplateV2(corpus, visibleCount);
  const conditioningBridgeNodeIds = new Set(
    conditioningBridgeNodes
      .map((node) => (typeof node.id === "number" ? node.id : -1))
      .filter((id) => id >= 0)
  );
  const bridgeSamplerNodes = samplerNodes.filter((samplerNode) => {
    const positiveSource = findWorkflowSourceNodeByInputName(samplerNode, "positive", byId, linksById);
    const negativeSource = findWorkflowSourceNodeByInputName(samplerNode, "negative", byId, linksById);
    if (typeof positiveSource?.id !== "number" || typeof negativeSource?.id !== "number") return false;
    return conditioningBridgeNodeIds.has(positiveSource.id) && conditioningBridgeNodeIds.has(negativeSource.id);
  });
  const bridgeSamplerNodeIds = new Set(
    bridgeSamplerNodes
      .map((node) => (typeof node.id === "number" ? node.id : -1))
      .filter((id) => id >= 0)
  );
  const refineSamplerNodes = samplerNodes.filter(
    (node) => typeof node.id === "number" && !bridgeSamplerNodeIds.has(node.id)
  );
  const bridgeDecodeNodes = vaeDecodeNodes.filter((decodeNode) => {
    const latentSource = findWorkflowSourceNodeByInputName(decodeNode, "samples", byId, linksById);
    return typeof latentSource?.id === "number" && bridgeSamplerNodeIds.has(latentSource.id);
  });
  const useSamplingBridge =
    conditioningBridgeNodes.length > 0 && bridgeSamplerNodes.length > 0 && checkpointNodes.length > 0;
  const strictIdentityToken = String(tokens.STORYBOARD_COMPOSER_STRICT_IDENTITY ?? "").trim();
  const sourceImageSecondaryToken = String(tokens.STORYBOARD_COMPOSER_SOURCE_IMAGE_SECONDARY ?? "").trim();
  const qualityModeToken = String(tokens.STORYBOARD_COMPOSER_QUALITY_MODE ?? "").trim();
  const maskScopeToken = String(tokens.STORYBOARD_COMPOSER_MASK_SCOPE ?? "").trim();
  const allowSecondarySourceImage = sourceImageSecondaryToken === "1";
  const strictIdentityLock =
    strictIdentityToken.length > 0
      ? strictIdentityToken !== "0"
      : true;
  const qualityProfile = resolveStoryboardComposerQualityProfile({
    qualityModeToken,
    maskScopeToken,
    strictIdentityLock,
    visibleCount,
    corpus,
    tokens
  });
  tokens.STORYBOARD_COMPOSER_STRICT_IDENTITY = strictIdentityLock ? "1" : "0";
  tokens.STORYBOARD_COMPOSER_QUALITY_MODE = qualityProfile.qualityMode;
  tokens.STORYBOARD_COMPOSER_MASK_SCOPE = qualityProfile.maskScope;
  tokens.STORYBOARD_COMPOSER_REFINE_STEPS = String(qualityProfile.refineSteps);
  tokens.STORYBOARD_COMPOSER_REFINE_CFG = qualityProfile.refineCfg.toFixed(2);
  tokens.STORYBOARD_COMPOSER_REFINE_DENOISE = qualityProfile.refineDenoise.toFixed(2);
  tokens.STORYBOARD_COMPOSER_MASK_GROW = String(qualityProfile.maskGrow);
  tokens.STORYBOARD_COMPOSER_MASK_FEATHER = String(qualityProfile.maskFeather);
  const viewSelectionPolicyToken = String(tokens.STORYBOARD_COMPOSER_VIEW_POLICY ?? "").trim().toLowerCase();
  const viewSelectionPolicy =
    viewSelectionPolicyToken === "pose_only" || viewSelectionPolicyToken === "scene_only"
      ? viewSelectionPolicyToken
      : "scene_then_pose";

  const toggleCharacterBranchNodes = (branchNodes: WorkflowNode[]) => {
    branchNodes.forEach((node, index) => {
      setNodeEnabled(node, index < visibleCount);
    });
  };
  const rewireMaskInput = (
    targetNode: WorkflowNode | undefined,
    inputName: string,
    sourceNode: WorkflowNode | undefined,
    sourceSlot: number
  ) => {
    if (!targetNode || typeof targetNode.id !== "number" || !Array.isArray(targetNode.inputs)) return;
    const inputIndex = targetNode.inputs.findIndex((input) => (input?.name ?? "").trim() === inputName);
    if (inputIndex < 0) return;
    removeIncomingLinks(workflow, targetNode.id, [inputIndex]);
    if (!sourceNode || typeof sourceNode.id !== "number") return;
    ensureWorkflowLink(workflow, sourceNode.id, sourceSlot, targetNode.id, inputIndex, "MASK");
  };
  toggleCharacterBranchNodes(turnaroundNodes);
  toggleCharacterBranchNodes(poseNodes);
  toggleCharacterBranchNodes(specNodes);
  toggleCharacterBranchNodes(renderNodes);
  toggleCharacterBranchNodes(colorKeyNodes);
  toggleCharacterBranchNodes(autoPlacementNodes);
  toggleCharacterBranchNodes(semanticPlacementNodes);
  toggleCharacterBranchNodes(conditioningBridgeNodes);
  toggleCharacterBranchNodes(emptyLatentNodes);
  toggleCharacterBranchNodes(bridgeSamplerNodes);
  toggleCharacterBranchNodes(bridgeDecodeNodes);

  if (strictIdentityLock) {
    conditioningBridgeNodes.forEach((node) => setNodeEnabled(node, false));
    emptyLatentNodes.forEach((node) => setNodeEnabled(node, false));
    bridgeSamplerNodes.forEach((node) => setNodeEnabled(node, false));
    bridgeDecodeNodes.forEach((node) => setNodeEnabled(node, false));
  }

  const renderCharacterWidth = Math.max(256, Math.min(768, snapRenderSize(Math.round(renderWidth * 0.275))));
  const renderCharacterHeight = Math.max(768, Math.min(1536, snapRenderSize(Math.round(renderHeight * 1.42))));
  const samplingWidth = Math.max(768, Math.min(1024, snapRenderSize(Math.round(renderCharacterWidth * 2.2))));
  const samplingHeight = Math.max(960, Math.min(1536, snapRenderSize(Math.round(renderCharacterHeight * 1.12))));
  const posePreviewHeight = Math.max(512, Math.min(1152, snapRenderSize(Math.round(renderHeight * 1.06))));
  const posePreviewWidth = Math.max(256, Math.min(768, snapRenderSize(Math.round(posePreviewHeight * 0.5))));
  const accentColors = ["#547AA5", "#D99D5E", "#7A8C63", "#8A7CB5"];

  if (useSamplingBridge) {
    const firstWidgetText = (node: WorkflowNode): string => {
      const widgets = node.widgets_values as unknown;
      if (!Array.isArray(widgets)) return "";
      return String(widgets[0] ?? "");
    };
    checkpointNodes.forEach((node) => {
      if (storyboardModel) setNodeWidgetValue(node, 0, storyboardModel);
    });
    const positiveEncodeNode =
      clipTextEncodeNodes.find((node) => !firstWidgetText(node).toLowerCase().includes("negative")) ??
      clipTextEncodeNodes[0];
    const negativeEncodeNode =
      clipTextEncodeNodes.find((node) => firstWidgetText(node).toLowerCase().includes("negative")) ??
      clipTextEncodeNodes[1];
    if (positiveEncodeNode) {
      const finalPositivePrompt = [
        structuredStoryboardPrompt,
        "When refining, preserve overall composition and camera framing.",
        "If a mask is present, edit only inside the mask and keep all unmasked pixels unchanged.",
        "Do not alter the primary character identity, costume, or silhouette outside masked regions."
      ].join("\n");
      setNodeWidgetValue(positiveEncodeNode, 0, finalPositivePrompt.slice(0, 900));
    }
    if (negativeEncodeNode) {
      const finalNegativePrompt = structuredNegativePrompt;
      setNodeWidgetValue(negativeEncodeNode, 0, finalNegativePrompt.slice(0, 900));
    }
    if (!strictIdentityLock) {
      conditioningBridgeNodes.forEach((node, index) => {
        setNodeWidgetValue(node, 0, samplingWidth);
        setNodeWidgetValue(node, 1, samplingHeight);
        const slot = visibleSlots[index] ?? fallbackSlot;
        const slotName = slot?.name || `character_${index + 1}`;
        const positivePrefix = structuredStoryboardPrompt;
        setNodeWidgetValue(node, 2, positivePrefix.slice(0, 320));
        setNodeWidgetValue(
          node,
          3,
          [
            `single character render: ${slotName}.`,
            "full body, natural anatomy, complete hands and feet, transparent background.",
            "preserve exact identity and outfit from turnaround references.",
            "clean silhouette, no halo, no cropping."
          ].join(" ")
        );
        setNodeWidgetValue(node, 4, structuredNegativePrompt.slice(0, 320));
        setNodeWidgetValue(
          node,
          5,
          "extra people, extra limbs, deformed body, sticker edge, white outline, halo, cropped body, messy artifacts, fragmented body, broken hands, broken feet"
        );
        setNodeWidgetValue(node, 6, true);
        setNodeWidgetValue(node, 7, false);
      });
      emptyLatentNodes.forEach((node) => {
        setNodeWidgetValue(node, 0, samplingWidth);
        setNodeWidgetValue(node, 1, samplingHeight);
        setNodeWidgetValue(node, 2, 1);
      });
      bridgeSamplerNodes.forEach((node, index) => {
        setKSamplerWidgetValues(node, {
          seed: safeSeed + index * 101,
          steps: 24,
          cfg: 6.2,
          samplerName: "euler",
          scheduler: "normal",
          denoise: 1,
          controlAfterGenerate: "fixed"
        });
      });
    }
    refineSamplerNodes.forEach((node, index) => {
      setKSamplerWidgetValues(node, {
        seed: safeSeed + 9000 + index * 131,
        steps: qualityProfile.refineSteps,
        cfg: qualityProfile.refineCfg,
        samplerName: qualityProfile.samplerName,
        scheduler: qualityProfile.scheduler,
        denoise: qualityProfile.refineDenoise,
        controlAfterGenerate: "fixed"
      });
    });
    maskCompositeNodes.forEach((node) => {
      setNodeWidgetValue(node, 0, 0);
      setNodeWidgetValue(node, 1, 0);
      setNodeWidgetValue(node, 2, "add");
    });
    growMaskNodes.forEach((node) => {
      setNodeWidgetValue(node, 0, qualityProfile.maskGrow);
      setNodeWidgetValue(node, 1, true);
    });
    featherMaskNodes.forEach((node) => {
      setNodeWidgetValue(node, 0, qualityProfile.maskFeather);
      setNodeWidgetValue(node, 1, qualityProfile.maskFeather);
      setNodeWidgetValue(node, 2, qualityProfile.maskFeather);
      setNodeWidgetValue(node, 3, qualityProfile.maskFeather);
    });
    inpaintConditioningNodes.forEach((node) => {
      setNodeWidgetValue(node, 0, true);
    });

    const maskCompositeA = maskCompositeNodes[0];
    const maskCompositeB = maskCompositeNodes[1];
    const growMaskNode = growMaskNodes[0];
    const featherMaskNode = featherMaskNodes[0];
    const inpaintNode = inpaintConditioningNodes[0];
    const primaryPlacement = autoPlacementNodes[0];
    const secondaryPlacement = autoPlacementNodes[1];
    const tertiaryPlacement = autoPlacementNodes[2];
    const quaternaryPlacement = autoPlacementNodes[3];

    const allPlacementMasks = [primaryPlacement, secondaryPlacement, tertiaryPlacement, quaternaryPlacement].filter(
      (node): node is WorkflowNode => Boolean(node) && !isNodeDisabled(node)
    );
    const newSubjectMasks = [secondaryPlacement, tertiaryPlacement, quaternaryPlacement].filter(
      (node): node is WorkflowNode => Boolean(node) && !isNodeDisabled(node)
    );
    const preferredMasks =
      qualityProfile.maskScope === "all_subjects"
        ? allPlacementMasks
        : newSubjectMasks.length > 0
          ? newSubjectMasks
          : allPlacementMasks;
    const selectedMasks = preferredMasks.slice(0, 3);

    let baseMaskSourceNode: WorkflowNode | undefined;
    let baseMaskSourceSlot = 0;
    const canUseMaskCompositeA = selectedMasks.length >= 2 && Boolean(maskCompositeA);
    if (maskCompositeA) {
      setNodeEnabled(maskCompositeA, canUseMaskCompositeA);
      if (canUseMaskCompositeA) {
        rewireMaskInput(maskCompositeA, "destination", selectedMasks[0], 2);
        rewireMaskInput(maskCompositeA, "source", selectedMasks[1], 2);
        baseMaskSourceNode = maskCompositeA;
        baseMaskSourceSlot = 0;
      } else if (typeof maskCompositeA.id === "number") {
        removeIncomingLinks(workflow, maskCompositeA.id, [0, 1]);
      }
    }

    const canUseMaskCompositeBForUnion = canUseMaskCompositeA && selectedMasks.length >= 3 && Boolean(maskCompositeB);
    if (maskCompositeB && canUseMaskCompositeBForUnion) {
      setNodeEnabled(maskCompositeB, true);
      setNodeWidgetValue(maskCompositeB, 2, "add");
      rewireMaskInput(maskCompositeB, "destination", maskCompositeA, 0);
      rewireMaskInput(maskCompositeB, "source", selectedMasks[2], 2);
      baseMaskSourceNode = maskCompositeB;
      baseMaskSourceSlot = 0;
    } else if (!baseMaskSourceNode) {
      baseMaskSourceNode = selectedMasks[0] ?? primaryPlacement;
      baseMaskSourceSlot = baseMaskSourceNode ? 2 : 0;
    }

    if (growMaskNode) {
      setNodeEnabled(growMaskNode, Boolean(baseMaskSourceNode));
      rewireMaskInput(growMaskNode, "mask", baseMaskSourceNode, baseMaskSourceSlot);
    }

    const canUseEdgeRingMask =
      Boolean(baseMaskSourceNode) && Boolean(growMaskNode) && Boolean(maskCompositeB) && !canUseMaskCompositeBForUnion;
    const edgeMaskSourceNode = canUseEdgeRingMask ? maskCompositeB : undefined;
    if (maskCompositeB && !canUseMaskCompositeBForUnion) {
      setNodeEnabled(maskCompositeB, Boolean(canUseEdgeRingMask));
      if (canUseEdgeRingMask) {
        // Prefer a local contour ring (dilated mask minus original mask) so pass-B inpaint
        // repairs integration edges instead of repainting full character interiors.
        setNodeWidgetValue(maskCompositeB, 2, "subtract");
        rewireMaskInput(maskCompositeB, "destination", growMaskNode, 0);
        rewireMaskInput(maskCompositeB, "source", baseMaskSourceNode, baseMaskSourceSlot);
      } else if (typeof maskCompositeB.id === "number") {
        removeIncomingLinks(workflow, maskCompositeB.id, [0, 1]);
      }
    }

    if (featherMaskNode) {
      const featherInputNode =
        edgeMaskSourceNode && !isNodeDisabled(edgeMaskSourceNode)
          ? edgeMaskSourceNode
          : growMaskNode && !isNodeDisabled(growMaskNode)
            ? growMaskNode
            : baseMaskSourceNode;
      setNodeEnabled(featherMaskNode, Boolean(featherInputNode));
      rewireMaskInput(
        featherMaskNode,
        "mask",
        featherInputNode,
        featherInputNode === baseMaskSourceNode ? baseMaskSourceSlot : 0
      );
    }
    if (inpaintNode) {
      const maskDriverNode =
        featherMaskNode && !isNodeDisabled(featherMaskNode)
          ? featherMaskNode
          : edgeMaskSourceNode && !isNodeDisabled(edgeMaskSourceNode)
            ? edgeMaskSourceNode
            : growMaskNode && !isNodeDisabled(growMaskNode)
              ? growMaskNode
              : baseMaskSourceNode;
      const maskDriverSlot = maskDriverNode === baseMaskSourceNode ? baseMaskSourceSlot : 0;
      const hasMaskDriver = Boolean(maskDriverNode);
      setNodeEnabled(inpaintNode, hasMaskDriver);
      if (hasMaskDriver) {
        rewireMaskInput(inpaintNode, "mask", maskDriverNode, maskDriverSlot);
      } else if (typeof inpaintNode.id === "number") {
        removeIncomingLinks(workflow, inpaintNode.id, [2]);
      }
    }
  } else {
    // If sampling bridge does not exist in current graph, force-disable mask/inpaint aux path
    // to avoid prompt validation errors from missing required mask inputs.
    maskCompositeNodes.forEach((node) => {
      setNodeEnabled(node, false);
      if (typeof node.id === "number") removeIncomingLinks(workflow, node.id, [0, 1]);
    });
    growMaskNodes.forEach((node) => {
      setNodeEnabled(node, false);
      if (typeof node.id === "number") removeIncomingLinks(workflow, node.id, [0]);
    });
    featherMaskNodes.forEach((node) => {
      setNodeEnabled(node, false);
      if (typeof node.id === "number") removeIncomingLinks(workflow, node.id, [0]);
    });
    inpaintConditioningNodes.forEach((node) => {
      setNodeEnabled(node, false);
      if (typeof node.id === "number") removeIncomingLinks(workflow, node.id, [2]);
    });
  }

  for (const blockingNode of blockingTemplateNodes) {
    setNodeWidgetValue(blockingNode, 0, blockingTemplate);
    setNodeWidgetValue(blockingNode, 1, visibleCount);
  }

  for (let index = 0; index < turnaroundNodes.length; index += 1) {
    const slot = visibleSlots[index] ?? fallbackSlot;
    const isVisibleCharacter = index < visibleSlots.length;
    const slotName = slot.name || `character_${index + 1}`;
    const frontPath = slot.frontPath || slot.referencePath;
    const sidePath = slot.sidePath || frontPath;
    const backPath = slot.backPath || frontPath;
    const referencePath = slot.referencePath || frontPath;
    const faceIdentityLine = slot.faceRefPath
      ? "preserve exact face proportions, eyes, eyebrows, nose and mouth spacing from face reference"
      : "preserve exact facial identity from turnaround references";
    const positivePrompt = [
      promptText,
      `${slotName}, keep exact identity from turnaround references`,
      "full body, clean anatomy, natural pose, clear facial details, stable clothing",
      faceIdentityLine
    ]
      .filter((item) => item.length > 0)
      .join(", ");
    const negativePrompt = [
      String(tokens.NEGATIVE_PROMPT ?? "").trim(),
      "extra people, extra arms, extra legs, deformed body, cropped body, blur, ghosting, artifacts"
    ]
      .filter((item) => item.length > 0)
      .join(", ");
    const costumePrompt =
      slot.detailRefPath.length > 0
        ? "match exact outfit and accessories from turnaround plus detail reference"
        : "match exact outfit and accessories from turnaround references";
    const expressionPrompt =
      dialogueText.length > 0
        ? `match dialogue emotion naturally: ${dialogueText.slice(0, 100)}`
        : `${expressionMode} expression, clean and readable face`;

    const turnaroundNode = turnaroundNodes[index];
    setNodeWidgetValue(turnaroundNode, 0, slotName);
    setNodeWidgetValue(turnaroundNode, 1, positivePrompt);
    setNodeWidgetValue(turnaroundNode, 2, negativePrompt);
    setNodeWidgetValue(turnaroundNode, 3, costumePrompt);
    setNodeWidgetValue(turnaroundNode, 4, expressionPrompt);
    setNodeWidgetValue(turnaroundNode, 5, 1.0);
    setNodeWidgetValue(turnaroundNode, 6, accentColors[index % accentColors.length] ?? "#547AA5");
    setNodeWidgetValue(turnaroundNode, 7, slot.sideViewDirection);
    setNodeWidgetValue(turnaroundNode, 8, slot.mirrorSideForOpposite);

    if (frontPath) bindStoryboardComposerLoadImageInput(turnaroundNode, "front_view_image", frontPath, byId, linksById);
    if (sidePath) bindStoryboardComposerLoadImageInput(turnaroundNode, "side_view_image", sidePath, byId, linksById);
    if (backPath) bindStoryboardComposerLoadImageInput(turnaroundNode, "back_view_image", backPath, byId, linksById);
    if (referencePath) bindStoryboardComposerLoadImageInput(turnaroundNode, "reference_image", referencePath, byId, linksById);

    const poseNode = poseNodes[index];
    const poseMode = inferStoryboardComposerPoseModeV2(corpus, index);
    const facingDirection = inferStoryboardComposerFacingDirectionStrictV2(corpus, preferredView, index);
    const isDialogueAction = /(?:dialogue|conversation|talk|speak|react|\u5bf9\u8bdd|\u4ea4\u8c08|\u8bf4\u8bdd|\u56de\u5e94|\u70b9\u5934)/u.test(
      corpus
    );
    const isLocomotionAction = poseMode === "walk_left" || poseMode === "walk_right" || poseMode === "run";
    const poseActionPromptBase = (promptText || shotTitle || "standing naturally").slice(0, 220);
    const isPairedInteraction = visibleCount >= 2 && isVisibleCharacter && (isDialogueAction || isLocomotionAction);
    const poseActionPrompt = isPairedInteraction
      ? index % 2 === 0
        ? `${poseActionPromptBase}, full-body natural motion, torso slightly turned inward toward partner, left arm naturally interacting near body center, grounded feet, clean hand anatomy`
        : `${poseActionPromptBase}, full-body natural motion, torso slightly turned inward toward partner, right arm naturally interacting near body center, grounded feet, clean hand anatomy`
      : isDialogueAction
        ? `${poseActionPromptBase}, subtle body turn toward the other subject, natural conversational hand gesture, relaxed shoulders`
        : isLocomotionAction
          ? `${poseActionPromptBase}, full-body motion, grounded stride, natural arm swing and weight shift`
          : `${poseActionPromptBase}, grounded feet, natural posture, balanced body weight`;
    if (poseNode) {
      setNodeWidgetValue(poseNode, 0, poseMode);
      setNodeWidgetValue(poseNode, 1, facingDirection);
      setNodeWidgetValue(poseNode, 2, expressionMode);
      setNodeWidgetValue(poseNode, 3, poseActionPrompt.slice(0, 220));
      setNodeWidgetValue(poseNode, 4, expressionPrompt.slice(0, 220));
      setNodeWidgetValue(poseNode, 5, isVisibleCharacter ? 0.85 : 0.68);
      setNodeWidgetValue(poseNode, 6, posePreviewWidth);
      setNodeWidgetValue(poseNode, 7, posePreviewHeight);
      setNodeWidgetValue(poseNode, 8, "#243447");
      setNodeWidgetValue(poseNode, 9, "#F8F3E8");
    }

    const specNode = specNodes[index];
    if (specNode) {
      setNodeWidgetValue(specNode, 0, viewSelectionPolicy);
    }

    const renderNode = renderNodes[index];
    if (renderNode) {
      const hasSamplingSource = Array.isArray(renderNode.inputs) && renderNode.inputs.some((item) => (item?.name ?? "") === "source_image");
      const useSourceImageRenderForThisSlot =
        allowSecondarySourceImage && useSamplingBridge && hasSamplingSource && !strictIdentityLock && index > 0;
      if (useSourceImageRenderForThisSlot) {
        setNodeWidgetValue(renderNode, 0, "source_image");
        setNodeWidgetValue(renderNode, 1, samplingWidth);
        setNodeWidgetValue(renderNode, 2, samplingHeight);
        setNodeWidgetValue(renderNode, 3, "#FFFFFF");
        // Keep source-image secondary injection responsive enough to follow pose,
        // while avoiding aggressive shape drift.
        setNodeWidgetValue(renderNode, 4, isVisibleCharacter ? 0.44 : 0.3);
      } else {
        const poseFitStrength = isVisibleCharacter
          ? isLocomotionAction
            ? 0.5
            : isDialogueAction
              ? 0.48
              : 0.46
          : 0.4;
        setNodeWidgetValue(renderNode, 0, "turnaround_pose_fit");
        setNodeWidgetValue(renderNode, 1, renderCharacterWidth);
        setNodeWidgetValue(renderNode, 2, renderCharacterHeight);
        setNodeWidgetValue(renderNode, 3, "#FFFFFF");
        setNodeWidgetValue(renderNode, 4, poseFitStrength);
      }
    }

    const colorKeyNode = colorKeyNodes[index];
    if (colorKeyNode) {
      if (useSamplingBridge) {
        setNodeEnabled(colorKeyNode, false);
      } else {
        setNodeWidgetValue(colorKeyNode, 0, "sample_corners");
        setNodeWidgetValue(colorKeyNode, 1, "#FFFFFF");
        setNodeWidgetValue(colorKeyNode, 2, 0.1);
        setNodeWidgetValue(colorKeyNode, 3, 2);
        setNodeWidgetValue(colorKeyNode, 4, 24);
      }
    }

    const placementNode = autoPlacementNodes[index];
    if (placementNode) {
      const xRatio = placementRatios[Math.min(index, placementRatios.length - 1)] ?? 0.5;
      const baseSceneHeightRatio = autoHeightRatios[Math.min(index, autoHeightRatios.length - 1)] ?? 0.5;
      const feetX = isVisibleCharacter ? Math.round(renderWidth * xRatio) : -4096 + index * 96;
      const groundY = Math.round(renderHeight * (isVisibleCharacter ? groundYRatio : 0.99));
      const sceneHeightRatio = isVisibleCharacter ? baseSceneHeightRatio : 0.08;
      const subjectHeight = Math.max(64, Math.round(renderHeight * sceneHeightRatio));
      setNodeWidgetValue(placementNode, 0, feetX);
      setNodeWidgetValue(placementNode, 1, groundY);
      setNodeWidgetValue(placementNode, 2, "scene_ratio");
      setNodeWidgetValue(placementNode, 3, subjectHeight);
      setNodeWidgetValue(placementNode, 4, sceneHeightRatio);
      setNodeWidgetValue(placementNode, 5, 9);
      setNodeWidgetValue(placementNode, 6, isVisibleCharacter ? index : -10 - index);
      setNodeWidgetValue(placementNode, 7, isVisibleCharacter ? 10 : 8);
      setNodeWidgetValue(placementNode, 8, isVisibleCharacter ? 0.38 : 0);
      setNodeWidgetValue(placementNode, 9, isVisibleCharacter ? slotName : `hidden_slot_${index + 1}`);
      if (useSamplingBridge && typeof renderNode?.id === "number") {
        if (typeof placementNode.id === "number") {
          removeIncomingLinks(workflow, placementNode.id, [2]);
          ensureWorkflowLink(workflow, renderNode.id, 1, placementNode.id, 2, "MASK");
        }
      }
    }

    const semanticPlacementNode = semanticPlacementNodes[index];
    if (semanticPlacementNode) {
      const semanticPrompt = semanticPlacementPrompts[Math.min(index, semanticPlacementPrompts.length - 1)] ?? "center midground";
      const promptPrefix = (shotTitle || promptText).trim();
      const placementPrompt = isVisibleCharacter
        ? `${promptPrefix ? `${promptPrefix}, ` : ""}${semanticPrompt}`
        : "outside frame, hidden background subject, no visible character";
      const subjectCount = Math.max(1, visibleCount);
      const subjectIndex = Math.min(index + 1, subjectCount);
      setNodeWidgetValue(semanticPlacementNode, 0, placementPrompt);
      setNodeWidgetValue(semanticPlacementNode, 1, subjectIndex);
      setNodeWidgetValue(semanticPlacementNode, 2, subjectCount);
      setNodeWidgetValue(semanticPlacementNode, 3, Math.round(renderHeight * 0.42));
      setNodeWidgetValue(semanticPlacementNode, 4, Math.round(renderHeight * 0.97));
      setNodeWidgetValue(semanticPlacementNode, 5, isVisibleCharacter ? 0.2 : 0.06);
      setNodeWidgetValue(semanticPlacementNode, 6, isVisibleCharacter ? 0.6 : 0.1);
      setNodeWidgetValue(semanticPlacementNode, 7, 8);
      setNodeWidgetValue(semanticPlacementNode, 8, -10);
      setNodeWidgetValue(semanticPlacementNode, 9, 10);
      setNodeWidgetValue(semanticPlacementNode, 10, 8);
      setNodeWidgetValue(semanticPlacementNode, 11, isVisibleCharacter ? 0.32 : 0);
      setNodeWidgetValue(semanticPlacementNode, 12, isVisibleCharacter ? slotName : `hidden_slot_${index + 1}`);
    }
  }

  for (const layoutNode of layoutAssistNodes) {
    setNodeWidgetValue(layoutNode, 0, 18);
    setNodeWidgetValue(layoutNode, 1, 0.18);
    setNodeWidgetValue(layoutNode, 2, 32);
    setNodeWidgetValue(layoutNode, 3, true);
    setNodeWidgetValue(layoutNode, 4, 0.9);
    setNodeWidgetValue(layoutNode, 5, true);
  }

  return true;
}

const FISHER_IMAGE_NODE_IDS = new Set([7, 8, 10, 13, 21, 49, 89, 123, 216]);
const FISHER_FIRST_LAST_VIDEO_NODE_IDS = new Set([
  126, 127, 128, 133, 134, 136, 137, 138, 139, 140, 141, 142, 144, 145, 146, 147, 148, 149,
  150, 151, 152, 153, 154, 155, 156, 157, 160, 161, 162, 164
]);
const FISHER_SINGLE_FRAME_VIDEO_NODE_IDS = new Set([
  175, 176, 177, 178, 179, 180, 182, 183, 184, 185, 186, 187, 192, 193, 194, 195, 196, 197,
  198, 201, 202, 203, 204, 205, 206, 207, 208
]);

function looksLikeFisherWorkflow(byId: Map<number, WorkflowNode>): boolean {
  return byId.has(21) && byId.has(49) && byId.has(89) && byId.has(160) && byId.has(197);
}

function bypassFisherSageAttentionNodes(
  workflow: Record<string, unknown>,
  byId: Map<number, WorkflowNode>,
  kind: "image" | "video" | "audio",
  tokens: Record<string, string>
) {
  if (!looksLikeFisherWorkflow(byId) || kind !== "video") return;
  const isFirstLast = tokens.VIDEO_MODE === "FIRST_LAST_FRAME";
  const rewires = isFirstLast
    ? [
        { sourceId: 152, patchId: 133, torchPatchId: 149, samplerTargetId: 155, samplerInput: 1 },
        { sourceId: 153, patchId: 134, torchPatchId: 154, samplerTargetId: 155, samplerInput: 0 }
      ]
    : [
        { sourceId: 203, patchId: 177, torchPatchId: 179, samplerTargetId: 196, samplerInput: 0 },
        { sourceId: 204, patchId: 178, torchPatchId: 180, samplerTargetId: 196, samplerInput: 1 }
      ];

  for (const item of rewires) {
    removeIncomingLinks(workflow, item.patchId, [0]);
    removeOutgoingLinks(workflow, item.patchId, 0);
    removeIncomingLinks(workflow, item.torchPatchId, [0]);
    removeOutgoingLinks(workflow, item.torchPatchId, 0);
    removeIncomingLinks(workflow, item.samplerTargetId, [item.samplerInput]);
    ensureWorkflowLink(workflow, item.sourceId, 0, item.samplerTargetId, item.samplerInput, "MODEL");
    deleteWorkflowNode(workflow, item.patchId);
    deleteWorkflowNode(workflow, item.torchPatchId);
  }
}

function bypassFisherSimpleMathNode(
  workflow: Record<string, unknown>,
  byId: Map<number, WorkflowNode>,
  kind: "image" | "video" | "audio",
  tokens: Record<string, string>
) {
  if (!looksLikeFisherWorkflow(byId) || kind !== "video") return;
  if (tokens.VIDEO_MODE === "FIRST_LAST_FRAME") return;

  const frameCount = Number(tokens.DURATION_FRAMES);
  const safeFrameCount = Number.isFinite(frameCount) ? Math.max(1, Math.round(frameCount)) : undefined;
  if (safeFrameCount === undefined) return;

  removeIncomingLinks(workflow, 187, [0, 1, 2, 3]);
  removeOutgoingLinks(workflow, 187, 0);
  removeOutgoingLinks(workflow, 187, 1);
  removeIncomingLinks(workflow, 197, [7]);
  ensureWorkflowLink(workflow, 201, 0, 197, 7, "INT");
  deleteWorkflowNode(workflow, 187);
}

function bypassFisherRifeNodes(
  workflow: Record<string, unknown>,
  byId: Map<number, WorkflowNode>,
  kind: "image" | "video" | "audio"
) {
  if (!looksLikeFisherWorkflow(byId) || kind !== "video") return;

  removeIncomingLinks(workflow, 148, [0]);
  ensureWorkflowLink(workflow, 141, 0, 148, 0, "IMAGE");
  deleteWorkflowNode(workflow, 142);

  removeIncomingLinks(workflow, 195, [0]);
  ensureWorkflowLink(workflow, 192, 0, 195, 0, "IMAGE");
  deleteWorkflowNode(workflow, 194);
}

function disableFisherImageStyleLoras(
  workflow: Record<string, unknown>,
  byId: Map<number, WorkflowNode>,
  kind: "image" | "video" | "audio"
) {
  if (!looksLikeFisherWorkflow(byId) || kind !== "image") return;
  const loader = byId.get(216);
  if (!loader) return;

  if (Array.isArray(loader.widgets_values)) {
    for (const item of loader.widgets_values) {
      if (!item || typeof item !== "object" || Array.isArray(item)) continue;
      if ("on" in item) {
        (item as Record<string, unknown>).on = false;
      }
      if ("strength" in item) {
        (item as Record<string, unknown>).strength = 0;
      }
      if ("strengthTwo" in item) {
        (item as Record<string, unknown>).strengthTwo = 0;
      }
    }
  }

  removeIncomingLinks(workflow, 10, [0]);
  ensureWorkflowLink(workflow, 49, 0, 10, 0, "MODEL");
  deleteWorkflowNode(workflow, 216);
}

function applyFisherWorkflowModes(
  byId: Map<number, WorkflowNode>,
  kind: "image" | "video" | "audio",
  tokens: Record<string, string>
) {
  if (!looksLikeFisherWorkflow(byId)) return;
  if (kind === "audio") return;
  if (kind === "image") {
    for (const id of FISHER_IMAGE_NODE_IDS) setNodeEnabled(byId.get(id), true);
    for (const id of FISHER_FIRST_LAST_VIDEO_NODE_IDS) setNodeEnabled(byId.get(id), false);
    for (const id of FISHER_SINGLE_FRAME_VIDEO_NODE_IDS) setNodeEnabled(byId.get(id), false);
    return;
  }

  const isFirstLast = tokens.VIDEO_MODE === "FIRST_LAST_FRAME";
  const activeVideoIds = isFirstLast ? FISHER_FIRST_LAST_VIDEO_NODE_IDS : FISHER_SINGLE_FRAME_VIDEO_NODE_IDS;
  const inactiveVideoIds = isFirstLast ? FISHER_SINGLE_FRAME_VIDEO_NODE_IDS : FISHER_FIRST_LAST_VIDEO_NODE_IDS;

  for (const id of FISHER_IMAGE_NODE_IDS) setNodeEnabled(byId.get(id), false);
  for (const id of activeVideoIds) setNodeEnabled(byId.get(id), true);
  for (const id of inactiveVideoIds) setNodeEnabled(byId.get(id), false);
}

type WorkflowLink = [number, number, number, number, number, string];

function workflowLinks(workflow: Record<string, unknown>): WorkflowLink[] {
  return Array.isArray(workflow.links) ? (workflow.links as WorkflowLink[]) : [];
}

function setWorkflowLinks(workflow: Record<string, unknown>, links: WorkflowLink[]) {
  workflow.links = links;
}

function workflowNodes(workflow: Record<string, unknown>): WorkflowNode[] {
  return Array.isArray(workflow.nodes) ? (workflow.nodes as WorkflowNode[]) : [];
}

const VIRTUAL_GRAPH_ONLY_NODE_TYPES = new Set(["SetNode", "GetNode"]);

function isVirtualGraphOnlyNodeType(type: string): boolean {
  return VIRTUAL_GRAPH_ONLY_NODE_TYPES.has(type.trim());
}

function extractWorkflowNodeTypes(workflow: Record<string, unknown>): string[] {
  const nodeTypes = workflowNodes(workflow)
    .map((node) => (typeof node.type === "string" ? node.type.trim() : ""))
    .filter((type) => type.length > 0 && !isVirtualGraphOnlyNodeType(type));
  return uniquePreserveOrder(nodeTypes);
}

function splitCsv(value: string | undefined): string[] {
  if (!value) return [];
  return value
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item.length > 0);
}

function uniquePreserveOrder(values: string[]): string[] {
  const seen = new Set<string>();
  const output: string[] = [];
  for (const value of values) {
    if (seen.has(value)) continue;
    seen.add(value);
    output.push(value);
  }
  return output;
}

function characterViewRole(view: CharacterReferenceView): WeightedImageRef["role"] {
  if (view === "front") return "character_front";
  if (view === "side") return "character_side";
  return "character_back";
}

function orderedCharacterViews(
  plan: ReturnType<typeof inferCharacterReferencePlan>
): CharacterReferenceView[] {
  return [plan.primaryView, ...plan.secondaryViews];
}

function joinNaturalChineseList(values: string[]): string {
  const filtered = values.map((item) => item.trim()).filter((item) => item.length > 0);
  if (filtered.length === 0) return "";
  if (filtered.length === 1) return filtered[0]!;
  if (filtered.length === 2) return `${filtered[0]}和${filtered[1]}`;
  return `${filtered.slice(0, -1).join("、")}和${filtered[filtered.length - 1]}`;
}

function skyboxFaceLabel(face: SkyboxFace): string {
  if (face === "front") return "正前";
  if (face === "right") return "右侧";
  if (face === "back") return "背面";
  if (face === "left") return "左侧";
  if (face === "up") return "上方";
  if (face === "down") return "下方";
  return face;
}

function characterReferenceViewLabel(view: CharacterReferenceView): string {
  if (view === "front") return "正面";
  if (view === "side") return "侧面";
  if (view === "back") return "背面";
  return view;
}

function containsKeywordWithNegativeContext(
  raw: string,
  keyword: string,
  negativePrefixes: string[]
): boolean {
  const text = raw.toLowerCase();
  const needle = keyword.toLowerCase();
  let startIndex = 0;
  while (startIndex < text.length) {
    const matchIndex = text.indexOf(needle, startIndex);
    if (matchIndex < 0) return false;
    const contextStart = Math.max(0, matchIndex - 48);
    const context = text
      .slice(contextStart, matchIndex)
      .replace(/\s+/g, " ")
      .trim();
    if (!negativePrefixes.some((prefix) => context.endsWith(prefix) || context.includes(prefix.trim()))) {
      return true;
    }
    startIndex = matchIndex + needle.length;
  }
  return false;
}

function shotCameraDescriptor(shot: Shot): string {
  const yaw = typeof shot.cameraYaw === "number" && Number.isFinite(shot.cameraYaw) ? shot.cameraYaw : undefined;
  const pitch = typeof shot.cameraPitch === "number" && Number.isFinite(shot.cameraPitch) ? shot.cameraPitch : undefined;
  const fov = typeof shot.cameraFov === "number" && Number.isFinite(shot.cameraFov) ? shot.cameraFov : undefined;
  const parts: string[] = [];
  if (yaw !== undefined) parts.push(`yaw ${yaw.toFixed(0)}°`);
  if (pitch !== undefined) parts.push(`pitch ${pitch.toFixed(0)}°`);
  if (fov !== undefined) parts.push(`fov ${fov.toFixed(0)}°`);
  return parts.join(" / ");
}

function inferCharacterReferencePlan(shot: Shot): {
  primaryView: CharacterReferenceView;
  secondaryViews: CharacterReferenceView[];
} {
  const corpus = [
    shot.title ?? "",
    shot.storyPrompt ?? "",
    shot.videoPrompt ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ]
    .join(" ")
    .toLowerCase();
  const shotScale = inferStoryboardCompositeScale(shot);

  const frontPreferred = containsAnyKeyword(corpus, [
    "正面",
    "正朝镜头",
    "朝向镜头",
    "面向镜头",
    "面对镜头",
    "正对镜头",
    "面向画面",
    "front-facing",
    "front facing",
    "facing camera",
    "toward camera",
    "towards camera",
    "mostly front-facing",
    "mostly front facing"
  ]);

  const backNegated = [
    "不要",
    "不能",
    "不是",
    "避免",
    "别",
    "禁止",
    "rather than",
    "instead of",
    "not ",
    "no ",
    "avoid ",
    "without "
  ];
  const backPositiveKeywords = [
    "背影",
    "背面",
    "背对",
    "背对镜头",
    "背身",
    "back view",
    "back-facing",
    "back facing",
    "rear view",
    "from behind",
    "seen from behind"
  ];
  const prefersBack = backPositiveKeywords.some((keyword) => containsKeywordWithNegativeContext(corpus, keyword, backNegated));
  if (frontPreferred && !prefersBack) {
    return { primaryView: "front", secondaryViews: ["side", "back"] };
  }

  const dialogueOrReactionFront = containsAnyKeyword(corpus, [
    "说话",
    "对白",
    "台词",
    "开口",
    "回应",
    "点头",
    "反应",
    "看向",
    "注视",
    "看着",
    "近景",
    "特写",
    "中近景",
    "close-up",
    "close up",
    "medium close",
    "reaction shot",
    "speaking",
    "talking",
    "looking at",
    "looking toward"
  ]);
  if (dialogueOrReactionFront && !prefersBack) {
    return { primaryView: "front", secondaryViews: ["side", "back"] };
  }

  if (prefersBack) {
    return { primaryView: "back", secondaryViews: ["side", "front"] };
  }

  const motionOrFollowingBack = containsAnyKeyword(corpus, [
    "并肩",
    "同行",
    "慢走",
    "沿河",
    "前行",
    "走向",
    "走过",
    "离去",
    "离开",
    "停步",
    "收尾",
    "背后跟拍",
    "跟拍",
    "背跟",
    "walking",
    "walk",
    "walking away",
    "follow shot",
    "following shot",
    "tracking from behind",
    "rear tracking"
  ]);
  if (motionOrFollowingBack && shotScale !== "close") {
    return { primaryView: "back", secondaryViews: ["side", "front"] };
  }

  const prefersSide = containsAnyKeyword(corpus, [
    "侧身",
    "侧面",
    "侧脸",
    "侧视",
    "侧拍",
    "斜侧",
    "profile",
    "side view",
    "three-quarter",
    "3/4"
  ]);
  if (prefersSide) {
    return { primaryView: "side", secondaryViews: ["front", "back"] };
  }

  return { primaryView: "front", secondaryViews: ["side", "back"] };
}

function characterReferenceWeight(view: CharacterReferenceView, plan: ReturnType<typeof inferCharacterReferencePlan>): number {
  if (view === plan.primaryView) return 1;
  const secondaryIndex = plan.secondaryViews.indexOf(view);
  if (secondaryIndex === 0) return 0.62;
  if (secondaryIndex === 1) return 0.34;
  return 0;
}

function inferCanonicalStoryboardCharacterViewPath(
  sourcePath: string,
  view: CharacterReferenceView
): string {
  const normalized = sourcePath.trim().replace(/\//g, "\\");
  if (!normalized) return "";
  const outputMarker = "\\output\\";
  const peopleMarker = "\\人物\\";
  const outputIndex = normalized.toLowerCase().lastIndexOf(outputMarker);
  const peopleIndex = normalized.lastIndexOf(peopleMarker);
  if (outputIndex < 0 || peopleIndex < 0 || peopleIndex <= outputIndex) return "";
  const outputRoot = normalized.slice(0, outputIndex + outputMarker.length);
  const trailing = normalized.slice(peopleIndex + peopleMarker.length);
  const folderName = trailing.split("\\").filter(Boolean)[0]?.trim() ?? "";
  if (!folderName) return "";
  return `${outputRoot}人物\\${folderName}\\${view}.png`;
}

function isMultiViewStoryboardReferencePath(path: string): boolean {
  const normalized = path.trim().replace(/\\/g, "/").toLowerCase();
  if (!normalized) return false;
  return (
    normalized.includes("threeview") ||
    normalized.includes("three_view") ||
    normalized.includes("character_identity_board") ||
    normalized.includes("identity_board")
  );
}

function normalizeStableStoryboardCharacterReferenceTokens(tokens: Record<string, string>): Record<string, string> {
  const nextTokens: Record<string, string> = {
    ...tokens,
    FRAME_IMAGE_PATH: "",
    PREV_SCENE_IMAGE_PATH: "",
    PREV_CHARACTER_IMAGE_PATH: ""
  };

  for (const slot of [1, 2] as const) {
    const frontKey = `CHAR${slot}_FRONT_PATH` as const;
    const sideKey = `CHAR${slot}_SIDE_PATH` as const;
    const backKey = `CHAR${slot}_BACK_PATH` as const;
    const primaryKey = `CHAR${slot}_PRIMARY_PATH` as const;
    const secondaryKey = `CHAR${slot}_SECONDARY_PATH` as const;
    const existingPrimaryPath = String(nextTokens[primaryKey] ?? "").trim();
    const existingSecondaryPath = String(nextTokens[secondaryKey] ?? "").trim();
    const rawCandidates = [
      String(nextTokens[frontKey] ?? "").trim(),
      existingPrimaryPath,
      String(nextTokens[sideKey] ?? "").trim(),
      String(nextTokens[backKey] ?? "").trim()
    ].filter((value) => value.length > 0);
    const seedPath = rawCandidates[0] ?? "";
    if (!seedPath) {
      continue;
    }

    const canonicalFrontPath = inferCanonicalStoryboardCharacterViewPath(seedPath, "front");
    const canonicalSidePath = inferCanonicalStoryboardCharacterViewPath(seedPath, "side");
    const canonicalBackPath = inferCanonicalStoryboardCharacterViewPath(seedPath, "back");

    if (canonicalFrontPath) {
      nextTokens[frontKey] = canonicalFrontPath;
    }
    if (canonicalSidePath) {
      nextTokens[sideKey] = canonicalSidePath;
    }
    if (canonicalBackPath) {
      nextTokens[backKey] = canonicalBackPath;
    }

    const preferredPrimaryPath = isMultiViewStoryboardReferencePath(existingPrimaryPath)
      ? existingPrimaryPath
      : isMultiViewStoryboardReferencePath(existingSecondaryPath)
        ? existingSecondaryPath
        : existingPrimaryPath || canonicalFrontPath || canonicalSidePath || canonicalBackPath;
    if (preferredPrimaryPath) {
      nextTokens[primaryKey] = preferredPrimaryPath;
    }
    if (existingSecondaryPath) {
      nextTokens[secondaryKey] = existingSecondaryPath;
    } else if (existingPrimaryPath && preferredPrimaryPath && existingPrimaryPath !== preferredPrimaryPath) {
      nextTokens[secondaryKey] = existingPrimaryPath;
    }
  }

  return nextTokens;
}

function assetPathForCharacterView(asset: Asset | undefined, view: CharacterReferenceView): string {
  if (!asset) return "";
  if (view === "front") return asset.characterFrontPath || asset.filePath || "";
  if (view === "side") return asset.characterSidePath || asset.characterFrontPath || asset.filePath || "";
  return asset.characterBackPath || asset.characterSidePath || asset.characterFrontPath || asset.filePath || "";
}

function inferStoryboardReferenceWeights(
  shot: Shot,
  hasSceneRef: boolean,
  hasSecondCharacter: boolean,
  hasSceneContinuityFrame: boolean
): {
  char1Primary: number;
  char1Secondary: number;
  char2Primary: number;
  denoise: number;
  steps: number;
  cfg: number;
} {
  const characterDriven = isCharacterDrivenShot(shot);
  const sceneLed = hasSceneRef && shouldLeadWithSceneReference(shot);
  if (sceneLed && hasSceneContinuityFrame && hasSecondCharacter) {
    if (characterDriven) {
      return {
        char1Primary: 0.72,
        char1Secondary: 0.08,
        char2Primary: 0.68,
        denoise: 0.4,
        steps: 28,
        cfg: 5.2
      };
    }
    return {
      char1Primary: 0.58,
      char1Secondary: 0.06,
      char2Primary: 0.54,
      denoise: 0.22,
      steps: 26,
      cfg: 4.9
    };
  }
  if (sceneLed && hasSceneContinuityFrame) {
    if (characterDriven) {
      return {
        char1Primary: 0.74,
        char1Secondary: 0.08,
        char2Primary: 0,
        denoise: 0.38,
        steps: 28,
        cfg: 5.2
      };
    }
    return {
      char1Primary: 0.6,
      char1Secondary: 0.06,
      char2Primary: 0,
      denoise: 0.22,
      steps: 26,
      cfg: 4.9
    };
  }
  if (sceneLed && hasSecondCharacter) {
    if (characterDriven) {
      return {
        // Scene-led dual-character storyboard shots are the most failure-prone:
        // keep the scene stable, but push both character anchors hard enough that
        // the second actor does not disappear into the background.
        char1Primary: 0.9,
        char1Secondary: 0.06,
        char2Primary: 0.88,
        denoise: 0.46,
        steps: 32,
        cfg: 6
      };
    }
    return {
      char1Primary: 0.82,
      char1Secondary: 0.04,
      char2Primary: 0.78,
      denoise: 0.36,
      steps: 30,
      cfg: 5.8
    };
  }
  if (sceneLed) {
    if (characterDriven) {
      return {
        char1Primary: 0.78,
        char1Secondary: 0.08,
        char2Primary: 0,
        denoise: 0.38,
        steps: 28,
        cfg: 5.2
      };
    }
    return {
      char1Primary: 0.6,
      char1Secondary: 0.04,
      char2Primary: 0,
      denoise: 0.24,
      steps: 24,
      cfg: 5.1
    };
  }
  if (hasSecondCharacter) {
    return {
      char1Primary: 0.94,
      char1Secondary: 0.08,
      char2Primary: 0.9,
      denoise: 0.42,
      steps: 30,
      cfg: 5.8
    };
  }
  return {
    char1Primary: 0.94,
    char1Secondary: 0.1,
    char2Primary: 0,
    denoise: 0.32,
    steps: 28,
    cfg: 5.2
  };
}

function isCharacterDrivenShot(shot: Shot): boolean {
  if ((shot.characterRefs?.length ?? 0) > 0) return true;
  if (shot.dialogue?.trim()) return true;
  const corpus = [
    shot.title ?? "",
    shot.storyPrompt ?? "",
    shot.videoPrompt ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ]
    .join(" ")
    .toLowerCase();
  return containsAnyKeyword(corpus, [
    "人物",
    "角色",
    "对峙",
    "对白",
    "打斗",
    "交手",
    "冲拳",
    "出拳",
    "闪避",
    "反击",
    "对话",
    "face off",
    "duel",
    "fight",
    "punch",
    "kick",
    "dodge"
  ]);
}

function shotsShareCharacters(left: Shot, right: Shot): boolean {
  const leftSet = new Set((left.characterRefs ?? []).filter((item) => item.trim().length > 0));
  if (leftSet.size === 0) return false;
  return (right.characterRefs ?? []).some((item) => leftSet.has(item));
}

function buildShotCharacterSignature(shot: Shot): string {
  const signature = Array.from(
    new Set(
      [
        ...(shot.characterRefs ?? []).map((item) => item.trim()),
        ...(shot.sourceCharacterNames ?? []).map((item) => item.trim().toLowerCase())
      ].filter(Boolean)
    )
  ).sort();
  return signature.join("|");
}

function shouldUseStoryboardContinuitySeed(currentShot: Shot, previousSceneShot: Shot | undefined): boolean {
  if (!previousSceneShot?.generatedImagePath?.trim()) return false;
  const currentSignature = buildShotCharacterSignature(currentShot);
  if (!currentSignature) return true;
  return currentSignature === buildShotCharacterSignature(previousSceneShot);
}

function hasGeneratedStill(shot: Shot | undefined): shot is Shot {
  return Boolean(shot?.generatedImagePath?.trim());
}

function inferShotContinuityPlan(shot: Shot, index: number, allShots: Shot[]): ShotContinuityPlan {
  let previousSceneShot: Shot | undefined;
  let previousCharacterShot: Shot | undefined;
  const currentShotCharacterCount = countExplicitShotCharacters(shot);
  const currentCharacterMode: "single" | "multi" | "unknown" =
    currentShotCharacterCount >= 2 ? "multi" : currentShotCharacterCount === 1 ? "single" : "unknown";

  for (let cursor = index - 1; cursor >= 0; cursor -= 1) {
    const candidate = allShots[cursor];
    if (!hasGeneratedStill(candidate)) continue;
    if (!previousSceneShot && shot.sceneRefId?.trim() && candidate.sceneRefId === shot.sceneRefId) {
      previousSceneShot = candidate;
    }
    if (!previousCharacterShot && shotsShareCharacters(shot, candidate)) {
      const candidateCharacterCount = countExplicitShotCharacters(candidate);
      const characterCountCompatible =
        currentCharacterMode === "single"
          ? candidateCharacterCount <= 1
          : currentCharacterMode === "multi"
            ? candidateCharacterCount >= 2
            : true;
      if (characterCountCompatible) {
        previousCharacterShot = candidate;
      }
    }
    if (previousSceneShot && previousCharacterShot) break;
  }

  return { previousSceneShot, previousCharacterShot };
}

function buildContinuityDirective(plan: ShotContinuityPlan): string {
  const lines: string[] = [];
  if (plan.previousSceneShot) {
    lines.push(
      `跨镜头场景连续：延续上一条同场景分镜“${plan.previousSceneShot.title}”的环境布局与空间锚点，桥梁、建筑、河岸、道路等固定物位置关系不得漂移或改造。`
    );
  }
  if (plan.previousCharacterShot) {
    lines.push(
      `跨镜头人物连续：延续上一条同角色分镜“${plan.previousCharacterShot.title}”中的角色外观，发型、服装、配饰、配色、体型和受光状态保持同一人设，不得突然变化。`
    );
  }
  if (lines.length > 0) {
    lines.push("连续性规则：这是同一段戏内的连续镜头，默认继承上一镜头已经建立的角色和场景，不允许重置设计。");
  }
  if (plan.previousSceneShot) {
    lines.push(
      `Style continuity lock: keep the final frame in the same painterly rendering family as "${plan.previousSceneShot.title}", with matching palette bias, contrast curve, texture grain, and atmosphere.`
    );
    lines.push(
      "Do not switch to a new environment art style; preserve the established scenic brushwork and color grading while keeping current shot blocking."
    );
  }
  return lines.join("\n");
}

function buildShotReferenceDirective(
  shot: Shot,
  sceneAsset: Asset | undefined,
  skyboxFaces: SkyboxFace[],
  characterAssets: Asset[],
  continuityPlan: ShotContinuityPlan
): string {
  const lines: string[] = [];
  const characterPlan = characterAssets.length > 0 ? inferCharacterReferencePlan(shot) : null;
  const continuityDirective = buildContinuityDirective(continuityPlan);
  const cameraDescriptor = shotCameraDescriptor(shot);
  if (sceneAsset?.type === "skybox") {
    const faceText = joinNaturalChineseList(skyboxFaces.map((face) => skyboxFaceLabel(face)));
    lines.push(
      `场景硬参考：必须以天空盒“${sceneAsset.name}”为准，优先参考${faceText || "正前"}视角，保持地平线、空间布局、建筑或地貌朝向、时间氛围与主色调一致，不得改成其他地点。`
    );
    if (cameraDescriptor) {
      lines.push(`机位硬约束：当前镜头机位 ${cameraDescriptor}，必须与天空盒方向保持一致。`);
    }
  } else if (sceneAsset?.type === "scene") {
    lines.push(`场景硬参考：必须保持场景“${sceneAsset.name}”的环境布局、主体元素、光线和色调一致，不得重设计场景。`);
  }
  if (characterAssets.length > 0) {
    for (const asset of characterAssets) {
      const availableViews = [
        asset.characterFrontPath || asset.filePath ? "front" : "",
        asset.characterSidePath ? "side" : "",
        asset.characterBackPath ? "back" : ""
      ].filter((item) => item.length > 0);
      const viewText = availableViews.length > 0 ? availableViews.join("/") : "front";
      const preferredView = characterPlan ? characterReferenceViewLabel(characterPlan.primaryView) : "正面";
      lines.push(
        `人物硬参考：角色“${asset.name}”必须严格匹配三视图，保持脸型、发型、服装、配色、体型和道具一致；当前镜头优先匹配${preferredView}参考，可用视图为 ${viewText}，不得换脸、换装、换配色或混入其他角色特征。`
      );
    }
    lines.push("人物构图硬约束：人物必须在中前景清晰可见，优先完整半身或全身，不得退化成远景小人影、剪影或被场景主体遮挡。");
    lines.push("动作与站位硬约束：必须执行脚本描述的动作和站位，镜头变化时不得沿用上一镜头姿态或无关模板姿势。");
    lines.push("表情硬约束：每个出镜角色都必须有与当前镜头动作匹配的可读面部表情，不允许面无表情、木讷站桩或统一模板脸。");
    lines.push("人物-场景物理约束：人物脚部与地面接触关系自然，接触阴影方向与场景主光一致，不允许漂浮、穿模、比例失真。");
    lines.push("人物融合硬约束：人物必须像真实存在于场景中的主体，而不是贴在背景上的纸片；人物边缘、灰度、线条密度、受光和阴影必须与环境一致。");
    lines.push("人物风格硬约束：禁止把角色改成室内写真、自拍、时装摆拍、裸露画面或无关陌生人，必须保持参考角色的身份与服装。");
  }
  if (continuityDirective) {
    lines.push(continuityDirective);
  }
  if (lines.length > 0) {
    lines.push("执行规则：参考图优先级高于自由发挥，先锁定参考一致性，再生成镜头动作和构图。");
  }
  return lines.join("\n");
}

function buildCharacterPresenceDirective(characterAssets: Asset[]): string {
  if (characterAssets.length === 0) return "";
  if (characterAssets.length === 1) {
    return `出镜硬要求：画面中必须且只能出现 1 名主要角色“${characterAssets[0]!.name}”，禁止生成为纯环境空镜；禁止换成其他人、禁止多出陌生人、禁止把主体画成远处小人影。角色必须位于中前景且清晰可辨识，建议占画面高度至少约 35%，并保证完整全身、头顶和脚底都留有安全边距、脚部接地、受光自然、阴影与环境一致。`;
  }
  const names = joinNaturalChineseList(characterAssets.map((item) => item.name));
  return `出镜硬要求：画面中必须且只能出现 ${characterAssets.length} 名角色${names}，禁止生成为纯环境空镜，禁止缺少任何一人，禁止出现第三人、路人、群演、重复人、融合人或身份互换；每个角色都需各自对应 1 名可辨识人物，不允许用同一张脸或同一套服装冒充两个人，也不允许只出现极远小人、严重裁切或被场景主体完全遮挡。所有角色都必须完整接地、头顶脚底保留安全边距、阴影自然、比例正确，并作为场景中的真实主体出现。`;
}

function buildCompactStoryboardPresencePrompt(characterAssets: Asset[]): string {
  if (characterAssets.length === 0) return "";
  if (characterAssets.length === 1) {
    return `exactly one full body character, character clearly visible from head to toe with safe margin above head and below feet, same face same hair same outfit in every shot, visible body action, readable facial expression, standing in the scene, feet touching the ground, shadow matching environment, integrated with the environment, never crop the body, not an empty scene`;
  }
  const names = characterAssets.map((item) => item.name.trim()).filter((item) => item.length > 0);
  const nameText = names.length > 0 ? `exactly ${characterAssets.length} characters: ${names.join(" and ")}` : `exactly ${characterAssets.length} characters`;
  return `${nameText}, all characters full body and clearly visible from head to toe with safe top and bottom margins, same faces same hairstyles same outfits in every shot, visible body acting, readable facial expressions, all characters inside the scene, feet touching the ground, shadow matching environment, no missing character, no body crop, no empty scene, natural interaction with environment`;
}

function buildCharacterPresenceDirectiveByShotScale(
  characterAssets: Asset[],
  shotScale: "wide" | "medium" | "close" | "default"
): string {
  if (shotScale === "wide" || shotScale === "default") {
    return buildCharacterPresenceDirective(characterAssets);
  }
  if (characterAssets.length === 0) return "";
  if (characterAssets.length === 1) {
    const name = characterAssets[0]?.name ?? "角色";
    if (shotScale === "close") {
      return `出镜硬要求：画面中必须且只能出现 1 名主要角色“${name}”，禁止空镜、禁止陌生人、禁止身份替换。近景镜头优先保证脸部与上半身清晰可读，不强制头到脚全身入镜；但姿态、服装与受光必须自然一致。`;
    }
    return `出镜硬要求：画面中必须且只能出现 1 名主要角色“${name}”，禁止空镜、禁止陌生人、禁止身份替换。中景镜头至少保证膝盖以上到全身的可读构图，避免退化成过紧的人像裁切；角色动作与阴影需与场景一致。`;
  }
  const names = joinNaturalChineseList(characterAssets.map((item) => item.name));
  if (shotScale === "close") {
    return `出镜硬要求：画面中必须且只能出现 ${characterAssets.length} 名角色 ${names}，禁止缺人、禁止第三人、禁止身份互换。近景镜头允许非全身构图，但主角色脸部与上半身必须清晰，次角色身份和服装必须可辨识，整体受光与动作逻辑一致。`;
  }
  return `出镜硬要求：画面中必须且只能出现 ${characterAssets.length} 名角色 ${names}，禁止缺人、禁止第三人、禁止身份互换。中景镜头至少保证每个角色中景可读（膝盖以上到全身），避免头像贴片或严重遮挡，动作与站位需与分镜一致。`;
}

function buildCompactStoryboardPresencePromptByShotScale(
  characterAssets: Asset[],
  shotScale: "wide" | "medium" | "close" | "default"
): string {
  if (shotScale === "wide" || shotScale === "default") {
    return buildCompactStoryboardPresencePrompt(characterAssets);
  }
  if (characterAssets.length === 0) return "";
  if (characterAssets.length === 1) {
    if (shotScale === "close") {
      return "exactly one character, close framing allowed, prioritize readable face and upper-body expression, preserve same face/hair/outfit across shots, grounded in scene lighting, no empty scene";
    }
    return "exactly one character, medium-to-full readable framing (knee-up to full), preserve same face/hair/outfit across shots, visible action and expression, grounded in scene lighting, no empty scene";
  }
  const names = characterAssets.map((item) => item.name.trim()).filter((item) => item.length > 0);
  const nameText = names.length > 0 ? `exactly ${characterAssets.length} characters: ${names.join(" and ")}` : `exactly ${characterAssets.length} characters`;
  if (shotScale === "close") {
    return `${nameText}, close framing allowed while keeping both identities readable, preserve same faces/hairstyles/outfits across shots, readable acting and interaction, no missing character, no extra person, no empty scene`;
  }
  return `${nameText}, medium-to-full readable framing for all roles (knee-up to full), preserve same faces/hairstyles/outfits across shots, readable acting and interaction, no missing character, no extra person, no empty scene`;
}

function buildStableStoryboardPassAPrompt(fullPrompt: string, char1Name: string, char2Name: string): string {
  const normalized = normalizePromptBody(fullPrompt);
  if (!normalized || !char1Name || !char2Name) return normalized;
  const filteredLines = normalized
    .split(/\r?\n+/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .filter((line) => !line.startsWith("出镜硬要求："))
    .filter((line) => !line.startsWith("人物参考："))
    .filter((line) => !line.startsWith("构图硬约束：本镜头必须清晰呈现"))
    .filter((line) => !line.includes(`动作硬约束（${char2Name}）`))
    .filter((line) => !line.includes(`站位硬约束：角色“${char2Name}”`));
  return [
    ...filteredLines,
    `人物参考：${char1Name}`,
    `过渡采样阶段硬约束：当前阶段只允许角色“${char1Name}”1 人清晰完整地出现在画面中，禁止生成角色“${char2Name}”或任何第二人；当前阶段只锁定角色“${char1Name}”的脸、发型、服装、比例、动作和落脚点，为后续第二名角色保留空间但不要画出第二人实体。`
  ]
    .filter((line) => line.length > 0)
    .join("\n");
}

function buildStableStoryboardPassANegativePrompt(fullNegativePrompt: string, char2Name: string): string {
  const extra = [
    "extra person",
    "second person",
    "another character",
    "additional human",
    "crowd",
    "group shot",
    "pair shot",
    "two people",
    "duplicate protagonist"
  ];
  if (char2Name.trim()) {
    extra.push(char2Name.trim(), `character ${char2Name.trim()}`);
  }
  return appendNegativePrompt(fullNegativePrompt, extra.join(", "));
}

function collectStableStoryboardRoleNames(char1Name: string, char2Name: string): string[] {
  return [char1Name, char2Name]
    .map((value) => value.trim())
    .filter((value, index, list) => value.length > 0 && list.indexOf(value) === index);
}

function formatStableStoryboardRoleLabel(names: string[]): string {
  if (names.length === 0) return "";
  if (names.length === 1) return names[0] ?? "";
  if (names.length === 2) return `${names[0]} and ${names[1]}`;
  return `${names.slice(0, -1).join(", ")}, and ${names[names.length - 1]}`;
}

function extractStableStoryboardPassACharacterCueLines(fullPrompt: string, roleNames: string[]): string[] {
  const normalized = normalizePromptBody(fullPrompt).replace(/\n/g, ", ");
  if (!normalized || roleNames.length === 0) return [];
  const clauses = normalized
    .split(/[,.;，。；]+/)
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
  const keepPattern =
    /\b(exact character count|both characters|all required characters|keep both characters|same appearance|same face|same outfit|same costume|full body|head to toe|grounded|foot contact|walking|running|turning|glancing|looking|expression|hair|bangs|face|dress|coat|shirt|trousers|pants|boots|shoes|belt|skirt|sleeve|young woman|young man|woman|man|girl|boy)\b|全身|人物|角色|动作|走|站|抬手|抬头|回头|低头|表情|头发|服装|外套|裙子|鞋子|靴子/i;
  const detailPattern =
    /\b(full body|head to toe|grounded|foot contact|walking|running|turning|glancing|expression|hair|bangs|face|dress|coat|shirt|trousers|pants|boots|shoes|belt|skirt|sleeve)\b|全身|动作|走|站|抬手|回头|表情|头发|服装|外套|裙子|鞋子|靴子/i;
  const sceneOnlyPattern =
    /\b(river|riverbank|bridge|path|stone path|background|environment|outdoor|dusk|sunset|camera|shot|tracking|eye-level|perspective|frame|scenery|landscape|horizon|archway|doorway|signage|logo|calligraphy|prop)\b|河|河边|河岸|桥|桥洞|门洞|石路|背景|环境|户外|傍晚|黄昏|镜头|景别|构图|风景|地平线|招牌|文字|标志|道具/i;
  const seen = new Set<string>();
  const cues: string[] = [];
  for (const clause of clauses) {
    const hasRoleName = roleNames.some((roleName) => roleName && clause.includes(roleName));
    const hasKeepCue = keepPattern.test(clause);
    if (!hasRoleName && !hasKeepCue) continue;
    const sanitized = clause
      .replace(/\bin the scene\b/gi, "")
      .replace(/\bnaturally integrated into the [^,.;]+/gi, "")
      .replace(/\bshadow matching environment\b/gi, "")
      .replace(/\bon the (left|right) side of the [^,.;]+/gi, "")
      .replace(/\bsame [^,.;]* axis\b/gi, "")
      .replace(/\bbridge closer in the background\b/gi, "")
      .replace(/\bdusk outdoor lighting\b/gi, "")
      .replace(/\bcorrect perspective\b/gi, "")
      .replace(/\bno pure scenery frame\b/gi, "")
      .replace(/\bno pasted cutout\b/gi, "")
      .replace(/桥洞|门洞|背景|环境|风景|构图|镜头|景别|黄昏|傍晚|招牌|文字|标志|道具/g, "")
      .replace(/\s{2,}/g, " ")
      .replace(/^[, ]+|[, ]+$/g, "")
      .trim();
    if (!sanitized) continue;
    if (sceneOnlyPattern.test(sanitized) && !detailPattern.test(sanitized)) {
      continue;
    }
    if (hasRoleName && !hasKeepCue && !detailPattern.test(sanitized)) {
      continue;
    }
    const key = sanitized.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    cues.push(sanitized);
    if (cues.length >= 8) break;
  }
  return cues;
}

function escapeRegexForPrompt(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function sanitizeStoryboardPromptForStage(fullPrompt: string): string {
  const normalized = normalizePromptBody(fullPrompt).replace(/\n/g, ", ");
  if (!normalized) return "";
  const clauses = normalized
    .split(/[,.;\uFF0C\u3002\uFF1B]+/)
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
  const filtered = clauses.filter((clause) => {
    if (
      /\b(main subject of the shot|secondary required character|every other scripted character)\b/i.test(clause)
    ) {
      return false;
    }
    if (/\b(main subject|secondary required character)\b/i.test(clause)) {
      return false;
    }
    if (
      /\b(the characters are the subject of the shot|no pure scenery frame|no pasted cutout look|visible body acting and readable facial expression are required)\b/i.test(
        clause
      )
    ) {
      return false;
    }
    if (/\b(full body,\s*clearly visible,\s*in the scene)\b/i.test(clause)) return false;
    if (
      /\b(keep exact same face|body proportions in every shot|both feet touching the ground|shadow matching environment|correct perspective|contact shadows|naturally integrated with)\b/i.test(
        clause
      )
    ) {
      return false;
    }
    if (/\b(readable reaction expression|readable natural expression|clearly visible|full body)\b/i.test(clause)) {
      return false;
    }
    if (/^[^,，]{1,40},\s*(main subject|secondary required character)\b/i.test(clause)) return false;
    return true;
  });
  const deduped = uniquePreserveOrder(filtered).slice(0, 28);
  const cleaned = deduped.join(", ").trim();
  return cleaned || normalized;
}

function splitStoryboardPromptClauses(fullPrompt: string): string[] {
  const normalized = sanitizeStoryboardPromptForStage(fullPrompt).replace(/\n/g, ", ");
  if (!normalized) return [];
  return normalized
    .split(/[,.;，。；]+/)
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
}

function splitStoryboardPromptClausesStable(fullPrompt: string): string[] {
  const normalized = sanitizeStoryboardPromptForStage(fullPrompt).replace(/\n/g, ", ");
  if (!normalized) return [];
  return normalized
    .split(/[,\.;\uFF0C\u3002\uFF1B]+/)
    .map((value) => value.trim())
    .filter((value) => value.length > 0);
}

function stripDualCharacterDirectivesForStageA_legacyBroken(prompt: string, char2Name: string): string {
  let output = String(prompt || "");
  const secondName = String(char2Name || "").trim();
  if (secondName) {
    output = output.replace(new RegExp(escapeRegexForPrompt(secondName), "gi"), "");
  }
  output = output
    .replace(/【\s*硬性人数[^\n。!！?？]*[。!！?？]?/g, "")
    .replace(/必须且只能有?\s*2\s*人[:：]?[^\n。!！?？]*/g, "")
    .replace(/只能有?\s*2\s*人[:：]?[^\n。!！?？]*/g, "")
    .replace(/必须有?\s*2\s*人[:：]?[^\n。!！?？]*/g, "")
    .replace(/双人|两人|二人|两位|二位|两名|2人|第二人|同伴|搭档/g, "")
    .replace(/\b(exact character count(?:\s*is)?\s*2|exactly\s*2\s*(?:people|characters)|both characters?|two characters?|two people|second character|another character|partner)\b/gi, "")
    .replace(/\s{2,}/g, " ")
    .replace(/,\s*,/g, ", ")
    .replace(/^[,;，。；\s]+|[,;，。；\s]+$/g, "");
  return output.trim();
}

function stripDualCharacterDirectivesForStageA(prompt: string, char2Name: string): string {
  let output = String(prompt || "");
  const secondName = String(char2Name || "").trim();
  if (secondName) {
    output = output.replace(new RegExp(escapeRegexForPrompt(secondName), "giu"), " ");
  }
  const removePatterns: RegExp[] = [
    /\b(exact character count(?:\s*is)?\s*2|exactly\s*2\s*(?:people|characters?)|both characters?|two characters?|two people|second character|another character|partner|dual[-\s]?character)\b/giu,
    /(?:硬性人数|画面中必须且只能有|必须且只能有|只能有|必须有)[^。\n,;，；]{0,32}[2二两]\s*人/gu,
    /(?:双人|两人|二人|两位|二位|两名|第二人|搭档|同伴|对手戏|双角色)/gu,
    /[（(]\s*[2二两]\s*人\s*[）)]/gu
  ];
  for (const pattern of removePatterns) {
    output = output.replace(pattern, " ");
  }
  output = output
    .replace(/\s{2,}/g, " ")
    .replace(/,\s*,/g, ", ")
    .replace(/^[,;，。；\s]+|[,;，。；\s]+$/g, "");
  return output.trim();
}

function buildQwenStageAStoryboardPrompt(fullPrompt: string, char1Name: string, char2Name: string): string {
  const normalized = sanitizeStoryboardPromptForStage(fullPrompt);
  const shotScale = inferStoryboardCompositeScaleFromCorpus(normalized.toLowerCase());
  const clauses = splitStoryboardPromptClausesStable(normalized);
  const char1Pattern = char1Name.trim() ? new RegExp(escapeRegexForPrompt(char1Name.trim()), "i") : null;
  const char2Pattern = char2Name.trim() ? new RegExp(escapeRegexForPrompt(char2Name.trim()), "i") : null;
  const blockedPatterns = [
    /\bexact character count\b/i,
    /\bexactly two\b/i,
    /\bexactly 2\b/i,
    /\btwo people\b/i,
    /\b2 people\b/i,
    /\btwo characters?\b/i,
    /\b2 characters?\b/i,
    /\bboth characters?\b/i,
    /\bsecond character\b/i,
    /\banother character\b/i,
    /\bevery other scripted character\b/i,
    /\bpartner\b/i,
    /必须且只能有2人/,
    /只能有2人/,
    /两人/,
    /双人/,
    /二人/,
    /第二人/,
    /同伴|搭档/
  ];
  const dualDirectivePattern =
    /(?:硬性人数|画面中必须且只能有|必须且只能有|只能有|必须有|双人|两人|二人|第二人|搭档|同伴|对手戏|[2二两]\s*人)/u;
  const keptClauses: string[] = [];
  const seen = new Set<string>();
  for (const clause of clauses) {
    if (char2Pattern?.test(clause)) continue;
    if (blockedPatterns.some((pattern) => pattern.test(clause))) continue;
    if (dualDirectivePattern.test(clause)) continue;
    if (!char1Pattern?.test(clause) && /\b(both|two|2)\b/i.test(clause)) continue;
    const key = clause.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    keptClauses.push(clause);
    if (keptClauses.length >= 14) break;
  }
  const stageABasePromptRaw = stripDualCharacterDirectivesForStageA(keptClauses.join(", ").trim() || normalized, char2Name);
  const stageABasePrompt = stageABasePromptRaw
    .replace(/\b(partner|interpersonal distance|mutual attention)\b/gi, "")
    .replace(/(?:双人|两人|二人|同伴|搭档|对手戏|[2二两]\s*人)/gu, " ")
    .replace(/双人|两人|同伴|搭档|对手戏/g, "")
    .replace(/\s{2,}/g, " ")
    .replace(/,\s*,/g, ", ")
    .trim();

  return [
    stageABasePrompt,
    "Single-character plate generation pass.",
    `Stage A target: render exactly one visible person only, ${char1Name}.`,
    `Only allowed human identity in this frame is ${char1Name || "character A"}; do not generate any stranger, bystander, silhouette person, reflection person, or background face.`,
    `Do not draw ${char2Name || "the second character"} in this pass.`,
    "Follow the shot script camera, framing, movement beat, and blocking for the visible character as closely as possible.",
    shotScale === "wide"
      ? "Wide establishing composition: keep the subject full body but relatively small in frame with generous environment around them, and do not drift into a medium-close crop."
      : "",
    "Reserve empty space for partner placement described in the shot script, but that reserved space must remain empty in this pass.",
    "Place the visible character strictly inside the pass-A mask slot and keep that slot position stable.",
    "Do not place any person in the pass-B mask slot during Stage A.",
    "Hard rule: final Stage A frame must contain one and only one human figure.",
    "If any second person appears, remove that second person completely.",
    "If the second-person placement zone changes, restore it to clean background.",
    "The visible character must be full body from head to toe with safe margins, grounded feet, readable face, consistent outfit, and natural anatomy.",
    "Use high-detail rendering with smooth anti-aliased contours and fine face/hair/fabric details; avoid coarse pixel blocks.",
    "Do not output empty scenery, tiny distant person, duplicate body, ghost limbs, silhouette-only figure, or a low-resolution pixelated look."
  ]
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .join("\n");
}

function stripDualCharacterDirectivesForStageARefined(prompt: string, char2Name: string): string {
  let output = String(prompt || "");
  const secondName = String(char2Name || "").trim();
  if (secondName) {
    output = output.replace(new RegExp(escapeRegexForPrompt(secondName), "giu"), " ");
  }
  const dualDirectivePatterns: RegExp[] = [
    /\b(exact character count(?:\s*is)?\s*2|exactly\s*2\s*(?:people|characters?)|both characters?|two characters?|two people|second character|another character|partner|companion|co-actor|dual[-\s]?character)\b/giu,
    /\b(?:must|required|should|need to|have to)\s*(?:be|show|contain|include)?\s*(?:exactly|strictly|only)?\s*(?:two|2)\s*(?:people|characters?)\b/giu,
    /(?:\u53cc\u4eba|\u4e24\u4eba|\u4e8c\u4eba|\u4e24\u4f4d|\u4e8c\u4f4d|\u4e24\u540d|\u7b2c\u4e8c\u4eba|\u540c\u4f34|\u642d\u6863|\u4f19\u4f34|\u5bf9\u624b|\u53cc\u89d2\u8272|(?:2|\u4e8c|\u4e24|\u4fe9)\s*\u4eba)/gu,
    /(?:\u5fc5\u987b|\u52a1\u5fc5|\u53ea\u80fd|\u4ec5\u80fd|\u9700\u8981)[^,;\n\u3002\uff1b]{0,24}(?:2|\u4e8c|\u4e24|\u4fe9)\s*\u4eba/gu,
    /[\(\[（【]\s*(?:2|\u4e8c|\u4e24|\u4fe9)\s*\u4eba\s*[\)\]）】]/gu
  ];
  for (const pattern of dualDirectivePatterns) {
    output = output.replace(pattern, " ");
  }
  return output
    .replace(/\s{2,}/g, " ")
    .replace(/,\s*,/g, ", ")
    .replace(/^[,;锛屻€傦紱\s]+|[,;锛屻€傦紱\s]+$/g, "")
    .trim();
}

function buildQwenStageAStoryboardPromptRefined(fullPrompt: string, char1Name: string, char2Name: string): string {
  const normalized = sanitizeStoryboardPromptForStage(fullPrompt);
  const shotScale = inferStoryboardCompositeScaleFromCorpus(normalized.toLowerCase());
  const fullBodyContinuityRequired = containsAnyKeyword(normalized, [
    "full body",
    "head to toe",
    "feet visible",
    "feet touching the ground",
    "全身",
    "头到脚",
    "脚部可见",
    "脚不被裁切",
    "完整全身",
    "保留全身"
  ]);
  const stageAFramingLock =
    shotScale === "wide"
      ? "Wide establishing composition: keep the subject full body but relatively small in frame with generous environment around them, and do not drift into a medium-close crop."
      : shotScale === "medium"
        ? "Medium-shot composition: keep the subject around knee-up to full-body in frame with stable scale; avoid collapsing into a tight portrait crop."
        : shotScale === "close"
          ? "Close-shot composition: prioritize face and upper-body readability according to script framing; do not force head-to-toe full-body framing in this shot."
          : "Respect the scripted framing scale and keep subject size consistent in frame.";
  const stageABodyIntegrityLine =
    shotScale === "close"
      ? "Keep natural anatomy, stable outfit details, and readable expression within the close-shot crop; avoid broken shoulders, neck, or torso."
      : "Keep coherent anatomy and grounded body structure when legs/feet are visible, with consistent outfit and natural pose.";
  const dialogueLike = /(?:dialogue|conversation|talk|speak|reply|respond|exchange lines|face to face|mutual eyeline|对话|说话|回应|交谈|对视|注视|看向)/iu.test(
    normalized
  );
  const cameraFacingForced = /(?:facing camera|toward camera|look at camera|directly to camera|fourth wall|看向镜头|面对镜头|直视镜头|朝向镜头)/iu.test(
    normalized
  );
  const stageADialogueFacingLines =
    dialogueLike && !cameraFacingForced
      ? [
          `Dialogue setup for Stage A: pose only ${char1Name.trim() || "character A"} in a three-quarter angle toward the partner slot, leaving clean space for ${
            char2Name.trim() || "character B"
          } in Stage B.`,
          "Eyeline setup for Stage A: the visible character should look toward the partner position, not directly into the camera."
        ]
      : [];
  const clauses = splitStoryboardPromptClausesStable(normalized);
  const char1Pattern = char1Name.trim() ? new RegExp(escapeRegexForPrompt(char1Name.trim()), "i") : null;
  const char2Pattern = char2Name.trim() ? new RegExp(escapeRegexForPrompt(char2Name.trim()), "i") : null;
  const dualDirectivePattern =
    /(?:\b(?:exact character count|exactly\s*2|two\s*(?:people|characters?)|both\s*characters?|second\s*character|another\s*character|partner|companion|co-actor|dual[-\s]?character)\b|(?:2|\u4e8c|\u4e24|\u4fe9)\s*\u4eba|\u53cc\u4eba|\u4e24\u4eba|\u4e8c\u4eba|\u7b2c\u4e8c\u4eba|\u540c\u4f34|\u642d\u6863|\u4f19\u4f34|\u5bf9\u624b|\u53cc\u89d2\u8272)/iu;
  const explicitSecondPersonPattern = /(?:\b(?:both|two|2|partner|companion|another)\b|(?:2|\u4e8c|\u4e24|\u4fe9)\s*\u4eba)/iu;
  const blockedPatterns = [
    /\bevery other scripted character\b/i,
    /\bmain subject of the shot\b/i,
    /\bsecondary required character\b/i,
    /\bhard character count\b/i,
    dualDirectivePattern
  ];

  const keptClauses: string[] = [];
  const seen = new Set<string>();
  for (const clause of clauses) {
    if (char2Pattern?.test(clause)) continue;
    if (blockedPatterns.some((pattern) => pattern.test(clause))) continue;
    if (!char1Pattern?.test(clause) && explicitSecondPersonPattern.test(clause)) continue;
    const key = clause.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    keptClauses.push(clause);
    if (keptClauses.length >= 14) break;
  }

  const stageABasePromptRaw = stripDualCharacterDirectivesForStageARefined(
    keptClauses.join(", ").trim() || normalized,
    char2Name
  );
  const char1Label = char1Name.trim() || "character A";
  const char2Label = char2Name.trim() || "the second character";
  const fullBodyContinuityLines = fullBodyContinuityRequired
    ? [
        `Scripted body-retention lock: keep ${char1Label} fully readable from head to toe inside the frame, with the head and feet still visible and grounded when the shot asks for full-body continuity.`,
        "Do not express intimacy by cropping the subject into a bust portrait; preserve the same scene depth and body readability instead.",
        "Reserve a full standing partner slot for Stage B rather than a face-only portrait gap."
      ]
    : [];
  const stageABasePrompt = stageABasePromptRaw
    .replace(/\b(partner|interpersonal distance|mutual attention|co-actor|companion)\b/giu, " ")
    .replace(/(?:\u53cc\u4eba|\u4e24\u4eba|\u4e8c\u4eba|\u540c\u4f34|\u642d\u6863|\u4f19\u4f34|\u5bf9\u624b|\u53cc\u89d2\u8272|(?:2|\u4e8c|\u4e24|\u4fe9)\s*\u4eba)/gu, " ")
    .replace(/\s{2,}/g, " ")
    .replace(/,\s*,/g, ", ")
    .replace(/^[,;锛屻€傦紱\s]+|[,;锛屻€傦紱\s]+$/g, "")
    .trim();

  return [
    stageABasePrompt,
    "Single-character plate generation pass.",
    `Stage A target: render exactly one visible person only, ${char1Label}.`,
    `Only allowed human identity in this frame is ${char1Label}; do not generate any stranger, bystander, silhouette person, reflection person, or background face.`,
    `Do not draw ${char2Label} in this pass.`,
    "Follow the shot script camera, framing, movement beat, and blocking for the visible character as closely as possible.",
    stageAFramingLock,
    "Keep scene layout, horizon, bridge opening, riverbank path, perspective, and lighting anchored to the scene reference; do not switch location.",
    "Do not turn the frame into indoor room, studio backdrop, blank wall, or unrelated environment.",
    "Reserve empty space for partner placement described in the shot script, but that reserved space must remain empty in this pass.",
    ...fullBodyContinuityLines,
    ...stageADialogueFacingLines,
    "Hard rule: final Stage A frame must contain one and only one human figure.",
    "If any second person appears, remove that second person completely.",
    "If the second-person placement zone changes, restore it to clean background.",
    stageABodyIntegrityLine,
    "Use high-detail rendering with smooth anti-aliased contours and fine face/hair/fabric details; avoid coarse pixel blocks.",
    "Do not output empty scenery, tiny distant person, duplicate body, ghost limbs, silhouette-only figure, or a low-resolution pixelated look."
  ]
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .join("\n");
}

