function isolateDualStageATokens(tokens: Record<string, string>): Record<string, string> {
  const normalized = { ...tokens };
  const char1Name = String(normalized.CHAR1_NAME ?? "").trim();
  const char1Front = String(normalized.CHAR1_FRONT_PATH ?? "").trim();
  const char1Side = String(normalized.CHAR1_SIDE_PATH ?? "").trim();
  const char1Back = String(normalized.CHAR1_BACK_PATH ?? "").trim();
  const char1Face = String(normalized.CHAR1_FACE_REF_PATH ?? "").trim();
  const char1Detail = String(normalized.CHAR1_DETAIL_REF_PATH ?? "").trim();
  const char1Primary = String(normalized.CHAR1_PRIMARY_PATH ?? "").trim();
  const char1Secondary = String(normalized.CHAR1_SECONDARY_PATH ?? "").trim();
  const maskChar1Name = String(normalized.STORYBOARD_MASK_CHAR1_NAME ?? char1Name).trim() || char1Name;
  const maskChar1Primary = String(normalized.STORYBOARD_MASK_CHAR1_PRIMARY_PATH ?? char1Primary).trim() || char1Primary;
  const passAMaskPath = String(normalized.PASS_A_CHARACTER_MASK_PATH ?? "").trim();
  const sceneRefPath = String(normalized.SCENE_REF_PATH ?? "").trim();
  const frameSeedMode = String(normalized.STORYBOARD_FRAME_SEED_MODE ?? "").trim().toLowerCase();
  const currentFrameSeed = String(normalized.FRAME_IMAGE_PATH ?? "").trim();
  const preserveExplicitFrameSeed = String(normalized.STORYBOARD_PRESERVE_FRAME_IMAGE_PATH ?? "").trim() === "1";
  const stageAFrameSeed =
    preserveExplicitFrameSeed && currentFrameSeed.length > 0
      ? currentFrameSeed
      : frameSeedMode === "composite" && currentFrameSeed.length > 0
      ? currentFrameSeed
      : sceneRefPath || currentFrameSeed;

  const characterRefIds = splitCsv(String(normalized.CHARACTER_REFS ?? "").trim());

  return {
    ...normalized,
    CHAR2_NAME: "",
    CHAR2_FRONT_PATH: "",
    CHAR2_SIDE_PATH: "",
    CHAR2_BACK_PATH: "",
    CHAR2_FACE_REF_PATH: "",
    CHAR2_DETAIL_REF_PATH: "",
    CHAR2_PRIMARY_PATH: "",
    CHAR2_SECONDARY_PATH: "",
    CHAR2_PRIMARY_WEIGHT: "0",
    CHAR2_SECONDARY_WEIGHT: "0",
    CHARACTER_REF_NAMES: char1Name,
    CHARACTER_FRONT_PATHS: char1Front,
    CHARACTER_SIDE_PATHS: char1Side,
    CHARACTER_BACK_PATHS: char1Back,
    CHARACTER_REF_PATHS: [char1Front, char1Side, char1Back].filter((item) => item.length > 0).join(","),
    CHARACTER_REFS: characterRefIds.slice(0, 1).join(","),
    CHAR1_FACE_REF_PATH: char1Face,
    CHAR1_DETAIL_REF_PATH: char1Detail,
    CHAR1_PRIMARY_PATH: char1Primary,
    CHAR1_SECONDARY_PATH: char1Secondary,
    STORYBOARD_MASK_CHAR1_NAME: maskChar1Name,
    STORYBOARD_MASK_CHAR2_NAME: "",
    STORYBOARD_MASK_CHAR1_PRIMARY_PATH: maskChar1Primary,
    STORYBOARD_MASK_CHAR2_PRIMARY_PATH: "",
    FRAME_IMAGE_PATH: stageAFrameSeed,
    PASS_B_CHARACTER_MASK_PATH: passAMaskPath,
    PASS_EDGE_CHARACTER_MASK_PATH: String(normalized.PASS_EDGE_CHARACTER_MASK_PATH ?? passAMaskPath).trim() || passAMaskPath
  };
}

type StageDualCharacterSlot = {
  slot: 1 | 2;
  name: string;
  frontPath: string;
  sidePath: string;
  backPath: string;
  faceRefPath: string;
  detailRefPath: string;
  primaryPath: string;
  secondaryPath: string;
  primaryWeight: string;
  secondaryWeight: string;
  sideDirection: string;
  mirrorSideForOpposite: string;
};

function normalizeStageCharacterNameForMatch(value: string): string {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[\s_\-.,，。！!？?"“”‘’'()（）\[\]{}]/g, "");
}

function readStageDualCharacterSlot(tokens: Record<string, string>, slot: 1 | 2): StageDualCharacterSlot {
  return {
    slot,
    name: String(tokens[`CHAR${slot}_NAME`] ?? "").trim(),
    frontPath: String(tokens[`CHAR${slot}_FRONT_PATH`] ?? "").trim(),
    sidePath: String(tokens[`CHAR${slot}_SIDE_PATH`] ?? "").trim(),
    backPath: String(tokens[`CHAR${slot}_BACK_PATH`] ?? "").trim(),
    faceRefPath: String(tokens[`CHAR${slot}_FACE_REF_PATH`] ?? "").trim(),
    detailRefPath: String(tokens[`CHAR${slot}_DETAIL_REF_PATH`] ?? "").trim(),
    primaryPath: String(tokens[`CHAR${slot}_PRIMARY_PATH`] ?? "").trim(),
    secondaryPath: String(tokens[`CHAR${slot}_SECONDARY_PATH`] ?? "").trim(),
    primaryWeight: String(tokens[`CHAR${slot}_PRIMARY_WEIGHT`] ?? "").trim(),
    secondaryWeight: String(tokens[`CHAR${slot}_SECONDARY_WEIGHT`] ?? "").trim(),
    sideDirection: String(tokens[`CHAR${slot}_SIDE_VIEW_DIRECTION`] ?? "").trim(),
    mirrorSideForOpposite: String(tokens[`CHAR${slot}_MIRROR_SIDE_FOR_OPPOSITE`] ?? "").trim()
  };
}

function writeStageDualCharacterSlot(
  target: Record<string, string>,
  slot: 1 | 2,
  value: StageDualCharacterSlot | null
) {
  target[`CHAR${slot}_NAME`] = value?.name ?? "";
  target[`CHAR${slot}_FRONT_PATH`] = value?.frontPath ?? "";
  target[`CHAR${slot}_SIDE_PATH`] = value?.sidePath ?? "";
  target[`CHAR${slot}_BACK_PATH`] = value?.backPath ?? "";
  target[`CHAR${slot}_FACE_REF_PATH`] = value?.faceRefPath ?? "";
  target[`CHAR${slot}_DETAIL_REF_PATH`] = value?.detailRefPath ?? "";
  target[`CHAR${slot}_PRIMARY_PATH`] = value?.primaryPath ?? "";
  target[`CHAR${slot}_SECONDARY_PATH`] = value?.secondaryPath ?? "";
  target[`CHAR${slot}_PRIMARY_WEIGHT`] = value?.primaryWeight ?? target[`CHAR${slot}_PRIMARY_WEIGHT`] ?? "";
  target[`CHAR${slot}_SECONDARY_WEIGHT`] = value?.secondaryWeight ?? target[`CHAR${slot}_SECONDARY_WEIGHT`] ?? "";
  target[`CHAR${slot}_SIDE_VIEW_DIRECTION`] = value?.sideDirection ?? "";
  target[`CHAR${slot}_MIRROR_SIDE_FOR_OPPOSITE`] = value?.mirrorSideForOpposite ?? "";
}

function alignQwenStageBCharacterSlotsByRole(
  tokens: Record<string, string>,
  stageACharacterName: string,
  stageBCharacterName: string
): Record<string, string> {
  const desiredStageA = normalizeStageCharacterNameForMatch(stageACharacterName);
  if (!desiredStageA) return tokens;
  const slots = [readStageDualCharacterSlot(tokens, 1), readStageDualCharacterSlot(tokens, 2)];
  const findSlotByName = (name: string, excludeSlot: number | null = null): StageDualCharacterSlot | null => {
    const normalizedName = normalizeStageCharacterNameForMatch(name);
    if (!normalizedName) return null;
    const exact =
      slots.find(
        (slot) =>
          slot.slot !== excludeSlot &&
          normalizeStageCharacterNameForMatch(slot.name) === normalizedName
      ) ?? null;
    if (exact) return exact;
    return (
      slots.find((slot) => {
        if (slot.slot === excludeSlot) return false;
        const candidate = normalizeStageCharacterNameForMatch(slot.name);
        if (!candidate) return false;
        return candidate.includes(normalizedName) || normalizedName.includes(candidate);
      }) ?? null
    );
  };

  const primarySlot = findSlotByName(stageACharacterName);
  if (!primarySlot) return tokens;
  const secondarySlot =
    findSlotByName(stageBCharacterName, primarySlot.slot) ??
    slots.find((slot) => slot.slot !== primarySlot.slot) ??
    null;

  const aligned: Record<string, string> = { ...tokens };
  writeStageDualCharacterSlot(aligned, 1, primarySlot);
  writeStageDualCharacterSlot(aligned, 2, secondarySlot);

  const frontPaths = [aligned.CHAR1_FRONT_PATH, aligned.CHAR2_FRONT_PATH].filter((item) => String(item ?? "").trim().length > 0);
  const sidePaths = [aligned.CHAR1_SIDE_PATH, aligned.CHAR2_SIDE_PATH].filter((item) => String(item ?? "").trim().length > 0);
  const backPaths = [aligned.CHAR1_BACK_PATH, aligned.CHAR2_BACK_PATH].filter((item) => String(item ?? "").trim().length > 0);
  const allRefPaths = [
    aligned.CHAR1_FRONT_PATH,
    aligned.CHAR1_SIDE_PATH,
    aligned.CHAR1_BACK_PATH,
    aligned.CHAR2_FRONT_PATH,
    aligned.CHAR2_SIDE_PATH,
    aligned.CHAR2_BACK_PATH
  ].filter((item) => String(item ?? "").trim().length > 0);
  const names = [aligned.CHAR1_NAME, aligned.CHAR2_NAME].filter((item) => String(item ?? "").trim().length > 0);

  aligned.CHARACTER_FRONT_PATHS = frontPaths.join(",");
  aligned.CHARACTER_SIDE_PATHS = sidePaths.join(",");
  aligned.CHARACTER_BACK_PATHS = backPaths.join(",");
  aligned.CHARACTER_REF_PATHS = allRefPaths.join(",");
  aligned.CHARACTER_REF_NAMES = names.join(",");
  return aligned;
}

function buildQwenStageBStoryboardPrompt(fullPrompt: string, char1Name: string, char2Name: string): string {
  const normalized = sanitizeStoryboardPromptForStage(fullPrompt);
  const shotScale = inferStoryboardCompositeScaleFromCorpus(normalized.toLowerCase());
  const fullBodyContinuityRequired = containsAnyKeyword(normalized, [
    "full body",
    "head to toe",
    "feet visible",
    "feet touching the ground",
    "全身",
    "头到脚",
    "脚部可见",
    "脚不被裁切",
    "完整全身",
    "保留全身"
  ]);
  const stageBFramingLock =
    shotScale === "wide"
      ? "Wide establishing composition: keep both characters full body but relatively small in frame, with broad riverbank/environment context and no medium-close crop."
      : shotScale === "medium"
        ? "Medium-shot composition: keep both characters around knee-up to full-body in frame with stable spacing; avoid portrait-only cropping."
        : shotScale === "close"
          ? "Close-shot composition: prioritize the scripted speaking/focus character in close framing while keeping the partner identity readable in its slot; do not force both roles into tiny full-body silhouettes."
          : "Respect the scripted framing scale and preserve stable character size and spacing.";
  const stageBBodyIntegrityLine =
    shotScale === "close"
      ? "Maintain clean anatomy and readable facial expression for the focus role, while preserving partner identity and outfit consistency in the allowed crop."
      : "Final frame must preserve coherent anatomy for both roles, readable expressions, and stable scene integration.";
  const dialogueLike = /(?:dialogue|conversation|talk|speak|reply|respond|对话|交谈|说话|回应|对视|看向|看着)/iu.test(normalized);
  const cameraFacingForced = /(?:facing camera|toward camera|look at camera|直视镜头|面向镜头|面对镜头|朝向镜头)/iu.test(normalized);
  const dialogueIntent =
    dialogueLike || /(?:exchange lines|face to face|mutual eyeline|对话|说话|回应|交谈|对视|注视|看向)/iu.test(normalized);
  const dialogueFacingLine =
    dialogueIntent && !cameraFacingForced
      ? "For dialogue beats, keep both characters oriented toward each other with mutual eyeline; do not stage both as front-facing camera poses."
      : "";
  const dialogueMutualGazeLockLines =
    dialogueIntent && !cameraFacingForced
      ? [
          "Dialogue blocking lock: stage both characters in a face-to-face conversation pose with reciprocal eyeline.",
          "Dialogue camera lock: avoid front-facing portrait pose or direct gaze to camera for both characters unless explicitly requested by the shot script.",
          "Keep character A stable, but if orientation adjustment is needed, preserve identity while rotating into a natural three-quarter conversational angle."
        ]
      : [];
  const fullBodyContinuityLines = fullBodyContinuityRequired
    ? [
        `Scripted body-retention lock: keep both ${char1Name || "character A"} and ${char2Name || "character B"} readable head to toe when the shot requires full-body continuity.`,
        "Do not solve near-medium intimacy by cropping either role into a portrait; preserve whole-body staging, grounded feet, and scene depth instead."
      ]
    : [];
  return [
    normalized,
    `Stage B target: keep ${char1Name || "character A"} unchanged and add exactly one new visible person only, ${char2Name || "character B"}.`,
    `Only allowed human identities in the final frame are ${char1Name || "character A"} and ${char2Name || "character B"}; do not introduce any other person, bystander, reflection person, or background face.`,
    `Add ${char2Name || "the second character"} according to the shot script blocking and action timing, while preserving ${char1Name || "character A"} face, outfit, pose rhythm, and body scale.`,
    `Character B must strictly follow the character-B primary reference for face, hairstyle, outfit palette, and silhouette. Do not invent unrelated costume.`,
    "Place character B strictly inside the pass-B mask slot; do not move character B to a different slot.",
    "Keep character A anchored in the pass-A slot; do not relocate either character and do not recenter camera.",
    "Preserve the scene layout, bridge opening, riverbank path, perspective, horizon, and lighting from the base frame.",
    "Preserve the same time-of-day and scene atmosphere from the scene reference and Stage A base; do not reset into a different location style.",
    dialogueFacingLine,
    stageBFramingLock,
    ...fullBodyContinuityLines,
    ...dialogueMutualGazeLockLines,
    "Hard rule: final Stage B frame must contain exactly two people, no more and no less.",
    stageBBodyIntegrityLine,
    "Keep high-frequency details and smooth edges across both characters; avoid coarse pixelation and blocky textures.",
    "Do not replace the first character, do not add a third person, and do not turn either role into a sticker-like cutout."
  ]
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .join("\n");
}

