function buildStableStoryboardPassAReservePrompt(fullPrompt: string, char1Name: string, char2Name: string): string {
  const roleNames = collectStableStoryboardRoleNames(char1Name, char2Name);
  if (roleNames.length === 0) return normalizePromptBody(fullPrompt);
  const roleLabel = formatStableStoryboardRoleLabel(roleNames);
  const normalizedPrompt = fullPrompt.toLowerCase();
  const allowsRearView = containsAnyKeyword(normalizedPrompt, [
    "back view",
    "rear view",
    "from behind",
    "back turned",
    "turned away",
    "背影",
    "背面",
    "转身离开"
  ]);
  const roleCountLine =
    roleNames.length === 1
      ? `Exactly one story character only: ${roleLabel}.`
      : `Exactly ${roleNames.length} story characters only: ${roleLabel}.`;
  const anatomyLine =
    roleNames.length === 1
      ? `Pass A must render ${roleLabel} as a normal full-body human with readable anatomy, a clear pose, stable proportions, grounded feet, and obvious head-to-toe presence.`
      : `Pass A must already render ${roleLabel} as normal full-body humans with readable anatomy, clear pose, correct body scale, grounded feet, and obvious head-to-toe presence.`;
  const identityLine =
    roleNames.length === 1
      ? `Keep ${roleLabel} aligned to that character's own reference image; do not let the face, hair, outfit, or body proportions drift away from the supplied character reference.`
      : `Each role must stay aligned to that character's own reference image; do not merge faces, swap outfits, or let one role overwrite the other.`;
  return [
    `Character plate generation only.`,
    roleCountLine,
    `Pass A must render the required character${roleNames.length === 1 ? "" : "s"} as normal detailed humans on a plain light gray solid background that will be discarded during compositing.`,
    anatomyLine,
    `Use even neutral studio lighting with clear front fill so the face, hair, eyes, clothing texture, hands, and feet stay readable. The result must not look backlit, silhouetted, or swallowed by shadow.`,
    `Follow the shared pose guide exactly so the body action, limb direction, stance, and ground contact stay readable.`,
    `The supplied character reference set is the identity source. Match the face, hairstyle silhouette, bangs, eye shape, outfit layers, neckline, collar, sleeve design, waist seam, belt placement, hem length, color blocking, fabric structure, and shoes from that reference set instead of inventing new design details.`,
    `Preserve the character's facial structure and default expression language from the face anchor. Lock the same eyebrow shape, eye spacing, nose shape, lip shape, cheek contour, and expression mood. Do not replace it with a blank mannequin face, a generic smile, or an unrelated expression.`,
    `Treat the clothing anchor as authoritative for outfit coverage and garment length. Keep the same outer-layer count, same sleeve length, same skirt or coat length, same lower-body coverage, and same footwear. Never shorten, expose, simplify, glamourize, or redesign the costume.`,
    `Ignore shot-level requests about other characters, same-frame staging, dialogue partners, scene props, bridge elements, river background, signage, symbols, or any environment detail. Pass A is a single-character people plate only.`,
    allowsRearView
      ? `Respect the supplied pose guide's body direction, including rear-facing orientation when required. Preserve clean anatomy and ground contact, and never add a second frontal portrait, floating bust, or duplicate body just to show the face.`
      : `Respect the supplied pose guide's body direction and camera-facing angle. If the pose naturally shows the face, keep it readable; if it is profile or partially turned, preserve that orientation instead of inventing a separate frontal portrait. Never add a second head, floating bust, reference portrait, or duplicate body to show the face.`,
    identityLine,
    `Preserve footwear, hem structure, and lower-body costume cues from the supplied character reference instead of replacing them with barefoot legs, generic pants, or missing shoes.`,
    `The required character must occupy most of the frame height in pass A, stay visually centered as the only readable subject, and never appear as a distant small figure.`,
    `Keep the characters large and visually clear at storyboard scale, with readable facial features, readable clothing folds, and solid limb definition.`,
    `Do not spend detail on final scenery in pass A. No bridge, no riverbank, no horizon, no dusk landscape, no environment props, and no decorative background competing with the body shapes.`,
    `The plate is invalid if any required character is missing, tiny, cropped, melted, merged, turned into a silhouette blob, low-contrast shadow smear, or swallowed by random background fragments.`
  ]
    .filter((line) => line.length > 0)
    .join("\n");
}

