function buildStableStoryboardPassBRecoverPrompt(fullPrompt: string, char1Name: string, char2Name: string): string {
  const normalized = normalizePromptBody(fullPrompt);
  const roleNames = collectStableStoryboardRoleNames(char1Name, char2Name);
  if (!normalized || roleNames.length === 0) return normalized;
  const roleLabel = formatStableStoryboardRoleLabel(roleNames);
  const roleCountLine =
    roleNames.length === 1
      ? `Exactly one story character only: ${roleLabel}.`
      : `Exactly ${roleNames.length} story characters only: ${roleLabel}.`;
  const refinementLine =
    roleNames.length === 1
      ? `Blend ${roleLabel} cleanly into the locked background with natural edge lighting, grounded feet, believable contact shadows, and a normal human silhouette.`
      : `Blend ${roleLabel} cleanly into the locked background with natural edge lighting, grounded feet, believable contact shadows, and normal human silhouettes.`;
  return [
    normalized,
    roleCountLine,
    `Pass B is the masked img2img integration pass. Start from the locked background plus the composited character plate, and only repair the outer contour, foot-to-ground contact area, contact shadow, and local lighting transition around the characters.`,
    refinementLine,
    `Preserve the exact scene layout, camera framing, pose blocking, face placement, clothing design, and body proportions from the composite. Do not restage, enlarge, shrink, rotate, or replace any role.`,
    `Keep the character interior crisp and high-definition. Preserve facial features, hands, feet, hair strands, clothing folds, and line clarity from the composite instead of softening or repainting them.`,
    `Do not redraw the whole scene, do not repaint the body interior, and do not turn the integration pass into a full-frame regeneration.`
  ]
    .filter((line) => line.length > 0)
    .join("\n");
}

