function storyboardScreenZoneLabel(centerXRatio: number): string {
  if (centerXRatio <= 0.18) return "画面左边缘";
  if (centerXRatio <= 0.36) return "画面左侧";
  if (centerXRatio <= 0.47) return "画面中左";
  if (centerXRatio < 0.53) return "画面中间";
  if (centerXRatio < 0.66) return "画面中右";
  if (centerXRatio < 0.82) return "画面右侧";
  return "画面右边缘";
}

function storyboardDepthLabel(floorYRatio: number): string {
  if (floorYRatio >= 0.92) return "更靠前";
  if (floorYRatio >= 0.87) return "中前景";
  if (floorYRatio >= 0.82) return "中景";
  return "偏后";
}

function storyboardScaleLabel(sizeScale: number): string {
  if (sizeScale >= 1.02) return "主体更大";
  if (sizeScale <= 0.84) return "次要更小";
  return "常规大小";
}


function extractCharacterActionCues(text: string, characterNames: string[]): Array<{ characterName: string; actionCue: string }> {
  const cues = [];
  let remainingText = text;

  for (const characterName of characterNames) {
    const regex = new RegExp(`${characterName}([^,.]*)`, 'g');
    let match;
    while ((match = regex.exec(remainingText)) !== null) {
      cues.push({ characterName, actionCue: match[1].trim() });
    }
  }

  return cues;
}

function buildStoryboardBlockingDirective(shot: Shot, characterAssets: Asset[]): string {
  if (characterAssets.length === 0) return "";
  const refs = characterAssets.map((asset) => ({
    source: asset.characterFrontPath || asset.filePath || "",
    weight: 1,
    priority: 1,
    bucket: `character:${asset.id}`,
    label: `${asset.name}:front`,
    role: "character_front" as WeightedImageRef["role"]
  }));
  const placements = inferStoryboardCompositeLayout(shot, refs);
  const exactCountLine =
    characterAssets.length === 1
      ? `构图硬约束：本镜头只允许 1 名主体角色清晰可见，即“${characterAssets[0]!.name}”。`
      : `构图硬约束：本镜头必须清晰呈现 ${characterAssets.length} 名角色，且人数必须与剧本一致，不得多也不得少。`;
  const allowedIdentityLine =
    characterAssets.length > 0
      ? `Identity lock: only these scripted characters may appear in this frame: ${characterAssets
          .map((asset) => asset.name)
          .join(", ")}. No stranger, no bystander, no extra silhouette, no reflection person, and no background face.`
      : "";
  const shotActionCue = compactTextParts(shot.title, shot.storyPrompt, shot.notes, shot.videoPrompt)
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 220);

  const characterCues = extractCharacterActionCues(shotActionCue, characterAssets.map(c => c.name));
  const actionLines = characterCues.map(cue => `动作硬约束（${cue.characterName}）: ${cue.actionCue}`);

  const genericActionLine = shotActionCue
    ? `动作硬约束：严格执行本镜头脚本动作（${shotActionCue}），禁止把角色退化为静止站姿、模板摆拍或与剧情无关的姿态。`
    : "动作硬约束：严格执行本镜头脚本动作，禁止把角色退化为静止站姿、模板摆拍或与剧情无关的姿态。";

  const finalActionLines = actionLines.length > 0 ? actionLines : [genericActionLine];
  const interactionCorpus = compactTextParts(
    shot.title,
    shot.storyPrompt,
    shot.notes,
    shot.videoPrompt,
    shot.dialogue,
    ...(shot.tags ?? [])
  ).toLowerCase();
  const dialogueLike =
    Boolean(shot.dialogue?.trim()) ||
    containsAnyKeyword(interactionCorpus, [
      "对话",
      "交谈",
      "说话",
      "回应",
      "对视",
      "看向",
      "看着",
      "conversation",
      "dialogue",
      "talk",
      "speak",
      "reply",
      "respond",
      "eyeline",
      "eye contact"
    ]);
  const cameraFacingForced = containsAnyKeyword(interactionCorpus, [
    "直视镜头",
    "面向镜头",
    "面对镜头",
    "朝向镜头",
    "正对镜头",
    "facing camera",
    "toward camera",
    "look at camera"
  ]);
  const dialogueFacingLine =
    characterAssets.length >= 2 && dialogueLike && !cameraFacingForced
      ? "对话朝向硬约束：双人对白镜头中，两位角色必须以彼此为视线目标并相向站位，优先互相看向对方；禁止两人同时正面朝镜头摆拍。"
      : "";
  const sceneLockLine = containsAnyKeyword(interactionCorpus, [
    "河边",
    "河岸",
    "石桥",
    "同场景",
    "连续",
    "river",
    "riverbank",
    "bridge",
    "same scene",
    "continuity"
  ])
    ? "场景连续硬约束：保持已建立的同一环境布局与时间氛围（河岸/石桥/石路等），禁止切换成不相关的新场景风格。"
    : "";
  const performanceLine =
    "表演硬约束：所有出镜角色都必须表现出清晰可见的身体动作和与情境一致的面部表情，不允许木讷站立、没有表情、没有反应或像证件照一样僵硬。";
  const framingConflictLine =
    "景别冲突处理规则：如果文案里出现近景、中景、反应镜头等表述，但本工作流又要求 full body，则必须以 full body 为最高优先级，通过让人物在画面中更大、更靠前来体现景别，禁止把头顶、脚底、手臂或躯干裁出画面，禁止退化成半身像或肖像裁切。";

  const placementLines = characterAssets.map((asset, index) => {
    const placement = placements[index] ?? placements[placements.length - 1] ?? { centerXRatio: 0.5, floorYRatio: 0.88, sizeScale: 1 };
    return `站位硬约束：角色“${asset.name}”位于${storyboardScreenZoneLabel(placement.centerXRatio)}、${storyboardDepthLabel(placement.floorYRatio)}，画面尺度为${storyboardScaleLabel(placement.sizeScale)}；该角色不得缺失，不得被另一角色替代，也不得缩成不可辨识的小人。`;
  });
  return [exactCountLine, allowedIdentityLine, ...finalActionLines, dialogueFacingLine, sceneLockLine, performanceLine, framingConflictLine, ...placementLines]
    .filter((line) => line.trim().length > 0)
    .join("\n");
}

function buildStoryboardStabilityDirective(hasSceneRef: boolean, hasCharacters: boolean): string {
  const parts: string[] = [
    "画面稳定约束：单张分镜图，透视关系稳定，构图清晰，主体边界清楚，拒绝抽象涂抹和随机扭曲。",
    "clean single storyboard frame, coherent perspective, clear composition, no surreal warping, no abstract artifacts.",
    "物理常识约束：重力方向、接触关系和遮挡关系合理，禁止人物漂浮、穿透地面或与场景尺度冲突。",
    "光照约束：主光方向统一，人物与场景阴影逻辑一致，不允许前后光源矛盾。"
  ];
  if (hasSceneRef) {
    parts.push("场景稳定约束：地平线、道路、栏杆、树木、建筑等结构保持笔直或自然透视，不允许融化、卷曲、漂浮。");
  }
  if (hasCharacters) {
    parts.push("人物稳定约束：人物解剖正确，四肢完整，站姿自然，禁止畸形肢体、重复身体、拼贴分身。");
    parts.push("人物尺度约束：人物头身比、手脚比例、与环境物体尺度保持常识范围，不允许巨人化或玩偶化。");
    parts.push("人物融合约束：人物轮廓、灰度、线条密度、材质表现与场景统一，不允许贴纸感、硬边抠图感、白底残留或人物像单独图层漂浮在背景前。");
    parts.push("表演稳定约束：角色动作要自然符合正常审美和身体重心，面部表情要清楚可读，不允许僵硬站桩、木偶姿势或空白脸。");
  }
  return parts.join("\n");
}

function shouldUseSecondaryCharacterView(shot: Shot): boolean {
  const corpus = [shot.title ?? "", shot.storyPrompt ?? "", shot.videoPrompt ?? "", shot.notes ?? "", ...(shot.tags ?? [])]
    .join(" ")
    .toLowerCase();
  return containsAnyKeyword(corpus, [
    "侧身",
    "回头",
    "背影",
    "背面",
    "背对",
    "profile",
    "side view",
    "back view",
    "over shoulder"
  ]);
}

function countExplicitShotCharacters(shot: Shot): number {
  const byRefs = shot.characterRefs?.filter((item) => item.trim().length > 0).length ?? 0;
  const byNames = shot.sourceCharacterNames?.filter((item) => item.trim().length > 0).length ?? 0;
  return Math.max(byRefs, byNames);
}

function inferPromptMentionedCharacterCount(shot: Shot, characterAssets: Asset[]): number {
  const corpus = compactTextParts(
    shot.title,
    shot.storyPrompt,
    shot.notes,
    shot.dialogue,
    shot.videoPrompt,
    ...(shot.tags ?? [])
  ).toLowerCase();
  if (!corpus.trim()) return 0;
  const names = uniquePreserveOrder(
    characterAssets
      .map((asset) => asset.name.trim().toLowerCase())
      .filter((name) => name.length > 0)
  );
  return names.filter((name) => corpus.includes(name)).length;
}

function inferRequiredStoryboardCharacterCount(shot: Shot, characterAssets: Asset[]): number {
  return Math.max(countExplicitShotCharacters(shot), inferPromptMentionedCharacterCount(shot, characterAssets));
}

function inferStrictStoryboardCharacterNames(shot: Shot, characterAssets: Asset[]): string[] {
  const explicitNames = uniquePreserveOrder(
    (shot.sourceCharacterNames ?? []).map((item) => item.trim()).filter((item) => item.length > 0)
  );
  if (explicitNames.length >= 2) return explicitNames.slice(0, 2);

  const corpus = compactTextParts(
    shot.title,
    shot.storyPrompt,
    shot.notes,
    shot.dialogue,
    shot.videoPrompt,
    ...(shot.tags ?? [])
  ).toLowerCase();
  const mentionedNames = characterAssets
    .map((asset, index) => {
      const name = asset.name.trim();
      return {
        name,
        index,
        mentionAt: name ? corpus.indexOf(name.toLowerCase()) : -1
      };
    })
    .filter((item) => item.name.length > 0 && item.mentionAt >= 0)
    .sort((left, right) => left.mentionAt - right.mentionAt || left.index - right.index)
    .map((item) => item.name);
  if (mentionedNames.length >= 2) return uniquePreserveOrder(mentionedNames).slice(0, 2);

  return uniquePreserveOrder(
    [...explicitNames, ...characterAssets.map((item) => item.name.trim())].filter((item) => item.length > 0)
  ).slice(0, 2);
}

function shotRequiresStrictDualCharactersInComfy(shot: Shot): boolean {
  const corpus = compactTextParts(
    shot.title,
    shot.storyPrompt,
    shot.videoPrompt,
    shot.notes,
    shot.dialogue,
    ...(shot.tags ?? []),
    ...(shot.sourceCharacterNames ?? [])
  );
  if (!corpus.trim()) return false;
  const compact = corpus.replace(/\s+/g, "");
  if (/蹇呴』涓斿彧鑳芥湁2浜簗鍙兘鏈?浜簗蹇呴』2浜?/.test(compact)) return true;
  const lower = corpus.toLowerCase();
  return (
    /\bexact character count\s*(?:is|=)\s*2\b/i.test(lower) ||
    /\bexactly\s*2\s*(?:people|characters)\b/i.test(lower) ||
    /\bboth characters?\b/i.test(lower) ||
    /\btwo characters?\b/i.test(lower) ||
    /\btwo people\b/i.test(lower) ||
    /鍙屼汉|涓や汉|浜屼汉/.test(corpus)
  );
}

function repairStoryboardShotForStagedGeneration(shot: Shot, assets: Asset[]): Shot {
  const characterAssets = assets.filter((item) => item.type === "character");
  if (characterAssets.length <= 0) return shot;

  const canonicalCharacterMap = buildCanonicalPrimaryCharacterMap(characterAssets);
  const shouldForceDual = shotRequiresStrictDualCharactersInComfy(shot);
  const repairedNames = shouldForceDual
    ? inferStrictStoryboardCharacterNames(shot, characterAssets)
    : uniquePreserveOrder((shot.sourceCharacterNames ?? []).map((item) => item.trim()).filter((item) => item.length > 0));
  const repairedRefs = uniquePreserveOrder([
    ...repairedNames
      .map((name) => resolveCharacterAssetIdByName(assets, canonicalCharacterMap, name))
      .filter((id) => id.length > 0),
    ...(shot.characterRefs ?? [])
      .map((id) => normalizeCharacterAssetRefId(assets, canonicalCharacterMap, id))
      .filter((id) => id.length > 0)
  ]);

  if (!shouldForceDual) return shot;
  if (repairedNames.length < 2 || repairedRefs.length < 2) return shot;

  const currentNames = uniquePreserveOrder((shot.sourceCharacterNames ?? []).map((item) => item.trim()).filter((item) => item.length > 0));
  const currentRefs = uniquePreserveOrder(
    (shot.characterRefs ?? [])
      .map((id) => normalizeCharacterAssetRefId(assets, canonicalCharacterMap, id))
      .filter((id) => id.length > 0)
  );
  if (currentNames.join("|") === repairedNames.join("|") && currentRefs.join("|") === repairedRefs.join("|")) {
    return shot;
  }

  return {
    ...shot,
    sourceCharacterNames: repairedNames,
    characterRefs: repairedRefs
  };
}

function selectStoryboardCharacterAssets(shot: Shot, assets: Asset[]): Asset[] {
  const inferDesiredStoryboardNames = () => {
    const explicitNames = uniquePreserveOrder(
      (shot.sourceCharacterNames ?? []).map((item) => item.trim().toLowerCase()).filter(Boolean)
    );
    if (explicitNames.length > 0) return explicitNames;

    const corpus = compactTextParts(
      shot.title,
      shot.storyPrompt,
      shot.notes,
      shot.dialogue,
      shot.videoPrompt,
      ...(shot.tags ?? [])
    ).toLowerCase();
    const mentionedNames = assets
      .map((asset, index) => {
        const normalizedName = asset.name.trim().toLowerCase();
        return {
          normalizedName,
          index,
          mentionIndex: normalizedName ? corpus.indexOf(normalizedName) : -1
        };
      })
      .filter((item) => item.normalizedName.length > 0 && item.mentionIndex >= 0)
      .sort((left, right) => left.mentionIndex - right.mentionIndex || left.index - right.index)
      .map((item) => item.normalizedName);
    return uniquePreserveOrder(mentionedNames);
  };

  const orderedAssets = (() => {
    if (assets.length <= 1) return assets;
    const desiredNames = inferDesiredStoryboardNames();
    if (desiredNames.length === 0) return assets;
    const ordered: Asset[] = [];
    const usedIds = new Set<string>();
    for (const desiredName of desiredNames) {
      const matched = assets.find((asset) => asset.name.trim().toLowerCase() === desiredName);
      if (!matched || usedIds.has(matched.id)) continue;
      ordered.push(matched);
      usedIds.add(matched.id);
    }
    for (const asset of assets) {
      if (usedIds.has(asset.id)) continue;
      ordered.push(asset);
      usedIds.add(asset.id);
    }
    return ordered;
  })();
  if (orderedAssets.length <= 1) return orderedAssets;
  const requiredCharacterCount = inferRequiredStoryboardCharacterCount(shot, orderedAssets);
  if (requiredCharacterCount >= 2) {
    // Respect explicit per-shot bindings first. If the script explicitly binds two
    // characters, do not let close-up heuristics silently degrade to single-person.
    return orderedAssets.slice(0, 2);
  }
  const corpus = [shot.title ?? "", shot.storyPrompt ?? "", shot.videoPrompt ?? "", shot.notes ?? "", ...(shot.tags ?? [])]
    .join(" ")
    .toLowerCase();
  const closeFramingLikely = containsAnyKeyword(corpus, [
    "特写",
    "近景",
    "中近景",
    "反应",
    "半身",
    "面部",
    "胸像",
    "close-up",
    "medium close",
    "reaction"
  ]);
  const forcedDualByAction = containsAnyKeyword(corpus, [
    "exact character count is 2",
    "only 2",
    "both characters",
    "双人",
    "两人",
    "二人",
    "对峙",
    "对打",
    "打斗",
    "交手",
    "冲拳",
    "直拳",
    "闪避",
    "反击",
    "互相",
    "face off",
    "duel",
    "versus"
  ]);
  if (closeFramingLikely && !forcedDualByAction) {
    const focusedName = inferStoryboardFocusedCharacterName(
      shot,
      orderedAssets.map((asset) => asset.name.trim()).filter((value) => value.length > 0)
    );
    if (focusedName) {
      const focusedAsset = orderedAssets.find(
        (asset) => asset.name.trim().toLowerCase() === focusedName.trim().toLowerCase()
      );
      if (focusedAsset) return [focusedAsset];
    }
    const directlyMentionedAsset = orderedAssets.find((asset) => corpus.includes(asset.name.toLowerCase()));
    if (directlyMentionedAsset) return [directlyMentionedAsset];
    return [orderedAssets[0]!];
  }
  if (
    containsAnyKeyword(corpus, [
      "exact character count is 2",
      "only 2",
      "both characters",
      "两个人都",
      "两人都",
      "双人",
      "二人"
    ])
  ) {
    return orderedAssets.slice(0, 2);
  }
  const isForcedDual = containsAnyKeyword(corpus, [
    "双人",
    "两人",
    "二人",
    "对峙",
    "对打",
    "打斗",
    "交手",
    "冲拳",
    "直拳",
    "闪避",
    "反击",
    "互相",
    "face off",
    "duel",
    "versus"
  ]);
  if (isForcedDual) return orderedAssets.slice(0, 2);

  const mentioned = orderedAssets.filter((asset) => corpus.includes(asset.name.toLowerCase()));
  if (mentioned.length === 1) return [mentioned[0]!];
  if (mentioned.length >= 2) return mentioned.slice(0, 2);

  const likelySingleFraming = containsAnyKeyword(corpus, [
    "特写",
    "近景",
    "中近景",
    "反应",
    "半身",
    "面部",
    "胸像",
    "close-up",
    "medium close",
    "reaction"
  ]);
  if (likelySingleFraming) return [orderedAssets[0]!];
  return orderedAssets.slice(0, 2);
}

function buildQwenReferenceInstruction(tokens: Record<string, string>): string {
  const sceneName = tokens.SCENE_REF_NAME?.trim() ?? "";
  const characterNames = splitCsv(tokens.CHARACTER_REF_NAMES);
  const preferredCharacterView = tokens.PREFERRED_CHARACTER_VIEW?.trim().toLowerCase() ?? "";
  const cameraYaw = tokens.CAMERA_YAW?.trim() ?? "";
  const cameraPitch = tokens.CAMERA_PITCH?.trim() ?? "";
  const cameraFov = tokens.CAMERA_FOV?.trim() ?? "";
  const previousSceneTitle = tokens.PREV_SCENE_SHOT_TITLE?.trim() ?? "";
  const previousCharacterTitle = tokens.PREV_CHARACTER_SHOT_TITLE?.trim() ?? "";
  const globalVisualStyle = tokens.GLOBAL_VISUAL_STYLE?.trim() ?? "";
  const currentShotTitle = tokens.SHOT_TITLE?.trim() ?? "";
  const pieces = ["Treat every provided input image as a binding reference, not optional inspiration."];
  if (globalVisualStyle) {
    pieces.push(`Keep one unified visual style across every shot: ${globalVisualStyle}.`);
    if (/2d|二维|国漫|动画/i.test(globalVisualStyle)) {
      pieces.push(
        "Render the final image as a polished 2D Chinese animation storyboard keyframe with clean line art, cel-shaded forms, unified stylization between characters and environment, and zero photorealistic or live-action texture."
      );
      pieces.push(
        "Do not drift into realistic cinema, grayscale photography, painterly concept art, or 3D render look; keep the result flat-to-semi-flat 2D animation art with readable silhouettes."
      );
      if (/一人之下/.test(globalVisualStyle)) {
        pieces.push(
          "Favor a modern Chinese donghua look similar to The Outcast: restrained realistic proportions, crisp controlled linework, subdued balanced palette, grounded urban-fantasy mood, and mature non-cute facial design."
        );
        pieces.push(
          "Avoid chibi, moe, glossy idol-anime, candy pastel, exaggerated manga comedy, or overly decorative fantasy styling."
        );
      }
    }
  }
  if (currentShotTitle) {
    pieces.push(`Current shot objective is ${currentShotTitle}; the framing and action of this shot must visibly differ when the script asks for a new angle, distance, reaction, walk, reverse, or dialogue beat.`);
  }
  if (previousSceneTitle) {
    pieces.push(
      `Maintain visual continuity from the previous same-scene shot ${previousSceneTitle}; keep fixed landmarks and environment layout stable.`
    );
  }
  if (previousCharacterTitle) {
    pieces.push(
      `Maintain character continuity from the previous same-character shot ${previousCharacterTitle}; do not change hairstyle, costume, props, body shape, or palette.`
    );
  }
  if (sceneName) {
    pieces.push(
      `Lock the environment to the scene reference ${sceneName}; keep layout, horizon, camera direction, lighting mood, and materials consistent.`
    );
  }
  if (cameraYaw || cameraPitch || cameraFov) {
    pieces.push(
      `Respect camera pose constraints (yaw=${cameraYaw || "auto"}, pitch=${cameraPitch || "auto"}, fov=${cameraFov || "auto"}); keep framing and perspective consistent with this shot setup.`
    );
  }
  if (characterNames.length > 0) {
    pieces.push(
      `Lock character identity for ${characterNames.join(", ")}; keep face, hair, costume, silhouette, proportions, and colors consistent, and choose ${preferredCharacterView || "front/side/back"} appearance according to the shot angle.`
    );
    pieces.push("Never output an empty environment plate when character references are provided.");
    pieces.push(
      "Characters must be naturally integrated into the scene with grounded feet, matched perspective, matched grayscale/lighting, and contact shadows; never paste a flat character sheet or white-background cutout on top of the scene."
    );
    pieces.push(
      "Use the raw character reference images only for identity and costume fidelity. Do not copy their flat shading, white-background illustration look, or reference-sheet rendering style into the final storyboard frame."
    );
    pieces.push(
      "Character reference images are identity-only guides. They must not dominate composition, camera distance, pose staging, or scene layout."
    );
    pieces.push(
      "Do not output empty environment-only frames when the shot script includes characters. Always place all required characters in visible positions and execute the scripted body actions for this shot."
    );
    pieces.push(
      "Every visible character must show a readable facial expression and a clear body action matching the shot, never an expressionless mannequin pose."
    );
  }
  pieces.push(
    "Treat the skybox environment and same-scene continuity frame as the main composition anchors. Treat character references as identity anchors only."
  );
  pieces.push(
    "If a layout guide is provided, use it only for blocking and placement. The actual environment must come from the scene reference, and the final characters must be freshly redrawn into that environment."
  );
  pieces.push(
    "If previous-shot continuity conflicts with character three-view or skybox references, always follow the character three-view and skybox assets first."
  );
  pieces.push(
    "Prefer the shot-matching character view and the matching skybox face over any weaker or generic reference."
  );
  pieces.push(
    "Generate one coherent cinematic shot in the same world. Do not redesign the environment, do not change character identity, and do not ignore any provided reference image."
  );
  pieces.push(
    "When a previous-scene frame is provided, use it only to preserve scene style, lighting family, and landmark placement; do not clone its exact framing or composition if the current shot prompt asks for a different camera distance, angle, or body action."
  );
  pieces.push("Ignore any accidental UI panels, inset cards, split-screen blocks, text labels, borders, or watermark-like artifacts that may appear inside reference frames; they are not part of the scene.");
  return pieces.join(" ");
}

function buildQwenSlotInstruction(
  stagedRefs: Array<{ role?: WeightedImageRef["role"]; label?: string }>
): string {
  if (stagedRefs.length === 0) return "";
  const lines = stagedRefs
    .slice(0, 6)
    .map((item, index) => {
      // Match the QwenEdit node's own image labels so slot instructions stay
      // aligned with the pictures injected into the prompt.
      const slot = `Picture ${index + 1}`;
      const label = item.label?.trim() ?? "";
      if (label === "scene_character_composite") {
        return `${slot} is a soft occupancy map for character placement only; use it only to understand where people stand, their spacing, and their rough scale, then redraw them naturally into the environment without copying the guide silhouettes, edges, or tones.`;
      }
      if (label === "character_identity_board") {
        return `${slot} is a character identity board; use it only for face, hair, costume silhouette, and palette consistency across all characters, not for pose, framing, or white-background cutout shapes.`;
      }
      if (item.role === "scene_primary" || item.role === "scene_secondary") {
        return `${slot} is the binding environment reference${label ? ` (${label})` : ""}; keep location layout and camera direction aligned to it.`;
      }
      if (item.role === "character_front" || item.role === "character_side" || item.role === "character_back") {
        return `${slot} is the binding character identity reference${label ? ` (${label})` : ""}; keep face, hair, costume, and palette aligned to it, but do not copy the flat reference pose, white background, or cutout edges into the final shot.`;
      }
      if (item.role === "continuity_scene") {
        return `${slot} is a weak continuity environment hint${label ? ` (${label})` : ""}; only use it if it does not conflict with the skybox asset.`;
      }
      if (item.role === "continuity_character") {
        return `${slot} is a weak continuity character hint${label ? ` (${label})` : ""}; only use it if it does not conflict with the character three-view asset.`;
      }
      return `${slot} is a binding reference${label ? ` (${label})` : ""}.`;
    })
    .filter((item) => item.length > 0);
  return lines.join(" ");
}

function qwenReferenceChunkSize(stagedRefs: Array<{ role?: WeightedImageRef["role"] }>): number {
  if (stagedRefs.length <= 0) return 1;
  if (
    stagedRefs.some(
      (item) =>
        (item as { label?: string }).label === "scene_character_composite" ||
        (item as { label?: string }).label === "character_identity_board"
    )
  ) {
    // For storyboard stills, keep environment, layout guide, and identity guide in
    // separate encoders so weighting can actually bias the scene over the guides.
    return 1;
  }
  // Keep refs in one encoder when possible; multi-encoder averaging tends to
  // introduce geometry tearing and identity drift on storyboard stills.
  return 3;
}

function extractImageReferenceSources(
  shot: Shot,
  assets: Asset[],
  index: number,
  allShots: Shot[] = []
): WeightedImageRef[] {
  const sceneAsset = assets.find(
    (item) => item.id === (shot.sceneRefId ?? "") && (item.type === "scene" || item.type === "skybox")
  );
  const characterPlan = inferCharacterReferencePlan(shot);
  const continuityPlan = inferShotContinuityPlan(shot, index, allShots);
  const strictMultiCharacterShot =
    inferRequiredStoryboardCharacterCount(
      shot,
      assets.filter((item) => item.type === "character")
    ) >= 2;
  const sceneRefs: WeightedImageRef[] = [];
  if (sceneAsset?.type === "scene") {
    if ((sceneAsset.filePath ?? "").trim()) {
      sceneRefs.push({
        source: sceneAsset.filePath,
        weight: 0.86,
        priority: 320,
        bucket: `scene:${sceneAsset.id}`,
        label: `${sceneAsset.name}:scene_primary`,
        role: "scene_primary"
      });
    }
  } else if (sceneAsset?.type === "skybox") {
    const plan = inferSkyboxReferencePlan(shot);
    // Keep one stable scene anchor for storyboard stills. Switching cube faces
    // between shots causes large environment drift and surreal composites.
    const shouldRespectDynamicFace =
      plan.manualFaces ||
      plan.manualWeights ||
      (typeof shot.cameraYaw === "number" && Number.isFinite(shot.cameraYaw)) ||
      (typeof shot.cameraPitch === "number" && Number.isFinite(shot.cameraPitch)) ||
      (typeof shot.cameraFov === "number" && Number.isFinite(shot.cameraFov));
    const faceCandidates = uniquePreserveOrder([
      shouldRespectDynamicFace ? plan.primaryFace : "front",
      ...(!shouldRespectDynamicFace ? ["front"] : []),
      ...plan.faces,
      "right",
      "left",
      "back",
      "up",
      "down"
    ]) as SkyboxFace[];
    const selectedFace = faceCandidates.find((face) => Boolean(sceneAsset.skyboxFaces?.[face]?.trim()));
    if (selectedFace) {
      const facePath = sceneAsset.skyboxFaces?.[selectedFace] ?? "";
      const rawWeight = plan.weights[selectedFace] ?? skyboxFaceWeight(shot, selectedFace);
      const weight = Math.max(0.7, Math.min(0.9, rawWeight));
      sceneRefs.push({
        source: facePath,
        weight,
        priority: 320,
        bucket: `scene:${sceneAsset.id}`,
        label: `${sceneAsset.name}:${selectedFace}`,
        role: "scene_primary"
      });
    }
    if (sceneRefs.length === 0 && (sceneAsset.filePath ?? "").trim()) {
      sceneRefs.push({
        source: sceneAsset.filePath,
        weight: 0.86,
        priority: 320,
        bucket: `scene:${sceneAsset.id}`,
        label: `${sceneAsset.name}:scene_primary`,
        role: "scene_primary"
      });
    }
  }

  const explicitCharacters: Asset[] = [];
  const usedCharacterIds = new Set<string>();
  const pushCharacterAsset = (asset: Asset | undefined) => {
    if (!asset || asset.type !== "character" || usedCharacterIds.has(asset.id)) return;
    explicitCharacters.push(asset);
    usedCharacterIds.add(asset.id);
  };
  for (const id of shot.characterRefs ?? []) {
    pushCharacterAsset(assets.find((item) => item.id === id && item.type === "character"));
  }
  for (const name of shot.sourceCharacterNames ?? []) {
    const desiredName = name.trim().toLowerCase();
    if (!desiredName) continue;
    pushCharacterAsset(
      assets.find((item) => item.type === "character" && item.name.trim().toLowerCase() === desiredName)
    );
  }
  const selectedCharacters = selectStoryboardCharacterAssets(shot, explicitCharacters);
  const prefersAngleMatchedView = shouldUseSecondaryCharacterView(shot);
  const shouldPreferFrontIdentityRefs =
    (sceneRefs.length > 0 || selectedCharacters.length > 1 || shotLooksCharacterDrivenInComfy(shot)) &&
    !prefersAngleMatchedView;
  const characterRefs = selectedCharacters.flatMap((asset, assetIndex) => {
    const refs: WeightedImageRef[] = [];
    const front = asset.characterFrontPath || asset.filePath || "";
    const side = asset.characterSidePath || "";
    const back = asset.characterBackPath || "";
    const byView: Record<CharacterReferenceView, string> = { front, side, back };
    const primaryView = shouldPreferFrontIdentityRefs ? "front" : characterPlan.primaryView;
    const primarySource =
      primaryView === "front"
        ? byView.front.trim() || byView.side.trim() || byView.back.trim()
        : byView[primaryView].trim() || byView.front.trim() || byView.side.trim() || byView.back.trim();
    const primaryWeight =
      sceneRefs.length > 0 ? (selectedCharacters.length > 1 ? 0.34 : 0.4) : 0.72;
    const primaryPriority = sceneRefs.length > 0 ? 245 - assetIndex * 10 : 420 - assetIndex * 20;
    if (primarySource) {
      refs.push({
        source: primarySource,
        weight: primaryWeight,
        priority: primaryPriority,
        bucket: `character:${asset.id}`,
        label: `${asset.name}:${primaryView}`,
        role: characterViewRole(primaryView)
      });
    }
    // Only use a secondary character view as fallback when scene anchor is missing
    // and there is a single character in shot.
    if (selectedCharacters.length === 1 && sceneRefs.length === 0) {
      const secondaryView = shouldPreferFrontIdentityRefs
        ? characterPlan.primaryView === "front"
          ? characterPlan.secondaryViews[0]
          : characterPlan.primaryView
        : characterPlan.secondaryViews[0];
      if (secondaryView) {
        const secondarySource = byView[secondaryView].trim();
        if (secondarySource && secondarySource !== primarySource) {
          refs.push({
            source: secondarySource,
            weight: 0.28,
            priority: 360,
            bucket: `character:${asset.id}`,
            label: `${asset.name}:${secondaryView}`,
            role: characterViewRole(secondaryView)
          });
        }
      }
    }
    return refs;
  });
  const continuityRefs: WeightedImageRef[] = [];
  const previousSceneImage = parseComfyViewPath(continuityPlan.previousSceneShot?.generatedImagePath ?? "");
  if (previousSceneImage && !(strictMultiCharacterShot && sceneRefs.length > 0)) {
    continuityRefs.push({
      source: previousSceneImage,
      weight: sceneRefs.length > 0 ? 0.34 : 0.36,
      priority: sceneRefs.length > 0 ? 185 : 110,
      bucket: "continuity:scene",
      label: continuityPlan.previousSceneShot?.title
        ? `continuity_scene:${continuityPlan.previousSceneShot.title}`
        : "continuity_scene",
      role: "continuity_scene"
    });
  }
  const previousCharacterImage = parseComfyViewPath(continuityPlan.previousCharacterShot?.generatedImagePath ?? "");
  const previousCharacterShotCharacterCount = continuityPlan.previousCharacterShot
    ? countExplicitShotCharacters(continuityPlan.previousCharacterShot)
    : 0;
  const allowContinuityCharacterRef =
    !strictMultiCharacterShot &&
    (selectedCharacters.length <= 0 ||
      previousCharacterShotCharacterCount <= Math.max(1, selectedCharacters.length));
  if (previousCharacterImage && allowContinuityCharacterRef) {
    continuityRefs.push({
      source: previousCharacterImage,
      weight: characterRefs.length > 0 ? 0.34 : 0.3,
      priority: characterRefs.length > 0 ? 240 : 120,
      bucket: "continuity:character",
      label: continuityPlan.previousCharacterShot?.title
        ? `continuity_character:${continuityPlan.previousCharacterShot.title}`
        : "continuity_character",
      role: "continuity_character"
    });
  }
  const merged = [...characterRefs, ...sceneRefs, ...continuityRefs].filter((item) => item.source.trim().length > 0);
  const deduped = new Map<string, WeightedImageRef>();
  for (const item of merged) {
    const prev = deduped.get(item.source);
    if (!prev) {
      deduped.set(item.source, item);
      continue;
    }
    if (item.priority > prev.priority || (item.priority === prev.priority && item.weight > prev.weight)) {
      deduped.set(item.source, {
        ...item,
        weight: Math.max(prev.weight, item.weight),
        priority: Math.max(prev.priority, item.priority)
      });
      continue;
    }
    deduped.set(item.source, {
      ...prev,
      weight: Math.max(prev.weight, item.weight),
      priority: Math.max(prev.priority, item.priority)
    });
  }
  return [...deduped.values()].sort((left, right) => {
    const priorityDelta = right.priority - left.priority;
    if (priorityDelta !== 0) return priorityDelta;
    return right.weight - left.weight;
  });
}

function pushUniqueWeightedRef(
  target: WeightedImageRef[],
  usedSources: Set<string>,
  candidate: WeightedImageRef | undefined
) {
  if (!candidate) return;
  const source = candidate.source.trim();
  if (!source || usedSources.has(source)) return;
  target.push(candidate);
  usedSources.add(source);
}

function firstDistinctBucketRef(
  refs: WeightedImageRef[],
  predicate: (item: WeightedImageRef) => boolean,
  excludedBuckets: Set<string>,
  usedSources: Set<string>
): WeightedImageRef | undefined {
  return refs.find((item) => predicate(item) && !excludedBuckets.has(item.bucket) && !usedSources.has(item.source.trim()));
}

function adjustStoryboardReferenceWeight(
  shot: Shot,
  ref: WeightedImageRef,
  selectedRefs: WeightedImageRef[]
): WeightedImageRef {
  const availableCharacterNames = selectedRefs
    .filter((item) => item.role.startsWith("character_"))
    .map((item) => extractCharacterNameFromReferenceLabel(item.label))
    .filter((item) => item.length > 0);
  const focusedCharacterName = inferStoryboardFocusedCharacterName(shot, availableCharacterNames);
  const refCharacterName = extractCharacterNameFromReferenceLabel(ref.label);
  const hasCompositeGuide = selectedRefs.some((item) => item.label === "scene_character_composite");
  const hasExplicitSceneAnchor = selectedRefs.some(
    (item) => item.role === "scene_primary" || item.role === "scene_secondary"
  );
  const characterRefCount = selectedRefs.filter((item) => item.role.startsWith("character_")).length;
  const usesCleanDualCharacterPack = !hasCompositeGuide && hasExplicitSceneAnchor && characterRefCount >= 2;
  if (ref.label === "scene_character_composite") {
    return {
      ...ref,
      weight: 0.14,
      priority: Math.min(ref.priority, 230)
    };
  }
  if (ref.label === "character_identity_board") {
    return {
      ...ref,
      weight: focusedCharacterName ? 0.26 : 0.38,
      priority: Math.min(ref.priority, focusedCharacterName ? 300 : 320)
    };
  }
  if (ref.role === "scene_primary" || ref.role === "scene_secondary") {
    return {
      ...ref,
      weight: Math.max(ref.weight, 1.0)
    };
  }
  if (ref.role === "continuity_scene") {
    return {
      ...ref,
      weight: hasCompositeGuide ? Math.max(ref.weight, 0.72) : Math.max(ref.weight, 0.46),
      priority: hasCompositeGuide ? Math.max(ref.priority, 250) : ref.priority
    };
  }
  if (ref.role === "character_front" || ref.role === "character_side" || ref.role === "character_back") {
    if (usesCleanDualCharacterPack && focusedCharacterName && refCharacterName === focusedCharacterName) {
      return {
        ...ref,
        weight: Math.max(ref.weight, 0.96),
        priority: Math.max(ref.priority, 380)
      };
    }
    if (usesCleanDualCharacterPack) {
      return {
        ...ref,
        weight: Math.max(ref.weight, 0.88),
        priority: Math.max(ref.priority, 350)
      };
    }
    if (hasCompositeGuide && focusedCharacterName && refCharacterName === focusedCharacterName) {
      return {
        ...ref,
        weight: Math.max(ref.weight, 0.96),
        priority: Math.max(ref.priority, 380)
      };
    }
    if (hasCompositeGuide && characterRefCount >= 2) {
      return {
        ...ref,
        weight: Math.max(ref.weight, 0.88),
        priority: Math.max(ref.priority, 350)
      };
    }
    return {
      ...ref,
      weight: hasCompositeGuide ? Math.max(ref.weight, 0.82) : Math.min(ref.weight, 0.48)
    };
  }
  return ref;
}

function selectStoryboardReferenceSlots(shot: Shot, refs: WeightedImageRef[]): WeightedImageRef[] {
  if (refs.length <= 5) return refs.slice(0, 5);
  const ordered = [...refs].sort((left, right) => {
    const priorityDelta = right.priority - left.priority;
    if (priorityDelta !== 0) return priorityDelta;
    return right.weight - left.weight;
  });
  const composite = ordered.find((item) => item.label === "scene_character_composite");
  const identityBoard = ordered.find((item) => item.label === "character_identity_board");
  const characters = ordered.filter(
    (item) => item.role.startsWith("character_") && item.label !== "character_identity_board"
  );
  const primaryScene =
    ordered.find(
      (item) =>
        (item.role === "scene_primary" || item.role === "scene_secondary") && item.label !== "scene_character_composite"
    ) ??
    ordered.find((item) => item.role === "continuity_scene");
  const focusedCharacterName = inferStoryboardFocusedCharacterName(
    shot,
    characters.map((item) => extractCharacterNameFromReferenceLabel(item.label)).filter((item) => item.length > 0)
  );
  const focusedCharacterRef =
    focusedCharacterName
      ? characters.find((item) => extractCharacterNameFromReferenceLabel(item.label) === focusedCharacterName)
      : undefined;
  const compositeContinuityScene = ordered.find((item) => item.role === "continuity_scene");
  const scale = inferStoryboardCompositeScale(shot);
  if (composite) {
    const selectedWithComposite: WeightedImageRef[] = [];
    const usedSources = new Set<string>();
    if (primaryScene && !usedSources.has(primaryScene.source.trim())) {
      selectedWithComposite.push(primaryScene);
      usedSources.add(primaryScene.source.trim());
    }
    if (compositeContinuityScene && !usedSources.has(compositeContinuityScene.source.trim())) {
      selectedWithComposite.push(compositeContinuityScene);
      usedSources.add(compositeContinuityScene.source.trim());
    }
    if (!usedSources.has(composite.source.trim())) {
      selectedWithComposite.push(composite);
      usedSources.add(composite.source.trim());
    }
    if (selectedWithComposite.length < 4 && focusedCharacterRef && !usedSources.has(focusedCharacterRef.source.trim())) {
      selectedWithComposite.push(focusedCharacterRef);
      usedSources.add(focusedCharacterRef.source.trim());
    }
    const usedCharacterBuckets = new Set<string>();
    for (const characterRef of characters) {
      if (selectedWithComposite.length >= 5) break;
      if (usedCharacterBuckets.has(characterRef.bucket) || usedSources.has(characterRef.source.trim())) continue;
      selectedWithComposite.push(characterRef);
      usedSources.add(characterRef.source.trim());
      usedCharacterBuckets.add(characterRef.bucket);
    }
    if (!compositeContinuityScene && selectedWithComposite.length < 5 && identityBoard && !usedSources.has(identityBoard.source.trim())) {
      selectedWithComposite.push(identityBoard);
      usedSources.add(identityBoard.source.trim());
    }
    return selectedWithComposite.slice(0, 5);
  }
  const selected: WeightedImageRef[] = [];
  const usedSources = new Set<string>();
  pushUniqueWeightedRef(selected, usedSources, primaryScene);
  pushUniqueWeightedRef(selected, usedSources, identityBoard);
  const usedCharacterBuckets = new Set<string>();
  for (const characterRef of characters) {
    if (selected.length >= 4) break;
    if (usedCharacterBuckets.has(characterRef.bucket)) continue;
    pushUniqueWeightedRef(selected, usedSources, characterRef);
    usedCharacterBuckets.add(characterRef.bucket);
  }
  const continuityCharacter = ordered.find(
    (item) => item.role === "continuity_character" && !usedSources.has(item.source.trim())
  );
  const continuityScene = ordered.find(
    (item) => item.role === "continuity_scene" && !usedSources.has(item.source.trim())
  );

  const fallbackCandidates = [
    continuityCharacter,
    continuityScene,
    ...ordered.filter((item) => !usedSources.has(item.source.trim()))
  ];
  for (const candidate of fallbackCandidates) {
    pushUniqueWeightedRef(selected, usedSources, candidate);
    if (selected.length >= 4) break;
  }

  return selected.slice(0, 4);
}

function shouldLeadWithSceneReference(shot: Shot): boolean {
  const corpus = [
    shot.title ?? "",
    shot.storyPrompt ?? "",
    shot.videoPrompt ?? "",
    shot.notes ?? "",
    ...(shot.tags ?? [])
  ]
    .join(" ")
    .toLowerCase();
  const explicitCharacterFocus = containsAnyKeyword(corpus, [
    "人物主体",
    "角色主体",
    "对白",
    "对话",
    "起话",
    "回应",
    "反打",
    "近景",
    "中近景",
    "特写",
    "单人主镜头",
    "人物明确存在",
    "walk",
    "walking",
    "speak",
    "speaking",
    "reaction",
    "medium close",
    "close-up"
  ]);
  if (explicitCharacterFocus) return false;
  return containsAnyKeyword(corpus, [
    "全景",
    "大全景",
    "远景",
    "建立镜头",
    "环境空镜",
    "环境建立",
    "wide establishing",
    "establishing",
    "environment plate",
    "scenery frame"
  ]);
}

function reorderStoryboardReferenceSlots(shot: Shot, refs: WeightedImageRef[]): WeightedImageRef[] {
  if (refs.length <= 1) return refs;
  const hasIdentityCoverage = refs.some((item) => item.label === "character_identity_board");
  const characterRefCount = refs.filter((item) => item.role.startsWith("character_") && item.label !== "character_identity_board").length;
  const maxStoryboardRefs = hasIdentityCoverage && characterRefCount >= 2 ? 5 : 4;
  const composite = refs.filter((item) => item.label === "scene_character_composite");
  const identityBoards = refs.filter((item) => item.label === "character_identity_board");
  const characters = refs.filter(
    (item) => item.role.startsWith("character_") && item.label !== "character_identity_board"
  );
  const scenes = refs.filter(
    (item) => (item.role === "scene_primary" || item.role === "scene_secondary") && item.label !== "scene_character_composite"
  );
  const continuity = refs.filter((item) => item.role === "continuity_character" || item.role === "continuity_scene");
  const continuityScene = continuity.filter((item) => item.role === "continuity_scene");
  const continuityCharacter = continuity.filter((item) => item.role === "continuity_character");
  const focusedCharacterName = inferStoryboardFocusedCharacterName(
    shot,
    characters.map((item) => extractCharacterNameFromReferenceLabel(item.label)).filter((item) => item.length > 0)
  );
  const focusedCharacterRef =
    focusedCharacterName
      ? characters.find((item) => extractCharacterNameFromReferenceLabel(item.label) === focusedCharacterName)
      : undefined;
  const scale = inferStoryboardCompositeScale(shot);
  if (composite.length > 0) {
    return [
      ...scenes.slice(0, 1),
      ...continuityScene.slice(0, 1),
      ...composite.slice(0, 1),
      ...(focusedCharacterRef ? [focusedCharacterRef] : identityBoards.slice(0, 1)),
      ...characters.filter((item) => item !== focusedCharacterRef).slice(0, focusedCharacterRef ? 1 : 2),
      ...(!continuityScene.length ? identityBoards.slice(0, 1) : []),
      ...continuityCharacter
    ].slice(0, maxStoryboardRefs);
  }
  // Always keep environment anchor first when a scene/skybox reference exists.
  if (continuityScene.length > 0 && scenes.length > 0) {
    return [
      ...scenes.slice(0, 1),
      ...continuityScene.slice(0, 1),
      ...identityBoards.slice(0, 1),
      ...characters.slice(0, 1),
      ...continuityCharacter,
      ...characters.slice(1)
    ].slice(0, maxStoryboardRefs);
  }
  if (scenes.length > 0) {
    return [...scenes.slice(0, 1), ...identityBoards.slice(0, 1), ...characters.slice(0, 2), ...continuity, ...scenes.slice(1), ...characters.slice(2)].slice(0, maxStoryboardRefs);
  }
  if (shouldLeadWithSceneReference(shot)) {
    return [...continuityScene, ...identityBoards.slice(0, 1), ...characters.slice(0, 2), ...continuityCharacter].slice(0, maxStoryboardRefs);
  }
  return [...identityBoards.slice(0, 1), ...characters.slice(0, 2), ...continuity].slice(0, maxStoryboardRefs);
}

function canProcessStoryboardReferenceImages(): boolean {
  return typeof window !== "undefined" && typeof document !== "undefined";
}

async function loadReferenceImageElement(pathOrUrl: string): Promise<HTMLImageElement | null> {
  if (!canProcessStoryboardReferenceImages()) return null;
  const trimmed = pathOrUrl.trim();
  if (!trimmed) return null;
  const source = /^data:|^https?:|^blob:|^file:/i.test(trimmed) ? trimmed : toDesktopMediaSource(trimmed);
  if (!source) return null;
  const shouldBypassImageCache =
    /^file:/i.test(source) ||
    /\/api\/local-file\?path=/i.test(source) ||
    /\/view\?filename=/i.test(source);
  const finalSource = shouldBypassImageCache
    ? `${source}${source.includes("?") ? "&" : "?"}cache_bust=${Date.now()}_${Math.random().toString(36).slice(2, 8)}`
    : source;
  return await new Promise<HTMLImageElement | null>((resolve) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => resolve(null);
    image.src = finalSource;
  });
}

async function loadComparableImageData(
  pathOrUrl: string,
  width = 96,
  height = 54
): Promise<ImageData | null> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.drawImage(image, 0, 0, width, height);
  return context.getImageData(0, 0, width, height);
}

function detectReferenceContentBounds(context: CanvasRenderingContext2D, width: number, height: number) {
  const frame = context.getImageData(0, 0, width, height);
  const data = frame.data;
  const background = estimateBorderBackgroundColor(context, width, height);
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  for (let index = 0; index < data.length; index += 4) {
    const alpha = data[index + 3] ?? 255;
    if (alpha <= 8) continue;
    const dr = (data[index] ?? 0) - background.r;
    const dg = (data[index + 1] ?? 0) - background.g;
    const db = (data[index + 2] ?? 0) - background.b;
    const distance = Math.sqrt(dr * dr + dg * dg + db * db);
    if (distance < 18) continue;
    const pixel = index / 4;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  if (maxX < minX || maxY < minY) return null;
  const padding = Math.max(6, Math.round(Math.min(width, height) * 0.015));
  const cropX = Math.max(0, minX - padding);
  const cropY = Math.max(0, minY - padding);
  return {
    x: cropX,
    y: cropY,
    width: Math.min(width - cropX, maxX - minX + 1 + padding * 2),
    height: Math.min(height - cropY, maxY - minY + 1 + padding * 2),
    background
  };
}

type OpaqueComponentAnalysis = {
  labels: Int32Array;
  components: Array<{
    id: number;
    area: number;
    minX: number;
    minY: number;
    maxX: number;
    maxY: number;
    touchesEdge: boolean;
  }>;
};

function buildReferenceForegroundAlpha(
  data: Uint8ClampedArray,
  width: number,
  height: number,
  background: { r: number; g: number; b: number }
) {
  const pixelCount = width * height;
  const opaque = new Uint8Array(pixelCount);
  const distances = new Float32Array(pixelCount);
  const backgroundMask = new Uint8Array(pixelCount);
  const queue = new Int32Array(pixelCount);
  const strictBackgroundDistance = 18;
  const neutralBackgroundDistance = 48;
  const softEdgeDistance = 72;
  const featherFloorAlpha = 132;

  const measureDistance = (pixel: number) => {
    const index = pixel * 4;
    const dr = (data[index] ?? 0) - background.r;
    const dg = (data[index + 1] ?? 0) - background.g;
    const db = (data[index + 2] ?? 0) - background.b;
    return Math.sqrt(dr * dr + dg * dg + db * db);
  };

  for (let pixel = 0; pixel < pixelCount; pixel += 1) {
    const index = pixel * 4;
    const sourceAlpha = data[index + 3] ?? 255;
    if (sourceAlpha <= 8) {
      data[index + 3] = 0;
      continue;
    }
    distances[pixel] = measureDistance(pixel);
  }

  let head = 0;
  let tail = 0;
  const enqueueBackground = (pixel: number) => {
    if (pixel < 0 || pixel >= pixelCount) return;
    if (backgroundMask[pixel]) return;
    const index = pixel * 4;
    const alpha = data[index + 3] ?? 0;
    if (alpha <= 8) return;
    const r = data[index] ?? 0;
    const g = data[index + 1] ?? 0;
    const b = data[index + 2] ?? 0;
    const chroma = Math.max(r, g, b) - Math.min(r, g, b);
    const distance = distances[pixel] ?? Number.POSITIVE_INFINITY;
    const isStrictBackgroundMatch = distance <= strictBackgroundDistance;
    const isNeutralBackgroundMatch = distance <= neutralBackgroundDistance && chroma <= 18;
    if (!isStrictBackgroundMatch && !isNeutralBackgroundMatch) return;
    backgroundMask[pixel] = 1;
    queue[tail++] = pixel;
  };

  for (let x = 0; x < width; x += 1) {
    enqueueBackground(x);
    enqueueBackground((height - 1) * width + x);
  }
  for (let y = 1; y < height - 1; y += 1) {
    enqueueBackground(y * width);
    enqueueBackground(y * width + (width - 1));
  }

  while (head < tail) {
    const current = queue[head++];
    const x = current % width;
    const y = Math.floor(current / width);
    if (x > 0) enqueueBackground(current - 1);
    if (x + 1 < width) enqueueBackground(current + 1);
    if (y > 0) enqueueBackground(current - width);
    if (y + 1 < height) enqueueBackground(current + width);
  }

  const touchesBackground = (pixel: number) => {
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    for (let dy = -1; dy <= 1; dy += 1) {
      for (let dx = -1; dx <= 1; dx += 1) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        if (backgroundMask[ny * width + nx]) return true;
      }
    }
    return false;
  };

  for (let pixel = 0; pixel < pixelCount; pixel += 1) {
    const index = pixel * 4;
    const sourceAlpha = data[index + 3] ?? 255;
    if (sourceAlpha <= 8 || backgroundMask[pixel]) {
      data[index + 3] = 0;
      continue;
    }
    const distance = distances[pixel] ?? neutralBackgroundDistance;
    const shouldFeatherEdge = distance <= softEdgeDistance && touchesBackground(pixel);
    if (shouldFeatherEdge) {
      const ratio = Math.max(0, Math.min(1, distance / Math.max(1, softEdgeDistance)));
      data[index + 3] = clampChannel(featherFloorAlpha + ratio * (255 - featherFloorAlpha));
    } else {
      data[index + 3] = 255;
    }
    if ((data[index + 3] ?? 0) > 32) {
      opaque[pixel] = 1;
    }
  }

  return opaque;
}

function analyzeOpaqueComponents(mask: Uint8Array, width: number, height: number): OpaqueComponentAnalysis {
  const labels = new Int32Array(width * height);
  const components: OpaqueComponentAnalysis["components"] = [];
  let nextId = 1;
  const queue = new Int32Array(width * height);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const start = y * width + x;
      if (!mask[start] || labels[start] !== 0) continue;
      let head = 0;
      let tail = 0;
      queue[tail++] = start;
      labels[start] = nextId;
      let area = 0;
      let minX = x;
      let minY = y;
      let maxX = x;
      let maxY = y;
      let touchesEdge = x === 0 || y === 0 || x === width - 1 || y === height - 1;
      while (head < tail) {
        const current = queue[head++];
        const cx = current % width;
        const cy = Math.floor(current / width);
        area += 1;
        if (cx < minX) minX = cx;
        if (cy < minY) minY = cy;
        if (cx > maxX) maxX = cx;
        if (cy > maxY) maxY = cy;
        if (cx === 0 || cy === 0 || cx === width - 1 || cy === height - 1) touchesEdge = true;
        const neighbors = [
          current - 1,
          current + 1,
          current - width,
          current + width
        ];
        for (const neighbor of neighbors) {
          if (neighbor < 0 || neighbor >= mask.length) continue;
          const nx = neighbor % width;
          const ny = Math.floor(neighbor / width);
          if (Math.abs(nx - cx) + Math.abs(ny - cy) !== 1) continue;
          if (!mask[neighbor] || labels[neighbor] !== 0) continue;
          labels[neighbor] = nextId;
          queue[tail++] = neighbor;
        }
      }
      components.push({ id: nextId, area, minX, minY, maxX, maxY, touchesEdge });
      nextId += 1;
    }
  }
  components.sort((left, right) => right.area - left.area);
  return { labels, components };
}

function fillEnclosedTransparentIslands(
  data: Uint8ClampedArray,
  width: number,
  height: number,
  maxArea: number
) {
  if (width <= 0 || height <= 0 || maxArea <= 0) return;
  const transparent = new Uint8Array(width * height);
  for (let pixel = 0; pixel < transparent.length; pixel += 1) {
    if ((data[pixel * 4 + 3] ?? 0) <= 18) {
      transparent[pixel] = 1;
    }
  }
  const analysis = analyzeOpaqueComponents(transparent, width, height);
  const fillIds = new Set(
    analysis.components.filter((component) => !component.touchesEdge && component.area <= maxArea).map((component) => component.id)
  );
  if (fillIds.size <= 0) return;
  for (let pixel = 0; pixel < analysis.labels.length; pixel += 1) {
    if (!fillIds.has(analysis.labels[pixel] ?? 0)) continue;
    data[pixel * 4 + 3] = 255;
  }
}

function applyLargestOpaqueComponent(
  data: Uint8ClampedArray,
  analysis: OpaqueComponentAnalysis
) {
  const largest = analysis.components[0];
  if (!largest) return;
  if (analysis.components.length <= 1) return;
  const minKeepArea = Math.max(48, Math.round(largest.area * 0.18));
  const keepIds = new Set(
    analysis.components
      .filter((component) => component.area >= minKeepArea)
      .map((component) => component.id)
  );
  for (let pixel = 0; pixel < analysis.labels.length; pixel += 1) {
    const label = analysis.labels[pixel];
    if (label <= 0 || keepIds.has(label)) continue;
    data[pixel * 4 + 3] = 0;
  }
}

async function analyzeCharacterReferenceQuality(pathOrUrl: string): Promise<{
  fragmented: boolean;
  edgeTouch: boolean;
  componentCount: number;
}> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) {
    return { fragmented: false, edgeTouch: false, componentCount: 0 };
  }
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) {
    return { fragmented: false, edgeTouch: false, componentCount: 0 };
  }
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) {
    return { fragmented: false, edgeTouch: false, componentCount: 0 };
  }
  context.drawImage(image, 0, 0, width, height);
  const frame = context.getImageData(0, 0, width, height);
  const background = estimateBorderBackgroundColor(context, width, height);
  const opaque = buildReferenceForegroundAlpha(frame.data, width, height, background);
  const analysis = analyzeOpaqueComponents(opaque, width, height);
  const largest = analysis.components[0];
  const second = analysis.components[1];
  if (!largest) {
    return { fragmented: false, edgeTouch: false, componentCount: 0 };
  }
  const fragmentArea = analysis.components.slice(1).reduce((sum, component) => sum + component.area, 0);
  const fragmented =
    Boolean(second && second.area >= Math.max(64, Math.round(largest.area * 0.08))) ||
    fragmentArea >= Math.max(96, Math.round(largest.area * 0.12));
  const edgeMargin = Math.max(2, Math.round(Math.min(width, height) * 0.01));
  const edgeTouch =
    largest.touchesEdge ||
    largest.minX <= edgeMargin ||
    largest.minY <= edgeMargin ||
    largest.maxX >= width - 1 - edgeMargin ||
    largest.maxY >= height - 1 - edgeMargin;
  return {
    fragmented,
    edgeTouch,
    componentCount: analysis.components.length
  };
}

async function stagePreparedReferenceImage(
  settings: ComfySettings,
  source: string,
  targetAbs: string,
  mode: "scene" | "character"
): Promise<string> {
  const trimmedSource = source.trim();
  if (!trimmedSource || !canProcessStoryboardReferenceImages()) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }
  const image = await loadReferenceImageElement(trimmedSource);
  if (!image) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }

  if (mode === "character") {
    const preparedCanvas = await buildPreparedCharacterReferenceCanvas(trimmedSource);
    if (preparedCanvas) {
      try {
        const written = await invokeDesktop<FileWriteResult>("write_base64_file", {
          filePath: targetAbs,
          base64Data: preparedCanvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
        });
        if (written.filePath.trim()) return written.filePath;
      } catch {
        // Fall back to regular staging when cleaned character materialization fails.
      }
    }
  }

  const sampleCanvas = document.createElement("canvas");
  sampleCanvas.width = width;
  sampleCanvas.height = height;
  const sampleContext = sampleCanvas.getContext("2d");
  if (!sampleContext) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }
  sampleContext.drawImage(image, 0, 0, width, height);
  const bounds = detectReferenceContentBounds(sampleContext, width, height);
  if (!bounds) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }

  const trimmedCanvas = document.createElement("canvas");
  trimmedCanvas.width = bounds.width;
  trimmedCanvas.height = bounds.height;
  const trimmedContext = trimmedCanvas.getContext("2d");
  if (!trimmedContext) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }
  trimmedContext.drawImage(
    sampleCanvas,
    bounds.x,
    bounds.y,
    bounds.width,
    bounds.height,
    0,
    0,
    bounds.width,
    bounds.height
  );

  const shouldSquarePad = mode === "character";
  const padding = shouldSquarePad ? Math.max(24, Math.round(Math.max(bounds.width, bounds.height) * 0.08)) : 0;
  const outWidth = shouldSquarePad ? Math.max(bounds.width, bounds.height) + padding * 2 : bounds.width;
  const outHeight = shouldSquarePad ? Math.max(bounds.width, bounds.height) + padding * 2 : bounds.height;
  const canvas = document.createElement("canvas");
  canvas.width = outWidth;
  canvas.height = outHeight;
  const context = canvas.getContext("2d");
  if (!context) {
    return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
  }

  context.fillStyle = `rgb(${clampChannel(bounds.background.r)}, ${clampChannel(bounds.background.g)}, ${clampChannel(bounds.background.b)})`;
  context.fillRect(0, 0, outWidth, outHeight);
  context.drawImage(
    trimmedCanvas,
    Math.round((outWidth - bounds.width) / 2),
    Math.round((outHeight - bounds.height) / 2),
    bounds.width,
    bounds.height
  );

  try {
    const written = await invokeDesktop<FileWriteResult>("write_base64_file", {
      filePath: targetAbs,
      base64Data: canvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
    });
    if (written.filePath.trim()) return written.filePath;
  } catch {
    // Keep the original staging path when square padding cannot be materialized.
  }
  return stageSourceFileToComfyInput(trimmedSource, targetAbs, settings.baseUrl, settings.outputDir);
}

function averageImageDifference(left: ImageData, right: ImageData): number {
  if (left.width !== right.width || left.height !== right.height) return Number.POSITIVE_INFINITY;
  const leftData = left.data;
  const rightData = right.data;
  if (leftData.length !== rightData.length || leftData.length === 0) return Number.POSITIVE_INFINITY;
  let total = 0;
  for (let index = 0; index < leftData.length; index += 4) {
    total += Math.abs((leftData[index] ?? 0) - (rightData[index] ?? 0));
    total += Math.abs((leftData[index + 1] ?? 0) - (rightData[index + 1] ?? 0));
    total += Math.abs((leftData[index + 2] ?? 0) - (rightData[index + 2] ?? 0));
  }
  return total / ((leftData.length / 4) * 3);
}

async function compareImageSources(leftSource: string, rightSource: string): Promise<number | null> {
  const [left, right] = await Promise.all([loadComparableImageData(leftSource), loadComparableImageData(rightSource)]);
  if (!left || !right) return null;
  return averageImageDifference(left, right);
}

function resolveInputTokenSourcePath(settings: ComfySettings, tokenValue: string): string {
  const trimmed = tokenValue.trim();
  if (!trimmed) return "";
  if (canUseAbsoluteLocalPath(trimmed)) return trimmed;
  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) return trimmed;
  return `${inputDir.replace(/\/+$/, "")}/${trimmed.replace(/^\/+/, "")}`;
}

function hasStoryboardCharacterSeed(tokens: Record<string, string>): boolean {
  return Boolean(
    String(tokens.CHAR1_PRIMARY_PATH ?? tokens.CHAR1_FRONT_PATH ?? "").trim() ||
      String(tokens.CHAR2_PRIMARY_PATH ?? tokens.CHAR2_FRONT_PATH ?? "").trim()
  );
}

function toStableMediaPreviewUrl(source: string): string {
  const mediaSource = toDesktopMediaSource(source).trim();
  if (!mediaSource) return source;
  if (/^(https?:|blob:|data:|file:|asset:)/i.test(mediaSource)) return mediaSource;
  if (mediaSource.startsWith("/") && typeof window !== "undefined" && window.location?.origin) {
    try {
      return new URL(mediaSource, window.location.origin).toString();
    } catch {
      return mediaSource;
    }
  }
  return mediaSource;
}

async function materializeStoryboardFallbackStill(
  settings: ComfySettings,
  shot: Shot,
  sourcePath: string,
  label: string,
  onArtifactTarget?: (path: string) => void
): Promise<{ previewUrl: string; localPath: string }> {
  const outputRoot = settings.outputDir.trim().replace(/\/+$/, "");
  const ext = fileExtensionFromSource(sourcePath);
  const safeLabel = sanitizePathSegment(`${shot.id}_${label}`);
  const targetPath = outputRoot
    ? `${outputRoot}/Storyboard/${Date.now()}_${safeLabel}.${ext}`
    : localStillCachePath(settings, `${shot.id}_${label}`, sourcePath);
  onArtifactTarget?.(targetPath);
  const copied = await invokeDesktop<FileWriteResult>("copy_file_to", {
    sourcePath,
    targetPath
  });
  return {
    previewUrl: toStableMediaPreviewUrl(copied.filePath),
    localPath: copied.filePath
  };
}

async function maybeFallbackToStoryboardComposite(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>,
  generatedLocalPath: string,
  kind: "image" | "video" | "audio",
  assetOutputContext: AssetOutputContext | null
): Promise<{ previewUrl: string; localPath: string } | null> {
  return null;
}

async function isStoryboardCharacterDropout(
  settings: ComfySettings,
  tokens: Record<string, string>,
  generatedLocalPath: string
): Promise<boolean> {
  if (!canProcessStoryboardReferenceImages()) return false;
  const outputSource = generatedLocalPath.trim();
  if (!outputSource) return false;
  const requiredNames = [String(tokens.CHAR1_NAME ?? "").trim(), String(tokens.CHAR2_NAME ?? "").trim()].filter(Boolean);
  const requiredCount = requiredNames.length;
  if (requiredCount <= 0) return false;

  const generatedImage = await loadReferenceImageElement(outputSource);
  if (!generatedImage) return false;
  const width = generatedImage.naturalWidth || generatedImage.width;
  const height = generatedImage.naturalHeight || generatedImage.height;
  if (width <= 0 || height <= 0) return false;

  const generatedCanvas = document.createElement("canvas");
  generatedCanvas.width = width;
  generatedCanvas.height = height;
  const generatedContext = generatedCanvas.getContext("2d");
  if (!generatedContext) return false;
  generatedContext.drawImage(generatedImage, 0, 0, width, height);
  const generatedData = generatedContext.getImageData(0, 0, width, height).data;

  let baselineData: Uint8ClampedArray | null = null;
  let baselineKind: "frame" | "scene" | "none" = "none";
  const frameToken = String(tokens.FRAME_IMAGE_PATH ?? "").trim();
  const frameSource = resolveInputTokenSourcePath(settings, frameToken);
  if (requiredCount >= 2 && frameSource.trim()) {
    const frameImage = await loadReferenceImageElement(frameSource);
    if (frameImage) {
      const frameCanvas = document.createElement("canvas");
      frameCanvas.width = width;
      frameCanvas.height = height;
      const frameContext = frameCanvas.getContext("2d");
      if (frameContext) {
        frameContext.drawImage(frameImage, 0, 0, width, height);
        baselineData = frameContext.getImageData(0, 0, width, height).data;
        baselineKind = "frame";
      }
    }
  }

  const sceneToken = String(tokens.SCENE_REF_PATH ?? "").trim();
  const sceneSource = resolveInputTokenSourcePath(settings, sceneToken);
  if (!baselineData && sceneSource.trim()) {
    const sceneImage = await loadReferenceImageElement(sceneSource);
    if (sceneImage) {
      const sceneCanvas = document.createElement("canvas");
      sceneCanvas.width = width;
      sceneCanvas.height = height;
      const sceneContext = sceneCanvas.getContext("2d");
      if (sceneContext) {
        sceneContext.drawImage(sceneImage, 0, 0, width, height);
        baselineData = sceneContext.getImageData(0, 0, width, height).data;
        baselineKind = "scene";
      }
    }
  }

  const passAMaskToken = String(tokens.PASS_A_CHARACTER_MASK_PATH ?? "").trim();
  const passBMaskToken = String(tokens.PASS_B_CHARACTER_MASK_PATH ?? passAMaskToken).trim() || passAMaskToken;
  const requestedMaskTokens = requiredCount >= 2 ? [passAMaskToken, passBMaskToken] : [passAMaskToken];
  const uniqueMaskTokens = uniquePreserveOrder(requestedMaskTokens.map((item) => item.trim()).filter(Boolean));
  const maskSources = uniqueMaskTokens
    .map((item) => resolveInputTokenSourcePath(settings, item))
    .map((item) => item.trim())
    .filter(Boolean);
  if (maskSources.length <= 0) return false;

  const minMaskAreaPixels = Math.max(900, Math.round(width * height * 0.004));
  let evaluatedMasks = 0;
  let unchangedMasks = 0;
  let weakMasks = 0;
  const maskStats: Array<{ meanDiff: number; changeRatio: number; area: number }> = [];

  for (const maskSource of maskSources) {
    const maskImage = await loadReferenceImageElement(maskSource);
    if (!maskImage) {
      weakMasks += 1;
      continue;
    }
    const maskCanvas = document.createElement("canvas");
    maskCanvas.width = width;
    maskCanvas.height = height;
    const maskContext = maskCanvas.getContext("2d");
    if (!maskContext) continue;
    maskContext.drawImage(maskImage, 0, 0, width, height);
    const maskData = maskContext.getImageData(0, 0, width, height).data;

    let areaCount = 0;
    let diffSum = 0;
    let changedStrongPixels = 0;
    let lumaSum = 0;
    let lumaSqSum = 0;
    for (let index = 0; index < maskData.length; index += 4) {
      const alpha = maskData[index + 3] ?? 0;
      if (alpha < 96) continue;
      areaCount += 1;
      const r = generatedData[index] ?? 0;
      const g = generatedData[index + 1] ?? 0;
      const b = generatedData[index + 2] ?? 0;
      const luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
      lumaSum += luma;
      lumaSqSum += luma * luma;
      if (baselineData) {
        const dr = Math.abs(r - (baselineData[index] ?? 0));
        const dg = Math.abs(g - (baselineData[index + 1] ?? 0));
        const db = Math.abs(b - (baselineData[index + 2] ?? 0));
        diffSum += dr + dg + db;
        if (dr + dg + db >= 48) {
          changedStrongPixels += 1;
        }
      }
    }

    if (areaCount < minMaskAreaPixels) {
      weakMasks += 1;
      continue;
    }

    evaluatedMasks += 1;
    if (baselineData) {
      const meanDiff = diffSum / (areaCount * 3);
      const changeRatio = changedStrongPixels / Math.max(1, areaCount);
      maskStats.push({ meanDiff, changeRatio, area: areaCount });
      if (meanDiff < 15 || changeRatio < 0.08) {
        unchangedMasks += 1;
      }
      continue;
    }

    // Fallback when scene reference is unavailable: low variance inside mask often
    // indicates that no character was rendered and the region stayed flat.
    const mean = lumaSum / Math.max(1, areaCount);
    const variance = lumaSqSum / Math.max(1, areaCount) - mean * mean;
    if (variance < 120) {
      unchangedMasks += 1;
    }
  }

  if (requiredCount >= 2) {
    if (evaluatedMasks < 2) return true;
    if (baselineKind === "frame" && maskStats.length >= 2) {
      // Dual-character Stage B validation:
      // - mask[0] is character A preservation zone on top of stage A base.
      // - mask[1] should show significant change because character B is added there.
      const firstMask = maskStats[0]!;
      const secondMask = maskStats[1]!;
      const secondCharacterMissing = secondMask.meanDiff < 12 || secondMask.changeRatio < 0.1;
      const firstCharacterDestroyed = firstMask.meanDiff > 36 && firstMask.changeRatio > 0.72;
      if (secondCharacterMissing || firstCharacterDestroyed || weakMasks > 0) {
        return true;
      }
      return false;
    }
    return unchangedMasks >= 1 || weakMasks >= 1;
  }
  if (evaluatedMasks <= 0) return weakMasks > 0;
  return unchangedMasks >= 1;
}

function estimateBorderBackgroundColor(context: CanvasRenderingContext2D, width: number, height: number) {
  const frame = context.getImageData(0, 0, width, height);
  const data = frame.data;
  const step = Math.max(1, Math.floor(Math.min(width, height) / 96));
  let sumR = 0;
  let sumG = 0;
  let sumB = 0;
  let count = 0;
  const sample = (x: number, y: number) => {
    const index = (y * width + x) * 4;
    sumR += data[index] ?? 0;
    sumG += data[index + 1] ?? 0;
    sumB += data[index + 2] ?? 0;
    count += 1;
  };
  for (let x = 0; x < width; x += step) {
    sample(x, 0);
    sample(x, Math.max(0, height - 1));
  }
  for (let y = step; y < height - step; y += step) {
    sample(0, y);
    sample(Math.max(0, width - 1), y);
  }
  return {
    r: count > 0 ? sumR / count : 255,
    g: count > 0 ? sumG / count : 255,
    b: count > 0 ? sumB / count : 255
  };
}

function suppressLowAlphaReferenceResidue(
  data: Uint8ClampedArray,
  width: number,
  height: number,
  background: { r: number; g: number; b: number }
) {
  const pixelCount = width * height;
  if (pixelCount <= 0) return;
  const strongForeground = new Uint8Array(pixelCount);
  const colorDistanceAt = (pixel: number) => {
    const index = pixel * 4;
    const dr = (data[index] ?? 0) - background.r;
    const dg = (data[index + 1] ?? 0) - background.g;
    const db = (data[index + 2] ?? 0) - background.b;
    return Math.sqrt(dr * dr + dg * dg + db * db);
  };
  for (let pixel = 0; pixel < pixelCount; pixel += 1) {
    if ((data[pixel * 4 + 3] ?? 0) >= 214) {
      strongForeground[pixel] = 1;
    }
  }
  const hasStrongSupport = (pixel: number, radius: number, minCount: number) => {
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    let count = 0;
    for (let dy = -radius; dy <= radius; dy += 1) {
      const ny = y + dy;
      if (ny < 0 || ny >= height) continue;
      for (let dx = -radius; dx <= radius; dx += 1) {
        const nx = x + dx;
        if (nx < 0 || nx >= width) continue;
        if (!strongForeground[ny * width + nx]) continue;
        count += 1;
        if (count >= minCount) return true;
      }
    }
    return false;
  };
  for (let pixel = 0; pixel < pixelCount; pixel += 1) {
    const index = pixel * 4;
    const alpha = data[index + 3] ?? 0;
    if (alpha <= 0 || strongForeground[pixel]) continue;
    const r = data[index] ?? 0;
    const g = data[index + 1] ?? 0;
    const b = data[index + 2] ?? 0;
    const chroma = Math.max(r, g, b) - Math.min(r, g, b);
    const distance = colorDistanceAt(pixel);
    const tightSupport = hasStrongSupport(pixel, 1, 2);
    const wideSupport = tightSupport || hasStrongSupport(pixel, 2, 5);
    if (alpha <= 92 && distance <= 92 && (!tightSupport || chroma <= 44)) {
      data[index + 3] = 0;
      continue;
    }
    if (alpha <= 144 && distance <= 56 && !wideSupport) {
      data[index + 3] = 0;
      continue;
    }
    if (alpha <= 176 && distance <= 32 && chroma <= 24 && !wideSupport) {
      data[index + 3] = 0;
    }
  }
}

async function buildCharacterCutoutCanvas(pathOrUrl: string): Promise<HTMLCanvasElement | null> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) return null;
  const workCanvas = document.createElement("canvas");
  workCanvas.width = width;
  workCanvas.height = height;
  const context = workCanvas.getContext("2d");
  if (!context) return null;
  context.drawImage(image, 0, 0, width, height);
  const frame = context.getImageData(0, 0, width, height);
  const data = frame.data;
  const background = estimateBorderBackgroundColor(context, width, height);
  const opaque = buildReferenceForegroundAlpha(data, width, height, background);
  const analysis = analyzeOpaqueComponents(opaque, width, height);
  applyLargestOpaqueComponent(data, analysis);
  const largestArea = analysis.components[0]?.area ?? 0;
  fillEnclosedTransparentIslands(data, width, height, Math.max(144, Math.round(largestArea * 0.14)));
  suppressLowAlphaReferenceResidue(data, width, height, background);
  const cleanedOpaque = new Uint8Array(width * height);
  for (let pixel = 0; pixel < cleanedOpaque.length; pixel += 1) {
    if ((data[pixel * 4 + 3] ?? 0) > 32) {
      cleanedOpaque[pixel] = 1;
    }
  }
  applyLargestOpaqueComponent(data, analyzeOpaqueComponents(cleanedOpaque, width, height));
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  for (let pixel = 0; pixel < opaque.length; pixel += 1) {
    const alpha = data[pixel * 4 + 3] ?? 0;
    if (alpha <= 32) continue;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  if (maxX < minX || maxY < minY) return null;
  context.putImageData(frame, 0, 0);
  const padding = Math.max(8, Math.round(Math.min(width, height) * 0.03));
  const cropX = Math.max(0, minX - padding);
  const cropY = Math.max(0, minY - padding);
  const cropWidth = Math.min(width - cropX, maxX - minX + 1 + padding * 2);
  const cropHeight = Math.min(height - cropY, maxY - minY + 1 + padding * 2);
  const cutoutCanvas = document.createElement("canvas");
  cutoutCanvas.width = cropWidth;
  cutoutCanvas.height = cropHeight;
  const cutoutContext = cutoutCanvas.getContext("2d");
  if (!cutoutContext) return null;
  cutoutContext.drawImage(workCanvas, cropX, cropY, cropWidth, cropHeight, 0, 0, cropWidth, cropHeight);
  return cutoutCanvas;
}

async function buildPreparedCharacterReferenceCanvas(pathOrUrl: string): Promise<HTMLCanvasElement | null> {
  const cutout = await buildCharacterCutoutCanvas(pathOrUrl);
  if (!cutout) return null;
  const longestSide = Math.max(cutout.width, cutout.height);
  const innerPadding = Math.max(36, Math.round(longestSide * 0.12));
  const canvasSize = longestSide + innerPadding * 2;
  const canvas = document.createElement("canvas");
  canvas.width = canvasSize;
  canvas.height = canvasSize;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, canvasSize, canvasSize);
  const maxDrawWidth = canvasSize - innerPadding * 2;
  const maxDrawHeight = canvasSize - innerPadding * 2;
  const scale = Math.min(maxDrawWidth / Math.max(1, cutout.width), maxDrawHeight / Math.max(1, cutout.height));
  const drawWidth = Math.max(1, Math.round(cutout.width * scale));
  const drawHeight = Math.max(1, Math.round(cutout.height * scale));
  const drawX = Math.round((canvasSize - drawWidth) / 2);
  const drawY = Math.round((canvasSize - drawHeight) / 2);
  context.drawImage(cutout, drawX, drawY, drawWidth, drawHeight);
  return canvas;
}

type StableStoryboardPreparedCharacterReferenceSources = {
  primaryPath: string;
  frontPath?: string;
  sidePath?: string;
  backPath?: string;
  secondaryPath?: string;
  facePath?: string;
  detailPath?: string;
};

type StableStoryboardPreparedCharacterReferenceSourceKey = keyof StableStoryboardPreparedCharacterReferenceSources;

function normalizeStableStoryboardPreparedReferenceSources(
  sources: StableStoryboardPreparedCharacterReferenceSources | string
): StableStoryboardPreparedCharacterReferenceSources {
  return typeof sources === "string" ? { primaryPath: sources } : sources;
}

function collectStableStoryboardPreparedReferenceCandidatePaths(
  sources: StableStoryboardPreparedCharacterReferenceSources | string,
  priority?: StableStoryboardPreparedCharacterReferenceSourceKey[]
): string[] {
  const normalizedSources = normalizeStableStoryboardPreparedReferenceSources(sources);
  const keys =
    priority && priority.length > 0
      ? priority
      : (["frontPath", "primaryPath", "secondaryPath", "sidePath", "backPath"] satisfies StableStoryboardPreparedCharacterReferenceSourceKey[]);
  const seen = new Set<string>();
  const candidates: string[] = [];
  for (const key of keys) {
    const value = String(normalizedSources[key] ?? "").trim();
    if (!value || seen.has(value)) continue;
    seen.add(value);
    candidates.push(value);
  }
  return candidates;
}

async function buildStableStoryboardPreparedReferenceBoardCanvas(
  settings: ComfySettings,
  sources: StableStoryboardPreparedCharacterReferenceSources | string,
  priority?: StableStoryboardPreparedCharacterReferenceSourceKey[]
): Promise<HTMLCanvasElement | null> {
  const candidates = collectStableStoryboardPreparedReferenceCandidatePaths(sources, priority);
  if (candidates.length < 2) return null;
  return await buildCharacterThreeViewTokenCanvas(settings, candidates);
}

async function buildStableStoryboardPreparedDetailBoardCanvas(
  settings: ComfySettings,
  sources: StableStoryboardPreparedCharacterReferenceSources | string,
  priority?: StableStoryboardPreparedCharacterReferenceSourceKey[]
): Promise<HTMLCanvasElement | null> {
  const candidates = collectStableStoryboardPreparedReferenceCandidatePaths(sources, priority);
  const patches = (
    await Promise.all(
      candidates.map(async (source) => {
        const resolved = resolveInputTokenSourcePath(settings, source);
        if (!resolved.trim()) return null;
        const cutout = await buildCharacterCutoutCanvas(resolved);
        if (!cutout) return null;
        return extractStoryboardIdentityOutfitPatch(cutout) ?? cutout;
      })
    )
  ).filter((item): item is HTMLCanvasElement => Boolean(item));
  if (patches.length < 2) return null;

  const canvasSize = 1024;
  const padding = 44;
  const gap = 20;
  const slotWidth = Math.floor((canvasSize - padding * 2 - gap * 2) / 3);
  const slotHeight = canvasSize - padding * 2;
  const canvas = document.createElement("canvas");
  canvas.width = canvasSize;
  canvas.height = canvasSize;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, canvasSize, canvasSize);

  for (let index = 0; index < 3; index += 1) {
    const patch = patches[index] ?? patches[patches.length - 1];
    if (!patch) continue;
    const scale = Math.min(slotWidth / Math.max(1, patch.width), slotHeight / Math.max(1, patch.height));
    const drawWidth = Math.max(1, Math.round(patch.width * scale));
    const drawHeight = Math.max(1, Math.round(patch.height * scale));
    const slotX = padding + index * (slotWidth + gap);
    const drawX = slotX + Math.round((slotWidth - drawWidth) / 2);
    const drawY = padding + Math.round((slotHeight - drawHeight) / 2);
    context.save();
    context.drawImage(patch, drawX, drawY, drawWidth, drawHeight);
    context.restore();
  }

  return canvas;
}

function drawStoryboardReferenceBoardSlot(args: {
  context: CanvasRenderingContext2D;
  source: HTMLCanvasElement | null | undefined;
  x: number;
  y: number;
  width: number;
  height: number;
  padding?: number;
  fit?: "contain" | "cover";
  alignY?: "top" | "center" | "bottom";
  zoom?: number;
  filter?: string;
}) {
  const {
    context,
    source,
    x,
    y,
    width,
    height,
    padding = 18,
    fit = "contain",
    alignY = "center",
    zoom = 1,
    filter = "none"
  } = args;
  context.save();
  context.fillStyle = "rgba(0, 0, 0, 0.035)";
  context.fillRect(x, y, width, height);
  context.strokeStyle = "rgba(0, 0, 0, 0.045)";
  context.lineWidth = 1;
  context.strokeRect(x + 0.5, y + 0.5, Math.max(0, width - 1), Math.max(0, height - 1));
  if (!source || source.width <= 0 || source.height <= 0) {
    context.restore();
    return;
  }

  const innerX = x + padding;
  const innerY = y + padding;
  const innerWidth = Math.max(1, width - padding * 2);
  const innerHeight = Math.max(1, height - padding * 2);
  const scaleBase =
    fit === "cover"
      ? Math.max(innerWidth / Math.max(1, source.width), innerHeight / Math.max(1, source.height))
      : Math.min(innerWidth / Math.max(1, source.width), innerHeight / Math.max(1, source.height));
  const scale = Math.max(0.1, scaleBase * zoom);
  const drawWidth = Math.max(1, Math.round(source.width * scale));
  const drawHeight = Math.max(1, Math.round(source.height * scale));
  const drawX = innerX + Math.round((innerWidth - drawWidth) / 2);
  const drawY =
    alignY === "top"
      ? innerY
      : alignY === "bottom"
        ? innerY + innerHeight - drawHeight
        : innerY + Math.round((innerHeight - drawHeight) / 2);
  context.beginPath();
  context.rect(innerX, innerY, innerWidth, innerHeight);
  context.clip();
  context.filter = filter;
  context.drawImage(source, drawX, drawY, drawWidth, drawHeight);
  context.restore();
}

function extractStoryboardIdentityFacePatch(cutout: HTMLCanvasElement): HTMLCanvasElement | null {
  return (
    extractCanvasRegion(cutout, 0.18, 0, 0.64, 0.38) ??
    extractCanvasRegion(cutout, 0.24, 0.01, 0.52, 0.28) ??
    extractCanvasRegion(cutout, 0.26, 0.02, 0.48, 0.22) ??
    cutout
  );
}

function extractStoryboardIdentityTorsoPatch(cutout: HTMLCanvasElement): HTMLCanvasElement | null {
  return (
    extractCanvasRegion(cutout, 0.18, 0.14, 0.64, 0.42) ??
    extractCanvasRegion(cutout, 0.2, 0.18, 0.6, 0.42) ??
    cutout
  );
}

function extractStoryboardIdentityOutfitPatch(cutout: HTMLCanvasElement): HTMLCanvasElement | null {
  return (
    extractCanvasRegion(cutout, 0.12, 0.1, 0.76, 0.86) ??
    extractCanvasRegion(cutout, 0.14, 0.12, 0.72, 0.84) ??
    extractCanvasRegion(cutout, 0.16, 0.14, 0.68, 0.8) ??
    extractStoryboardIdentityTorsoPatch(cutout) ??
    cutout
  );
}

async function resolveStableStoryboardPreparedReferenceCutout(
  sources: StableStoryboardPreparedCharacterReferenceSources | string,
  priority?: StableStoryboardPreparedCharacterReferenceSourceKey[]
): Promise<HTMLCanvasElement | null> {
  const candidates = collectStableStoryboardPreparedReferenceCandidatePaths(sources, priority);
  for (const path of candidates) {
    const cutout = await buildCharacterCutoutCanvas(path);
    if (cutout) return cutout;
  }
  return null;
}

function buildStableStoryboardPreparedReferencePatchCanvas(args: {
  source: HTMLCanvasElement;
  width: number;
  height: number;
  padding?: number;
  fit?: "contain" | "cover";
  zoom?: number;
  alignY?: "top" | "center" | "bottom";
}): HTMLCanvasElement | null {
  const { source, width, height, padding = 20, fit = "contain", zoom = 1, alignY = "center" } = args;
  if (width <= 0 || height <= 0 || source.width <= 0 || source.height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, width, height);
  drawStoryboardReferenceBoardSlot({
    context,
    source,
    x: 0,
    y: 0,
    width,
    height,
    padding,
    fit,
    alignY,
    zoom,
    filter: "saturate(1.02) contrast(1.02)"
  });
  return canvas;
}

async function loadStoryboardPreparedReferenceCanvas(pathOrUrl: string): Promise<HTMLCanvasElement | null> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.drawImage(image, 0, 0, width, height);
  return canvas;
}

async function buildStableStoryboardPreparedCharacterReferenceCanvas(
  settings: ComfySettings,
  sources: StableStoryboardPreparedCharacterReferenceSources | string
): Promise<HTMLCanvasElement | null> {
  const cutout = await resolveStableStoryboardPreparedReferenceCutout(sources, [
    "frontPath",
    "primaryPath",
    "secondaryPath",
    "sidePath",
    "backPath",
  ]);
  if (!cutout) return null;
  const longestSide = Math.max(cutout.width, cutout.height);
  const innerPadding = Math.max(30, Math.round(longestSide * 0.12));
  const canvasSize = longestSide + innerPadding * 2;
  return buildStableStoryboardPreparedReferencePatchCanvas({
    source: cutout,
    width: canvasSize,
    height: canvasSize,
    padding: innerPadding,
    fit: "contain",
    zoom: 1,
    alignY: "center"
  });
}

async function buildStableStoryboardPreparedCharacterFaceCanvas(
  sources: StableStoryboardPreparedCharacterReferenceSources | string
): Promise<HTMLCanvasElement | null> {
  const normalizedSources = normalizeStableStoryboardPreparedReferenceSources(sources);
  const directFacePath = String(normalizedSources.facePath ?? "").trim();
  if (directFacePath) {
    const directFace = await loadStoryboardPreparedReferenceCanvas(directFacePath);
    if (directFace) return directFace;
  }
  const cutout = await resolveStableStoryboardPreparedReferenceCutout(sources, [
    "frontPath",
    "primaryPath",
    "secondaryPath",
    "sidePath",
    "backPath"
  ]);
  if (!cutout) return null;
  const patch = extractStoryboardIdentityFacePatch(cutout) ?? cutout;
  return buildStableStoryboardPreparedReferencePatchCanvas({
    source: patch,
    width: 768,
    height: 768,
    padding: 20,
    fit: "cover",
    zoom: 1.06,
    alignY: "top"
  });
}

async function buildStableStoryboardPreparedCharacterDetailCanvas(
  settings: ComfySettings,
  sources: StableStoryboardPreparedCharacterReferenceSources | string
): Promise<HTMLCanvasElement | null> {
  const normalizedSources = normalizeStableStoryboardPreparedReferenceSources(sources);
  const directDetailPath = String(normalizedSources.detailPath ?? "").trim();
  if (directDetailPath) {
    const directDetail = await loadStoryboardPreparedReferenceCanvas(resolveInputTokenSourcePath(settings, directDetailPath));
    if (directDetail) return directDetail;
  }
  const board = await buildStableStoryboardPreparedDetailBoardCanvas(settings, sources, [
    "frontPath",
    "sidePath",
    "backPath",
    "primaryPath",
    "secondaryPath"
  ]);
  if (board) return board;
  const cutout = await resolveStableStoryboardPreparedReferenceCutout(sources, [
    "frontPath",
    "primaryPath",
    "sidePath",
    "backPath",
    "secondaryPath"
  ]);
  if (!cutout) return null;
  const patch = extractStoryboardIdentityOutfitPatch(cutout) ?? cutout;
  return buildStableStoryboardPreparedReferencePatchCanvas({
    source: patch,
    width: 704,
    height: 1024,
    padding: 22,
    fit: "contain",
    zoom: 1,
    alignY: "top"
  });
}

export async function materializeCanonicalCharacterIdentityReferenceAssets(args: {
  settings: ComfySettings;
  primaryPath: string;
  frontPath?: string;
  sidePath?: string;
  backPath?: string;
  secondaryPath?: string;
  faceRefTargetPath: string;
  detailRefTargetPath: string;
}): Promise<{ faceRefPath: string; detailRefPath: string }> {
  const { settings, primaryPath, frontPath, sidePath, backPath, secondaryPath, faceRefTargetPath, detailRefTargetPath } = args;
  const sources = {
    primaryPath,
    frontPath,
    sidePath,
    backPath,
    secondaryPath
  };
  const preparedFace = await buildStableStoryboardPreparedCharacterFaceCanvas(sources);
  const preparedDetail = await buildStableStoryboardPreparedCharacterDetailCanvas(settings, sources);
  if (!preparedFace || !preparedDetail) {
    throw new Error("角色身份参考图生成失败：缺少可用的人脸参考或服装参考源图");
  }
  const faceRef = await writeCanvasToLocalPng(faceRefTargetPath, preparedFace);
  const detailRef = await writeCanvasToLocalPng(detailRefTargetPath, preparedDetail);
  return {
    faceRefPath: faceRef.localPath,
    detailRefPath: detailRef.localPath
  };
}

function extractLocalInputName(localPath: string): string {
  return localPath.split("/").pop() ?? localPath.split("\\").pop() ?? localPath;
}

async function writeCanvasToLocalPng(filePath: string, canvas: HTMLCanvasElement): Promise<{ localPath: string; inputName: string }> {
  const result = await invokeDesktopCommand<{ filePath: string }>("write_base64_file", {
    filePath,
    base64Data: canvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
  });
  const localPath = result.filePath?.trim() ?? "";
  const inputName = localPath ? extractLocalInputName(localPath) : "";
  if (!localPath || !inputName) {
    throw new Error(`鍐欏叆 PNG 鏂囦欢澶辫触锛?${filePath}`);
  }
  return { localPath, inputName };
}

function featherCanvasAlphaEdges(source: HTMLCanvasElement, blurPx = 1): HTMLCanvasElement | null {
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const context = source.getContext("2d");
  if (!context) return null;
  const frame = context.getImageData(0, 0, width, height);

  const maskCanvas = document.createElement("canvas");
  maskCanvas.width = width;
  maskCanvas.height = height;
  const maskContext = maskCanvas.getContext("2d");
  if (!maskContext) return null;
  const maskFrame = maskContext.createImageData(width, height);
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const target = pixel * 4;
    const alpha = frame.data[target + 3] ?? 0;
    maskFrame.data[target] = 255;
    maskFrame.data[target + 1] = 255;
    maskFrame.data[target + 2] = 255;
    maskFrame.data[target + 3] = alpha;
  }
  maskContext.putImageData(maskFrame, 0, 0);

  const blurredCanvas = document.createElement("canvas");
  blurredCanvas.width = width;
  blurredCanvas.height = height;
  const blurredContext = blurredCanvas.getContext("2d");
  if (!blurredContext) return null;
  blurredContext.clearRect(0, 0, width, height);
  blurredContext.filter = `blur(${Math.max(0.5, blurPx)}px)`;
  blurredContext.drawImage(maskCanvas, 0, 0);
  blurredContext.filter = "none";
  const blurredFrame = blurredContext.getImageData(0, 0, width, height);

  const outputCanvas = document.createElement("canvas");
  outputCanvas.width = width;
  outputCanvas.height = height;
  const outputContext = outputCanvas.getContext("2d");
  if (!outputContext) return null;
  const outputFrame = outputContext.createImageData(width, height);
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const target = pixel * 4;
    const originalAlpha = frame.data[target + 3] ?? 0;
    const blurredAlpha = blurredFrame.data[target + 3] ?? 0;
    outputFrame.data[target] = frame.data[target] ?? 0;
    outputFrame.data[target + 1] = frame.data[target + 1] ?? 0;
    outputFrame.data[target + 2] = frame.data[target + 2] ?? 0;
    outputFrame.data[target + 3] =
      originalAlpha >= 248 && blurredAlpha >= 240 ? originalAlpha : Math.min(originalAlpha, blurredAlpha);
  }
  outputContext.putImageData(outputFrame, 0, 0);
  return outputCanvas;
}

function blurMaskCanvas(source: HTMLCanvasElement, blurPx = 1): HTMLCanvasElement | null {
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "black";
  context.fillRect(0, 0, width, height);
  context.filter = `blur(${Math.max(0.5, blurPx)}px)`;
  context.drawImage(source, 0, 0);
  context.filter = "none";
  return canvas;
}

function buildStableStoryboardPoseEnvelopeMask(args: {
  width: number;
  height: number;
  poseFigure: StoryboardPoseGuideFigure;
  bodyScale: number;
  includeEdgeContact?: boolean;
  profile?: "outer" | "core";
}): HTMLCanvasElement | null {
  const { width, height, poseFigure, bodyScale, includeEdgeContact = false, profile = "outer" } = args;
  if (width <= 0 || height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "black";
  context.fillRect(0, 0, width, height);
  const scaledBodyHeight = poseFigure.bodyHeight * bodyScale;
  const geometry = computeStoryboardPoseFigureGeometry(
    poseFigure.centerX,
    poseFigure.floorY,
    scaledBodyHeight,
    poseFigure.action,
    poseFigureUsesMirror(poseFigure)
  );
  const torsoWidth = Math.max(profile === "outer" ? 14 : 11, Math.round(scaledBodyHeight * (profile === "outer" ? 0.082 : 0.064)));
  const limbWidth = Math.max(profile === "outer" ? 9 : 7, Math.round(scaledBodyHeight * (profile === "outer" ? 0.046 : 0.034)));
  const jointRadius = Math.max(profile === "outer" ? 7 : 5, Math.round(scaledBodyHeight * (profile === "outer" ? 0.034 : 0.026)));
  const headRadius = Math.max(profile === "outer" ? 14 : 12, Math.round(scaledBodyHeight * (profile === "outer" ? 0.068 : 0.056)));
  const drawStroke = (from: { x: number; y: number }, to: { x: number; y: number }, widthValue: number) => {
    context.save();
    context.strokeStyle = "white";
    context.lineWidth = widthValue;
    context.lineCap = "round";
    context.lineJoin = "round";
    context.beginPath();
    context.moveTo(from.x, from.y);
    context.lineTo(to.x, to.y);
    context.stroke();
    context.restore();
  };
  const drawDot = (point: { x: number; y: number }, radius: number) => {
    context.save();
    context.fillStyle = "white";
    context.beginPath();
    context.arc(point.x, point.y, radius, 0, Math.PI * 2);
    context.fill();
    context.restore();
  };
  const drawPolygon = (points: Array<{ x: number; y: number }>) => {
    if (points.length < 3) return;
    context.save();
    context.fillStyle = "white";
    context.beginPath();
    context.moveTo(points[0]!.x, points[0]!.y);
    for (let index = 1; index < points.length; index += 1) {
      context.lineTo(points[index]!.x, points[index]!.y);
    }
    context.closePath();
    context.fill();
    context.restore();
  };

  drawPolygon([geometry.leftShoulder, geometry.rightShoulder, geometry.rightHip, geometry.leftHip]);
  drawStroke(geometry.neck, geometry.pelvis, torsoWidth);
  drawStroke(geometry.leftShoulder, geometry.rightShoulder, torsoWidth * 0.78);
  drawStroke(geometry.leftHip, geometry.rightHip, torsoWidth * 0.72);
  drawStroke(geometry.leftShoulder, geometry.leftElbow, limbWidth);
  drawStroke(geometry.leftElbow, geometry.leftWrist, limbWidth * 0.92);
  drawStroke(geometry.rightShoulder, geometry.rightElbow, limbWidth);
  drawStroke(geometry.rightElbow, geometry.rightWrist, limbWidth * 0.92);
  drawStroke(geometry.leftHip, geometry.leftKnee, limbWidth);
  drawStroke(geometry.leftKnee, geometry.leftAnkle, limbWidth * 0.92);
  drawStroke(geometry.rightHip, geometry.rightKnee, limbWidth);
  drawStroke(geometry.rightKnee, geometry.rightAnkle, limbWidth * 0.92);
  drawDot(geometry.head, headRadius);
  drawDot(geometry.neck, jointRadius);
  drawDot(geometry.pelvis, jointRadius);
  drawDot(geometry.leftShoulder, jointRadius);
  drawDot(geometry.rightShoulder, jointRadius);
  drawDot(geometry.leftElbow, jointRadius * 0.86);
  drawDot(geometry.rightElbow, jointRadius * 0.86);
  drawDot(geometry.leftWrist, jointRadius * 0.8);
  drawDot(geometry.rightWrist, jointRadius * 0.8);
  drawDot(geometry.leftHip, jointRadius * 0.86);
  drawDot(geometry.rightHip, jointRadius * 0.86);
  drawDot(geometry.leftKnee, jointRadius * 0.82);
  drawDot(geometry.rightKnee, jointRadius * 0.82);
  drawDot(geometry.leftAnkle, jointRadius * 0.8);
  drawDot(geometry.rightAnkle, jointRadius * 0.8);
  if (includeEdgeContact) {
    buildStoryboardCharacterEdgeContactMaskFigure(
      context,
      poseFigure.centerX,
      poseFigure.floorY,
      scaledBodyHeight,
      poseFigure.action,
      poseFigureUsesMirror(poseFigure)
    );
  }
  return blurMaskCanvas(canvas, profile === "outer" ? 1.4 : 0.9) ?? canvas;
}

function pruneStableStoryboardForegroundGhosts(
  canvas: HTMLCanvasElement,
  poseFigure: StoryboardPoseGuideFigure
): HTMLCanvasElement | null {
  const width = canvas.width;
  const height = canvas.height;
  if (width <= 0 || height <= 0) return null;
  const context = canvas.getContext("2d");
  if (!context) return null;
  const frame = context.getImageData(0, 0, width, height);
  const outerMaskCanvas = buildStableStoryboardPoseEnvelopeMask({
    width,
    height,
    poseFigure,
    bodyScale: 1.08,
    includeEdgeContact: true,
    profile: "outer"
  });
  const coreMaskCanvas = buildStableStoryboardPoseEnvelopeMask({
    width,
    height,
    poseFigure,
    bodyScale: 0.96,
    includeEdgeContact: true,
    profile: "core"
  });
  const outerMaskContext = outerMaskCanvas?.getContext("2d");
  const coreMaskContext = coreMaskCanvas?.getContext("2d");
  if (!outerMaskCanvas || !coreMaskCanvas || !outerMaskContext || !coreMaskContext) return canvas;
  const outerMaskData = outerMaskContext.getImageData(0, 0, width, height).data;
  const coreMaskData = coreMaskContext.getImageData(0, 0, width, height).data;

  const countOpaqueNeighbors = (x: number, y: number, radius: number) => {
    let count = 0;
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        const neighborAlpha = frame.data[(ny * width + nx) * 4 + 3] ?? 0;
        if (neighborAlpha > 56) count += 1;
      }
    }
    return count;
  };

  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const alphaIndex = pixel * 4 + 3;
    const alpha = frame.data[alphaIndex] ?? 0;
    if (alpha <= 0) continue;
    const outerAlpha = outerMaskData[alphaIndex] ?? 0;
    if (outerAlpha <= 18) {
      frame.data[alphaIndex] = 0;
      continue;
    }
    const coreAlpha = coreMaskData[alphaIndex] ?? 0;
    if (coreAlpha >= 180) continue;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    const localSupport = countOpaqueNeighbors(x, y, 2);
    const lowerBody = y >= Math.round(poseFigure.floorY - poseFigure.bodyHeight * 0.42);
    const weakAlphaThreshold = lowerBody ? 240 : 220;
    const weakSupportThreshold = lowerBody ? 9 : 7;
    if (outerAlpha < 110 && alpha < 252) {
      frame.data[alphaIndex] = 0;
      continue;
    }
    if ((coreAlpha < 132 && alpha < weakAlphaThreshold) || localSupport < weakSupportThreshold) {
      frame.data[alphaIndex] = 0;
    }
  }

  context.putImageData(frame, 0, 0);
  return canvas;
}

async function buildCleanStoryboardPoseReferenceCanvas(
  pathOrUrl: string,
  expectedCharacterCount: number
): Promise<HTMLCanvasElement | null> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) return null;

  const workCanvas = document.createElement("canvas");
  workCanvas.width = width;
  workCanvas.height = height;
  const workContext = workCanvas.getContext("2d");
  if (!workContext) return null;
  workContext.drawImage(image, 0, 0, width, height);
  const frame = workContext.getImageData(0, 0, width, height);
  const background = estimateBorderBackgroundColor(workContext, width, height);
  const foreground = buildReferenceForegroundAlpha(frame.data, width, height, background);
  const analysis = analyzeOpaqueComponents(foreground, width, height);
  if (analysis.components.length <= 0) return null;
  if (expectedCharacterCount <= 1) {
    const largest = analysis.components[0];
    const second = analysis.components[1];
    const fragmentArea = analysis.components.slice(1).reduce((sum, component) => sum + component.area, 0);
    const hasLargeSecondary =
      Boolean(largest) &&
      (Boolean(second && second.area >= Math.max(64, Math.round(largest.area * 0.08))) ||
        fragmentArea >= Math.max(96, Math.round(largest.area * 0.12)));
    if (hasLargeSecondary) {
      return null;
    }
  }

  applyLeadingOpaqueComponents(frame.data, analysis, expectedCharacterCount);

  const retainedMask = new Uint8Array(width * height);
  for (let pixel = 0; pixel < retainedMask.length; pixel += 1) {
    if ((frame.data[pixel * 4 + 3] ?? 0) > 24) {
      retainedMask[pixel] = 1;
    }
  }
  let retainedAnalysis = analyzeOpaqueComponents(retainedMask, width, height);
  if (expectedCharacterCount <= 1 && retainedAnalysis.components.length > 1) {
    retainOnlyLargestOpaqueComponent(frame.data, retainedAnalysis);
    retainedMask.fill(0);
    for (let pixel = 0; pixel < retainedMask.length; pixel += 1) {
      if ((frame.data[pixel * 4 + 3] ?? 0) > 24) {
        retainedMask[pixel] = 1;
      }
    }
    retainedAnalysis = analyzeOpaqueComponents(retainedMask, width, height);
    const retainedLargest = retainedAnalysis.components[0];
    const retainedSecond = retainedAnalysis.components[1];
    if (
      retainedLargest &&
      retainedSecond &&
      retainedSecond.area >= Math.max(64, Math.round(retainedLargest.area * 0.08))
    ) {
      return null;
    }
  }
  const retainedArea = retainedAnalysis.components
    .slice(0, Math.max(1, expectedCharacterCount))
    .reduce((sum, component) => sum + component.area, 0);
  fillEnclosedTransparentIslands(frame.data, width, height, Math.max(144, Math.round(Math.max(1, retainedArea) * 0.08)));
  workContext.putImageData(frame, 0, 0);

  const refinedCanvas = featherCanvasAlphaEdges(workCanvas, 1) ?? workCanvas;
  const refinedContext = refinedCanvas.getContext("2d");
  if (!refinedContext) return null;
  const refinedFrame = refinedContext.getImageData(0, 0, width, height).data;
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const alpha = refinedFrame[pixel * 4 + 3] ?? 0;
    if (alpha <= 24) continue;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  if (maxX < minX || maxY < minY) return null;

  const cropWidth = maxX - minX + 1;
  const cropHeight = maxY - minY + 1;
  const longestSide = Math.max(cropWidth, cropHeight);
  const cropPadding = Math.max(18, Math.round(longestSide * (expectedCharacterCount > 1 ? 0.06 : 0.08)));
  const cropX = Math.max(0, minX - cropPadding);
  const cropY = Math.max(0, minY - cropPadding);
  const clippedWidth = Math.min(width - cropX, cropWidth + cropPadding * 2);
  const clippedHeight = Math.min(height - cropY, cropHeight + cropPadding * 2);
  const outerPadding = Math.max(20, Math.round(longestSide * (expectedCharacterCount > 1 ? 0.05 : 0.07)));
  const outWidth = clippedWidth + outerPadding * 2;
  const outHeight = clippedHeight + outerPadding * 2;
  const cleanCanvas = document.createElement("canvas");
  cleanCanvas.width = outWidth;
  cleanCanvas.height = outHeight;
  const cleanContext = cleanCanvas.getContext("2d");
  if (!cleanContext) return null;
  cleanContext.fillStyle = "rgb(246, 243, 238)";
  cleanContext.fillRect(0, 0, outWidth, outHeight);
  cleanContext.imageSmoothingEnabled = true;
  cleanContext.imageSmoothingQuality = "high";
  cleanContext.drawImage(
    refinedCanvas,
    cropX,
    cropY,
    clippedWidth,
    clippedHeight,
    outerPadding,
    outerPadding,
    clippedWidth,
    clippedHeight
  );
  return cleanCanvas;
}

function canvasHasVisibleInk(source: HTMLCanvasElement, minPixels = 48): boolean {
  const context = source.getContext("2d");
  if (!context) return false;
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return false;
  const frame = context.getImageData(0, 0, width, height).data;
  let visiblePixels = 0;
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const index = pixel * 4;
    const alpha = frame[index + 3] ?? 0;
    if (alpha <= 12) continue;
    if ((frame[index] ?? 0) <= 16 && (frame[index + 1] ?? 0) <= 16 && (frame[index + 2] ?? 0) <= 16) continue;
    visiblePixels += 1;
    if (visiblePixels >= minPixels) return true;
  }
  return false;
}

function analyzeCanvasVisibleInkComponents(source: HTMLCanvasElement): OpaqueComponentAnalysis | null {
  const context = source.getContext("2d");
  if (!context) return null;
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const frame = context.getImageData(0, 0, width, height).data;
  const visible = new Uint8Array(width * height);
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const index = pixel * 4;
    const alpha = frame[index + 3] ?? 0;
    if (alpha <= 12) continue;
    if ((frame[index] ?? 0) <= 16 && (frame[index + 1] ?? 0) <= 16 && (frame[index + 2] ?? 0) <= 16) continue;
    visible[pixel] = 1;
  }
  const analysis = analyzeOpaqueComponents(visible, width, height);
  return analysis.components.length > 0 ? analysis : null;
}

function normalizeOpaqueComponentBounds(component: OpaqueComponentAnalysis["components"][number]) {
  const width = Math.max(1, component.maxX - component.minX + 1);
  const height = Math.max(1, component.maxY - component.minY + 1);
  return {
    ...component,
    width,
    height,
    centerX: (component.minX + component.maxX) / 2,
    centerY: (component.minY + component.maxY) / 2
  };
}

function computeBoundsIntersectionArea(
  left: { minX: number; minY: number; maxX: number; maxY: number },
  right: { minX: number; minY: number; maxX: number; maxY: number }
): number {
  const minX = Math.max(left.minX, right.minX);
  const minY = Math.max(left.minY, right.minY);
  const maxX = Math.min(left.maxX, right.maxX);
  const maxY = Math.min(left.maxY, right.maxY);
  if (maxX < minX || maxY < minY) return 0;
  return (maxX - minX + 1) * (maxY - minY + 1);
}

function pickStableStoryboardSharedPoseGuideComponent(args: {
  analysis: OpaqueComponentAnalysis;
  expectedBounds: { minX: number; minY: number; maxX: number; maxY: number; width: number; height: number };
}): ReturnType<typeof normalizeOpaqueComponentBounds> | null {
  const { analysis, expectedBounds } = args;
  const expectedArea = Math.max(1, expectedBounds.width * expectedBounds.height);
  const expectedCenterX = (expectedBounds.minX + expectedBounds.maxX) / 2;
  const expectedCenterY = (expectedBounds.minY + expectedBounds.maxY) / 2;
  const candidates = analysis.components
    .map((component) => normalizeOpaqueComponentBounds(component))
    .filter((component) => component.area >= Math.max(48, Math.round(expectedArea * 0.002)));
  if (candidates.length <= 0) return null;

  const ranked = candidates
    .map((component) => {
      const overlapArea = computeBoundsIntersectionArea(component, expectedBounds);
      const overlapRatio = overlapArea / expectedArea;
      const centerDriftX = Math.abs(component.centerX - expectedCenterX) / Math.max(1, expectedBounds.width);
      const centerDriftY = Math.abs(component.centerY - expectedCenterY) / Math.max(1, expectedBounds.height);
      const widthRatio = component.width / Math.max(1, expectedBounds.width);
      const heightRatio = component.height / Math.max(1, expectedBounds.height);
      const sizePenalty = Math.abs(1 - widthRatio) * 0.35 + Math.abs(1 - heightRatio) * 0.6;
      const score = centerDriftX * 1.3 + centerDriftY * 0.9 + sizePenalty - overlapRatio * 1.4;
      return { component, overlapArea, score };
    })
    .sort(
      (left, right) =>
        left.score - right.score ||
        right.overlapArea - left.overlapArea ||
        right.component.area - left.component.area
    );
  return ranked[0]?.component ?? null;
}

function retainLargestVisibleInkComponentCanvas(source: HTMLCanvasElement): HTMLCanvasElement | null {
  const analysis = analyzeCanvasVisibleInkComponents(source);
  const context = source.getContext("2d");
  if (!analysis || !context) return null;
  const width = source.width;
  const height = source.height;
  const largest = analysis.components[0];
  if (!largest) return null;
  const frame = context.getImageData(0, 0, width, height);
  for (let pixel = 0; pixel < analysis.labels.length; pixel += 1) {
    if (analysis.labels[pixel] === largest.id) continue;
    const index = pixel * 4;
    frame.data[index] = 0;
    frame.data[index + 1] = 0;
    frame.data[index + 2] = 0;
    frame.data[index + 3] = 255;
  }
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const outputContext = canvas.getContext("2d");
  if (!outputContext) return null;
  outputContext.putImageData(frame, 0, 0);
  return canvas;
}

type CanvasVisibleInkBounds = {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  width: number;
  height: number;
  visiblePixels: number;
  centerX: number;
  centerY: number;
};

function measureCanvasVisibleInkBounds(source: HTMLCanvasElement, minPixels = 48): CanvasVisibleInkBounds | null {
  const context = source.getContext("2d");
  if (!context) return null;
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const frame = context.getImageData(0, 0, width, height).data;
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  let visiblePixels = 0;
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const index = pixel * 4;
    const alpha = frame[index + 3] ?? 0;
    if (alpha <= 12) continue;
    if ((frame[index] ?? 0) <= 16 && (frame[index + 1] ?? 0) <= 16 && (frame[index + 2] ?? 0) <= 16) continue;
    visiblePixels += 1;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  }
  if (visiblePixels < minPixels || maxX < minX || maxY < minY) return null;
  return {
    minX,
    minY,
    maxX,
    maxY,
    width: maxX - minX + 1,
    height: maxY - minY + 1,
    visiblePixels,
    centerX: (minX + maxX) / 2,
    centerY: (minY + maxY) / 2
  };
}

async function loadReferenceCanvas(pathOrUrl: string): Promise<HTMLCanvasElement | null> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.drawImage(image, 0, 0, width, height);
  return canvas;
}

function isPoseGuideCoverageAcceptable(args: {
  canvas: HTMLCanvasElement;
  expectedBounds: { minX: number; minY: number; maxX: number; maxY: number; width: number; height: number };
  minPixels?: number;
  minWidthRatio?: number;
  minHeightRatio?: number;
  maxCenterDriftRatio?: number;
  maxTopSlackRatio?: number;
  maxBottomSlackRatio?: number;
}): boolean {
  const {
    canvas,
    expectedBounds,
    minPixels = 64,
    minWidthRatio = 0.36,
    minHeightRatio = 0.52,
    maxCenterDriftRatio = 0.3,
    maxTopSlackRatio = 0.32,
    maxBottomSlackRatio = 0.24
  } = args;
  const actualBounds = measureCanvasVisibleInkBounds(canvas, minPixels);
  if (!actualBounds) return false;
  const expectedWidth = Math.max(1, expectedBounds.width);
  const expectedHeight = Math.max(1, expectedBounds.height);
  if (actualBounds.width < expectedWidth * minWidthRatio) return false;
  if (actualBounds.height < expectedHeight * minHeightRatio) return false;
  const expectedCenterX = (expectedBounds.minX + expectedBounds.maxX) / 2;
  const centerDrift = Math.abs(actualBounds.centerX - expectedCenterX);
  if (centerDrift > expectedWidth * maxCenterDriftRatio) return false;
  if (actualBounds.minY > expectedBounds.minY + expectedHeight * maxTopSlackRatio) return false;
  if (actualBounds.maxY < expectedBounds.maxY - expectedHeight * maxBottomSlackRatio) return false;
  return true;
}

function isStableStoryboardSharedPoseGuideAcceptable(args: {
  canvas: HTMLCanvasElement;
  expectedBounds: { minX: number; minY: number; maxX: number; maxY: number; width: number; height: number };
}): boolean {
  const { canvas, expectedBounds } = args;
  if (
    !isPoseGuideCoverageAcceptable({
      canvas,
      expectedBounds,
      minPixels: 96,
      minWidthRatio: 0.3,
      minHeightRatio: 0.56,
      maxCenterDriftRatio: 0.3,
      maxTopSlackRatio: 0.3,
      maxBottomSlackRatio: 0.2
    })
  ) {
    return false;
  }

  const actualBounds = measureCanvasVisibleInkBounds(canvas, 120);
  const context = canvas.getContext("2d");
  if (!actualBounds || !context) return false;

  const frame = context.getImageData(0, 0, canvas.width, canvas.height).data;
  const zoneMinX = Math.max(0, Math.floor(expectedBounds.minX));
  const zoneMaxX = Math.min(canvas.width - 1, Math.ceil(expectedBounds.maxX));
  const zoneMinY = Math.max(0, Math.floor(expectedBounds.minY));
  const zoneMaxY = Math.min(canvas.height - 1, Math.ceil(expectedBounds.maxY));
  const headZoneEnd = Math.min(zoneMaxY, Math.round(expectedBounds.minY + expectedBounds.height * 0.2));
  const bottomZoneStart = Math.max(zoneMinY, Math.round(expectedBounds.maxY - expectedBounds.height * 0.18));

  let headInk = 0;
  let bottomInk = 0;
  for (let y = zoneMinY; y <= zoneMaxY; y += 1) {
    for (let x = zoneMinX; x <= zoneMaxX; x += 1) {
      const index = (y * canvas.width + x) * 4;
      const alpha = frame[index + 3] ?? 0;
      if (alpha <= 12) continue;
      if ((frame[index] ?? 0) <= 16 && (frame[index + 1] ?? 0) <= 16 && (frame[index + 2] ?? 0) <= 16) continue;
      if (y <= headZoneEnd) headInk += 1;
      if (y >= bottomZoneStart) bottomInk += 1;
    }
  }

  if (headInk < 10) return false;
  if (bottomInk < Math.max(10, Math.round(actualBounds.visiblePixels * 0.02))) return false;
  return true;
}

function sanitizeStableStoryboardSingleFigurePoseGuideCanvas(args: {
  source: HTMLCanvasElement;
  poseFigure: StoryboardPoseGuideFigure;
}): HTMLCanvasElement | null {
  const { source, poseFigure } = args;
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;

  const inkCanvas = document.createElement("canvas");
  inkCanvas.width = width;
  inkCanvas.height = height;
  const inkContext = inkCanvas.getContext("2d");
  if (!inkContext) return null;
  inkContext.drawImage(source, 0, 0);

  const frame = inkContext.getImageData(0, 0, width, height);
  const maskCanvas = buildStableStoryboardSingleFigureAcceptanceMask({ width, height, poseFigure });
  const maskContext = maskCanvas?.getContext("2d");
  const maskData = maskCanvas && maskContext ? maskContext.getImageData(0, 0, width, height).data : null;
  const visible = new Uint8Array(width * height);

  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const index = pixel * 4;
    const insideMask = !maskData || (maskData[index + 3] ?? 0) > 12;
    const alpha = frame.data[index + 3] ?? 0;
    const isInk =
      insideMask &&
      alpha > 12 &&
      ((frame.data[index] ?? 0) > 16 || (frame.data[index + 1] ?? 0) > 16 || (frame.data[index + 2] ?? 0) > 16);
    if (!isInk) {
      frame.data[index + 3] = 0;
      continue;
    }
    visible[pixel] = 1;
  }

  const analysis = analyzeOpaqueComponents(visible, width, height);
  if (analysis.components.length <= 0) return null;
  retainOnlyLargestOpaqueComponent(frame.data, analysis);
  inkContext.clearRect(0, 0, width, height);
  inkContext.putImageData(frame, 0, 0);

  const finalCanvas = document.createElement("canvas");
  finalCanvas.width = width;
  finalCanvas.height = height;
  const finalContext = finalCanvas.getContext("2d");
  if (!finalContext) return null;
  finalContext.fillStyle = "black";
  finalContext.fillRect(0, 0, width, height);
  finalContext.drawImage(inkCanvas, 0, 0);
  return canvasHasVisibleInk(finalCanvas, 96) ? finalCanvas : null;
}

async function imageHasVisibleInk(pathOrUrl: string, minPixels = 48): Promise<boolean> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return false;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) return false;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return false;
  context.drawImage(image, 0, 0, width, height);
  return canvasHasVisibleInk(canvas, minPixels);
}

function clampChannel(value: number): number {
  return Math.max(0, Math.min(255, Math.round(value)));
}

function sampleSceneRegionColor(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number
): { r: number; g: number; b: number } {
  const safeX = Math.max(0, Math.min(context.canvas.width - 1, Math.round(x)));
  const safeY = Math.max(0, Math.min(context.canvas.height - 1, Math.round(y)));
  const safeWidth = Math.max(1, Math.min(context.canvas.width - safeX, Math.round(width)));
  const safeHeight = Math.max(1, Math.min(context.canvas.height - safeY, Math.round(height)));
  const image = context.getImageData(safeX, safeY, safeWidth, safeHeight);
  const data = image.data;
  let sumR = 0;
  let sumG = 0;
  let sumB = 0;
  let count = 0;
  for (let index = 0; index < data.length; index += 4) {
    const alpha = (data[index + 3] ?? 0) / 255;
    if (alpha <= 0.05) continue;
    sumR += (data[index] ?? 0) * alpha;
    sumG += (data[index + 1] ?? 0) * alpha;
    sumB += (data[index + 2] ?? 0) * alpha;
    count += alpha;
  }
  if (count <= 0) return { r: 180, g: 180, b: 180 };
  return {
    r: sumR / count,
    g: sumG / count,
    b: sumB / count
  };
}

function extractScenePatchCanvas(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number
): HTMLCanvasElement | null {
  const safeX = Math.max(0, Math.min(context.canvas.width - 1, Math.round(x)));
  const safeY = Math.max(0, Math.min(context.canvas.height - 1, Math.round(y)));
  const safeWidth = Math.max(1, Math.min(context.canvas.width - safeX, Math.round(width)));
  const safeHeight = Math.max(1, Math.min(context.canvas.height - safeY, Math.round(height)));
  const canvas = document.createElement("canvas");
  canvas.width = safeWidth;
  canvas.height = safeHeight;
  const patchContext = canvas.getContext("2d");
  if (!patchContext) return null;
  patchContext.drawImage(context.canvas, safeX, safeY, safeWidth, safeHeight, 0, 0, safeWidth, safeHeight);
  return canvas;
}

function createStoryboardSceneGroundProbe(
  context: CanvasRenderingContext2D,
  options?: {
    minYRatio?: number;
    maxYRatio?: number;
    xRadiusRatio?: number;
  }
): ((centerXRatio: number) => { yRatio: number; confidence: number } | null) | null {
  const width = context.canvas.width;
  const height = context.canvas.height;
  if (width <= 0 || height <= 0) return null;
  const minY = Math.max(1, Math.min(height - 2, Math.round(height * (options?.minYRatio ?? 0.44))));
  const maxY = Math.max(minY + 1, Math.min(height - 2, Math.round(height * (options?.maxYRatio ?? 0.9))));
  const imageData = context.getImageData(0, 0, width, height).data;
  const lumaAt = (x: number, y: number): number => {
    const safeX = Math.max(0, Math.min(width - 1, x));
    const safeY = Math.max(0, Math.min(height - 1, y));
    const index = (safeY * width + safeX) * 4;
    return (
      ((imageData[index] ?? 0) * 0.299 +
        (imageData[index + 1] ?? 0) * 0.587 +
        (imageData[index + 2] ?? 0) * 0.114) /
      255
    );
  };
  const xRadius = Math.max(24, Math.round(width * (options?.xRadiusRatio ?? 0.12)));
  return (centerXRatio: number) => {
    const centerX = Math.max(1, Math.min(width - 2, Math.round(centerXRatio * width)));
    const startX = Math.max(1, centerX - xRadius);
    const endX = Math.min(width - 2, centerX + xRadius);
    let bestY = -1;
    let bestScore = -Infinity;
    for (let y = minY; y <= maxY; y += 1) {
      let score = 0;
      let samples = 0;
      for (let x = startX; x <= endX; x += 6) {
        const aboveLuma = lumaAt(x, y - 1);
        const currentLuma = lumaAt(x, y);
        const belowLuma = lumaAt(x, y + 1);
        const verticalContrast = Math.abs(currentLuma - aboveLuma) + Math.abs(belowLuma - currentLuma);
        const edgeBalance = Math.abs(aboveLuma - belowLuma);
        score += verticalContrast * 0.9 + edgeBalance * 0.55 - Math.abs(currentLuma - 0.52) * 0.12;
        samples += 1;
      }
      const normalizedScore = score / Math.max(1, samples);
      if (normalizedScore > bestScore) {
        bestScore = normalizedScore;
        bestY = y;
      }
    }
    if (bestY < 0) return null;
    return {
      yRatio: bestY / Math.max(1, height),
      confidence: Math.max(0, Math.min(1, bestScore / 0.18))
    };
  };
}

function buildIntegratedCharacterCanvas(
  cutout: HTMLCanvasElement,
  drawWidth: number,
  drawHeight: number,
  sceneTint: { r: number; g: number; b: number },
  scenePatch?: HTMLCanvasElement | null
): HTMLCanvasElement | null {
  const width = Math.max(1, Math.round(drawWidth));
  const height = Math.max(1, Math.round(drawHeight));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.drawImage(cutout, 0, 0, width, height);
  const image = context.getImageData(0, 0, width, height);
  const data = image.data;
  let patchData: Uint8ClampedArray | null = null;
  let patchWidth = 0;
  let patchHeight = 0;
  if (scenePatch) {
    const patchCanvas = document.createElement("canvas");
    patchCanvas.width = width;
    patchCanvas.height = height;
    const patchContext = patchCanvas.getContext("2d");
    if (patchContext) {
      patchContext.drawImage(scenePatch, 0, 0, width, height);
      const patchImage = patchContext.getImageData(0, 0, width, height);
      patchData = patchImage.data;
      patchWidth = width;
      patchHeight = height;
    }
  }
  for (let index = 0; index < data.length; index += 4) {
    const alpha = (data[index + 3] ?? 0) / 255;
    if (alpha <= 0.01) continue;
    const pixel = index / 4;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    const verticalRatio = height <= 1 ? 0 : y / Math.max(1, height - 1);
    const floorBlend = verticalRatio <= 0.58 ? 0 : Math.min(1, (verticalRatio - 0.58) / 0.42);
    const edgeDistance = Math.min(x, y, Math.max(0, width - 1 - x), Math.max(0, height - 1 - y));
    const edgeBlend = edgeDistance >= 10 ? 0 : 1 - edgeDistance / 10;
    let patchR = sceneTint.r;
    let patchG = sceneTint.g;
    let patchB = sceneTint.b;
    if (patchData && patchWidth > 0 && patchHeight > 0) {
      const patchIndex = (Math.min(patchHeight - 1, y) * patchWidth + Math.min(patchWidth - 1, x)) * 4;
      patchR = patchData[patchIndex] ?? patchR;
      patchG = patchData[patchIndex + 1] ?? patchG;
      patchB = patchData[patchIndex + 2] ?? patchB;
    }
    const baseR = data[index] ?? 0;
    const baseG = data[index + 1] ?? 0;
    const baseB = data[index + 2] ?? 0;
    const patchLuma = patchR * 0.299 + patchG * 0.587 + patchB * 0.114;
    const baseLuma = baseR * 0.299 + baseG * 0.587 + baseB * 0.114;
    const brightnessScale = Math.max(0.88, Math.min(1.08, (patchLuma + 1) / Math.max(1, baseLuma + 1)));
    const sceneBlend = 0.06 + floorBlend * 0.08 + edgeBlend * 0.04;
    const litR = clampChannel(baseR * brightnessScale);
    const litG = clampChannel(baseG * brightnessScale);
    const litB = clampChannel(baseB * brightnessScale);
    data[index] = clampChannel(litR * (1 - sceneBlend) + patchR * sceneBlend);
    data[index + 1] = clampChannel(litG * (1 - sceneBlend) + patchG * sceneBlend);
    data[index + 2] = clampChannel(litB * (1 - sceneBlend) + patchB * sceneBlend);
    data[index + 3] = clampChannel((data[index + 3] ?? 255) * (1 - edgeBlend * 0.015));
  }
  context.putImageData(image, 0, 0);
  return canvas;
}

function applyLeadingOpaqueComponents(
  data: Uint8ClampedArray,
  analysis: OpaqueComponentAnalysis,
  expectedCount: number
) {
  const largest = analysis.components[0];
  if (!largest) return;
  const desiredCount = Math.max(1, Math.min(expectedCount, analysis.components.length));
  const minKeepArea = Math.max(48, Math.round(largest.area * (desiredCount > 1 ? 0.12 : 0.18)));
  const keepIds = new Set(
    analysis.components
      .filter((component, index) => index < desiredCount && component.area >= minKeepArea)
      .map((component) => component.id)
  );
  if (keepIds.size <= 0) {
    keepIds.add(largest.id);
  }
  for (let pixel = 0; pixel < analysis.labels.length; pixel += 1) {
    const label = analysis.labels[pixel];
    if (label <= 0 || keepIds.has(label)) continue;
    data[pixel * 4 + 3] = 0;
  }
}

function applyRelevantOpaqueComponents(
  data: Uint8ClampedArray,
  analysis: OpaqueComponentAnalysis,
  expectedComponentCount: number
) {
  const largest = analysis.components[0];
  if (!largest) return;
  const requestedCount = Math.max(1, expectedComponentCount);
  const minKeepArea = Math.max(48, Math.round(largest.area * (requestedCount > 1 ? 0.05 : 0.12)));
  const keepIds = new Set(
    analysis.components
      .filter((component, index) => index < requestedCount || (!component.touchesEdge && component.area >= minKeepArea))
      .map((component) => component.id)
  );
  if (keepIds.size <= 0) {
    applyLargestOpaqueComponent(data, analysis);
    return;
  }
  for (let pixel = 0; pixel < analysis.labels.length; pixel += 1) {
    const label = analysis.labels[pixel];
    if (label <= 0 || keepIds.has(label)) continue;
    data[pixel * 4 + 3] = 0;
  }
}

function retainOnlyLargestOpaqueComponent(
  data: Uint8ClampedArray,
  analysis: OpaqueComponentAnalysis
) {
  const largest = analysis.components[0];
  if (!largest) return;
  for (let pixel = 0; pixel < analysis.labels.length; pixel += 1) {
    if (analysis.labels[pixel] === largest.id) continue;
    data[pixel * 4 + 3] = 0;
  }
}

function analyzeCanvasAlphaComponents(source: HTMLCanvasElement, minAlpha = 24): OpaqueComponentAnalysis | null {
  const context = source.getContext("2d");
  if (!context) return null;
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const frame = context.getImageData(0, 0, width, height);
  const opaque = new Uint8Array(width * height);
  for (let pixel = 0; pixel < opaque.length; pixel += 1) {
    if ((frame.data[pixel * 4 + 3] ?? 0) > minAlpha) {
      opaque[pixel] = 1;
    }
  }
  return analyzeOpaqueComponents(opaque, width, height);
}

function buildOpaqueWhiteMaskCanvasFromAlpha(source: HTMLCanvasElement, minAlpha = 24): HTMLCanvasElement | null {
  const context = source.getContext("2d");
  if (!context) return null;
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const frame = context.getImageData(0, 0, width, height);
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const maskContext = canvas.getContext("2d");
  if (!maskContext) return null;
  const maskImage = maskContext.createImageData(width, height);
  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const alpha = frame.data[pixel * 4 + 3] ?? 0;
    const target = pixel * 4;
    const isForeground = alpha > minAlpha;
    const channel = isForeground ? 255 : 0;
    maskImage.data[target] = channel;
    maskImage.data[target + 1] = channel;
    maskImage.data[target + 2] = channel;
    maskImage.data[target + 3] = 255;
  }
  maskContext.putImageData(maskImage, 0, 0);
  return canvas;
}

function constrainStoryboardPosedIdentityToCutoutSilhouette(
  posedIdentity: HTMLCanvasElement,
  cutout: HTMLCanvasElement,
  options?: {
    featherPx?: number;
    expandPx?: number;
    minAlpha?: number;
  }
): HTMLCanvasElement | null {
  const width = Math.max(1, posedIdentity.width);
  const height = Math.max(1, posedIdentity.height);
  if (cutout.width <= 0 || cutout.height <= 0) return posedIdentity;

  const baseMask = buildOpaqueWhiteMaskCanvasFromAlpha(cutout, options?.minAlpha ?? 18) ?? cutout;
  const maskCanvas = document.createElement("canvas");
  maskCanvas.width = width;
  maskCanvas.height = height;
  const maskContext = maskCanvas.getContext("2d");
  if (!maskContext) return posedIdentity;

  const expandPx = Math.max(0, Math.round(options?.expandPx ?? 0));
  const featherPx = Math.max(0, options?.featherPx ?? 0);
  const offsets =
    expandPx <= 0
      ? [{ x: 0, y: 0 }]
      : [
          { x: 0, y: 0 },
          { x: -expandPx, y: 0 },
          { x: expandPx, y: 0 },
          { x: 0, y: -expandPx },
          { x: 0, y: expandPx },
          { x: -Math.round(expandPx * 0.6), y: -Math.round(expandPx * 0.6) },
          { x: Math.round(expandPx * 0.6), y: -Math.round(expandPx * 0.6) },
          { x: -Math.round(expandPx * 0.6), y: Math.round(expandPx * 0.6) },
          { x: Math.round(expandPx * 0.6), y: Math.round(expandPx * 0.6) }
        ];

  maskContext.clearRect(0, 0, width, height);
  maskContext.globalCompositeOperation = "source-over";
  maskContext.filter = featherPx > 0 ? `blur(${featherPx}px)` : "none";
  for (const offset of offsets) {
    maskContext.drawImage(baseMask, offset.x, offset.y, width, height);
  }
  maskContext.filter = "none";

  const constrainedCanvas = document.createElement("canvas");
  constrainedCanvas.width = width;
  constrainedCanvas.height = height;
  const constrainedContext = constrainedCanvas.getContext("2d");
  if (!constrainedContext) return posedIdentity;
  constrainedContext.drawImage(posedIdentity, 0, 0, width, height);
  constrainedContext.globalCompositeOperation = "destination-in";
  constrainedContext.drawImage(maskCanvas, 0, 0, width, height);
  constrainedContext.globalCompositeOperation = "source-over";

  return featherCanvasAlphaEdges(constrainedCanvas, featherPx > 0 ? 0.8 : 0.6) ?? constrainedCanvas;
}

function buildStableStoryboardEdgeMaskFromPlate(
  plateCanvas: HTMLCanvasElement,
  componentAnalysis?: OpaqueComponentAnalysis | null
): HTMLCanvasElement | null {
  const plateContext = plateCanvas.getContext("2d");
  if (!plateContext) return null;
  const width = plateCanvas.width;
  const height = plateCanvas.height;
  if (width <= 0 || height <= 0) return null;
  const frame = plateContext.getImageData(0, 0, width, height);
  const foreground = new Uint8Array(width * height);
  for (let pixel = 0; pixel < foreground.length; pixel += 1) {
    if ((frame.data[pixel * 4 + 3] ?? 0) > 24) {
      foreground[pixel] = 1;
    }
  }
  const ringCanvas = document.createElement("canvas");
  ringCanvas.width = width;
  ringCanvas.height = height;
  const ringContext = ringCanvas.getContext("2d");
  if (!ringContext) return null;
  const ringImage = ringContext.createImageData(width, height);

  const hasForegroundAround = (x: number, y: number, radius: number) => {
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        if (foreground[ny * width + nx]) return true;
      }
    }
    return false;
  };

  const hasBackgroundAround = (x: number, y: number, radius: number) => {
    for (let dy = -radius; dy <= radius; dy += 1) {
      for (let dx = -radius; dx <= radius; dx += 1) {
        if (dx === 0 && dy === 0) continue;
        const nx = x + dx;
        const ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) return true;
        if (!foreground[ny * width + nx]) return true;
      }
    }
    return false;
  };

  for (let pixel = 0; pixel < width * height; pixel += 1) {
    const target = pixel * 4;
    const alpha = frame.data[target + 3] ?? 0;
    const x = pixel % width;
    const y = Math.floor(pixel / width);
    const isForeground = foreground[pixel] === 1;
    const isSoftForeground = alpha > 18 && alpha < 248;
    const isInnerEdge = isForeground && hasBackgroundAround(x, y, 2);
    const isOuterEdge = !isForeground && hasForegroundAround(x, y, 4);
    const keep = isSoftForeground || isInnerEdge || isOuterEdge;
    const channel = keep ? 255 : 0;
    ringImage.data[target] = channel;
    ringImage.data[target + 1] = channel;
    ringImage.data[target + 2] = channel;
    ringImage.data[target + 3] = 255;
  }
  ringContext.putImageData(ringImage, 0, 0);

  const components = componentAnalysis?.components ?? [];
  const meaningfulComponents =
    components.length > 0
      ? components.filter((component) => component.area >= Math.max(96, Math.round(components[0]!.area * 0.08)))
      : [];
  meaningfulComponents.forEach((component) => {
    const componentWidth = Math.max(1, component.maxX - component.minX + 1);
    const footRadiusX = Math.max(16, Math.round(componentWidth * 0.18));
    const footRadiusY = Math.max(6, Math.round(componentWidth * 0.055));
    const centerX = (component.minX + component.maxX) / 2;
    const contactY = Math.min(height - 2, component.maxY + footRadiusY * 0.3);
    ringContext.save();
    ringContext.fillStyle = "white";
    ringContext.beginPath();
    ringContext.ellipse(centerX, contactY, footRadiusX, footRadiusY, 0, 0, Math.PI * 2);
    ringContext.fill();
    ringContext.restore();
  });
  return ringCanvas;
}

function drawStableStoryboardCompositeShadows(
  context: CanvasRenderingContext2D,
  components: OpaqueComponentAnalysis["components"]
) {
  if (components.length <= 0) return;
  const largestArea = components[0]?.area ?? 0;
  components
    .filter((component) => component.area >= Math.max(96, Math.round(largestArea * 0.08)))
    .forEach((component) => {
      const componentWidth = Math.max(1, component.maxX - component.minX + 1);
      const centerX = (component.minX + component.maxX) / 2;
      const floorY = component.maxY + Math.max(4, componentWidth * 0.02);
      context.save();
      context.fillStyle = "rgba(0,0,0,0.16)";
      context.filter = "blur(10px)";
      context.beginPath();
      context.ellipse(
        centerX,
        floorY,
        Math.max(20, componentWidth * 0.22),
        Math.max(8, componentWidth * 0.07),
        0,
        0,
        Math.PI * 2
      );
      context.fill();
      context.restore();
    });
}

async function materializeStableStoryboardFusionInputs(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>,
  passAPath: string
): Promise<{
  characterPlatePath: string;
  compositePath: string;
  bodyMaskPath: string;
  edgeMaskPath: string;
} | null> {
  if (!canProcessStoryboardReferenceImages()) return null;
  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) return null;
  const renderWidth = Math.max(64, Number.parseInt(String(tokens.RENDER_WIDTH ?? "1024"), 10) || 1024);
  const renderHeight = Math.max(64, Number.parseInt(String(tokens.RENDER_HEIGHT ?? "576"), 10) || 576);
  const scenePath = resolveInputTokenSourcePath(settings, String(tokens.SCENE_REF_PATH ?? ""));
  const [passAImage, sceneImage] = await Promise.all([
    loadReferenceImageElement(passAPath),
    loadReferenceImageElement(scenePath)
  ]);
  if (!passAImage || !sceneImage) return null;

  const characterCount = [String(tokens.CHAR1_NAME ?? "").trim(), String(tokens.CHAR2_NAME ?? "").trim()].filter(Boolean).length || 1;
  const plateCanvas = document.createElement("canvas");
  plateCanvas.width = renderWidth;
  plateCanvas.height = renderHeight;
  const plateContext = plateCanvas.getContext("2d");
  if (!plateContext) return null;
  plateContext.drawImage(passAImage, 0, 0, renderWidth, renderHeight);
  const plateFrame = plateContext.getImageData(0, 0, renderWidth, renderHeight);
  const foreground = buildReferenceForegroundAlpha(
    plateFrame.data,
    renderWidth,
    renderHeight,
    estimateBorderBackgroundColor(plateContext, renderWidth, renderHeight)
  );
  const analysis = analyzeOpaqueComponents(foreground, renderWidth, renderHeight);
  if (characterCount > 1) {
    applyLeadingOpaqueComponents(plateFrame.data, analysis, characterCount);
  } else {
    applyLargestOpaqueComponent(plateFrame.data, analysis);
  }
  const largestArea = analysis.components[0]?.area ?? 0;
  fillEnclosedTransparentIslands(plateFrame.data, renderWidth, renderHeight, Math.max(196, Math.round(largestArea * 0.16)));
  plateContext.putImageData(plateFrame, 0, 0);
  const refinedPlateCanvas = featherCanvasAlphaEdges(plateCanvas, 1) ?? plateCanvas;
  const retainedComponents = analyzeCanvasAlphaComponents(refinedPlateCanvas, 24);
  if (!retainedComponents || retainedComponents.components.length <= 0) return null;

  const sceneCanvas = document.createElement("canvas");
  sceneCanvas.width = renderWidth;
  sceneCanvas.height = renderHeight;
  const sceneContext = sceneCanvas.getContext("2d");
  if (!sceneContext) return null;
  sceneContext.drawImage(sceneImage, 0, 0, renderWidth, renderHeight);
  const scenePatch = extractScenePatchCanvas(sceneContext, 0, 0, renderWidth, renderHeight);
  const sceneTint = sampleSceneRegionColor(sceneContext, 0, 0, renderWidth, renderHeight);
  const integratedPlate =
    buildIntegratedCharacterCanvas(refinedPlateCanvas, renderWidth, renderHeight, sceneTint, scenePatch) ?? refinedPlateCanvas;

  const compositeCanvas = document.createElement("canvas");
  compositeCanvas.width = renderWidth;
  compositeCanvas.height = renderHeight;
  const compositeContext = compositeCanvas.getContext("2d");
  if (!compositeContext) return null;
  compositeContext.drawImage(sceneCanvas, 0, 0);
  drawStableStoryboardCompositeShadows(compositeContext, retainedComponents.components);
  compositeContext.drawImage(integratedPlate, 0, 0);

  const rawEdgeMaskCanvas = buildStableStoryboardEdgeMaskFromPlate(refinedPlateCanvas, retainedComponents);
  const edgeMaskCanvas = rawEdgeMaskCanvas ? blurMaskCanvas(rawEdgeMaskCanvas, 1) ?? rawEdgeMaskCanvas : null;
  if (!edgeMaskCanvas) return null;
  const bodyMaskCanvas = buildOpaqueWhiteMaskCanvasFromAlpha(refinedPlateCanvas, 18);
  if (!bodyMaskCanvas) return null;

  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const writeCanvas = async (fileSuffix: string, canvas: HTMLCanvasElement) => {
    const filePath = `${inputDir}/shot_${safeShotId}_${fileSuffix}.png`;
    const result = await invokeDesktopCommand<{ filePath: string }>("write_base64_file", {
      filePath,
      base64Data: canvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
    });
    return result.filePath ? result.filePath.split("/").pop() ?? result.filePath : "";
  };

  const characterPlatePath = await writeCanvas("character_plate", refinedPlateCanvas);
  const compositePath = await writeCanvas("scene_character_composite_refined", compositeCanvas);
  const bodyMaskPath = await writeCanvas("character_body_mask_refined", bodyMaskCanvas);
  const edgeMaskPath = await writeCanvas("edge_contact_mask_refined", edgeMaskCanvas);
  if (!characterPlatePath || !compositePath || !bodyMaskPath || !edgeMaskPath) return null;
  return {
    characterPlatePath,
    compositePath,
    bodyMaskPath,
    edgeMaskPath
  };
}

function averageOpaqueRegionColor(
  context: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  fallback: { r: number; g: number; b: number }
): { r: number; g: number; b: number } {
  const safeX = Math.max(0, Math.min(context.canvas.width - 1, Math.round(x)));
  const safeY = Math.max(0, Math.min(context.canvas.height - 1, Math.round(y)));
  const safeWidth = Math.max(1, Math.min(context.canvas.width - safeX, Math.round(width)));
  const safeHeight = Math.max(1, Math.min(context.canvas.height - safeY, Math.round(height)));
  const image = context.getImageData(safeX, safeY, safeWidth, safeHeight);
  const data = image.data;
  let sumR = 0;
  let sumG = 0;
  let sumB = 0;
  let count = 0;
  for (let index = 0; index < data.length; index += 4) {
    const alpha = (data[index + 3] ?? 0) / 255;
    if (alpha <= 0.08) continue;
    sumR += (data[index] ?? 0) * alpha;
    sumG += (data[index + 1] ?? 0) * alpha;
    sumB += (data[index + 2] ?? 0) * alpha;
    count += alpha;
  }
  if (count <= 0) return fallback;
  return {
    r: sumR / count,
    g: sumG / count,
    b: sumB / count
  };
}

function colorToRgba(color: { r: number; g: number; b: number }, alpha: number): string {
  return `rgba(${clampChannel(color.r)}, ${clampChannel(color.g)}, ${clampChannel(color.b)}, ${Math.max(0, Math.min(1, alpha))})`;
}

function extractCanvasRegion(
  source: HTMLCanvasElement,
  xRatio: number,
  yRatio: number,
  widthRatio: number,
  heightRatio: number
): HTMLCanvasElement | null {
  const width = source.width;
  const height = source.height;
  if (width <= 0 || height <= 0) return null;
  const x = Math.max(0, Math.min(width - 1, Math.round(width * xRatio)));
  const y = Math.max(0, Math.min(height - 1, Math.round(height * yRatio)));
  const w = Math.max(1, Math.min(width - x, Math.round(width * widthRatio)));
  const h = Math.max(1, Math.min(height - y, Math.round(height * heightRatio)));
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.drawImage(source, x, y, w, h, 0, 0, w, h);
  const image = context.getImageData(0, 0, w, h);
  let minX = w;
  let minY = h;
  let maxX = -1;
  let maxY = -1;
  const scanOpaqueBounds = (minAlpha: number) => {
    minX = w;
    minY = h;
    maxX = -1;
    maxY = -1;
    for (let pixel = 0; pixel < w * h; pixel += 1) {
      const alpha = image.data[pixel * 4 + 3] ?? 0;
      if (alpha < minAlpha) continue;
      const px = pixel % w;
      const py = Math.floor(pixel / w);
      if (px < minX) minX = px;
      if (py < minY) minY = py;
      if (px > maxX) maxX = px;
      if (py > maxY) maxY = py;
    }
    return maxX >= minX && maxY >= minY;
  };
  if (!scanOpaqueBounds(172) && !scanOpaqueBounds(112)) {
    return canvas;
  }
  const trimPadding = Math.max(1, Math.round(Math.min(w, h) * 0.02));
  const cropX = Math.max(0, minX - trimPadding);
  const cropY = Math.max(0, minY - trimPadding);
  const cropW = Math.min(w - cropX, maxX - minX + 1 + trimPadding * 2);
  const cropH = Math.min(h - cropY, maxY - minY + 1 + trimPadding * 2);
  if (cropW >= w - 2 && cropH >= h - 2) return canvas;
  const trimmedCanvas = document.createElement("canvas");
  trimmedCanvas.width = cropW;
  trimmedCanvas.height = cropH;
  const trimmedContext = trimmedCanvas.getContext("2d");
  if (!trimmedContext) return canvas;
  trimmedContext.drawImage(canvas, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);
  return trimmedCanvas;
}

function mirrorCanvasHorizontally(source: HTMLCanvasElement): HTMLCanvasElement | null {
  const canvas = document.createElement("canvas");
  canvas.width = source.width;
  canvas.height = source.height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.translate(source.width, 0);
  context.scale(-1, 1);
  context.drawImage(source, 0, 0);
  return canvas;
}

function inferStoryboardSideFacingDirectionFromLabel(label: string | undefined): "left" | "right" | null {
  const normalized = String(label ?? "").trim().toLowerCase();
  if (!normalized) return null;
  if (
    /(?:left\s*profile|face\s*left|facing\s*left|turn(?:ed|ing)?\s*left|look(?:ing)?\s*left|profile\s*to\s*left|看向左|面向左|左侧脸|左转)/u.test(
      normalized
    )
  ) {
    return "left";
  }
  if (
    /(?:right\s*profile|face\s*right|facing\s*right|turn(?:ed|ing)?\s*right|look(?:ing)?\s*right|profile\s*to\s*right|看向右|面向右|右侧脸|右转)/u.test(
      normalized
    )
  ) {
    return "right";
  }
  return null;
}

function inferStoryboardSideFacingDirectionFromCutout(cutout: HTMLCanvasElement): "left" | "right" | null {
  const context = cutout.getContext("2d");
  if (!context || cutout.width <= 0 || cutout.height <= 0) return null;
  const width = cutout.width;
  const height = cutout.height;
  const frame = context.getImageData(0, 0, width, height);
  const data = frame.data;
  const headBottom = Math.max(1, Math.min(height, Math.round(height * 0.44)));
  const leftLimit = Math.floor(width * 0.42);
  const rightLimit = Math.ceil(width * 0.58);
  let leftSkinScore = 0;
  let rightSkinScore = 0;

  for (let y = 0; y < headBottom; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const index = (y * width + x) * 4;
      const alpha = data[index + 3] ?? 0;
      if (alpha <= 96) continue;
      const r = data[index] ?? 0;
      const g = data[index + 1] ?? 0;
      const b = data[index + 2] ?? 0;
      const maxChannel = Math.max(r, g, b);
      const minChannel = Math.min(r, g, b);
      const chroma = maxChannel - minChannel;
      const likelySkin =
        r >= 92 &&
        g >= 58 &&
        b >= 36 &&
        r > g * 1.02 &&
        g >= b * 0.92 &&
        chroma >= 8 &&
        chroma <= 128;
      if (!likelySkin) continue;
      if (x <= leftLimit) {
        leftSkinScore += leftLimit - x + 1;
      } else if (x >= rightLimit) {
        rightSkinScore += x - rightLimit + 1;
      }
    }
  }

  const strongerSkinScore = Math.max(leftSkinScore, rightSkinScore);
  const skinScoreGap = Math.abs(leftSkinScore - rightSkinScore);
  if (strongerSkinScore >= 48 && skinScoreGap >= Math.max(18, strongerSkinScore * 0.2)) {
    return leftSkinScore > rightSkinScore ? "left" : "right";
  }
  return null;
}

function resolveStoryboardSideReferenceFacingDirection(
  ref: Pick<WeightedImageRef, "source" | "label">,
  cutout: HTMLCanvasElement
): "left" | "right" | null {
  return (
    inferStoryboardComposerSideViewDirectionFromPath(ref.source) ??
    inferStoryboardSideFacingDirectionFromLabel(ref.label) ??
    inferStoryboardSideFacingDirectionFromCutout(cutout)
  );
}

function resolveStoryboardSideMirrorDecision(args: {
  ref: Pick<WeightedImageRef, "role" | "source" | "label">;
  cutout: HTMLCanvasElement;
  desiredFacingDirection: "left" | "right";
}): boolean {
  if (args.ref.role !== "character_side") return false;
  const currentFacingDirection = resolveStoryboardSideReferenceFacingDirection(args.ref, args.cutout);
  if (!currentFacingDirection) return false;
  return currentFacingDirection !== args.desiredFacingDirection;
}

function drawRotatedPatch(
  context: CanvasRenderingContext2D,
  patch: HTMLCanvasElement,
  centerX: number,
  centerY: number,
  targetWidth: number,
  targetHeight: number,
  angleRad: number,
  alpha = 1
) {
  context.save();
  context.globalAlpha = Math.max(0, Math.min(1, alpha));
  context.translate(centerX, centerY);
  context.rotate(angleRad);
  context.drawImage(
    patch,
    -targetWidth / 2,
    -targetHeight / 2,
    targetWidth,
    targetHeight
  );
  context.restore();
}

function traceTaperedLimbPath(
  context: CanvasRenderingContext2D,
  from: { x: number; y: number },
  to: { x: number; y: number },
  startWidth: number,
  endWidth: number
) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.max(1, Math.sqrt(dx * dx + dy * dy));
  const nx = -dy / length;
  const ny = dx / length;
  const halfStart = startWidth / 2;
  const halfEnd = endWidth / 2;
  context.beginPath();
  context.moveTo(from.x + nx * halfStart, from.y + ny * halfStart);
  context.lineTo(from.x - nx * halfStart, from.y - ny * halfStart);
  context.lineTo(to.x - nx * halfEnd, to.y - ny * halfEnd);
  context.lineTo(to.x + nx * halfEnd, to.y + ny * halfEnd);
  context.closePath();
}

function drawPatchAlongLimb(
  context: CanvasRenderingContext2D,
  patch: HTMLCanvasElement | null,
  from: { x: number; y: number },
  to: { x: number; y: number },
  startWidth: number,
  endWidth: number,
  alpha = 0.75,
  filter = "blur(0.18px) saturate(1.03) contrast(1.03) brightness(1.01)"
) {
  if (!patch) return;
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.max(1, Math.sqrt(dx * dx + dy * dy));
  const angle = Math.atan2(dy, dx);
  const thickness = Math.max(8, Math.max(startWidth, endWidth) * 1.36);
  context.save();
  traceTaperedLimbPath(context, from, to, startWidth, endWidth);
  context.clip();
  context.filter = filter;
  drawRotatedPatch(
    context,
    patch,
    (from.x + to.x) / 2,
    (from.y + to.y) / 2,
    length + Math.max(startWidth, endWidth) * 0.72,
    thickness,
    angle,
    alpha
  );
  context.restore();
}

function mixRgb(
  left: { r: number; g: number; b: number },
  right: { r: number; g: number; b: number },
  ratio: number
): { r: number; g: number; b: number } {
  const t = Math.max(0, Math.min(1, ratio));
  return {
    r: left.r * (1 - t) + right.r * t,
    g: left.g * (1 - t) + right.g * t,
    b: left.b * (1 - t) + right.b * t
  };
}

function offsetPoint(
  from: { x: number; y: number },
  to: { x: number; y: number },
  distance: number
): { x: number; y: number } {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.max(1e-5, Math.sqrt(dx * dx + dy * dy));
  return {
    x: from.x + (dx / length) * distance,
    y: from.y + (dy / length) * distance
  };
}

function drawTaperedLimb(
  context: CanvasRenderingContext2D,
  from: { x: number; y: number },
  to: { x: number; y: number },
  startWidth: number,
  endWidth: number,
  color: { r: number; g: number; b: number }
) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.max(1, Math.sqrt(dx * dx + dy * dy));
  const nx = -dy / length;
  const ny = dx / length;
  const halfStart = startWidth / 2;
  const halfEnd = endWidth / 2;
  context.beginPath();
  context.moveTo(from.x + nx * halfStart, from.y + ny * halfStart);
  context.lineTo(from.x - nx * halfStart, from.y - ny * halfStart);
  context.lineTo(to.x - nx * halfEnd, to.y - ny * halfEnd);
  context.lineTo(to.x + nx * halfEnd, to.y + ny * halfEnd);
  context.closePath();
  context.fillStyle = colorToRgba(color, 0.98);
  context.fill();
}

function sampleStoryboardGuidePalette(cutout: HTMLCanvasElement) {
  const context = cutout.getContext("2d");
  if (!context) {
    return {
      hair: { r: 34, g: 34, b: 40 },
      skin: { r: 230, g: 205, b: 188 },
      upper: { r: 95, g: 110, b: 145 },
      lower: { r: 78, g: 82, b: 110 },
      accent: { r: 40, g: 40, b: 48 },
      shoes: { r: 30, g: 30, b: 34 },
      hasLongGarment: true
    };
  }
  const width = cutout.width;
  const height = cutout.height;
  const darkFallback = { r: 36, g: 36, b: 42 };
  const upperFallback = { r: 100, g: 116, b: 150 };
  const lowerFallback = { r: 88, g: 94, b: 128 };
  const skinFallback = { r: 228, g: 204, b: 190 };
  const hair = averageOpaqueRegionColor(context, width * 0.28, height * 0.02, width * 0.44, height * 0.16, darkFallback);
  const skin = averageOpaqueRegionColor(context, width * 0.34, height * 0.1, width * 0.32, height * 0.16, skinFallback);
  const upper = averageOpaqueRegionColor(context, width * 0.24, height * 0.22, width * 0.52, height * 0.28, upperFallback);
  const lower = averageOpaqueRegionColor(context, width * 0.22, height * 0.5, width * 0.56, height * 0.28, lowerFallback);
  const accent = averageOpaqueRegionColor(context, width * 0.38, height * 0.42, width * 0.24, height * 0.12, darkFallback);
  const shoes = averageOpaqueRegionColor(context, width * 0.28, height * 0.86, width * 0.44, height * 0.12, darkFallback);
  const centerLower = context.getImageData(
    Math.max(0, Math.round(width * 0.42)),
    Math.max(0, Math.round(height * 0.58)),
    Math.max(1, Math.round(width * 0.16)),
    Math.max(1, Math.round(height * 0.24))
  );
  let opaqueCount = 0;
  for (let index = 0; index < centerLower.data.length; index += 4) {
    if ((centerLower.data[index + 3] ?? 0) > 48) opaqueCount += 1;
  }
  const hasLongGarment = opaqueCount >= Math.max(12, centerLower.data.length / 20);
  return { hair, skin, upper, lower, accent, shoes, hasLongGarment };
}

function buildStoryboardGuideCharacterCanvas(
  cutout: HTMLCanvasElement,
  drawWidth: number,
  drawHeight: number,
  sceneTint: { r: number; g: number; b: number },
  scenePatch?: HTMLCanvasElement | null,
  action: StoryboardPoseAction = "stand",
  mirror = false
): HTMLCanvasElement | null {
  const width = Math.max(1, Math.round(drawWidth));
  const height = Math.max(1, Math.round(drawHeight));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.clearRect(0, 0, width, height);
  const headPatch = extractCanvasRegion(cutout, 0.26, 0.02, 0.48, 0.22);
  const torsoPatch = extractCanvasRegion(cutout, 0.2, 0.18, 0.6, 0.42);
  const lowerPatch = extractCanvasRegion(cutout, 0.16, 0.44, 0.68, 0.48);
  const palette = sampleStoryboardGuidePalette(cutout);
  const patchInfluence = scenePatch
    ? sampleSceneRegionColor(
        (() => {
          const patchCanvas = document.createElement("canvas");
          patchCanvas.width = width;
          patchCanvas.height = height;
          const patchContext = patchCanvas.getContext("2d");
          if (patchContext) patchContext.drawImage(scenePatch, 0, 0, width, height);
          return patchContext ?? context;
        })(),
        width * 0.3,
        height * 0.28,
        width * 0.4,
        height * 0.54
      )
    : sceneTint;
  const tonedUpper = mixRgb(palette.upper, patchInfluence, 0.08);
  const tonedLower = mixRgb(palette.lower, patchInfluence, 0.1);
  const tonedHair = mixRgb(palette.hair, patchInfluence, 0.04);
  const tonedSkin = mixRgb(palette.skin, patchInfluence, 0.05);
  const tonedAccent = mixRgb(palette.accent, patchInfluence, 0.06);
  const tonedShoes = mixRgb(palette.shoes, patchInfluence, 0.04);

  const geometry = computeStoryboardPoseFigureGeometry(width / 2, height * 0.95, height * 0.92, action, mirror);
  const shadowCenterX = (geometry.leftAnkle.x + geometry.rightAnkle.x) / 2;
  const shadowCenterY = Math.max(geometry.leftAnkle.y, geometry.rightAnkle.y) + height * 0.02;
  const shoulderWidth = Math.abs(geometry.rightShoulder.x - geometry.leftShoulder.x);
  const hipWidth = Math.abs(geometry.rightHip.x - geometry.leftHip.x);
  const armWidth = Math.max(10, shoulderWidth * 0.22);
  const legWidth = Math.max(11, hipWidth * 0.38);
  const headRadius = Math.max(10, shoulderWidth * 0.34);
  const waistY = geometry.pelvis.y - height * 0.035;
  const hemY = palette.hasLongGarment
    ? Math.min(height * 0.92, Math.max(geometry.leftKnee.y, geometry.rightKnee.y) + height * 0.06)
    : Math.min(height * 0.78, geometry.pelvis.y + height * 0.14);
  const bodyCenterX = (geometry.leftShoulder.x + geometry.rightShoulder.x + geometry.leftHip.x + geometry.rightHip.x) / 4;
  const torsoLeftX = bodyCenterX - shoulderWidth * 0.62;
  const torsoRightX = bodyCenterX + shoulderWidth * 0.62;
  const hemLeftX = bodyCenterX - shoulderWidth * (palette.hasLongGarment ? 0.92 : 0.48);
  const hemRightX = bodyCenterX + shoulderWidth * (palette.hasLongGarment ? 0.92 : 0.48);
  const torsoAngle = Math.atan2(geometry.pelvis.y - geometry.neck.y, geometry.pelvis.x - geometry.neck.x);
  const outlineColor = mixRgb(mixRgb(tonedAccent, tonedHair, 0.42), patchInfluence, 0.16);
  const traceBodyShape = () => {
    context.beginPath();
    context.moveTo(geometry.leftShoulder.x, geometry.leftShoulder.y);
    context.lineTo(geometry.rightShoulder.x, geometry.rightShoulder.y);
    context.lineTo(torsoRightX, waistY);
    context.lineTo(hemRightX, hemY);
    context.lineTo(hemLeftX, hemY);
    context.lineTo(torsoLeftX, waistY);
    context.closePath();
  };

  context.save();
  context.filter = "blur(6px)";
  context.fillStyle = colorToRgba(mixRgb(sceneTint, { r: 12, g: 12, b: 18 }, 0.48), 0.3);
  context.beginPath();
  context.ellipse(
    shadowCenterX,
    shadowCenterY,
    Math.max(16, shoulderWidth * 0.52),
    Math.max(7, shoulderWidth * 0.16),
    0,
    0,
    Math.PI * 2
  );
  context.fill();
  context.restore();

  context.save();
  context.filter = "blur(0.35px)";
  drawTaperedLimb(context, geometry.leftHip, geometry.leftKnee, legWidth, legWidth * 0.78, tonedLower);
  drawTaperedLimb(context, geometry.leftKnee, geometry.leftAnkle, legWidth * 0.78, legWidth * 0.62, tonedLower);
  drawTaperedLimb(context, geometry.rightHip, geometry.rightKnee, legWidth, legWidth * 0.78, tonedLower);
  drawTaperedLimb(context, geometry.rightKnee, geometry.rightAnkle, legWidth * 0.78, legWidth * 0.62, tonedLower);

  traceBodyShape();
  const garmentGradient = context.createLinearGradient(bodyCenterX, geometry.leftShoulder.y, bodyCenterX, hemY);
  garmentGradient.addColorStop(0, colorToRgba(tonedUpper, 0.98));
  garmentGradient.addColorStop(1, colorToRgba(tonedLower, 0.96));
  context.fillStyle = garmentGradient;
  context.fill();

  if (palette.hasLongGarment) {
    context.strokeStyle = colorToRgba(mixRgb(tonedAccent, tonedLower, 0.4), 0.56);
    context.lineWidth = Math.max(2, shoulderWidth * 0.05);
    context.beginPath();
    context.moveTo(bodyCenterX, waistY + height * 0.03);
    context.lineTo(bodyCenterX + (mirror ? -1 : 1) * shoulderWidth * 0.1, hemY - height * 0.02);
    context.stroke();
  }

  context.fillStyle = colorToRgba(tonedAccent, 0.92);
  context.fillRect(
    bodyCenterX - shoulderWidth * 0.22,
    waistY - height * 0.022,
    shoulderWidth * 0.44,
    Math.max(5, height * 0.032)
  );

  drawTaperedLimb(context, geometry.leftShoulder, geometry.leftElbow, armWidth, armWidth * 0.84, tonedUpper);
  drawTaperedLimb(context, geometry.leftElbow, geometry.leftWrist, armWidth * 0.82, armWidth * 0.64, tonedUpper);
  drawTaperedLimb(context, geometry.rightShoulder, geometry.rightElbow, armWidth, armWidth * 0.84, tonedUpper);
  drawTaperedLimb(context, geometry.rightElbow, geometry.rightWrist, armWidth * 0.82, armWidth * 0.64, tonedUpper);

  context.fillStyle = colorToRgba(tonedSkin, 0.94);
  context.beginPath();
  context.arc(geometry.head.x, geometry.head.y, headRadius, 0, Math.PI * 2);
  context.fill();
  context.beginPath();
  context.arc(geometry.leftWrist.x, geometry.leftWrist.y, Math.max(4, armWidth * 0.26), 0, Math.PI * 2);
  context.arc(geometry.rightWrist.x, geometry.rightWrist.y, Math.max(4, armWidth * 0.26), 0, Math.PI * 2);
  context.fill();

  context.fillStyle = colorToRgba(tonedHair, 0.9);
  context.beginPath();
  context.arc(geometry.head.x, geometry.head.y - headRadius * 0.08, headRadius * 1.03, Math.PI, Math.PI * 2);
  context.lineTo(geometry.head.x + headRadius * 0.88, geometry.head.y + headRadius * 0.24);
  context.quadraticCurveTo(
    geometry.head.x,
    geometry.head.y - headRadius * 0.24,
    geometry.head.x - headRadius * 0.92,
    geometry.head.y + headRadius * 0.3
  );
  context.closePath();
  context.fill();
  context.fillRect(
    geometry.head.x - headRadius * 0.92,
    geometry.head.y - headRadius * 0.12,
    headRadius * 1.84,
    headRadius * 0.3
  );

  context.fillStyle = colorToRgba(tonedShoes, 0.98);
  context.beginPath();
  context.ellipse(geometry.leftAnkle.x, geometry.leftAnkle.y + height * 0.012, legWidth * 0.34, legWidth * 0.16, 0, 0, Math.PI * 2);
  context.ellipse(geometry.rightAnkle.x, geometry.rightAnkle.y + height * 0.012, legWidth * 0.34, legWidth * 0.16, 0, 0, Math.PI * 2);
  context.fill();
  context.strokeStyle = colorToRgba(outlineColor, 0.5);
  context.lineWidth = Math.max(1.6, shoulderWidth * 0.04);
  context.lineCap = "round";
  context.lineJoin = "round";
  drawTaperedLimb(context, geometry.leftShoulder, geometry.leftElbow, armWidth * 0.52, armWidth * 0.44, outlineColor);
  drawTaperedLimb(context, geometry.leftElbow, geometry.leftWrist, armWidth * 0.44, armWidth * 0.34, outlineColor);
  drawTaperedLimb(context, geometry.rightShoulder, geometry.rightElbow, armWidth * 0.52, armWidth * 0.44, outlineColor);
  drawTaperedLimb(context, geometry.rightElbow, geometry.rightWrist, armWidth * 0.44, armWidth * 0.34, outlineColor);
  drawTaperedLimb(context, geometry.leftHip, geometry.leftKnee, legWidth * 0.5, legWidth * 0.42, outlineColor);
  drawTaperedLimb(context, geometry.leftKnee, geometry.leftAnkle, legWidth * 0.42, legWidth * 0.34, outlineColor);
  drawTaperedLimb(context, geometry.rightHip, geometry.rightKnee, legWidth * 0.5, legWidth * 0.42, outlineColor);
  drawTaperedLimb(context, geometry.rightKnee, geometry.rightAnkle, legWidth * 0.42, legWidth * 0.34, outlineColor);
  traceBodyShape();
  context.strokeStyle = colorToRgba(outlineColor, 0.32);
  context.lineWidth = Math.max(1.2, shoulderWidth * 0.03);
  context.stroke();
  context.restore();

  if (torsoPatch) {
    context.save();
    traceBodyShape();
    context.clip();
    context.filter = "blur(0.3px) saturate(0.94) contrast(0.98) brightness(0.99)";
    drawRotatedPatch(
      context,
      torsoPatch,
      bodyCenterX,
      (geometry.neck.y + hemY) / 2,
      shoulderWidth * (palette.hasLongGarment ? 2.2 : 1.5),
      (hemY - geometry.neck.y) * 1.08,
      torsoAngle,
      0.52
    );
    context.restore();
  }

  if (lowerPatch && !palette.hasLongGarment) {
    context.save();
    context.beginPath();
    context.moveTo(geometry.leftHip.x - legWidth * 0.9, geometry.leftHip.y);
    context.lineTo(geometry.rightHip.x + legWidth * 0.9, geometry.rightHip.y);
    context.lineTo(geometry.rightAnkle.x + legWidth * 0.4, geometry.rightAnkle.y + height * 0.03);
    context.lineTo(geometry.leftAnkle.x - legWidth * 0.4, geometry.leftAnkle.y + height * 0.03);
    context.closePath();
    context.clip();
    context.filter = "blur(0.25px) saturate(0.92) contrast(0.98)";
    drawRotatedPatch(
      context,
      lowerPatch,
      (geometry.leftHip.x + geometry.rightHip.x + geometry.leftAnkle.x + geometry.rightAnkle.x) / 4,
      (geometry.leftHip.y + geometry.rightHip.y + geometry.leftAnkle.y + geometry.rightAnkle.y) / 4,
      shoulderWidth * 1.35,
      Math.max(legWidth * 4.2, hemY - waistY),
      0,
      0.4
    );
    context.restore();
  }

  if (headPatch) {
    context.save();
    context.beginPath();
    context.arc(geometry.head.x, geometry.head.y, headRadius * 1.02, 0, Math.PI * 2);
    context.closePath();
    context.clip();
    context.filter = "blur(0.2px) saturate(0.95) contrast(0.99)";
    drawRotatedPatch(
      context,
      headPatch,
      geometry.head.x,
      geometry.head.y + headRadius * 0.04,
      headRadius * 2.1,
      headRadius * 2.3,
      0,
      0.82
    );
    context.restore();
  }

  return canvas;
}

type StoryboardPoseHumanPalette = ReturnType<typeof sampleStoryboardGuidePalette>;

function buildStoryboardPoseHumanPaletteVariant(index: number): StoryboardPoseHumanPalette {
  const variants: StoryboardPoseHumanPalette[] = [
    {
      hair: { r: 34, g: 34, b: 40 },
      skin: { r: 228, g: 204, b: 190 },
      upper: { r: 96, g: 110, b: 144 },
      lower: { r: 80, g: 88, b: 118 },
      accent: { r: 40, g: 40, b: 48 },
      shoes: { r: 32, g: 32, b: 36 },
      hasLongGarment: false
    },
    {
      hair: { r: 30, g: 30, b: 38 },
      skin: { r: 232, g: 209, b: 196 },
      upper: { r: 112, g: 124, b: 142 },
      lower: { r: 118, g: 132, b: 154 },
      accent: { r: 58, g: 62, b: 74 },
      shoes: { r: 36, g: 36, b: 40 },
      hasLongGarment: true
    }
  ];
  const selected = variants[Math.abs(index) % variants.length] ?? variants[0]!;
  return {
    hair: { ...selected.hair },
    skin: { ...selected.skin },
    upper: { ...selected.upper },
    lower: { ...selected.lower },
    accent: { ...selected.accent },
    shoes: { ...selected.shoes },
    hasLongGarment: selected.hasLongGarment
  };
}

function resolveStoryboardPoseHumanPalette(
  cutout: HTMLCanvasElement | null | undefined,
  fallbackIndex = 0
): StoryboardPoseHumanPalette {
  if (!cutout) {
    return buildStoryboardPoseHumanPaletteVariant(fallbackIndex);
  }
  const sampled = sampleStoryboardGuidePalette(cutout);
  return {
    hair: { ...sampled.hair },
    skin: { ...sampled.skin },
    upper: { ...sampled.upper },
    lower: { ...sampled.lower },
    accent: { ...sampled.accent },
    shoes: { ...sampled.shoes },
    hasLongGarment: sampled.hasLongGarment
  };
}

function drawStoryboardReadableHumanFigure(args: {
  context: CanvasRenderingContext2D;
  poseFigure: StoryboardPoseGuideFigure;
  palette: StoryboardPoseHumanPalette;
  mode?: "clean_pose" | "plate";
}) {
  const { context, poseFigure, palette, mode = "clean_pose" } = args;
  const isCleanPose = mode === "clean_pose";
  const geometry = computeStoryboardPoseFigureGeometry(
    poseFigure.centerX,
    poseFigure.floorY,
    poseFigure.bodyHeight,
    poseFigure.action,
    poseFigureUsesMirror(poseFigure)
  );
  const bodyHeight = poseFigure.bodyHeight;
  const shoulderWidth = Math.max(18, Math.abs(geometry.rightShoulder.x - geometry.leftShoulder.x));
  const hipWidth = Math.max(14, Math.abs(geometry.rightHip.x - geometry.leftHip.x));
  const armWidth = Math.max(12, shoulderWidth * (mode === "plate" ? 0.34 : 0.3));
  const legWidth = Math.max(14, hipWidth * (mode === "plate" ? 0.82 : 0.74));
  const headRadius = Math.max(18, shoulderWidth * (mode === "plate" ? 0.62 : 0.56));
  const bodyCenterX = (geometry.leftShoulder.x + geometry.rightShoulder.x + geometry.leftHip.x + geometry.rightHip.x) / 4;
  const torsoTopY = geometry.neck.y - bodyHeight * 0.014;
  const waistY = geometry.pelvis.y - bodyHeight * 0.018;
  const torsoBottomY = geometry.pelvis.y + bodyHeight * 0.035;
  const coatHemY = Math.min(
    poseFigure.floorY - bodyHeight * 0.04,
    geometry.pelvis.y + bodyHeight * (palette.hasLongGarment ? 0.34 : 0.17)
  );
  const torsoOutline = mixRgb(palette.accent, { r: 18, g: 18, b: 22 }, 0.22);
  const upperColor = mixRgb(palette.upper, palette.accent, 0.08);
  const lowerColor = mixRgb(palette.lower, palette.accent, 0.06);
  const shadowColor = mixRgb(palette.shoes, { r: 12, g: 12, b: 16 }, 0.42);
  if (mode === "plate") {
    context.save();
    context.filter = `blur(${Math.max(3, Math.round(bodyHeight * 0.014))}px)`;
    context.fillStyle = colorToRgba(shadowColor, 0.18);
    context.beginPath();
    context.ellipse(
      (geometry.leftAnkle.x + geometry.rightAnkle.x) / 2,
      Math.max(geometry.leftAnkle.y, geometry.rightAnkle.y) + bodyHeight * 0.016,
      Math.max(14, shoulderWidth * 0.58),
      Math.max(5, shoulderWidth * 0.14),
      0,
      0,
      Math.PI * 2
    );
    context.fill();
    context.restore();
  }

  context.save();
  context.filter = isCleanPose ? "none" : "blur(0.2px)";
  drawTaperedLimb(context, geometry.leftHip, geometry.leftKnee, legWidth, legWidth * 0.84, lowerColor);
  drawTaperedLimb(context, geometry.leftKnee, geometry.leftAnkle, legWidth * 0.84, legWidth * 0.66, lowerColor);
  drawTaperedLimb(context, geometry.rightHip, geometry.rightKnee, legWidth, legWidth * 0.84, lowerColor);
  drawTaperedLimb(context, geometry.rightKnee, geometry.rightAnkle, legWidth * 0.84, legWidth * 0.66, lowerColor);
  context.restore();

  const torsoGradient = context.createLinearGradient(bodyCenterX, torsoTopY, bodyCenterX, coatHemY);
  torsoGradient.addColorStop(0, colorToRgba(upperColor, 0.99));
  torsoGradient.addColorStop(1, colorToRgba(palette.hasLongGarment ? mixRgb(upperColor, lowerColor, 0.3) : lowerColor, 0.98));

  const drawTorsoShell = () => {
    context.beginPath();
    context.moveTo(geometry.leftShoulder.x - shoulderWidth * 0.14, geometry.leftShoulder.y + bodyHeight * 0.01);
    context.quadraticCurveTo(bodyCenterX, torsoTopY - bodyHeight * 0.03, geometry.rightShoulder.x + shoulderWidth * 0.14, geometry.rightShoulder.y + bodyHeight * 0.01);
    context.lineTo(bodyCenterX + hipWidth * 1.14, torsoBottomY);
    context.quadraticCurveTo(bodyCenterX, coatHemY + bodyHeight * 0.02, bodyCenterX - hipWidth * 1.14, torsoBottomY);
    context.closePath();
  };

  context.save();
  drawTorsoShell();
  context.fillStyle = isCleanPose ? colorToRgba(mixRgb(upperColor, lowerColor, 0.18), 0.99) : torsoGradient;
  context.fill();
  context.restore();

  if (palette.hasLongGarment) {
    const panelGap = Math.max(legWidth * 0.48, shoulderWidth * 0.22);
    const panelOuter = shoulderWidth * 0.98;
    const leftOuterX = bodyCenterX - panelOuter;
    const rightOuterX = bodyCenterX + panelOuter;
    const leftInnerX = bodyCenterX - panelGap * 0.7;
    const rightInnerX = bodyCenterX + panelGap * 0.7;
    context.save();
    context.fillStyle = colorToRgba(mixRgb(lowerColor, palette.accent, 0.12), 0.98);
    context.beginPath();
    context.moveTo(geometry.leftShoulder.x - shoulderWidth * 0.08, geometry.leftShoulder.y + bodyHeight * 0.06);
    context.lineTo(bodyCenterX - shoulderWidth * 0.14, waistY);
    context.lineTo(leftInnerX, coatHemY - bodyHeight * 0.02);
    context.lineTo(leftOuterX, coatHemY);
    context.lineTo(bodyCenterX - hipWidth * 1.06, torsoBottomY);
    context.closePath();
    context.fill();
    context.beginPath();
    context.moveTo(geometry.rightShoulder.x + shoulderWidth * 0.08, geometry.rightShoulder.y + bodyHeight * 0.06);
    context.lineTo(bodyCenterX + shoulderWidth * 0.14, waistY);
    context.lineTo(rightInnerX, coatHemY - bodyHeight * 0.02);
    context.lineTo(rightOuterX, coatHemY);
    context.lineTo(bodyCenterX + hipWidth * 1.06, torsoBottomY);
    context.closePath();
    context.fill();
    context.restore();
  }

  context.save();
  context.fillStyle = colorToRgba(mixRgb(palette.accent, palette.upper, 0.12), 0.96);
  const sashWidth = shoulderWidth * (palette.hasLongGarment ? 1.08 : 0.82);
  const sashHeight = Math.max(8, bodyHeight * 0.03);
  context.fillRect(bodyCenterX - sashWidth / 2, waistY - sashHeight / 2, sashWidth, sashHeight);
  if (mode === "plate") {
    context.beginPath();
    context.moveTo(bodyCenterX + sashWidth * 0.32, waistY);
    context.lineTo(bodyCenterX + sashWidth * 0.52, waistY + bodyHeight * 0.1);
    context.lineTo(bodyCenterX + sashWidth * 0.42, waistY + bodyHeight * 0.22);
    context.lineTo(bodyCenterX + sashWidth * 0.26, waistY + bodyHeight * 0.11);
    context.closePath();
    context.fill();
  }
  context.restore();

  context.save();
  context.filter = isCleanPose ? "none" : "blur(0.16px)";
  drawTaperedLimb(context, geometry.leftShoulder, geometry.leftElbow, armWidth, armWidth * 0.82, upperColor);
  drawTaperedLimb(context, geometry.leftElbow, geometry.leftWrist, armWidth * 0.82, armWidth * 0.64, upperColor);
  drawTaperedLimb(context, geometry.rightShoulder, geometry.rightElbow, armWidth, armWidth * 0.82, upperColor);
  drawTaperedLimb(context, geometry.rightElbow, geometry.rightWrist, armWidth * 0.82, armWidth * 0.64, upperColor);
  context.restore();

  context.save();
  context.fillStyle = colorToRgba(isCleanPose ? mixRgb(palette.skin, palette.hair, 0.14) : palette.skin, 0.98);
  context.beginPath();
  context.arc(geometry.head.x, geometry.head.y, headRadius, 0, Math.PI * 2);
  context.fill();
  context.beginPath();
  context.arc(geometry.leftWrist.x, geometry.leftWrist.y, Math.max(4, armWidth * 0.26), 0, Math.PI * 2);
  context.arc(geometry.rightWrist.x, geometry.rightWrist.y, Math.max(4, armWidth * 0.26), 0, Math.PI * 2);
  context.fill();
  context.restore();

  if (!isCleanPose) {
    context.save();
    context.fillStyle = colorToRgba(palette.hair, 0.98);
    context.beginPath();
    context.arc(geometry.head.x, geometry.head.y - headRadius * 0.08, headRadius * 1.06, Math.PI, Math.PI * 2);
    context.lineTo(geometry.head.x + headRadius * 0.92, geometry.head.y + headRadius * 0.2);
    context.quadraticCurveTo(
      geometry.head.x,
      geometry.head.y - headRadius * 0.28,
      geometry.head.x - headRadius * 0.94,
      geometry.head.y + headRadius * 0.26
    );
    context.closePath();
    context.fill();
    context.restore();
  }

  if (!isCleanPose && mode !== "plate" && headRadius >= 16) {
    const eyeY = geometry.head.y - headRadius * 0.02;
    const eyeOffsetX = headRadius * 0.34;
    const eyeRadiusX = Math.max(2, headRadius * 0.12);
    const eyeRadiusY = Math.max(1.5, headRadius * 0.08);
    context.save();
    context.fillStyle = colorToRgba(torsoOutline, 0.92);
    context.beginPath();
    context.ellipse(geometry.head.x - eyeOffsetX, eyeY, eyeRadiusX, eyeRadiusY, 0, 0, Math.PI * 2);
    context.ellipse(geometry.head.x + eyeOffsetX, eyeY, eyeRadiusX, eyeRadiusY, 0, 0, Math.PI * 2);
    context.fill();
    context.lineWidth = Math.max(1, headRadius * 0.06);
    context.strokeStyle = colorToRgba(mixRgb(palette.accent, palette.skin, 0.16), 0.74);
    context.beginPath();
    context.moveTo(geometry.head.x - headRadius * 0.18, geometry.head.y + headRadius * 0.24);
    context.quadraticCurveTo(geometry.head.x, geometry.head.y + headRadius * 0.34, geometry.head.x + headRadius * 0.18, geometry.head.y + headRadius * 0.24);
    context.stroke();
    context.restore();
  }

  context.save();
  context.fillStyle = colorToRgba(palette.shoes, 0.98);
  context.beginPath();
  context.ellipse(geometry.leftAnkle.x, geometry.leftAnkle.y + bodyHeight * 0.01, legWidth * 0.42, legWidth * 0.16, -0.08, 0, Math.PI * 2);
  context.ellipse(geometry.rightAnkle.x, geometry.rightAnkle.y + bodyHeight * 0.01, legWidth * 0.42, legWidth * 0.16, 0.08, 0, Math.PI * 2);
  context.fill();
  context.restore();

  context.save();
  context.lineCap = "round";
  context.lineJoin = "round";
  context.strokeStyle = colorToRgba(torsoOutline, mode === "plate" ? 0.42 : isCleanPose ? 0.22 : 0.3);
  context.lineWidth = Math.max(1.2, shoulderWidth * 0.06);
  drawTorsoShell();
  context.stroke();
  context.restore();
}

function buildStoryboardPosedIdentityCanvas(
  cutout: HTMLCanvasElement,
  drawWidth: number,
  drawHeight: number,
  action: StoryboardPoseAction = "stand",
  mirror = false
): HTMLCanvasElement | null {
  const width = Math.max(1, Math.round(drawWidth));
  const height = Math.max(1, Math.round(drawHeight));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;

  const baseGuide = buildStoryboardGuideCharacterCanvas(
    cutout,
    width,
    height,
    { r: 238, g: 234, b: 228 },
    null,
    action,
    mirror
  );
  if (baseGuide) {
    context.save();
    context.globalAlpha = 1;
    context.filter = "saturate(1.01) contrast(1.01)";
    context.drawImage(baseGuide, 0, 0, width, height);
    context.restore();
  }

  const headPatch = extractCanvasRegion(cutout, 0.26, 0.02, 0.48, 0.22);
  const torsoPatch = extractCanvasRegion(cutout, 0.18, 0.16, 0.64, 0.36);
  const lowerPatch = extractCanvasRegion(cutout, 0.16, 0.44, 0.68, 0.5);
  const leftArmPatch = extractCanvasRegion(cutout, 0.02, 0.16, 0.34, 0.48);
  const rightArmPatch = extractCanvasRegion(cutout, 0.64, 0.16, 0.34, 0.48);
  const leftLegPatch = extractCanvasRegion(cutout, 0.16, 0.52, 0.28, 0.44);
  const rightLegPatch = extractCanvasRegion(cutout, 0.56, 0.52, 0.28, 0.44);
  const palette = sampleStoryboardGuidePalette(cutout);
  const geometry = computeStoryboardPoseFigureGeometry(width / 2, height * 0.95, height * 0.92, action, mirror);
  const shoulderWidth = Math.abs(geometry.rightShoulder.x - geometry.leftShoulder.x);
  const hipWidth = Math.abs(geometry.rightHip.x - geometry.leftHip.x);
  const armWidth = Math.max(10, shoulderWidth * 0.22);
  const legWidth = Math.max(11, hipWidth * 0.38);
  const headRadius = Math.max(10, shoulderWidth * 0.34);
  const waistY = geometry.pelvis.y - height * 0.035;
  const hemY = palette.hasLongGarment
    ? Math.min(height * 0.92, Math.max(geometry.leftKnee.y, geometry.rightKnee.y) + height * 0.06)
    : Math.min(height * 0.8, geometry.pelvis.y + height * 0.16);
  const bodyCenterX = (geometry.leftShoulder.x + geometry.rightShoulder.x + geometry.leftHip.x + geometry.rightHip.x) / 4;
  const torsoLeftX = bodyCenterX - shoulderWidth * 0.62;
  const torsoRightX = bodyCenterX + shoulderWidth * 0.62;
  const hemLeftX = bodyCenterX - shoulderWidth * (palette.hasLongGarment ? 0.94 : 0.48);
  const hemRightX = bodyCenterX + shoulderWidth * (palette.hasLongGarment ? 0.94 : 0.48);
  const torsoAngle = Math.atan2(geometry.pelvis.y - geometry.neck.y, geometry.pelvis.x - geometry.neck.x);
  const traceBodyShape = () => {
    context.beginPath();
    context.moveTo(geometry.leftShoulder.x, geometry.leftShoulder.y);
    context.lineTo(geometry.rightShoulder.x, geometry.rightShoulder.y);
    context.lineTo(torsoRightX, waistY);
    context.lineTo(hemRightX, hemY);
    context.lineTo(hemLeftX, hemY);
    context.lineTo(torsoLeftX, waistY);
    context.closePath();
  };

  if (torsoPatch) {
    context.save();
    traceBodyShape();
    context.clip();
    context.filter = "blur(0.18px) saturate(1.04) contrast(1.04) brightness(1.01)";
    drawRotatedPatch(
      context,
      torsoPatch,
      bodyCenterX,
      (geometry.neck.y + waistY) / 2,
      shoulderWidth * (palette.hasLongGarment ? 2.12 : 1.54),
      Math.max(shoulderWidth * 1.46, hemY - geometry.neck.y),
      torsoAngle,
      0.14
    );
    context.restore();
  }

  if (lowerPatch) {
    context.save();
    if (palette.hasLongGarment) {
      context.beginPath();
      context.moveTo(torsoLeftX - shoulderWidth * 0.08, waistY - height * 0.01);
      context.lineTo(torsoRightX + shoulderWidth * 0.08, waistY - height * 0.01);
      context.lineTo(hemRightX, hemY);
      context.lineTo(hemLeftX, hemY);
      context.closePath();
    } else {
      context.beginPath();
      context.moveTo(geometry.leftHip.x - legWidth * 0.8, geometry.leftHip.y);
      context.lineTo(geometry.rightHip.x + legWidth * 0.8, geometry.rightHip.y);
      context.lineTo(geometry.rightKnee.x + legWidth * 0.58, geometry.rightKnee.y + height * 0.03);
      context.lineTo(geometry.leftKnee.x - legWidth * 0.58, geometry.leftKnee.y + height * 0.03);
      context.closePath();
    }
    context.clip();
    context.filter = "blur(0.16px) saturate(1.03) contrast(1.03) brightness(1.01)";
    drawRotatedPatch(
      context,
      lowerPatch,
      bodyCenterX,
      (waistY + hemY) / 2,
      shoulderWidth * (palette.hasLongGarment ? 2.28 : 1.46),
      Math.max(shoulderWidth * 1.34, hemY - waistY),
      palette.hasLongGarment ? torsoAngle * 0.35 : 0,
      0.08
    );
    context.restore();
  }

  drawPatchAlongLimb(
    context,
    leftArmPatch,
    geometry.leftShoulder,
    geometry.leftElbow,
    armWidth * 1.04,
    armWidth * 0.88,
    0.06
  );
  drawPatchAlongLimb(
    context,
    leftArmPatch,
    geometry.leftElbow,
    geometry.leftWrist,
    armWidth * 0.84,
    armWidth * 0.66,
    0.04
  );
  drawPatchAlongLimb(
    context,
    rightArmPatch,
    geometry.rightShoulder,
    geometry.rightElbow,
    armWidth * 1.04,
    armWidth * 0.88,
    0.06
  );
  drawPatchAlongLimb(
    context,
    rightArmPatch,
    geometry.rightElbow,
    geometry.rightWrist,
    armWidth * 0.84,
    armWidth * 0.66,
    0.04
  );

  if (!palette.hasLongGarment) {
    drawPatchAlongLimb(
      context,
      leftLegPatch,
      geometry.leftHip,
      geometry.leftKnee,
      legWidth * 1.12,
      legWidth * 0.9,
      0.04
    );
    drawPatchAlongLimb(
      context,
      leftLegPatch,
      geometry.leftKnee,
      geometry.leftAnkle,
      legWidth * 0.88,
      legWidth * 0.68,
      0.03
    );
    drawPatchAlongLimb(
      context,
      rightLegPatch,
      geometry.rightHip,
      geometry.rightKnee,
      legWidth * 1.12,
      legWidth * 0.9,
      0.04
    );
    drawPatchAlongLimb(
      context,
      rightLegPatch,
      geometry.rightKnee,
      geometry.rightAnkle,
      legWidth * 0.88,
      legWidth * 0.68,
      0.03
    );
  }

  if (headPatch) {
    context.save();
    context.beginPath();
    context.arc(geometry.head.x, geometry.head.y, headRadius * 1.02, 0, Math.PI * 2);
    context.closePath();
    context.clip();
    context.filter = "blur(0.12px) saturate(1.03) contrast(1.04) brightness(1.02)";
      drawRotatedPatch(
        context,
        headPatch,
        geometry.head.x,
        geometry.head.y + headRadius * 0.04,
        headRadius * 2.08,
        headRadius * 2.28,
        0,
        0.98
      );
    context.restore();
  }

  if (baseGuide) {
    context.save();
    context.globalAlpha = 0.1;
    context.filter = "blur(0.12px)";
    context.drawImage(baseGuide, 0, 0, width, height);
    context.restore();
  }

  const image = context.getImageData(0, 0, width, height);
  const data = image.data;
  for (let index = 0; index < data.length; index += 4) {
    const alpha = data[index + 3] ?? 0;
    if (alpha <= 18) continue;
    data[index + 3] = Math.max(alpha, 214);
  }
  context.putImageData(image, 0, 0);

  return canvas;
}

function buildStoryboardOccupancyGuideCanvas(
  cutout: HTMLCanvasElement,
  drawWidth: number,
  drawHeight: number,
  sceneTint: { r: number; g: number; b: number },
  scenePatch?: HTMLCanvasElement | null,
  mirror = false
): HTMLCanvasElement | null {
  const width = Math.max(1, Math.round(drawWidth));
  const height = Math.max(1, Math.round(drawHeight));
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;

  const patchInfluence = scenePatch
    ? sampleSceneRegionColor(
        (() => {
          const patchCanvas = document.createElement("canvas");
          patchCanvas.width = width;
          patchCanvas.height = height;
          const patchContext = patchCanvas.getContext("2d");
          if (patchContext) patchContext.drawImage(scenePatch, 0, 0, width, height);
          return patchContext ?? context;
        })(),
        width * 0.24,
        height * 0.18,
        width * 0.52,
        height * 0.68
      )
    : sceneTint;
  const occupancyTint = mixRgb(sceneTint, patchInfluence, 0.42);

  context.save();
  if (mirror) {
    context.translate(width, 0);
    context.scale(-1, 1);
  }
  context.filter = "saturate(0.82) contrast(0.94) brightness(0.98)";
  context.drawImage(cutout, 0, 0, width, height);
  context.restore();

  const imageData = context.getImageData(0, 0, width, height);
  const { data } = imageData;
  for (let index = 0; index < data.length; index += 4) {
    const alpha = data[index + 3] ?? 0;
    if (alpha <= 0) continue;
    const alphaRatio = alpha / 255;
    const source = {
      r: data[index] ?? 0,
      g: data[index + 1] ?? 0,
      b: data[index + 2] ?? 0
    };
    const grayscale = Math.round(source.r * 0.299 + source.g * 0.587 + source.b * 0.114);
    const desaturated = mixRgb(source, { r: grayscale, g: grayscale, b: grayscale }, 0.18);
    const toned = mixRgb(desaturated, occupancyTint, alphaRatio < 0.55 ? 0.24 : 0.12);
    data[index] = toned.r;
    data[index + 1] = toned.g;
    data[index + 2] = toned.b;
    data[index + 3] = Math.max(108, Math.min(236, Math.round(alpha * 0.92)));
  }
  context.putImageData(imageData, 0, 0);

  context.save();
  context.globalCompositeOperation = "destination-over";
  context.filter = "blur(4px)";
  context.globalAlpha = 0.36;
  context.drawImage(canvas, 0, 0);
  context.restore();

  return canvas;
}

function buildStoryboardCompositeCharacterLayers(
  cutout: HTMLCanvasElement,
  drawWidth: number,
  drawHeight: number,
  sceneTint: { r: number; g: number; b: number },
  scenePatch: HTMLCanvasElement | null | undefined,
  action: StoryboardPoseAction,
  options?: {
    includePosedIdentity?: boolean;
    integratePosedIdentityWithScene?: boolean;
  }
): {
  occupancyGuide: HTMLCanvasElement | null;
  guideFigure: HTMLCanvasElement | null;
  sceneReadyCutout: HTMLCanvasElement;
  sceneReadyPosedIdentity: HTMLCanvasElement | null;
} {
  const occupancyGuide = buildStoryboardOccupancyGuideCanvas(
    cutout,
    drawWidth,
    drawHeight,
    sceneTint,
    scenePatch,
    false
  );
  const guideFigure = buildStoryboardGuideCharacterCanvas(
    cutout,
    drawWidth,
    drawHeight,
    sceneTint,
    scenePatch,
    action,
    false
  );
  const includePosedIdentity = options?.includePosedIdentity ?? action !== "stand";
  const integratePosedIdentityWithScene = options?.integratePosedIdentityWithScene ?? true;
  const rawPosedIdentityGuide = includePosedIdentity
    ? buildStoryboardPosedIdentityCanvas(cutout, drawWidth, drawHeight, action, false)
    : null;
  const dynamicAction =
    action === "walk" ||
    action === "gesture" ||
    action === "gesture_left" ||
    action === "stop" ||
    action === "stop_left" ||
    action === "nod" ||
    action === "lean" ||
    action === "reach_down" ||
    action === "reach_down_left";
  const posedIdentityGuide = rawPosedIdentityGuide
    ? constrainStoryboardPosedIdentityToCutoutSilhouette(rawPosedIdentityGuide, cutout, {
        featherPx: dynamicAction ? 3.4 : 2.4,
        expandPx: dynamicAction ? 5 : 3,
        minAlpha: 18
      }) ?? rawPosedIdentityGuide
    : null;
  return {
    occupancyGuide,
    guideFigure,
    sceneReadyCutout: buildIntegratedCharacterCanvas(cutout, drawWidth, drawHeight, sceneTint, scenePatch) ?? cutout,
    sceneReadyPosedIdentity:
      posedIdentityGuide && integratePosedIdentityWithScene
        ? buildIntegratedCharacterCanvas(posedIdentityGuide, drawWidth, drawHeight, sceneTint, scenePatch) ?? posedIdentityGuide
        : posedIdentityGuide
  };
}

function buildStoryboardFallbackHeroLayer(
  cutout: HTMLCanvasElement,
  posedIdentity: HTMLCanvasElement | null,
  action: StoryboardPoseAction,
  options?: {
    posedIdentityOpacity?: number;
  }
): HTMLCanvasElement {
  const width = Math.max(1, posedIdentity?.width || cutout.width);
  const height = Math.max(1, posedIdentity?.height || cutout.height);
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return cutout;

  const dynamicAction =
    action === "walk" ||
    action === "gesture" ||
    action === "gesture_left" ||
    action === "stop" ||
    action === "stop_left" ||
    action === "nod" ||
    action === "lean" ||
    action === "reach_down" ||
    action === "reach_down_left" ||
    action === "look";
  const posedIdentityOpacity = Math.max(
    0,
    Math.min(1, options?.posedIdentityOpacity ?? (dynamicAction ? 0.05 : 0.04))
  );

  context.save();
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  context.filter = "contrast(1.02) brightness(1.015) saturate(1.01)";
  context.drawImage(cutout, 0, 0, width, height);
  context.restore();

  if (posedIdentity) {
    context.save();
    // Keep the pose cue subtle enough to avoid pasted rectangular patch artifacts.
    context.globalCompositeOperation = dynamicAction ? "source-over" : "source-atop";
    context.globalAlpha = dynamicAction
      ? Math.max(0.1, Math.min(0.18, Math.max(posedIdentityOpacity * 2.1, 0.12)))
      : Math.max(0.025, Math.min(0.06, posedIdentityOpacity * 0.9));
    context.filter = dynamicAction
      ? "blur(0.18px) contrast(1.02) brightness(1.01) saturate(1.01)"
      : "blur(0.15px) saturate(0.99) contrast(1)";
    context.drawImage(posedIdentity, 0, 0, width, height);
    context.restore();
  }

  return canvas;
}

function readStoryboardMaskWeightAtPixel(rgba: Uint8ClampedArray, index: number): number {
  const alpha = (rgba[index + 3] ?? 0) / 255;
  if (alpha <= 0.04) return 0;
  const luminance = ((rgba[index] ?? 0) + (rgba[index + 1] ?? 0) + (rgba[index + 2] ?? 0)) / (255 * 3);
  if (luminance <= 0.05) return 0;
  const weight = alpha * luminance * 1.35;
  if (weight <= 0.04) return 0;
  return Math.min(1, weight);
}

async function readStoryboardMaskBounds(
  pathOrUrl: string
): Promise<{
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  centerX: number;
  floorY: number;
  width: number;
  height: number;
  canvasWidth: number;
  canvasHeight: number;
} | null> {
  const image = await loadReferenceImageElement(pathOrUrl);
  if (!image) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  if (width <= 0 || height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.drawImage(image, 0, 0, width, height);
  const { data } = context.getImageData(0, 0, width, height);
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;
  for (let index = 0; index < data.length; index += 4) {
    const weight = readStoryboardMaskWeightAtPixel(data, index);
    if (weight <= 0.04) continue;
    const pixelIndex = index / 4;
    const y = Math.floor(pixelIndex / width);
    const x = pixelIndex - y * width;
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  if (maxX < minX || maxY < minY) return null;
  return {
    minX,
    minY,
    maxX,
    maxY,
    centerX: (minX + maxX) / 2,
    floorY: maxY,
    width: maxX - minX + 1,
    height: maxY - minY + 1,
    canvasWidth: width,
    canvasHeight: height
  };
}

function scaleMaskBoundsToScene(
  bounds: { minX: number; minY: number; maxX: number; maxY: number; centerX: number; floorY: number; width: number; height: number },
  maskCanvasWidth: number,
  maskCanvasHeight: number,
  sceneWidth: number,
  sceneHeight: number
): { centerXRatio: number; floorYRatio: number; bodyHeightRatio: number } {
  const scaleX = sceneWidth / Math.max(1, maskCanvasWidth);
  const scaleY = sceneHeight / Math.max(1, maskCanvasHeight);
  const centerX = bounds.centerX * scaleX;
  const floorY = bounds.floorY * scaleY;
  const bodyHeight = bounds.height * scaleY;
  return {
    centerXRatio: centerX / Math.max(1, sceneWidth),
    floorYRatio: floorY / Math.max(1, sceneHeight),
    bodyHeightRatio: bodyHeight / Math.max(1, sceneHeight)
  };
}

type StoryboardMaskSlotPlacement = {
  slot: 1 | 2;
  centerXRatio: number;
  floorYRatio: number;
  bodyHeightRatio: number;
};

async function readStoryboardMaskSlotPlacements(
  inputDir: string,
  safeShotId: string,
  sceneWidth: number,
  sceneHeight: number
): Promise<StoryboardMaskSlotPlacement[]> {
  const placements = (
    await Promise.all(
      ([1, 2] as const).map(async (slot) => {
        const bounds = await readStoryboardMaskBounds(`${inputDir}/shot_${safeShotId}_char${slot}_mask.png`);
        if (!bounds) return null;
        const scaled = scaleMaskBoundsToScene(
          bounds,
          bounds.canvasWidth,
          bounds.canvasHeight,
          sceneWidth,
          sceneHeight
        );
        return {
          slot,
          centerXRatio: Math.min(0.94, Math.max(0.06, scaled.centerXRatio)),
          floorYRatio: clampStoryboardFloorRatio(scaled.floorYRatio),
          bodyHeightRatio: Math.min(0.82, Math.max(0.12, scaled.bodyHeightRatio))
        } satisfies StoryboardMaskSlotPlacement;
      })
    )
  ).filter((item): item is StoryboardMaskSlotPlacement => Boolean(item));
  return placements;
}

async function buildStoryboardIdentityBoardReference(
  shot: Shot,
  refs: WeightedImageRef[],
  inputDir: string,
  assets: Asset[]
): Promise<WeightedImageRef | null> {
  if (!canProcessStoryboardReferenceImages()) return null;
  const selectedCharacters = (shot.characterRefs ?? [])
    .map((id) => assets.find((item) => item.id === id && item.type === "character"))
    .filter((item): item is Asset => Boolean(item))
    .slice(0, 2);
  if (selectedCharacters.length < 2) return null;

  const strips = (
    await Promise.all(
      selectedCharacters.map(async (asset) => {
        const preferredSource =
          asset.characterFrontPath?.trim() ||
          refs.find((item) => item.bucket === `character:${asset.id}` && item.role === "character_front")?.source?.trim() ||
          asset.filePath?.trim() ||
          refs.find((item) => item.bucket === `character:${asset.id}`)?.source?.trim() ||
          "";
        return await buildCharacterThreeViewStripCanvas(asset, preferredSource);
      })
    )
  ).filter((item): item is HTMLCanvasElement => Boolean(item));
  if (strips.length === 0) return null;

  const slotHeight = 420;
  const gap = 28;
  const padding = 28;
  const slotWidth = 420;
  const boardWidth = padding * 2 + slotWidth * strips.length + gap * Math.max(0, strips.length - 1);
  const boardHeight = slotHeight + padding * 2;
  const canvas = document.createElement("canvas");
  canvas.width = boardWidth;
  canvas.height = boardHeight;
  const context = canvas.getContext("2d");
  if (!context) return null;

  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, boardWidth, boardHeight);

  strips.forEach((strip, index) => {
    const scale = Math.min(slotWidth / Math.max(1, strip.width), slotHeight / Math.max(1, strip.height));
    const drawWidth = Math.round(strip.width * scale);
    const drawHeight = Math.round(strip.height * scale);
    const slotX = padding + index * (slotWidth + gap);
    const drawX = slotX + Math.round((slotWidth - drawWidth) / 2);
    const drawY = padding + Math.round((slotHeight - drawHeight) / 2);
    context.save();
    context.fillStyle = "rgba(0,0,0,0.04)";
    context.fillRect(slotX, padding, slotWidth, slotHeight);
    context.filter = "saturate(0.92) contrast(0.96) brightness(0.98)";
    context.drawImage(strip, drawX, drawY, drawWidth, drawHeight);
    context.restore();
  });

  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const filePath = `${inputDir}/shot_${safeShotId}_character_identity_board.png`;
  const result = await invokeDesktopCommand<{ filePath: string }>("write_base64_file", {
    filePath,
    base64Data: canvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
  });
  if (!result.filePath) return null;
  return {
    source: result.filePath,
    weight: 0.72,
    priority: 360,
    bucket: `scene_identity:${shot.id}`,
    label: "character_identity_board",
    role: "continuity_character"
  };
}

async function buildCharacterThreeViewStripCanvas(
  asset: Asset,
  fallbackSource = ""
): Promise<HTMLCanvasElement | null> {
  const sources = [
    asset.characterFrontPath?.trim() || asset.filePath?.trim() || fallbackSource.trim(),
    asset.characterSidePath?.trim() || "",
    asset.characterBackPath?.trim() || ""
  ];
  const cutouts = (
    await Promise.all(
      sources.map(async (source) => {
        if (!source) return null;
        return await buildCharacterCutoutCanvas(source);
      })
    )
  ).filter((item): item is HTMLCanvasElement => Boolean(item));
  if (cutouts.length === 0) return null;

  const slotWidth = 180;
  const slotHeight = 320;
  const gap = 12;
  const padding = 16;
  const canvas = document.createElement("canvas");
  canvas.width = padding * 2 + slotWidth * cutouts.length + gap * Math.max(0, cutouts.length - 1);
  canvas.height = padding * 2 + slotHeight;
  const context = canvas.getContext("2d");
  if (!context) return null;

  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, canvas.width, canvas.height);

  cutouts.forEach((cutout, index) => {
    const scale = Math.min(slotWidth / Math.max(1, cutout.width), slotHeight / Math.max(1, cutout.height));
    const drawWidth = Math.round(cutout.width * scale);
    const drawHeight = Math.round(cutout.height * scale);
    const slotX = padding + index * (slotWidth + gap);
    const drawX = slotX + Math.round((slotWidth - drawWidth) / 2);
    const drawY = padding + Math.round((slotHeight - drawHeight) / 2);
    context.save();
    context.fillStyle = "rgba(0,0,0,0.04)";
    context.fillRect(slotX, padding, slotWidth, slotHeight);
    context.filter = "saturate(0.94) contrast(0.97) brightness(0.99)";
    context.drawImage(cutout, drawX, drawY, drawWidth, drawHeight);
    context.restore();
  });

  return canvas;
}

async function buildCharacterThreeViewTokenCanvas(
  settings: ComfySettings,
  sources: string[]
): Promise<HTMLCanvasElement | null> {
  if (!canProcessStoryboardReferenceImages()) return null;
  const cutouts = (
    await Promise.all(
      sources
        .map((source) => resolveInputTokenSourcePath(settings, source))
        .filter((source) => source.trim().length > 0)
        .map(async (source) => await buildCharacterCutoutCanvas(source))
    )
  ).filter((item): item is HTMLCanvasElement => Boolean(item));
  if (cutouts.length === 0) return null;

  const canvasSize = 1024;
  const padding = 48;
  const gap = 24;
  const slotWidth = Math.floor((canvasSize - padding * 2 - gap * 2) / 3);
  const slotHeight = canvasSize - padding * 2;
  const canvas = document.createElement("canvas");
  canvas.width = canvasSize;
  canvas.height = canvasSize;
  const context = canvas.getContext("2d");
  if (!context) return null;

  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, canvasSize, canvasSize);

  for (let index = 0; index < 3; index += 1) {
    const cutout = cutouts[index] ?? cutouts[cutouts.length - 1];
    if (!cutout) continue;
    const scale = Math.min(slotWidth / Math.max(1, cutout.width), slotHeight / Math.max(1, cutout.height));
    const drawWidth = Math.round(cutout.width * scale);
    const drawHeight = Math.round(cutout.height * scale);
    const slotX = padding + index * (slotWidth + gap);
    const drawX = slotX + Math.round((slotWidth - drawWidth) / 2);
    const drawY = padding + Math.round((slotHeight - drawHeight) / 2);
    context.save();
    context.fillStyle = "rgba(0,0,0,0.035)";
    context.fillRect(slotX, padding, slotWidth, slotHeight);
    context.filter = "saturate(0.94) contrast(0.97) brightness(0.99)";
    context.drawImage(cutout, drawX, drawY, drawWidth, drawHeight);
    context.restore();
  }

  return canvas;
}

async function stageStoryboardThreeViewTokens(
  settings: ComfySettings,
  shot: Shot,
  tokens: Record<string, string>
): Promise<Record<string, string>> {
  if (!canProcessStoryboardReferenceImages()) return tokens;
  const inputDir = inferComfyInputDir(settings);
  if (!inputDir) return tokens;
  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const nextTokens = { ...tokens };
  const isUsableIdentityView = (quality: { fragmented: boolean; edgeTouch: boolean; componentCount: number }) =>
    !quality.fragmented && !quality.edgeTouch && quality.componentCount <= 4;

  for (const slot of [1, 2] as const) {
    const frontKey = `CHAR${slot}_FRONT_PATH` as const;
    const sideKey = `CHAR${slot}_SIDE_PATH` as const;
    const backKey = `CHAR${slot}_BACK_PATH` as const;
    const primaryKey = `CHAR${slot}_PRIMARY_PATH` as const;
    const secondaryKey = `CHAR${slot}_SECONDARY_PATH` as const;
    const frontPath = String(nextTokens[frontKey] ?? "").trim();
    const sidePath = String(nextTokens[sideKey] ?? "").trim();
    const backPath = String(nextTokens[backKey] ?? "").trim();
    const primaryPath = String(nextTokens[primaryKey] ?? "").trim();
    if (!frontPath && !sidePath && !backPath && !primaryPath) continue;

    const [frontQuality, sideQuality, backQuality, primaryQuality] = await Promise.all([
      frontPath ? analyzeCharacterReferenceQuality(resolveInputTokenSourcePath(settings, frontPath)) : Promise.resolve({ fragmented: false, edgeTouch: false, componentCount: 0 }),
      sidePath ? analyzeCharacterReferenceQuality(resolveInputTokenSourcePath(settings, sidePath)) : Promise.resolve({ fragmented: false, edgeTouch: false, componentCount: 0 }),
      backPath ? analyzeCharacterReferenceQuality(resolveInputTokenSourcePath(settings, backPath)) : Promise.resolve({ fragmented: false, edgeTouch: false, componentCount: 0 }),
      primaryPath ? analyzeCharacterReferenceQuality(resolveInputTokenSourcePath(settings, primaryPath)) : Promise.resolve({ fragmented: false, edgeTouch: false, componentCount: 0 })
    ]);

    const canonicalFrontPath = frontPath || primaryPath;
    const usableSidePath = sidePath && isUsableIdentityView(sideQuality) ? sidePath : "";
    const usableBackPath = backPath && isUsableIdentityView(backQuality) ? backPath : "";
    const middlePath = usableSidePath || usableBackPath || canonicalFrontPath;
    const terminalPath = usableBackPath || usableSidePath || canonicalFrontPath;
    const boardSources = [canonicalFrontPath, middlePath, terminalPath].filter((item) => item.trim().length > 0);
    const shouldFallbackToThreeView =
      frontQuality.fragmented ||
      sideQuality.fragmented ||
      backQuality.fragmented ||
      primaryQuality.fragmented ||
      frontQuality.edgeTouch ||
      sideQuality.edgeTouch ||
      backQuality.edgeTouch ||
      primaryQuality.edgeTouch;
    if (!shouldFallbackToThreeView) continue;

    const threeViewCanvas = await buildCharacterThreeViewTokenCanvas(settings, boardSources);
    if (!threeViewCanvas) continue;
    const filePath = `${inputDir}/shot_${safeShotId}_char${slot}_threeview_identity.png`;
    const result = await invokeDesktopCommand<{ filePath: string }>("write_base64_file", {
      filePath,
      base64Data: threeViewCanvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
    });
    if (!result.filePath) continue;
    nextTokens[primaryKey] = result.filePath.split("/").pop() ?? result.filePath;
    nextTokens[secondaryKey] = canonicalFrontPath || usableBackPath || usableSidePath || nextTokens[secondaryKey] || "";
  }

  return nextTokens;
}

type StoryboardPoseAction =
  | "stand"
  | "walk"
  | "gesture"
  | "gesture_left"
  | "stop"
  | "stop_left"
  | "nod"
  | "lean"
  | "reach_down"
  | "reach_down_left"
  | "look";

type StoryboardPoseFigureGeometry = {
  head: { x: number; y: number };
  neck: { x: number; y: number };
  pelvis: { x: number; y: number };
  leftShoulder: { x: number; y: number };
  rightShoulder: { x: number; y: number };
  leftHip: { x: number; y: number };
  rightHip: { x: number; y: number };
  leftElbow: { x: number; y: number };
  rightElbow: { x: number; y: number };
  leftWrist: { x: number; y: number };
  rightWrist: { x: number; y: number };
  leftKnee: { x: number; y: number };
  rightKnee: { x: number; y: number };
  leftAnkle: { x: number; y: number };
  rightAnkle: { x: number; y: number };
  jointRadius: number;
  limbWidth: number;
};

function inferStoryboardPoseAction(shot: Shot, characterName: string, isFocused: boolean): StoryboardPoseAction {
  const corpus = compactTextParts(shot.title, shot.storyPrompt, shot.notes, shot.dialogue, shot.videoPrompt, ...(shot.tags ?? [])).toLowerCase();
  const { contexts } = collectCharacterMentionContexts(shot, corpus, characterName);
  const localText = contexts.join(" ");
  const shotScale = inferStoryboardCompositeScale(shot);
  const multiCharacterShot =
    (Array.isArray(shot.characterRefs) && shot.characterRefs.length >= 2) ||
    containsAnyKeyword(corpus, ["双人", "两人", "二人", "two shot", "two-shot", "paired", "并肩"]);
  const mentionsLeftHand = containsAnyKeyword(localText, ["左手", "left hand", "left arm"]);
  const mentionsRightHand = containsAnyKeyword(localText, ["右手", "right hand", "right arm"]);
  const mentionsWalk = containsAnyKeyword(localText, ["走", "慢走", "前行", "迈步", "跟随", "半步", "walk", "walking", "step", "stepping"]);
  const mentionsLook = containsAnyKeyword(localText, [
    "回头",
    "转头",
    "看向",
    "看着",
    "看去",
    "目光",
    "视线",
    "观察",
    "警觉",
    "警戒",
    "look at",
    "look toward",
    "turn head",
    "turn back",
    "glance",
    "watch"
  ]);
  const mentionsTurnOrFace = containsAnyKeyword(localText, [
    "转身",
    "面向",
    "朝向",
    "侧身",
    "侧面",
    "turn",
    "turned",
    "turning",
    "face toward",
    "facing",
    "facing toward"
  ]);
  const mentionsReachDown = containsAnyKeyword(localText, [
    "lowering one hand",
    "lowering her hand",
    "lowering his hand",
    "lowering her left hand",
    "lowering his left hand",
    "lowering her right hand",
    "lowering his right hand",
    "向石边",
    "toward the stone edge",
    "toward the water",
    "探向水边",
    "探向石边",
    "查看水边",
    "水边",
    "reach down",
    "reaching down"
  ]);
  const mentionsGesture = containsAnyKeyword(localText, ["抬手", "举手", "伸手", "示意", "说话", "开口", "raise hand", "lift hand", "gesture", "extending"]);
  if (containsAnyKeyword(localText, ["俯身", "弯腰", "bend", "lean forward", "leaning"]) || mentionsReachDown) {
    if (mentionsLeftHand && !mentionsRightHand) return "reach_down_left";
    if (mentionsRightHand && !mentionsLeftHand) return "reach_down";
    return "reach_down_left";
  }
  if (containsAnyKeyword(localText, ["停下", "停步", "stop", "halt"])) {
    return mentionsLeftHand && !mentionsRightHand ? "stop_left" : "stop";
  }
  if (containsAnyKeyword(localText, ["点头", "nod"])) return "nod";
  if (mentionsTurnOrFace && mentionsLook && !isFocused) return "look";
  if (mentionsGesture) {
    if (mentionsLeftHand && !mentionsRightHand) return "gesture_left";
    return "gesture";
  }
  if (containsAnyKeyword(localText, ["lean toward", "leaning toward", "lean toward jiang lan", "lean toward shen yan", "lean in", "倾向", "靠近"])) return "lean";
  if (mentionsWalk && mentionsLook && multiCharacterShot && !isFocused) return "look";
  if (mentionsWalk) return "walk";
  if (mentionsLook) {
    return isFocused ? (mentionsLeftHand ? "gesture_left" : "gesture") : "look";
  }
  if (isFocused && containsAnyKeyword(corpus, ["回应", "说话", "起话", "对话", "反应", "reply", "speak", "speaking", "reaction"])) {
    return mentionsLeftHand ? "gesture_left" : "gesture";
  }
  if (
    multiCharacterShot &&
    shotScale === "wide" &&
    containsAnyKeyword(corpus, ["骞惰偐", "并肩", "沿河", "side by side", "walking together", "walk together", "along the same path", "along the path", "慢走"])
  ) {
    return "walk";
  }
  if (multiCharacterShot && shotScale === "wide") {
    return isFocused ? "walk" : "look";
  }
  if (multiCharacterShot && shotScale === "medium") {
    return isFocused ? (mentionsLeftHand ? "gesture_left" : "gesture") : "look";
  }
  return "stand";
}

function drawStoryboardPoseLimb(
  context: CanvasRenderingContext2D,
  from: { x: number; y: number },
  to: { x: number; y: number },
  color: string,
  width: number
) {
  context.save();
  context.strokeStyle = color;
  context.lineWidth = width;
  context.lineCap = "round";
  context.beginPath();
  context.moveTo(from.x, from.y);
  context.lineTo(to.x, to.y);
  context.stroke();
  context.restore();
}

function drawStoryboardPoseJoint(
  context: CanvasRenderingContext2D,
  point: { x: number; y: number },
  color: string,
  radius: number
) {
  context.save();
  context.fillStyle = color;
  context.beginPath();
  context.arc(point.x, point.y, radius, 0, Math.PI * 2);
  context.fill();
  context.restore();
}

function computeStoryboardPoseFigureGeometry(
  centerX: number,
  floorY: number,
  bodyHeight: number,
  action: StoryboardPoseAction,
  mirror = false
): StoryboardPoseFigureGeometry {
  const dir = mirror ? -1 : 1;
  const headY = floorY - bodyHeight * 0.92;
  const neck = { x: centerX, y: floorY - bodyHeight * 0.78 };
  const pelvis = { x: centerX, y: floorY - bodyHeight * 0.42 };
  const shoulderOffset = bodyHeight * 0.11;
  const hipOffset = bodyHeight * 0.075;
  const elbowDrop = bodyHeight * 0.18;
  const wristDrop = bodyHeight * 0.16;
  const kneeDrop = bodyHeight * 0.23;
  const ankleDrop = bodyHeight * 0.24;
  const jointRadius = Math.max(3, Math.round(bodyHeight * 0.025));
  const limbWidth = Math.max(4, Math.round(bodyHeight * 0.026));
  const leftShoulder = { x: neck.x - shoulderOffset, y: neck.y + bodyHeight * 0.02 };
  const rightShoulder = { x: neck.x + shoulderOffset, y: neck.y + bodyHeight * 0.02 };
  const leftHip = { x: pelvis.x - hipOffset, y: pelvis.y };
  const rightHip = { x: pelvis.x + hipOffset, y: pelvis.y };
  let leftElbow = { x: leftShoulder.x - shoulderOffset * 0.3 * dir, y: leftShoulder.y + elbowDrop * 0.96 };
  let rightElbow = { x: rightShoulder.x + shoulderOffset * 0.18 * dir, y: rightShoulder.y + elbowDrop * 0.84 };
  let leftWrist = { x: leftElbow.x - shoulderOffset * 0.16 * dir, y: leftElbow.y + wristDrop * 0.86 };
  let rightWrist = { x: rightElbow.x + shoulderOffset * 0.08 * dir, y: rightElbow.y + wristDrop * 0.8 };
  let leftKnee = { x: leftHip.x + hipOffset * 0.04 * dir, y: leftHip.y + kneeDrop * 0.98 };
  let rightKnee = { x: rightHip.x - hipOffset * 0.14 * dir, y: rightHip.y + kneeDrop * 1.02 };
  let leftAnkle = { x: leftKnee.x + hipOffset * 0.04 * dir, y: leftKnee.y + ankleDrop };
  let rightAnkle = { x: rightKnee.x - hipOffset * 0.14 * dir, y: rightKnee.y + ankleDrop * 0.98 };
  let headX = centerX + shoulderOffset * 0.06 * dir;
  let headTiltY = headY;

  if (action === "walk") {
    leftShoulder.x += shoulderOffset * 0.14 * dir;
    rightShoulder.x += shoulderOffset * 0.02 * dir;
    leftHip.x += hipOffset * 0.18 * dir;
    rightHip.x -= hipOffset * 0.04 * dir;
    pelvis.x += shoulderOffset * 0.08 * dir;
    leftElbow = { x: leftShoulder.x - shoulderOffset * 0.22 * dir, y: leftShoulder.y + elbowDrop * 0.96 };
    rightElbow = { x: rightShoulder.x + shoulderOffset * 0.52 * dir, y: rightShoulder.y + elbowDrop * 0.76 };
    leftWrist = { x: leftElbow.x - shoulderOffset * 0.18 * dir, y: leftElbow.y + wristDrop * 0.82 };
    rightWrist = { x: rightElbow.x + shoulderOffset * 0.34 * dir, y: rightElbow.y + wristDrop * 0.64 };
    leftKnee = { x: leftHip.x + hipOffset * 0.62 * dir, y: leftHip.y + kneeDrop * 0.84 };
    rightKnee = { x: rightHip.x - hipOffset * 0.26 * dir, y: rightHip.y + kneeDrop * 1.08 };
    leftAnkle = { x: leftKnee.x + hipOffset * 0.54 * dir, y: leftKnee.y + ankleDrop * 0.76 };
    rightAnkle = { x: rightKnee.x - hipOffset * 0.34 * dir, y: rightKnee.y + ankleDrop * 1.06 };
    headX += shoulderOffset * 0.16 * dir;
    headTiltY += bodyHeight * 0.012;
  } else if (action === "gesture") {
    rightElbow = { x: rightShoulder.x + shoulderOffset * 0.85 * dir, y: rightShoulder.y + elbowDrop * 0.42 };
    rightWrist = { x: rightElbow.x + shoulderOffset * 0.48 * dir, y: rightElbow.y - wristDrop * 0.08 };
    leftElbow = { x: leftShoulder.x - shoulderOffset * 0.28 * dir, y: leftShoulder.y + elbowDrop * 0.96 };
    leftWrist = { x: leftElbow.x - shoulderOffset * 0.18 * dir, y: leftElbow.y + wristDrop * 0.82 };
    headX += shoulderOffset * 0.18 * dir;
  } else if (action === "gesture_left") {
    leftElbow = { x: leftShoulder.x - shoulderOffset * 0.85 * dir, y: leftShoulder.y + elbowDrop * 0.42 };
    leftWrist = { x: leftElbow.x - shoulderOffset * 0.48 * dir, y: leftElbow.y - wristDrop * 0.08 };
    rightElbow = { x: rightShoulder.x + shoulderOffset * 0.24 * dir, y: rightShoulder.y + elbowDrop * 0.96 };
    rightWrist = { x: rightElbow.x + shoulderOffset * 0.18 * dir, y: rightElbow.y + wristDrop * 0.82 };
    headX -= shoulderOffset * 0.14 * dir;
  } else if (action === "stop") {
    rightElbow = { x: rightShoulder.x + shoulderOffset * 0.7 * dir, y: rightShoulder.y + elbowDrop * 0.5 };
    rightWrist = { x: rightElbow.x + shoulderOffset * 0.3 * dir, y: rightElbow.y + wristDrop * 0.08 };
    leftKnee = { x: leftHip.x + hipOffset * 0.18 * dir, y: leftHip.y + kneeDrop };
    rightKnee = { x: rightHip.x - hipOffset * 0.12 * dir, y: rightHip.y + kneeDrop };
  } else if (action === "stop_left") {
    leftElbow = { x: leftShoulder.x - shoulderOffset * 0.7 * dir, y: leftShoulder.y + elbowDrop * 0.5 };
    leftWrist = { x: leftElbow.x - shoulderOffset * 0.3 * dir, y: leftElbow.y + wristDrop * 0.08 };
    leftKnee = { x: leftHip.x + hipOffset * 0.12 * dir, y: leftHip.y + kneeDrop };
    rightKnee = { x: rightHip.x - hipOffset * 0.18 * dir, y: rightHip.y + kneeDrop };
  } else if (action === "nod") {
    headTiltY += bodyHeight * 0.02;
  } else if (action === "lean") {
    headX += shoulderOffset * 0.5 * dir;
    headTiltY += bodyHeight * 0.02;
    leftShoulder.x += shoulderOffset * 0.3 * dir;
    rightShoulder.x += shoulderOffset * 0.3 * dir;
    pelvis.x += shoulderOffset * 0.18 * dir;
    leftElbow.x += shoulderOffset * 0.25 * dir;
    rightElbow.x += shoulderOffset * 0.25 * dir;
    leftWrist.x += shoulderOffset * 0.25 * dir;
    rightWrist.x += shoulderOffset * 0.25 * dir;
  } else if (action === "reach_down" || action === "reach_down_left") {
    const useLeft = action === "reach_down_left";
    headX += shoulderOffset * 0.54 * dir;
    headTiltY += bodyHeight * 0.032;
    leftShoulder.x += shoulderOffset * 0.26 * dir;
    rightShoulder.x += shoulderOffset * 0.26 * dir;
    pelvis.x += shoulderOffset * 0.16 * dir;
    if (useLeft) {
      leftElbow = { x: leftShoulder.x + shoulderOffset * 0.12 * dir, y: leftShoulder.y + elbowDrop * 1.18 };
      leftWrist = { x: leftElbow.x + shoulderOffset * 0.16 * dir, y: leftElbow.y + wristDrop * 1.08 };
      rightElbow = { x: rightShoulder.x + shoulderOffset * 0.24 * dir, y: rightShoulder.y + elbowDrop * 0.74 };
      rightWrist = { x: rightElbow.x + shoulderOffset * 0.18 * dir, y: rightElbow.y + wristDrop * 0.72 };
    } else {
      rightElbow = { x: rightShoulder.x + shoulderOffset * 0.12 * dir, y: rightShoulder.y + elbowDrop * 1.18 };
      rightWrist = { x: rightElbow.x + shoulderOffset * 0.16 * dir, y: rightElbow.y + wristDrop * 1.08 };
      leftElbow = { x: leftShoulder.x - shoulderOffset * 0.24 * dir, y: leftShoulder.y + elbowDrop * 0.74 };
      leftWrist = { x: leftElbow.x - shoulderOffset * 0.18 * dir, y: leftElbow.y + wristDrop * 0.72 };
    }
    leftKnee = { x: leftHip.x + hipOffset * 0.12 * dir, y: leftHip.y + kneeDrop * 0.98 };
    rightKnee = { x: rightHip.x - hipOffset * 0.06 * dir, y: rightHip.y + kneeDrop * 1.04 };
  } else if (action === "look") {
    headX += shoulderOffset * 0.22 * dir;
  }

  return {
    head: { x: headX, y: headTiltY },
    neck,
    pelvis,
    leftShoulder,
    rightShoulder,
    leftHip,
    rightHip,
    leftElbow,
    rightElbow,
    leftWrist,
    rightWrist,
    leftKnee,
    rightKnee,
    leftAnkle,
    rightAnkle,
    jointRadius,
    limbWidth
  };
}

function buildStoryboardPoseFigure(
  context: CanvasRenderingContext2D,
  centerX: number,
  floorY: number,
  bodyHeight: number,
  action: StoryboardPoseAction,
  mirror = false
) {
  const geometry = computeStoryboardPoseFigureGeometry(centerX, floorY, bodyHeight, action, mirror);
  const {
    head,
    neck,
    pelvis,
    leftShoulder,
    rightShoulder,
    leftHip,
    rightHip,
    leftElbow,
    rightElbow,
    leftWrist,
    rightWrist,
    leftKnee,
    rightKnee,
    leftAnkle,
    rightAnkle,
    jointRadius,
    limbWidth
  } = geometry;
  const torsoTop = { x: neck.x, y: neck.y };
  const torsoBottom = { x: pelvis.x, y: pelvis.y };
  const limbColors = ["#ff4444", "#ffbb33", "#ffee55", "#66cc66", "#33b5e5", "#9966ff"];

  drawStoryboardPoseLimb(context, head, neck, limbColors[0], limbWidth);
  drawStoryboardPoseLimb(context, torsoTop, torsoBottom, limbColors[1], limbWidth);
  drawStoryboardPoseLimb(context, leftShoulder, rightShoulder, limbColors[2], limbWidth);
  drawStoryboardPoseLimb(context, leftHip, rightHip, limbColors[2], limbWidth);
  drawStoryboardPoseLimb(context, leftShoulder, leftElbow, limbColors[3], limbWidth);
  drawStoryboardPoseLimb(context, leftElbow, leftWrist, limbColors[3], limbWidth);
  drawStoryboardPoseLimb(context, rightShoulder, rightElbow, limbColors[4], limbWidth);
  drawStoryboardPoseLimb(context, rightElbow, rightWrist, limbColors[4], limbWidth);
  drawStoryboardPoseLimb(context, leftHip, leftKnee, limbColors[5], limbWidth);
  drawStoryboardPoseLimb(context, leftKnee, leftAnkle, limbColors[5], limbWidth);
  drawStoryboardPoseLimb(context, rightHip, rightKnee, limbColors[0], limbWidth);
  drawStoryboardPoseLimb(context, rightKnee, rightAnkle, limbColors[0], limbWidth);

  for (const [point, color] of [
    [head, limbColors[0]],
    [neck, limbColors[1]],
    [leftShoulder, limbColors[3]],
    [rightShoulder, limbColors[4]],
    [pelvis, limbColors[1]],
    [leftElbow, limbColors[3]],
    [rightElbow, limbColors[4]],
    [leftWrist, limbColors[3]],
    [rightWrist, limbColors[4]],
    [leftHip, limbColors[5]],
    [rightHip, limbColors[0]],
    [leftKnee, limbColors[5]],
    [rightKnee, limbColors[0]],
    [leftAnkle, limbColors[5]],
    [rightAnkle, limbColors[0]]
  ] as const) {
    drawStoryboardPoseJoint(context, point, color, jointRadius);
  }
}

function buildStoryboardPoseGuideCanvas(args: {
  width: number;
  height: number;
  poseFigures: StoryboardPoseGuideFigure[];
}): HTMLCanvasElement | null {
  const { width, height, poseFigures } = args;
  if (width <= 0 || height <= 0 || poseFigures.length <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "black";
  context.fillRect(0, 0, width, height);
  for (const figure of poseFigures) {
    buildStoryboardPoseFigure(
      context,
      figure.centerX,
      figure.floorY,
      figure.bodyHeight,
      figure.action,
      poseFigureUsesMirror(figure)
    );
  }
  return canvas;
}

async function writeSingleFigureStoryboardPoseGuide(args: {
  settings: ComfySettings;
  shot: Shot;
  tokens: Record<string, string>;
  inputDir: string;
}): Promise<{
  poseGuidePath: string;
  poseGuideMode: string;
  actionReferencePath: string;
} | null> {
  const { settings, shot, tokens, inputDir } = args;
  if (!canProcessStoryboardReferenceImages()) return null;
  const renderWidth = Math.max(512, Number.parseInt(String(tokens.RENDER_WIDTH ?? "1280"), 10) || 1280);
  const renderHeight = Math.max(512, Number.parseInt(String(tokens.RENDER_HEIGHT ?? "704"), 10) || 704);
  const plan = await buildStoryboardPoseGuidePlanFromTokens(settings, shot, tokens, renderWidth, renderHeight);
  const figure = plan.poseFigures[0];
  if (!figure) return null;

  const allowLockedPose =
    String(tokens.STORYBOARD_ENABLE_STAGEA_LOCKED_POSE ?? "").trim() === "1";
  if (allowLockedPose) {
    try {
      const lockedPoseGuide = await generateStructuredStoryboardPoseGuideFromLockedReference(
        settings,
        shot,
        tokens,
        [figure],
        inputDir
      );
      if (lockedPoseGuide?.poseGuidePath?.trim()) {
        return lockedPoseGuide;
      }
    } catch {
      // Fall back to the simpler line pose guide when the clean-pose reference chain is unavailable.
    }
  }

  const poseCanvas = buildStoryboardPoseGuideCanvas({
    width: renderWidth,
    height: renderHeight,
    poseFigures: [figure]
  });
  if (!poseCanvas) return null;
  const safeShotId = shot.id.replace(/[^a-zA-Z0-9_-]/g, "_");
  const poseWrite = await writeCanvasToLocalPng(`${inputDir}/shot_${safeShotId}_passA_pose_map.png`, poseCanvas);
  return {
    poseGuidePath: poseWrite.inputName,
    poseGuideMode: "pose_map_explicit_pass_a",
    actionReferencePath: ""
  };
}

function measureStoryboardPoseFigureSetBounds(
  poseFigures: StoryboardPoseGuideFigure[]
): {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  width: number;
  height: number;
} | null {
  if (poseFigures.length <= 0) return null;
  return poseFigures.reduce(
    (acc, figure) => {
      const bounds = measureStableStoryboardPoseFigureBounds(figure);
      if (!acc) return { ...bounds };
      const minX = Math.min(acc.minX, bounds.minX);
      const minY = Math.min(acc.minY, bounds.minY);
      const maxX = Math.max(acc.maxX, bounds.maxX);
      const maxY = Math.max(acc.maxY, bounds.maxY);
      return {
        minX,
        minY,
        maxX,
        maxY,
        width: Math.max(1, maxX - minX),
        height: Math.max(1, maxY - minY)
      };
    },
    null as {
      minX: number;
      minY: number;
      maxX: number;
      maxY: number;
      width: number;
      height: number;
    } | null
  );
}

async function buildStoryboardPosedFigureLayerFromReference(args: {
  characterRefPath: string;
  poseFigure: StoryboardPoseGuideFigure;
}): Promise<{
  canvas: HTMLCanvasElement;
  scale: number;
  anchorCenterX: number;
  anchorFloorY: number;
} | null> {
  const { characterRefPath, poseFigure } = args;
  const cutout = await buildCharacterCutoutCanvas(characterRefPath);
  if (!cutout) return null;

  const measuredBounds = measureStableStoryboardPoseFigureBounds({
    ...poseFigure,
    centerX: poseFigure.bodyHeight,
    floorY: poseFigure.bodyHeight * 1.12
  });
  const localHeight = snapRenderSize(
    Math.max(320, Math.round(Math.max(poseFigure.bodyHeight / 0.92, measuredBounds.height * 1.08)))
  );
  const localWidth = snapRenderSize(Math.max(256, Math.round(measuredBounds.width * 1.12)));
  const canvas = buildStoryboardPosedIdentityCanvas(
    cutout,
    localWidth,
    localHeight,
    poseFigure.action,
    poseFigureUsesMirror(poseFigure)
  );
  if (!canvas) return null;

  return {
    canvas,
    scale: poseFigure.bodyHeight / Math.max(1, localHeight * 0.92),
    anchorCenterX: localWidth / 2,
    anchorFloorY: localHeight * 0.95
  };
}

function drawStoryboardPosedFigureLayer(
  context: CanvasRenderingContext2D,
  figureLayer: {
    canvas: HTMLCanvasElement;
    scale: number;
    anchorCenterX: number;
    anchorFloorY: number;
  },
  poseFigure: StoryboardPoseGuideFigure
) {
  const drawWidth = figureLayer.canvas.width * figureLayer.scale;
  const drawHeight = figureLayer.canvas.height * figureLayer.scale;
  const drawX = poseFigure.centerX - figureLayer.anchorCenterX * figureLayer.scale;
  const drawY = poseFigure.floorY - figureLayer.anchorFloorY * figureLayer.scale;
  context.drawImage(figureLayer.canvas, drawX, drawY, drawWidth, drawHeight);
}

async function buildStructuredStoryboardCleanPoseReferenceCanvas(args: {
  width: number;
  height: number;
  poseFigures: StoryboardPoseGuideFigure[];
  characterRefPaths: string[];
}): Promise<{
  transparentCanvas: HTMLCanvasElement;
  cleanCanvas: HTMLCanvasElement;
} | null> {
  const { width, height, poseFigures, characterRefPaths } = args;
  if (width <= 0 || height <= 0 || poseFigures.length <= 0) return null;

  const transparentCanvas = document.createElement("canvas");
  transparentCanvas.width = width;
  transparentCanvas.height = height;
  const transparentContext = transparentCanvas.getContext("2d");
  if (!transparentContext) return null;
  transparentContext.clearRect(0, 0, width, height);
  transparentContext.imageSmoothingEnabled = true;
  transparentContext.imageSmoothingQuality = "high";
  const figureEntries = poseFigures
    .map((poseFigure, index) => ({
      poseFigure,
      characterRefPath: String(characterRefPaths[index] ?? "").trim()
    }))
    .sort((left, right) => left.poseFigure.floorY - right.poseFigure.floorY);

  for (const entry of figureEntries) {
    let drewReferencePose = false;
    if (entry.characterRefPath) {
      const figureLayer = await buildStoryboardPosedFigureLayerFromReference({
        characterRefPath: entry.characterRefPath,
        poseFigure: entry.poseFigure
      });
      if (figureLayer) {
        const figureCanvas = document.createElement("canvas");
        figureCanvas.width = width;
        figureCanvas.height = height;
        const figureContext = figureCanvas.getContext("2d");
        if (figureContext) {
          figureContext.clearRect(0, 0, width, height);
          figureContext.imageSmoothingEnabled = true;
          figureContext.imageSmoothingQuality = "high";
          drawStoryboardPosedFigureLayer(figureContext, figureLayer, entry.poseFigure);
          const prunedFigureCanvas = pruneStableStoryboardForegroundGhosts(figureCanvas, entry.poseFigure) ?? figureCanvas;
          transparentContext.save();
          transparentContext.globalAlpha = 1;
          transparentContext.drawImage(prunedFigureCanvas, 0, 0);
          transparentContext.restore();
          drewReferencePose = true;
        }
      }
    }

    if (!drewReferencePose) {
      drawStoryboardReadableHumanFigure({
        context: transparentContext,
        poseFigure: entry.poseFigure,
        palette: buildStoryboardPoseHumanPaletteVariant(entry.poseFigure.index),
        mode: "clean_pose"
      });
    }
  }

  const componentAnalysis = analyzeCanvasAlphaComponents(transparentCanvas, 18);
  if (!componentAnalysis || componentAnalysis.components.length <= 0) {
    return null;
  }

  const refinedTransparentCanvas = transparentCanvas;
  const cleanCanvas = document.createElement("canvas");
  cleanCanvas.width = width;
  cleanCanvas.height = height;
  const cleanContext = cleanCanvas.getContext("2d");
  if (!cleanContext) return null;
  cleanContext.fillStyle = "rgb(246, 243, 238)";
  cleanContext.fillRect(0, 0, width, height);
  cleanContext.imageSmoothingEnabled = true;
  cleanContext.imageSmoothingQuality = "high";
  cleanContext.drawImage(refinedTransparentCanvas, 0, 0);
  return {
    transparentCanvas: refinedTransparentCanvas,
    cleanCanvas
  };
}

function buildStoryboardCharacterMaskFigure(
  context: CanvasRenderingContext2D,
  centerX: number,
  floorY: number,
  bodyHeight: number,
  action: StoryboardPoseAction,
  mirror = false,
  fillColor = "white"
) {
  const geometry = computeStoryboardPoseFigureGeometry(centerX, floorY, bodyHeight, action, mirror);
  const {
    head,
    neck,
    pelvis,
    leftShoulder,
    rightShoulder,
    leftHip,
    rightHip,
    leftElbow,
    rightElbow,
    leftWrist,
    rightWrist,
    leftKnee,
    rightKnee,
    leftAnkle,
    rightAnkle
  } = geometry;
  const torsoWidth = Math.max(22, Math.round(bodyHeight * 0.14));
  const limbWidth = Math.max(16, Math.round(bodyHeight * 0.1));
  const jointRadius = Math.max(8, Math.round(bodyHeight * 0.055));
  const headRadius = Math.max(18, Math.round(bodyHeight * 0.095));
  const drawStroke = (from: { x: number; y: number }, to: { x: number; y: number }, width: number) => {
    context.save();
    context.strokeStyle = fillColor;
    context.lineWidth = width;
    context.lineCap = "round";
    context.lineJoin = "round";
    context.beginPath();
    context.moveTo(from.x, from.y);
    context.lineTo(to.x, to.y);
    context.stroke();
    context.restore();
  };
  const drawDot = (point: { x: number; y: number }, radius: number) => {
    context.save();
    context.fillStyle = fillColor;
    context.beginPath();
    context.arc(point.x, point.y, radius, 0, Math.PI * 2);
    context.fill();
    context.restore();
  };
  const drawPolygon = (points: Array<{ x: number; y: number }>) => {
    if (points.length < 3) return;
    context.save();
    context.fillStyle = fillColor;
    context.beginPath();
    context.moveTo(points[0]!.x, points[0]!.y);
    for (let index = 1; index < points.length; index += 1) {
      context.lineTo(points[index]!.x, points[index]!.y);
    }
    context.closePath();
    context.fill();
    context.restore();
  };

  drawPolygon([leftShoulder, rightShoulder, rightHip, leftHip]);
  drawStroke(neck, pelvis, torsoWidth);
  drawStroke(leftShoulder, rightShoulder, torsoWidth * 0.84);
  drawStroke(leftHip, rightHip, torsoWidth * 0.78);
  drawStroke(leftShoulder, leftElbow, limbWidth);
  drawStroke(leftElbow, leftWrist, limbWidth * 0.92);
  drawStroke(rightShoulder, rightElbow, limbWidth);
  drawStroke(rightElbow, rightWrist, limbWidth * 0.92);
  drawStroke(leftHip, leftKnee, limbWidth);
  drawStroke(leftKnee, leftAnkle, limbWidth * 0.96);
  drawStroke(rightHip, rightKnee, limbWidth);
  drawStroke(rightKnee, rightAnkle, limbWidth * 0.96);
  drawDot(head, headRadius);
  drawDot(neck, jointRadius);
  drawDot(pelvis, jointRadius);
  drawDot(leftShoulder, jointRadius);
  drawDot(rightShoulder, jointRadius);
  drawDot(leftElbow, jointRadius * 0.9);
  drawDot(rightElbow, jointRadius * 0.9);
  drawDot(leftWrist, jointRadius * 0.92);
  drawDot(rightWrist, jointRadius * 0.92);
  drawDot(leftHip, jointRadius * 0.92);
  drawDot(rightHip, jointRadius * 0.92);
  drawDot(leftKnee, jointRadius * 0.9);
  drawDot(rightKnee, jointRadius * 0.9);
  drawDot(leftAnkle, jointRadius * 0.94);
  drawDot(rightAnkle, jointRadius * 0.94);
}

function buildStoryboardCharacterEdgeContactMaskFigure(
  context: CanvasRenderingContext2D,
  centerX: number,
  floorY: number,
  bodyHeight: number,
  action: StoryboardPoseAction,
  mirror = false
) {
  const width = context.canvas.width;
  const height = context.canvas.height;
  if (width <= 0 || height <= 0) return;

  const ringCanvas = document.createElement("canvas");
  ringCanvas.width = width;
  ringCanvas.height = height;
  const ringContext = ringCanvas.getContext("2d");
  if (!ringContext) return;

  buildStoryboardCharacterMaskFigure(ringContext, centerX, floorY, bodyHeight * 1.06, action, mirror);
  ringContext.save();
  ringContext.globalCompositeOperation = "destination-out";
  buildStoryboardCharacterMaskFigure(ringContext, centerX, floorY, bodyHeight * 0.9, action, mirror);
  ringContext.restore();

  context.save();
  context.drawImage(ringCanvas, 0, 0);
  context.restore();

  const geometry = computeStoryboardPoseFigureGeometry(centerX, floorY, bodyHeight, action, mirror);
  const footRadiusX = Math.max(18, Math.round(bodyHeight * 0.07));
  const footRadiusY = Math.max(6, Math.round(bodyHeight * 0.02));
  const contactY = Math.min(height - 2, Math.round(Math.max(geometry.leftAnkle.y, geometry.rightAnkle.y) + footRadiusY * 0.35));
  const drawContact = (x: number, rotation: number) => {
    context.save();
    context.fillStyle = "white";
    context.translate(x, contactY);
    context.rotate(rotation);
    context.beginPath();
    context.ellipse(0, 0, footRadiusX, footRadiusY, 0, 0, Math.PI * 2);
    context.fill();
    context.restore();
  };

  drawContact(geometry.leftAnkle.x, -0.1);
  drawContact(geometry.rightAnkle.x, 0.1);

  const contactSpan = Math.abs(geometry.rightAnkle.x - geometry.leftAnkle.x);
  if (contactSpan > footRadiusX * 0.9) {
    context.save();
    context.fillStyle = "white";
    context.beginPath();
    context.roundRect(
      Math.min(geometry.leftAnkle.x, geometry.rightAnkle.x) + footRadiusX * 0.15,
      contactY - footRadiusY * 0.6,
      Math.max(footRadiusX * 0.8, contactSpan - footRadiusX * 0.3),
      footRadiusY * 1.2,
      footRadiusY
    );
    context.fill();
    context.restore();
  }
}

type StoryboardPoseGuideFigure = {
  name: string;
  index: number;
  centerX: number;
  floorY: number;
  bodyHeight: number;
  action: StoryboardPoseAction;
  mirror?: boolean;
};

function poseFigureUsesMirror(figure: StoryboardPoseGuideFigure): boolean {
  return figure.mirror ?? figure.index % 2 === 1;
}

function shouldMirrorStoryboardPoseFigure(
  shot: Shot,
  action: StoryboardPoseAction,
  index: number,
  characterCount: number
): boolean {
  if (index <= 0) return false;
  const corpus = compactTextParts(shot.title, shot.storyPrompt, shot.notes, shot.dialogue).toLowerCase();
  const sharedWalkDirection =
    characterCount >= 2 &&
    action === "walk" &&
    containsAnyKeyword(corpus, ["并肩", "沿河", "慢走", "side by side", "walking together", "walk together", "along the same path", "along the path"]);
  if (sharedWalkDirection) return false;
  return index % 2 === 1;
}

function describeStoryboardPoseActionForReference(action: StoryboardPoseAction): string {
  if (action === "walk") return "walking mid-step with natural body balance";
  if (action === "gesture") return "speaking with one hand raised in a natural gesture";
  if (action === "gesture_left") return "speaking with the left hand raised in a natural gesture";
  if (action === "stop") return "stopping mid-movement with a controlled posture";
  if (action === "stop_left") return "stopping mid-movement with the left hand active";
  if (action === "nod") return "standing and nodding subtly";
  if (action === "lean") return "leaning forward naturally";
  if (action === "reach_down") return "reaching one hand downward";
  if (action === "reach_down_left") return "reaching the left hand downward";
  if (action === "look") return "standing and looking toward the other subject";
  return "standing naturally";
}

function buildStoryboardPoseReferencePrompt(
  shot: Shot,
  poseFigures: StoryboardPoseGuideFigure[],
  attempt = 0
): string {
  const characterCount = poseFigures.length;
  const corpus = compactTextParts(shot.title, shot.storyPrompt, shot.notes, shot.dialogue).toLowerCase();
  const allWalkLike = poseFigures.every((figure) => figure.action === "walk");
  const pairedWalkLike =
    characterCount === 2 &&
    allWalkLike &&
    containsAnyKeyword(corpus, ["并肩", "沿河", "慢走", "side by side", "walking together", "walk together", "along the path"]);
  const subjectLine =
    characterCount <= 1
      ? "exactly one anonymous adult pose-reference model, full body, whole figure visible from head to feet, absolutely no second person, no background person, no mirrored partner"
      : `exactly ${characterCount} anonymous adult pose-reference models in one shared frame, full body, all figures visible from head to feet`;
  const sharedCameraLine =
    characterCount <= 1
      ? "single continuous studio reference photo, one subject only, no duplicated body, no comparison layout, no body clone, no second figure"
      : "single continuous studio reference photo, everyone captured together in the same camera view, not split-screen, not a comparison board, not a turnaround sheet";
  const figureActionLines = poseFigures.map((figure) => {
    const lane =
      characterCount <= 1 ? "center subject" : figure.centerX <= poseFigures.reduce((sum, item) => sum + item.centerX, 0) / poseFigures.length ? "left subject" : "right subject";
    return `${lane}: ${describeStoryboardPoseActionForReference(figure.action)}`;
  });
  const interactionHint =
    pairedWalkLike
      ? "two adults walking side by side in the same direction, relaxed natural gait, gentle opposite arm swing, one foot stepping forward for each subject, readable gap between bodies, both figures grounded, no overlap hiding limbs, no mirrored duplicate"
      : characterCount >= 2
      ? "shared interaction, one pose image containing everyone together, both bodies fully inside frame with margin above heads and below feet, visible gap between torsos and legs, no severe overlap hiding joints, each body separate and readable, no body cloning, no body stacking"
      : "clean solo pose reference, simple staging, readable silhouette, full body inside frame with margin, stable ground contact, normal human proportions";
  const soloIsolationHint =
    characterCount <= 1
      ? attempt <= 0
        ? "the whole frame contains one human only, one body only, one head only, with empty background around the subject; absolutely no second person, no distant passerby, no reflected partner, no shadow body, no duplicate silhouette"
        : "retry with stricter isolation: keep exactly one isolated person in the entire frame and leave every other area empty; if a second body, second head, partner, passerby, reflection, or shadow person would appear, remove it completely instead of drawing it"
      : "";
  return compactTextParts(
    pairedWalkLike
      ? "full-body neutral studio motion-study photo, anonymous practice models, casual walking reference"
      : "full-body neutral studio motion-study photo, anonymous practice model, simple action reference",
    subjectLine,
    sharedCameraLine,
    interactionHint,
    soloIsolationHint,
    figureActionLines.join(", "),
    "wearing plain fitted neutral rehearsal clothing, simple light gray or beige training outfit, not a character costume, not fashion styling, not underwear, not armor, not robe, not accessories",
    "bright even front lighting, clean seamless light-gray studio cyclorama background, soft floor contact only, almost no cast shadow, no backdrop shadow, no head shadow, no props, no scenery, no text, no logo, no extra objects",
    "natural anatomy, realistic human body, readable limbs, readable hands, readable feet, clear elbows, clear knees, full head and full feet visible, subjects large enough for readable full-body pose, no mannequin look, no silhouette look, no collage look, no split panel, no triptych, no front-side comparison, no duplicate person"
  );
}

