async function analyzeSoloStoryboardPoseReferenceCandidate(pathOrUrl: string): Promise<{
  acceptable: boolean;
  issues: string[];
}> {
  const quality = await analyzeCharacterReferenceQuality(pathOrUrl);
  const issues: string[] = [];
  if (quality.fragmented) {
    issues.push(`fragmented_subjects=${quality.componentCount}`);
  }
  if (quality.componentCount > 2) {
    issues.push(`multi_components=${quality.componentCount}`);
  }
  if (quality.edgeTouch) {
    issues.push("subject_touching_edge");
  }
  return {
    acceptable: issues.length === 0,
    issues
  };
}

