function adaptBuiltinStoryboardWorkflowForShot(
  workflow: Record<string, unknown>,
  tokens: Record<string, string>,
  objectInfo?: Record<string, unknown>
): void {
  if (adaptStableStoryboardWorkflowForShot(workflow, tokens, objectInfo)) {
    return;
  }
  const sceneRefPath = String(tokens.SCENE_REF_PATH ?? "").trim();
  const frameImagePath = String(tokens.FRAME_IMAGE_PATH ?? "").trim();
  const frameSeedMode = String(tokens.STORYBOARD_FRAME_SEED_MODE ?? "").trim().toLowerCase();
  const poseGuidePath = String(tokens.POSE_GUIDE_PATH ?? "").trim();
  const char1PrimaryPath = String(tokens.CHAR1_PRIMARY_PATH ?? "").trim();
  const char1SecondaryPath = String(tokens.CHAR1_SECONDARY_PATH ?? "").trim();
  const char2PrimaryPath = String(tokens.CHAR2_PRIMARY_PATH ?? "").trim();
  const char2SecondaryPath = String(tokens.CHAR2_SECONDARY_PATH ?? "").trim();
  const storyboardModel = String(tokens.STORYBOARD_IMAGE_MODEL ?? "").trim() || "realisticVisionV60B1_v51VAE.safetensors";
  const hasCharacters = char1PrimaryPath.length > 0 || char2PrimaryPath.length > 0;
  const hasSceneRef = sceneRefPath.length > 0;
  const usePoseGuide = poseGuidePath.length > 0;
  if (!hasCharacters || !hasSceneRef) return;

  const checkpointNode = workflow["1"];
  const samplerNode = workflow["13"];
  const sceneAdapterNode = workflow["17"];
  const char1AdapterNode = workflow["8"];
  const char1SecondaryAdapterNode = workflow["10"];
  const char2AdapterNode = workflow["12"];
  const controlNetLoaderNode = workflow["19"];
  const controlNetNode = workflow["20"];
  if (
    !samplerNode ||
    !sceneAdapterNode ||
    typeof samplerNode !== "object" ||
    typeof sceneAdapterNode !== "object"
  ) {
    return;
  }

  const samplerClass = String((samplerNode as Record<string, unknown>).class_type ?? "").trim();
  const sceneAdapterClass = String((sceneAdapterNode as Record<string, unknown>).class_type ?? "").trim();
  if (samplerClass !== "KSampler" || sceneAdapterClass !== "IPAdapterAdvanced") return;

  const controlNetChoice = resolveStoryboardControlNetChoice(storyboardModel, usePoseGuide, objectInfo);
  if (controlNetChoice.qualityError) {
    throw new Error(controlNetChoice.qualityError);
  }
  const effectiveStoryboardModel = controlNetChoice.checkpointOverride ?? storyboardModel;

  if (checkpointNode && typeof checkpointNode === "object") {
    const checkpointInputs = (checkpointNode as Record<string, unknown>).inputs;
    if (checkpointInputs && typeof checkpointInputs === "object" && !Array.isArray(checkpointInputs)) {
      (checkpointInputs as Record<string, unknown>).ckpt_name = effectiveStoryboardModel;
    }
  }

  const renderWidth = Math.max(64, Number.parseInt(String(tokens.RENDER_WIDTH ?? "1024"), 10) || 1024);
  const renderHeight = Math.max(64, Number.parseInt(String(tokens.RENDER_HEIGHT ?? "576"), 10) || 576);
  const hasSecondCharacter = char2PrimaryPath.length > 0;
  const lockCharacterIdentityAndCount = usePoseGuide && hasSecondCharacter;
  const useCompositeFrameSeed = lockCharacterIdentityAndCount && frameSeedMode === "composite" && frameImagePath.length > 0;
  const useSceneFrameSeed = frameImagePath.length > 0 && !useCompositeFrameSeed;
  const hasFrameSeed = frameImagePath.length > 0;
  const shotScale = inferStoryboardCompositeScaleFromCorpus(
    compactTextParts(tokens.SHOT_TITLE, tokens.STORY_PROMPT, tokens.NOTES, tokens.DIALOGUE).toLowerCase()
  );
  const samplerInputs =
    typeof (samplerNode as Record<string, unknown>).inputs === "object" &&
    (samplerNode as Record<string, unknown>).inputs &&
    !Array.isArray((samplerNode as Record<string, unknown>).inputs)
      ? ((samplerNode as Record<string, unknown>).inputs as Record<string, unknown>)
      : null;
  const sceneAdapterInputs =
    typeof (sceneAdapterNode as Record<string, unknown>).inputs === "object" &&
    (sceneAdapterNode as Record<string, unknown>).inputs &&
    !Array.isArray((sceneAdapterNode as Record<string, unknown>).inputs)
      ? ((sceneAdapterNode as Record<string, unknown>).inputs as Record<string, unknown>)
      : null;
  const char1AdapterInputs =
    typeof (char1AdapterNode as Record<string, unknown>)?.inputs === "object" &&
    (char1AdapterNode as Record<string, unknown>).inputs &&
    !Array.isArray((char1AdapterNode as Record<string, unknown>).inputs)
      ? ((char1AdapterNode as Record<string, unknown>).inputs as Record<string, unknown>)
      : null;
  const char1SecondaryAdapterInputs =
    typeof (char1SecondaryAdapterNode as Record<string, unknown>)?.inputs === "object" &&
    (char1SecondaryAdapterNode as Record<string, unknown>).inputs &&
    !Array.isArray((char1SecondaryAdapterNode as Record<string, unknown>).inputs)
      ? ((char1SecondaryAdapterNode as Record<string, unknown>).inputs as Record<string, unknown>)
      : null;
  const controlNetLoaderInputs =
    typeof (controlNetLoaderNode as Record<string, unknown>)?.inputs === "object" &&
    (controlNetLoaderNode as Record<string, unknown>).inputs &&
    !Array.isArray((controlNetLoaderNode as Record<string, unknown>).inputs)
      ? ((controlNetLoaderNode as Record<string, unknown>).inputs as Record<string, unknown>)
      : null;
  const controlNetInputs =
    typeof (controlNetNode as Record<string, unknown>)?.inputs === "object" &&
    (controlNetNode as Record<string, unknown>).inputs &&
    !Array.isArray((controlNetNode as Record<string, unknown>).inputs)
      ? ((controlNetNode as Record<string, unknown>).inputs as Record<string, unknown>)
      : null;
  const workflowRef = (nodeId: string | number, outputIndex = 0) => [String(nodeId), outputIndex];

  const updateAdapterWeight = (
    node: unknown,
    fallbackWeight: number,
    mode: "at_least" | "cap_at_most" = "at_least",
    fallbackEndAt?: number
  ) => {
    if (!node || typeof node !== "object") return;
    const inputs = (node as Record<string, unknown>).inputs;
    if (!inputs || typeof inputs !== "object") return;
    const currentWeight = Number((inputs as Record<string, unknown>).weight);
    const safeFallback = Number.isFinite(fallbackWeight) ? fallbackWeight : 0;
    const resolvedWeight =
      mode === "cap_at_most"
        ? (Number.isFinite(currentWeight) ? Math.min(currentWeight, safeFallback) : safeFallback)
        : (Number.isFinite(currentWeight) ? Math.max(currentWeight, safeFallback) : safeFallback);
    (inputs as Record<string, unknown>).weight = resolvedWeight;
    const resolvedEndAt =
      typeof fallbackEndAt === "number" && Number.isFinite(fallbackEndAt)
        ? fallbackEndAt
        : resolvedWeight >= 0.78
          ? 1.0
          : resolvedWeight >= 0.62
            ? 0.9
            : 0.72;
    (inputs as Record<string, unknown>).end_at = resolvedEndAt;
  };
  const clampAdapterWeight = (
    node: unknown,
    minWeight: number,
    maxWeight: number,
    fallbackEndAt?: number
  ) => {
    if (!node || typeof node !== "object") return;
    const inputs = (node as Record<string, unknown>).inputs;
    if (!inputs || typeof inputs !== "object" || Array.isArray(inputs)) return;
    const currentWeight = Number((inputs as Record<string, unknown>).weight);
    const safeMin = Number.isFinite(minWeight) ? minWeight : 0;
    const safeMax = Number.isFinite(maxWeight) ? Math.max(safeMin, maxWeight) : safeMin;
    const resolvedWeight = Number.isFinite(currentWeight)
      ? Math.min(safeMax, Math.max(safeMin, currentWeight))
      : safeMin;
    (inputs as Record<string, unknown>).weight = resolvedWeight;
    (inputs as Record<string, unknown>).end_at =
      typeof fallbackEndAt === "number" && Number.isFinite(fallbackEndAt)
        ? fallbackEndAt
        : resolvedWeight >= 0.92
          ? 0.92
          : resolvedWeight >= 0.78
            ? 0.84
            : 0.72;
  };
  const disableAdapter = (node: unknown) => {
    if (!node || typeof node !== "object") return;
    const inputs = (node as Record<string, unknown>).inputs;
    if (!inputs || typeof inputs !== "object" || Array.isArray(inputs)) return;
    (inputs as Record<string, unknown>).weight = 0;
    (inputs as Record<string, unknown>).start_at = 0;
    (inputs as Record<string, unknown>).end_at = 0;
  };

  // Dual-character storyboard shots are more reliable when they start from a
  // clean scene/continuity frame and let pose + identity controls redraw the
  // people. Seeding from a precomposed fake-person frame locks in broken
  // anatomy and sticker artifacts.
  if (hasFrameSeed) {
    workflow["21"] = {
      inputs: {
        image: frameImagePath,
        upload: "image"
      },
      class_type: "LoadImage"
    };
  } else if (workflow["21"]) {
    delete workflow["21"];
  }
  workflow["16"] = {
    inputs: {
      image: hasFrameSeed ? ["21", 0] : ["2", 0],
      upscale_method: "lanczos",
      width: renderWidth,
      height: renderHeight,
      crop: hasFrameSeed ? "disabled" : "center"
    },
    class_type: "ImageScale"
  };
  workflow["3"] = {
    inputs: {
      pixels: ["16", 0],
      vae: ["1", 2]
    },
    class_type: "VAEEncode"
  };
  if (usePoseGuide) {
    workflow["18"] = {
      inputs: {
        image: poseGuidePath,
        upload: "image"
      },
      class_type: "LoadImage"
    };
  } else if (workflow["18"] && typeof workflow["18"] === "object") {
    const cannyInputs = (workflow["18"] as Record<string, unknown>).inputs;
    if (cannyInputs && typeof cannyInputs === "object" && !Array.isArray(cannyInputs)) {
      (cannyInputs as Record<string, unknown>).image = hasFrameSeed ? ["16", 0] : ["2", 0];
      (cannyInputs as Record<string, unknown>).low_threshold = hasFrameSeed ? 0.06 : 0.1;
      (cannyInputs as Record<string, unknown>).high_threshold = hasFrameSeed ? 0.22 : 0.4;
    }
  }
  if (controlNetLoaderInputs) {
    controlNetLoaderInputs.control_net_name = controlNetChoice.controlNetName ?? (usePoseGuide
      ? "control_v11p_sd15_openpose.pth"
      : "control_v11p_sd15_canny.pth");
  }

  const hasViewSpecificChar1 = char1SecondaryPath.length > 0 && char1SecondaryPath !== char1PrimaryPath;
  const hasViewSpecificChar2 = char2SecondaryPath.length > 0 && char2SecondaryPath !== char2PrimaryPath;
  const enableSecondaryIdentityViews = usePoseGuide ? !lockCharacterIdentityAndCount : true;
  const enableChar2ViewAdapter = enableSecondaryIdentityViews && usePoseGuide && hasSecondCharacter && hasViewSpecificChar2;
  if (enableChar2ViewAdapter) {
    workflow["22"] = {
      inputs: {
        image: char2SecondaryPath,
        upload: "image"
      },
      class_type: "LoadImage"
    };
  } else if (workflow["22"]) {
    delete workflow["22"];
  }
  if (char1AdapterInputs) {
    char1AdapterInputs.model = workflowRef(enableChar2ViewAdapter ? "17" : "6");
  }
  if (sceneAdapterInputs) {
    if (enableChar2ViewAdapter) {
      sceneAdapterInputs.model = workflowRef("6");
      sceneAdapterInputs.ipadapter = workflowRef("6", 1);
      sceneAdapterInputs.image = workflowRef("22");
      sceneAdapterInputs.weight = shotScale === "close" ? 0.24 : shotScale === "medium" ? 0.22 : 0.18;
      sceneAdapterInputs.weight_type = "linear";
      sceneAdapterInputs.combine_embeds = "concat";
      sceneAdapterInputs.start_at = 0;
      sceneAdapterInputs.end_at = 0.58;
      sceneAdapterInputs.embeds_scaling = "V only";
    } else {
      // Fully bypass the legacy scene IPAdapter. Weight=0 alone is not enough because
      // the node still encodes the wide scene image, reintroducing crop bias and hidden drift.
      disableAdapter(sceneAdapterNode);
    }
  }

  const denoiseTarget =
    lockCharacterIdentityAndCount
      ? shotScale === "close"
        ? useCompositeFrameSeed
          ? 0.44
          : useSceneFrameSeed
            ? 0.64
            : 0.42
        : shotScale === "medium"
          ? useCompositeFrameSeed
            ? 0.42
            : useSceneFrameSeed
              ? 0.6
              : 0.4
          : useCompositeFrameSeed
            ? 0.4
            : useSceneFrameSeed
              ? 0.56
              : 0.38
      : usePoseGuide
      ? shotScale === "close"
        ? hasSecondCharacter
          ? 0.6
          : 0.58
        : shotScale === "medium"
          ? hasSecondCharacter
            ? 0.56
            : 0.54
          : hasSecondCharacter
            ? 0.52
            : 0.5
      : hasFrameSeed
      ? shotScale === "close"
        ? hasSecondCharacter
          ? 0.44
          : 0.46
        : shotScale === "medium"
          ? hasSecondCharacter
            ? 0.42
            : 0.44
          : hasSecondCharacter
            ? 0.38
            : 0.4
      : shotScale === "close"
        ? hasSecondCharacter
          ? 0.72
          : 0.7
        : shotScale === "medium"
          ? hasSecondCharacter
            ? 0.7
            : 0.66
        : hasSecondCharacter
          ? 0.66
          : 0.62;
  if (usePoseGuide) {
    if (lockCharacterIdentityAndCount) {
      if (useSceneFrameSeed) {
        clampAdapterWeight(char1AdapterNode, 1.0, 1.08, 0.88);
        clampAdapterWeight(char2AdapterNode, 0.98, 1.06, 0.88);
      } else {
        clampAdapterWeight(char1AdapterNode, 0.94, 1.02, 0.76);
        clampAdapterWeight(char2AdapterNode, 0.92, 1.0, 0.76);
      }
    } else {
      clampAdapterWeight(char1AdapterNode, hasSecondCharacter ? 0.98 : 1.0, hasSecondCharacter ? 1.06 : 1.1, 0.92);
      clampAdapterWeight(char2AdapterNode, hasSecondCharacter ? 0.96 : 0, hasSecondCharacter ? 1.04 : 0, hasSecondCharacter ? 0.92 : 0);
    }
  } else {
    updateAdapterWeight(char1AdapterNode, hasSecondCharacter ? 1.02 : 0.98, "at_least", 0.9);
    updateAdapterWeight(char2AdapterNode, hasSecondCharacter ? 0.98 : 0, "at_least", hasSecondCharacter ? 0.88 : 0.72);
  }
  if (char1SecondaryAdapterInputs) {
    if (usePoseGuide) {
      if (lockCharacterIdentityAndCount) {
        char1SecondaryAdapterInputs.weight = 0;
        char1SecondaryAdapterInputs.start_at = 0;
        char1SecondaryAdapterInputs.end_at = 0;
      } else if (hasViewSpecificChar1) {
        char1SecondaryAdapterInputs.weight = hasSecondCharacter ? 0.18 : 0.3;
        char1SecondaryAdapterInputs.start_at = 0;
        char1SecondaryAdapterInputs.end_at = hasSecondCharacter ? 0.56 : 0.68;
      } else {
        char1SecondaryAdapterInputs.weight = 0;
        char1SecondaryAdapterInputs.start_at = 0;
        char1SecondaryAdapterInputs.end_at = 0;
      }
    } else if (hasSecondCharacter) {
      char1SecondaryAdapterInputs.weight = 0;
      char1SecondaryAdapterInputs.start_at = 0;
      char1SecondaryAdapterInputs.end_at = 0;
    } else {
      updateAdapterWeight(char1SecondaryAdapterNode, 0.28, "at_least", 0.56);
    }
  }

  if (controlNetInputs) {
    const targetStrength =
      lockCharacterIdentityAndCount
        ? useSceneFrameSeed
          ? (shotScale === "close" ? 0.92 : shotScale === "medium" ? 0.88 : 0.84)
          : (shotScale === "close" ? 0.84 : shotScale === "medium" ? 0.8 : 0.76)
        : usePoseGuide
        ? (shotScale === "close" ? 0.8 : shotScale === "medium" ? 0.76 : hasSecondCharacter ? 0.72 : 0.7)
        : hasFrameSeed
        ? (shotScale === "close" ? 0.56 : shotScale === "medium" ? 0.52 : hasSecondCharacter ? 0.5 : 0.46)
        : (shotScale === "close" ? 0.16 : shotScale === "medium" ? 0.2 : 0.24);
    controlNetInputs.strength = targetStrength;
    controlNetInputs.image = ["18", 0];
    controlNetInputs.start_percent = 0;
    controlNetInputs.end_percent = lockCharacterIdentityAndCount
      ? useSceneFrameSeed
        ? (shotScale === "close" ? 0.98 : shotScale === "medium" ? 0.95 : 0.92)
        : (shotScale === "close" ? 0.94 : shotScale === "medium" ? 0.9 : 0.86)
      : usePoseGuide
      ? (shotScale === "close" ? 0.94 : shotScale === "medium" ? 0.9 : 0.86)
      : hasFrameSeed
        ? (shotScale === "close" ? 0.84 : shotScale === "medium" ? 0.8 : 0.76)
        : (shotScale === "close" ? 0.42 : 0.5);
  }
  if (samplerInputs) {
    const current = Number(samplerInputs.denoise);
    if (lockCharacterIdentityAndCount) {
      samplerInputs.denoise = denoiseTarget;
      samplerInputs.steps = Math.max(34, Math.min(36, Number(samplerInputs.steps) || 34));
      samplerInputs.cfg =
        shotScale === "close"
          ? 5.8
          : shotScale === "medium"
            ? 5.6
            : 5.4;
    } else {
      samplerInputs.denoise =
        Number.isFinite(current) && current > 0
          ? (usePoseGuide ? Math.max(current, denoiseTarget) : hasFrameSeed ? Math.min(current, denoiseTarget) : Math.max(current, denoiseTarget))
          : denoiseTarget;
      samplerInputs.steps = Math.max(usePoseGuide ? (hasSecondCharacter ? 34 : 32) : (hasSecondCharacter ? 32 : 30), Number(samplerInputs.steps) || 0);
      const currentCfg = Number(samplerInputs.cfg);
      samplerInputs.cfg =
        Number.isFinite(currentCfg) && currentCfg > 0
          ? (usePoseGuide
              ? Math.max(currentCfg, hasSecondCharacter ? 6.0 : 5.8)
              : hasFrameSeed
                ? Math.min(currentCfg, hasSecondCharacter ? 6.2 : 5.9)
                : Math.max(hasSecondCharacter ? 6.8 : 6.2, currentCfg))
          : (usePoseGuide
              ? (hasSecondCharacter ? 6.0 : 5.8)
              : hasFrameSeed
                ? (hasSecondCharacter ? 6.2 : 5.9)
                : (hasSecondCharacter ? 6.8 : 6.2));
    }
  }
}

function getPromptStatus(raw: unknown): ComfyPromptStatus | null {
  if (!raw || typeof raw !== "object") return null;
  const status = (raw as Record<string, unknown>).status;
  if (!status || typeof status !== "object" || Array.isArray(status)) return null;
  return status as ComfyPromptStatus;
}

function extractPromptError(raw: unknown): string | null {
  const status = getPromptStatus(raw);
  if (!status) return null;
  const messages = Array.isArray(status.messages) ? status.messages : [];
  for (const item of messages) {
    if (!item || typeof item !== "object") continue;
    const type = String((item as Record<string, unknown>).type ?? "");
    const message = (item as Record<string, unknown>).message;
    if (type !== "execution_error") continue;
    if (Array.isArray(message)) {
      const compact = message
        .map((entry) => {
          if (!entry || typeof entry !== "object") return "";
          const value = (entry as Record<string, unknown>).exception_message;
          return typeof value === "string" ? value : "";
        })
        .filter((entry) => entry.length > 0)
        .join(" | ");
      if (compact) return compact;
    }
    if (typeof message === "string" && message.trim().length > 0) {
      return message.trim();
    }
  }
  return null;
}

function summarizePromptHistory(raw: unknown): string {
  if (!raw || typeof raw !== "object") return "history=empty";
  const record = raw as Record<string, unknown>;
  const outputs = record.outputs;
  const outputKeys =
    outputs && typeof outputs === "object" && !Array.isArray(outputs)
      ? Object.keys(outputs as Record<string, unknown>)
      : [];
  const status = getPromptStatus(raw);
  const statusStr = status ? String(status.status_str ?? "").trim() || "unknown" : "missing";
  const completed = status?.completed === true ? "true" : "false";
  const messages = Array.isArray(status?.messages) ? status?.messages : [];
  const compactMessages = messages
    .slice(-3)
    .map((item) => {
      if (!item || typeof item !== "object") return "";
      const entry = item as Record<string, unknown>;
      const type = String(entry.type ?? "").trim();
      const message = entry.message;
      if (typeof message === "string") return `${type}:${message}`.trim();
      if (Array.isArray(message)) {
        const brief = message
          .map((part) => {
            if (!part || typeof part !== "object") return "";
            const partRecord = part as Record<string, unknown>;
            return String(partRecord.exception_message ?? partRecord.message ?? "").trim();
          })
          .filter((text) => text.length > 0)
          .join(" | ");
        return brief ? `${type}:${brief}`.trim() : type;
      }
      return type;
    })
    .filter((text) => text.length > 0)
    .join(" || ");
  return [
    `status=${statusStr}`,
    `completed=${completed}`,
    `outputKeys=${outputKeys.join(",") || "none"}`,
    `messages=${compactMessages || "none"}`
  ].join("; ");
}

function isPromptCompleted(raw: unknown): boolean {
  const status = getPromptStatus(raw);
  if (!status) return false;
  if (status.completed === true) return true;
  const statusStr = String(status.status_str ?? "").trim().toLowerCase();
  return statusStr === "success" || statusStr === "failed" || statusStr === "error";
}

async function waitForComfyOutput(
  baseUrl: string,
  promptId: string,
  onProgress?: (progress: number, message: string) => void,
  options?: {
    requirePersistentImageOutput?: boolean;
    maxAttempts?: number;
    signal?: AbortSignal;
    terminalOutputNode?: string;
  }
): Promise<ComfyOutputAsset[]> {
  const notify = (progress: number, message: string) => {
    if (!onProgress) return;
    onProgress(Math.max(0, Math.min(1, progress)), message);
  };
  notify(0.02, "已提交到 ComfyUI 队列");
  let fallbackProgress = 0.02;
  const unsubscribe = subscribePromptProgress(promptId, (snapshot) => {
    notify(snapshot.progress, snapshot.message);
  });
  const maxAttempts = Math.max(120, Math.min(3600, Math.floor(options?.maxAttempts ?? 900)));
  try {
    for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
      options?.signal?.throwIfAborted();
      let history: Record<string, unknown> | null = null;
      try {
        history = await createComfyClient(baseUrl).getHistory(promptId);
      } catch {
        options?.signal?.throwIfAborted();
        await new Promise((resolve) => window.setTimeout(resolve, 1000));
        continue;
      }
      const promptHistory = history[promptId];
      const promptError = extractPromptError(promptHistory);
      if (promptError) {
        throw new Error(`ComfyUI 执行失败：${promptError}`);
      }
      const assets = collectOutputAssets(promptHistory, options?.terminalOutputNode);
      const persistentImageOutputs =
        options?.requirePersistentImageOutput
          ? filterOutputAssetsByKind(assets, "image").filter(
              (asset) => String(asset.type ?? "").trim().toLowerCase() === "output"
            )
          : [];
      if (
        assets.length > 0 &&
        (!options?.requirePersistentImageOutput || persistentImageOutputs.length > 0)
      ) {
        notify(1, "输出已生成");
        return options?.requirePersistentImageOutput ? persistentImageOutputs : assets;
      }
      if (promptHistory && isPromptCompleted(promptHistory)) {
        if (options?.requirePersistentImageOutput && assets.length > 0 && persistentImageOutputs.length === 0) {
          throw new Error(
            `ComfyUI 任务已完成，但只检测到 Preview/临时图片，没有检测到 SaveImage 正式输出文件。${summarizePromptHistory(promptHistory)}`
          );
        }
        throw new Error(`ComfyUI 任务已完成但未检测到输出文件，请检查工作流输出节点。${summarizePromptHistory(promptHistory)}`);
      }
      const status = getPromptStatus(promptHistory);
      const statusText = String(status?.status_str ?? "").trim().toLowerCase();
      const waitingForOutput =
        statusText === "success" ||
        statusText === "executing" ||
        statusText === "running" ||
        statusText === "processing";
      if (fallbackProgress < 0.92) {
        fallbackProgress = Math.min(0.92, fallbackProgress + 0.0022);
      } else {
        fallbackProgress = Math.min(0.985, fallbackProgress + 0.00035);
      }
      notify(
        fallbackProgress,
        waitingForOutput && fallbackProgress >= 0.92 ? "后处理中，等待输出文件写入" : "等待 ComfyUI 执行中"
      );
      await new Promise((resolve) => window.setTimeout(resolve, 1000));
      options?.signal?.throwIfAborted();
    }
    throw new Error(`ComfyUI 任务超时（等待超过 ${Math.round(maxAttempts / 60)} 分钟），未获取到输出`);
  } finally {
    unsubscribe();
  }
}

function toComfyViewUrl(baseUrl: string, asset: ComfyOutputAsset): string {
  const params = new URLSearchParams();
  params.set("filename", asset.filename);
  params.set("subfolder", asset.subfolder ?? "");
  params.set("type", asset.type ?? "output");
  return `${normalizeBaseUrl(baseUrl)}/view?${params.toString()}`;
}

function toLocalOutputPath(outputDir: string, asset: ComfyOutputAsset): string {
  const root = outputDir.trim().replace(/\/+$/, "");
  if (!root) return "";
  const sub = asset.subfolder?.trim().replace(/^\/+|\/+$/g, "");
  return sub ? `${root}/${sub}/${asset.filename}` : `${root}/${asset.filename}`;
}

const VIDEO_FILE_EXTENSIONS = new Set([
  "mp4",
  "mov",
  "m4v",
  "webm",
  "mkv",
  "avi",
  "gif"
]);

const AUDIO_FILE_EXTENSIONS = new Set([
  "wav",
  "mp3",
  "aac",
  "flac",
  "ogg",
  "m4a",
  "opus"
]);

function filenameExtension(filename: string): string {
  const clean = filename.trim().toLowerCase();
  const dotIndex = clean.lastIndexOf(".");
  if (dotIndex <= 0 || dotIndex >= clean.length - 1) return "";
  return clean.slice(dotIndex + 1);
}

function isVideoOutputAsset(asset: ComfyOutputAsset): boolean {
  if (asset.mediaKind === "video") return true;
  return VIDEO_FILE_EXTENSIONS.has(filenameExtension(asset.filename));
}

function isAudioOutputAsset(asset: ComfyOutputAsset): boolean {
  if (asset.mediaKind === "audio") return true;
  return AUDIO_FILE_EXTENSIONS.has(filenameExtension(asset.filename));
}

function scoreVideoOutputAsset(asset: ComfyOutputAsset): number {
  let score = 0;
  if ((asset.type ?? "").trim().toLowerCase() === "output") score += 10;
  const ext = filenameExtension(asset.filename);
  if (ext === "mp4" || ext === "mov" || ext === "webm") score += 5;
  if ((asset.subfolder ?? "").trim().length > 0) score += 1;
  return score;
}

function scoreAudioOutputAsset(asset: ComfyOutputAsset): number {
  let score = 0;
  if ((asset.type ?? "").trim().toLowerCase() === "output") score += 10;
  const ext = filenameExtension(asset.filename);
  if (ext === "wav" || ext === "flac") score += 5;
  if (ext === "mp3" || ext === "m4a" || ext === "ogg") score += 4;
  if ((asset.subfolder ?? "").trim().length > 0) score += 1;
  return score;
}

function selectOutputAsset(
  outputs: ComfyOutputAsset[],
  kind: "image" | "video" | "audio",
  shot?: Shot,
  assetOutputContext: AssetOutputContext | null = null
): ComfyOutputAsset | null {
  if (outputs.length === 0) return null;
  if (kind === "video") {
    const videos = outputs.filter((asset) => isVideoOutputAsset(asset));
    if (videos.length === 0) return null;
    return videos.sort((left, right) => scoreVideoOutputAsset(right) - scoreVideoOutputAsset(left))[0] ?? null;
  }
  if (kind === "audio") {
    const audios = outputs.filter((asset) => isAudioOutputAsset(asset));
    if (audios.length === 0) return null;
    return audios.sort((left, right) => scoreAudioOutputAsset(right) - scoreAudioOutputAsset(left))[0] ?? null;
  }
  const images = outputs.filter((asset) => !isVideoOutputAsset(asset) && !isAudioOutputAsset(asset));
  if (images.length === 0) return outputs[0] ?? null;
  const normalizedShotId = shot?.id.trim().toLowerCase() ?? "";
  const storyboardExpectedMarkers =
    !assetOutputContext && normalizedShotId
      ? [`image_asset_guided_${normalizedShotId}`, `shot_${normalizedShotId}`, normalizedShotId]
      : [];
  return (
    images.sort((left, right) => {
      const leftType = String(left.type ?? "").toLowerCase();
      const rightType = String(right.type ?? "").toLowerCase();
      const leftSubfolder = String(left.subfolder ?? "").toLowerCase();
      const rightSubfolder = String(right.subfolder ?? "").toLowerCase();
      const leftName = String(left.filename ?? "").toLowerCase();
      const rightName = String(right.filename ?? "").toLowerCase();
      const leftMatchesStoryboardMarker =
        storyboardExpectedMarkers.length > 0 &&
        storyboardExpectedMarkers.some((marker) => leftName.includes(marker) || leftSubfolder.includes(marker));
      const rightMatchesStoryboardMarker =
        storyboardExpectedMarkers.length > 0 &&
        storyboardExpectedMarkers.some((marker) => rightName.includes(marker) || rightSubfolder.includes(marker));
      const leftStoryboardPenalty =
        !assetOutputContext && /(character_anchor|character_orthoview|character_mv|skybox_)/.test(leftName) ? 120 : 0;
      const rightStoryboardPenalty =
        !assetOutputContext && /(character_anchor|character_orthoview|character_mv|skybox_)/.test(rightName) ? 120 : 0;
      const leftScore =
        (leftMatchesStoryboardMarker ? 160 : 0) +
        (leftType === "output" ? 100 : 0) +
        (leftType === "temp" ? -20 : 0) +
        (leftSubfolder.includes("storyboard") ? 20 : 0) +
        (/image_asset_|shot_/.test(leftName) ? 20 : 0) +
        (/character_orthoview|skybox_/.test(leftName) ? 6 : 0) -
        leftStoryboardPenalty;
      const rightScore =
        (rightMatchesStoryboardMarker ? 160 : 0) +
        (rightType === "output" ? 100 : 0) +
        (rightType === "temp" ? -20 : 0) +
        (rightSubfolder.includes("storyboard") ? 20 : 0) +
        (/image_asset_|shot_/.test(rightName) ? 20 : 0) +
        (/character_orthoview|skybox_/.test(rightName) ? 6 : 0) -
        rightStoryboardPenalty;
      return rightScore - leftScore;
    })[0] ?? null
  );
}

function filterOutputAssetsByKind(outputs: ComfyOutputAsset[], kind: "image" | "video" | "audio"): ComfyOutputAsset[] {
  if (kind === "video") {
    return outputs.filter((asset) => isVideoOutputAsset(asset));
  }
  if (kind === "audio") {
    return outputs.filter((asset) => isAudioOutputAsset(asset));
  }
  return outputs.filter((asset) => !isVideoOutputAsset(asset) && !isAudioOutputAsset(asset));
}

function sanitizePathSegment(value: string): string {
  const sanitized = value.replace(/[^a-zA-Z0-9._-]+/g, "_").replace(/^_+|_+$/g, "");
  return sanitized || "asset";
}

function localAssetCachePath(settings: ComfySettings, asset: ComfyOutputAsset): string {
  const outputRoot = settings.outputDir.trim().replace(/\/+$/, "");
  const cacheRoot = outputRoot ? `${outputRoot}/.storyboard-cache` : "/tmp/storyboard-pro-comfy";
  const safeSubfolder = sanitizePathSegment(asset.subfolder?.trim() || "root");
  const safeFilename = sanitizePathSegment(asset.filename.trim() || "output.bin");
  return `${cacheRoot}/${safeSubfolder}/${Date.now()}_${safeFilename}`;
}

function localStillCachePath(settings: ComfySettings, label: string, source: string): string {
  const outputRoot = settings.outputDir.trim().replace(/\/+$/, "");
  const cacheRoot = outputRoot ? `${outputRoot}/.storyboard-cache/stills` : "/tmp/storyboard-pro-comfy/stills";
  const safeLabel = sanitizePathSegment(label);
  const ext = fileExtensionFromSource(source);
  return `${cacheRoot}/${Date.now()}_${safeLabel}.${ext}`;
}

async function materializeStillImagePath(
  settings: ComfySettings,
  source: string,
  label: string
): Promise<string> {
  const trimmed = source.trim();
  if (!trimmed) return "";
  // Web Bridge media URLs are display URLs, not filesystem paths. Recover the
  // original path before handing the image to the local video renderer.
  if (/\/api\/local-file\?path=/i.test(trimmed)) {
    try {
      const parsed = new URL(trimmed, window.location.origin);
      const encodedPath = parsed.searchParams.get("path") ?? "";
      if (encodedPath.trim()) return decodeURIComponent(encodedPath);
    } catch {
      // Continue with the normal Comfy output resolution below.
    }
  }
  if (canUseAbsoluteLocalPath(trimmed)) {
    const normalizedOutput = settings.outputDir.trim().replace(/\\/g, "/").toLowerCase();
    const normalizedSource = trimmed.replace(/\\/g, "/").toLowerCase();
    if (normalizedOutput && normalizedSource.startsWith(`${normalizedOutput}/`)) return trimmed;
    // A stale absolute path can still refer to a Comfy output filename that is
    // available on the current installation. Resolve it through /view first.
    const staleName = trimmed.replace(/\\/g, "/").split("/").pop() ?? "";
    if (staleName) {
      try {
        const url = toComfyViewDownloadUrl(staleName, settings.baseUrl);
        const base64 = await invokeDesktop<string>("comfy_fetch_view_base64", { url });
        const written = await invokeDesktop<FileWriteResult>("write_base64_file", {
          filePath: localStillCachePath(settings, label, staleName),
          base64Data: base64
        });
        return written.filePath;
      } catch {
        // Keep the original path for the final error if the file is truly gone.
      }
    }
    return trimmed;
  }
  const downloadSource = inferComfyOutputDownloadSource(trimmed, settings.outputDir);
  if (downloadSource) {
    try {
      const url = toComfyViewDownloadUrl(downloadSource, settings.baseUrl);
      const base64 = await invokeDesktop<string>("comfy_fetch_view_base64", { url });
      const written = await invokeDesktop<FileWriteResult>("write_base64_file", {
        filePath: localStillCachePath(settings, label, trimmed),
        base64Data: base64
      });
      return written.filePath;
    } catch {
      // fall back to a direct output path only when view download is unavailable
    }
  }
  const relative = parseComfyViewPath(trimmed);
  if (relative && settings.outputDir.trim()) {
    const direct = `${settings.outputDir.trim().replace(/\/+$/, "")}/${relative.replace(/^\/+/, "")}`;
    if (canUseAbsoluteLocalPath(direct)) return direct;
  }
  return trimmed;
}

async function generateLocalCompatibleVideo(
  settings: ComfySettings,
  shot: Shot,
  index: number,
  allShots: Shot[]
): Promise<{ previewUrl: string; localPath: string }> {
  const tokens = inferPromptTokens(settings, shot, index, settings.tokenMapping, allShots, [], "video");
  const nextShot = allShots[index + 1];
  const mode = inferVideoMode(shot, nextShot);
  const motionPreset = inferLocalMotionPreset(shot, mode, nextShot);
  const sourceFrame = shot.videoStartFramePath?.trim() || shot.generatedImagePath?.trim() || "";
  const fallbackEnd =
    shot.videoEndFramePath?.trim() || nextShot?.generatedImagePath?.trim() || sourceFrame;
  const primaryImagePath = await materializeStillImagePath(
    settings,
    mode === "first_last_frame" ? (tokens.FIRST_FRAME_PATH || sourceFrame) : (tokens.FRAME_IMAGE_PATH || sourceFrame),
    `${shot.id}_primary`
  );
  const secondaryImagePath =
    mode === "first_last_frame"
      ? await materializeStillImagePath(
          settings,
          tokens.LAST_FRAME_PATH || fallbackEnd || primaryImagePath,
          `${shot.id}_secondary`
        )
      : "";

  if (!primaryImagePath.trim()) {
    throw new Error("本地兼容视频生成失败：当前镜头没有可用分镜图或首帧");
  }
  if (mode === "first_last_frame" && !secondaryImagePath.trim()) {
    throw new Error("本地兼容视频生成失败：首尾帧模式缺少尾帧");
  }

  const result = await invokeDesktop<LocalVideoRenderResult>("generate_local_video_from_images", {
    primaryImagePath,
    secondaryImagePath: secondaryImagePath || null,
    width: Math.max(320, Math.round(settings.renderWidth ?? 1920)),
    height: Math.max(320, Math.round(settings.renderHeight ?? 1080)),
    fps: Math.max(1, Math.round(settings.renderFps ?? 24)),
    durationFrames: Math.max(1, Math.round(shot.durationFrames)),
    mode,
    motionPreset
  });
  return {
    previewUrl: result.outputPath,
    localPath: result.outputPath
  };
}

async function materializeVideoAssetPath(
  settings: ComfySettings,
  asset: ComfyOutputAsset,
  onArtifactTarget?: (path: string) => void
): Promise<string> {
  const cachePath = localAssetCachePath(settings, asset);
  onArtifactTarget?.(cachePath);
  const directPath = toLocalOutputPath(settings.outputDir, asset);
  if (directPath) {
    try {
      const copied = await invokeDesktop<FileWriteResult>("copy_file_to", {
        sourcePath: directPath,
        targetPath: cachePath
      });
      return copied.filePath;
    } catch {
      // fallback to downloading from /view
    }
  }

  const url = toComfyViewUrl(settings.baseUrl, asset);
  const base64 = await invokeDesktop<string>("comfy_fetch_view_base64", { url });
  const written = await invokeDesktop<FileWriteResult>("write_base64_file", {
    filePath: cachePath,
    base64Data: base64
  });
  return written.filePath;
}

async function materializeImageAssetPath(
  settings: ComfySettings,
  asset: ComfyOutputAsset,
  onArtifactTarget?: (path: string) => void
): Promise<string> {
  const cachePath = localAssetCachePath(settings, asset);
  onArtifactTarget?.(cachePath);
  const directPath = toLocalOutputPath(settings.outputDir, asset);
  if (directPath) {
    try {
      const copied = await invokeDesktop<FileWriteResult>("copy_file_to", {
        sourcePath: directPath,
        targetPath: cachePath
      });
      return copied.filePath;
    } catch {
      // fallback to downloading from /view
    }
  }

  const url = toComfyViewUrl(settings.baseUrl, asset);
  const base64 = await invokeDesktop<string>("comfy_fetch_view_base64", { url });
  const written = await invokeDesktop<FileWriteResult>("write_base64_file", {
    filePath: cachePath,
    base64Data: base64
  });
  return written.filePath;
}

async function materializeOutputAssetPath(
  settings: ComfySettings,
  asset: ComfyOutputAsset,
  onArtifactTarget?: (path: string) => void
): Promise<string> {
  if (isVideoOutputAsset(asset) || isAudioOutputAsset(asset)) {
    return materializeVideoAssetPath(settings, asset, onArtifactTarget);
  }
  return materializeImageAssetPath(settings, asset, onArtifactTarget);
}

async function syncSanitizedStoryboardOutputToComfyOutput(
  settings: ComfySettings,
  previewUrl: string,
  localPath: string
): Promise<string> {
  const sourcePath = String(localPath ?? "").trim();
  if (!sourcePath) return "skip=missing_local_source";
  if (!canUseAbsoluteLocalPath(sourcePath)) return "skip=local_source_not_absolute";

  const outputRoot = settings.outputDir.trim().replace(/\/+$/, "");
  if (!outputRoot) return "skip=missing_output_dir";

  const relativeViewPath = parseComfyViewPath(String(previewUrl ?? "").trim());
  if (!relativeViewPath || /^https?:\/\//i.test(relativeViewPath)) {
    return "skip=preview_not_comfy_view_path";
  }
  const normalizedRelative = relativeViewPath.replace(/^\/+/, "");
  if (!normalizedRelative) return "skip=empty_relative_path";

  const targetPath = `${outputRoot}/${normalizedRelative}`;
  if (!canUseAbsoluteLocalPath(targetPath)) return "skip=invalid_target_path";

  if (normalizeComparablePath(sourcePath) === normalizeComparablePath(targetPath)) {
    return "skip=already_target_path";
  }

  try {
    await invokeDesktop<FileWriteResult>("copy_file_to", {
      sourcePath,
      targetPath
    });
    return `copied target=${summarizeStoryboardDebugSource(targetPath)}`;
  } catch (error) {
    return `copy_failed target=${summarizeStoryboardDebugSource(targetPath)} error=${String(error).slice(0, 180)}`;
  }
}

export async function splitCharacterThreeViewSheet(sourcePath: string): Promise<ThreeViewSplitResult> {
  const trimmed = sourcePath.trim();
  if (!trimmed) throw new Error("三视图整板输出路径为空，无法拆分 front / side / back");
  return invokeDesktop<ThreeViewSplitResult>("split_threeview_sheet", {
    sourcePath: trimmed
  });
}

async function readComfyServerLogTail(settings: ComfySettings, maxLines = 180): Promise<string | null> {
  const comfyRootDir = settings.comfyRootDir.trim();
  if (!comfyRootDir) return null;
  try {
    return await invokeDesktop<string>("comfy_read_server_log_tail", {
      comfyRootDir,
      baseUrl: settings.baseUrl,
      maxLines
    });
  } catch {
    return null;
  }
}

function summarizeComfyServerLogFailure(logTail: string): string | null {
  const lines = logTail
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
  if (lines.length === 0) return null;

  const parseComfyLogTime = (line: string): number | null => {
    const matched = line.match(/\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(?:\.\d{1,3})?)\]/);
    if (!matched) return null;
    const isoLike = matched[1].replace(" ", "T");
    const parsed = Date.parse(isoLike);
    return Number.isFinite(parsed) ? parsed : null;
  };

  let latestTimestamp: number | null = null;
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    const parsed = parseComfyLogTime(lines[index]!);
    if (parsed !== null) {
      latestTimestamp = parsed;
      break;
    }
  }

  const lastExceptionIndex = [...lines]
    .map((line, index) => ({ line, index }))
    .filter((item) => item.line.includes("!!! Exception during processing !!!"))
    .map((item) => item.index)
    .pop();

  if (lastExceptionIndex !== undefined && latestTimestamp !== null) {
    const exceptionTimestamp = parseComfyLogTime(lines[lastExceptionIndex]!);
    if (exceptionTimestamp !== null) {
      const ageMs = Math.max(0, latestTimestamp - exceptionTimestamp);
      // Ignore stale exceptions from previous runs to avoid misleading diagnostics.
      if (ageMs > 20 * 60 * 1000) {
        return null;
      }
    }
  }

  const scope = lastExceptionIndex !== undefined ? lines.slice(lastExceptionIndex) : lines.slice(-40);
  const headline =
    scope.find((line) => line.includes("!!! Exception during processing !!!")) ??
    scope.find((line) =>
      /(?:ModuleNotFoundError|NotImplementedError|RuntimeError|ValueError|AssertionError|OSError|ImportError):/i.test(
        line
      )
    ) ??
    null;

  const explicitError =
    scope.find((line) =>
      /(?:ModuleNotFoundError|NotImplementedError|RuntimeError|ValueError|AssertionError|OSError|ImportError):/i.test(
        line
      )
    ) ?? null;

  const merged = [headline, explicitError].filter((item, index, array) => item && array.indexOf(item) === index).join(" | ");
  const normalized = merged || scope.slice(0, 6).join(" | ");
  if (!normalized) return null;
  const normalizedLower = normalized.toLowerCase();

  if (
    normalizedLower.includes("convolution_overrideable not implemented") ||
    normalizedLower.includes("tensor backend other than cpu/cuda/mkldnn")
  ) {
    return "服务端诊断：当前 Wan 视频工作流在 MPS/非 CUDA 后端不可用。你这台 Mac 上的 ComfyUI 正在使用 MPS，Wan 视频模型所需 3D 卷积只能在 CUDA/CPU/MKLDNN 路径运行，实际生产建议改到 NVIDIA CUDA 环境。";
  }
  if (normalizedLower.includes("no module named 'sageattention'")) {
    return "服务端诊断：ComfyUI 缺少 sageattention 依赖，相关 KJNodes 加速节点无法运行。";
  }
  if (
    normalizedLower.includes("outofmemoryerror") ||
    normalizedLower.includes("cuda out of memory") ||
    normalizedLower.includes("allocation on device")
  ) {
    const wanRelated =
      normalizedLower.includes("wan") ||
      normalizedLower.includes("conv3d") ||
      normalizedLower.includes("wanmoeksampler");
    if (wanRelated) {
      return "服务端诊断：当前工作流在 Wan 采样阶段显存不足。你这台 16GB 显卡已经触发 3D 卷积显存溢出，优先建议把这两条失败分镜改用更轻的图片工作流，或把 Wan 工作流的分辨率、帧数、steps 明显降下来。";
    }
    return "服务端诊断：当前工作流执行时显存不足。请降低分辨率、batch size、steps，或改用更轻的模型/工作流。";
  }
  return `服务端诊断：${normalized}`;
}

function shouldFallbackToLocalVideo(errorText: string): boolean {
  const normalized = String(errorText || "").toLowerCase();
  if (!normalized) return false;
  return (
    normalized.includes("missing_node_type") ||
    normalized.includes("未检测到输出文件") ||
    normalized.includes("未找到输出文件") ||
    normalized.includes("未产出视频文件") ||
    normalized.includes("outputkeys=none") ||
    normalized.includes("status=error; completed=false")
  );
}

function isRequestTimeoutError(errorText: string): boolean {
  const normalized = String(errorText || "").toLowerCase();
  if (!normalized) return false;
  return (
    normalized.includes("请求超时") ||
    normalized.includes("operation was aborted") ||
    normalized.includes("aborterror")
  );
}

async function prepareStoryboardImageGenerationInputs(
  settings: ComfySettings,
  shot: Shot,
  index: number,
  allShots: Shot[],
  assets: Asset[],
  rewrittenWorkflow: Record<string, unknown>,
  assetOutputContext: AssetOutputContext | null,
  tokens: Record<string, string>
): Promise<{
  tokens: Record<string, string>;
  imageReferenceSources: WeightedImageRef[];
}> {
  let nextTokens = { ...tokens };
  let imageReferenceSources = extractImageReferenceSources(shot, assets, index, allShots);
  const storyboardMode = settings.storyboardImageWorkflowMode ?? "builtin_qwen";
  const isStoryboardImageRequest = !assetOutputContext;
  const preserveExplicitFrameSeed = String(nextTokens.STORYBOARD_PRESERVE_FRAME_IMAGE_PATH ?? "").trim() === "1";
  const explicitFrameSeedPath = String(nextTokens.FRAME_IMAGE_PATH ?? "").trim();
  const activeStageCharacterCount = [
    compactTextParts(
      String(nextTokens.CHAR1_NAME ?? "").trim(),
      String(nextTokens.CHAR1_PRIMARY_PATH ?? "").trim(),
      String(nextTokens.CHAR1_FRONT_PATH ?? "").trim()
    ),
    compactTextParts(
      String(nextTokens.CHAR2_NAME ?? "").trim(),
      String(nextTokens.CHAR2_PRIMARY_PATH ?? "").trim(),
      String(nextTokens.CHAR2_FRONT_PATH ?? "").trim()
    )
  ].filter((item) => item.length > 0).length;
  const useStableStoryboardCoreWorkflow =
    storyboardMode === "mature_asset_guided" &&
    isStoryboardImageRequest;
  const useCleanDualCharacterCoreRefs =
    isStoryboardImageRequest &&
    activeStageCharacterCount >= 2 &&
    (isQwenCustomMaskStoryboardWorkflow(rewrittenWorkflow) || isQwenProDualStoryboardWorkflow(rewrittenWorkflow));
  if (useStableStoryboardCoreWorkflow || useCleanDualCharacterCoreRefs) {
    // Stable storyboard generation should only depend on the core inputs:
    // scene ref, per-character refs, and the shared pose map.
    imageReferenceSources = imageReferenceSources.filter(
      (item) =>
        item.role !== "continuity_scene" &&
        item.role !== "continuity_character" &&
        item.label !== "scene_character_composite" &&
        item.label !== "character_identity_board"
    );
  }
  const shouldAutoForceCompositeSeed = isStoryboardImageRequest && activeStageCharacterCount >= 2 && inferStoryboardCompositeScale(shot) === "wide";
  const shouldForceCompositeSeed =
    String(nextTokens.STORYBOARD_FORCE_COMPOSITE_SEED ?? "").trim() === "1" || shouldAutoForceCompositeSeed;
  if (shouldAutoForceCompositeSeed && !(preserveExplicitFrameSeed && explicitFrameSeedPath)) {
    nextTokens = {
      ...nextTokens,
      STORYBOARD_FORCE_COMPOSITE_SEED: "1"
    };
  }
  const shouldPrepareDualCharacterGuidance =
    isStoryboardImageRequest &&
    activeStageCharacterCount >= 2;
  const shouldInjectCompositeGuidance =
    shouldPrepareDualCharacterGuidance &&
    !useStableStoryboardCoreWorkflow &&
    !useCleanDualCharacterCoreRefs;
  const shouldInjectIdentityBoard =
    shouldPrepareDualCharacterGuidance &&
    !useStableStoryboardCoreWorkflow &&
    !useCleanDualCharacterCoreRefs;
  if (isStoryboardImageRequest && (shouldInjectCompositeGuidance || shouldInjectIdentityBoard)) {
    const inputDir = inferComfyInputDir(settings);
    if (inputDir) {
      const [compositeGuideRef, identityBoardRef] = await Promise.all([
        shouldInjectCompositeGuidance
          ? buildStoryboardCompositeReference(settings, shot, imageReferenceSources, inputDir, assets)
          : Promise.resolve(null),
        shouldInjectIdentityBoard
          ? buildStoryboardIdentityBoardReference(shot, imageReferenceSources, inputDir, assets)
          : Promise.resolve(null)
      ]);
      if (
        compositeGuideRef?.source &&
        shouldPrepareDualCharacterGuidance &&
        shouldForceCompositeSeed &&
        !(preserveExplicitFrameSeed && explicitFrameSeedPath)
      ) {
        nextTokens = {
          ...nextTokens,
          FRAME_IMAGE_PATH: compositeGuideRef.source,
          STORYBOARD_FRAME_SEED_MODE: "composite"
        };
      }
      if (compositeGuideRef?.source) {
        imageReferenceSources = [
          ...imageReferenceSources.filter((item) => item.source.trim() !== compositeGuideRef.source.trim()),
          compositeGuideRef
        ];
      }
      if (identityBoardRef?.source) {
        imageReferenceSources = [
          ...imageReferenceSources.filter((item) => item.source.trim() !== identityBoardRef.source.trim()),
          identityBoardRef
        ];
      }
    }
  }
  return {
    tokens: nextTokens,
    imageReferenceSources
  };
}

function shouldUseStableStoryboardCoreWorkflow(
  settings: ComfySettings,
  workflow: Record<string, unknown>,
  assetOutputContext: AssetOutputContext | null
): boolean {
  if (
    isStoryboardComposerWorkflow(workflow) ||
    isFisherNextsceneWorkflow(workflow) ||
    isQwenCustomMaskStoryboardWorkflow(workflow) ||
    isQwenProDualStoryboardWorkflow(workflow)
  ) {
    return false;
  }
  return (
    (settings.storyboardImageWorkflowMode ?? "builtin_qwen") === "mature_asset_guided" &&
    !assetOutputContext
  );
}

function summarizeStoryboardDebugSource(value: string): string {
  const trimmed = String(value ?? "").trim();
  if (!trimmed) return "-";
  const normalized = trimmed.replace(/\\/g, "/").replace(/[?#].*$/, "");
  const basename = normalized.split("/").filter(Boolean).pop() ?? normalized;
  if (basename.length <= 56) return basename;
  return `${basename.slice(0, 20)}...${basename.slice(-28)}`;
}

function summarizeStoryboardDebugEntries(
  entries: Array<{ label?: string; role?: string; source?: string; filename?: string; weight?: number }>,
  sourceKey: "source" | "filename",
  limit = 5
): string {
  if (entries.length === 0) return "";
  const visible = entries.slice(0, limit).map((entry) => {
    const label = String(entry.label ?? entry.role ?? "ref").trim() || "ref";
    const source = summarizeStoryboardDebugSource(String(entry[sourceKey] ?? ""));
    const weight =
      typeof entry.weight === "number" && Number.isFinite(entry.weight) ? `@${entry.weight.toFixed(2)}` : "";
    return `${label}:${source}${weight}`;
  });
  if (entries.length > limit) {
    visible.push(`+${entries.length - limit} more`);
  }
  return visible.join(" | ");
}

function buildStoryboardImageDebugLines(args: {
  workflow: Record<string, unknown>;
  tokens: Record<string, string>;
  imageReferenceSources: WeightedImageRef[];
  stagedCharacterImages: Array<{ filename: string; weight: number; role: WeightedImageRef["role"]; label: string }>;
}): string[] {
  const { workflow, tokens, imageReferenceSources, stagedCharacterImages } = args;
  const sceneRefPath = String(tokens.SCENE_REF_PATH ?? "").trim();
  const frameImagePath = String(tokens.FRAME_IMAGE_PATH ?? "").trim();
  const lockedScenePath = frameImagePath || sceneRefPath;
  const frameSeedMode = String(tokens.STORYBOARD_FRAME_SEED_MODE ?? "").trim() || "unknown";
  const poseGuidePath = String(tokens.POSE_GUIDE_PATH ?? "").trim();
  const passAPoseGuidePath = String(tokens.PASS_A_POSE_GUIDE_PATH ?? poseGuidePath).trim() || poseGuidePath;
  const passBPoseGuidePath = String(tokens.PASS_B_POSE_GUIDE_PATH ?? poseGuidePath).trim() || poseGuidePath;
  const passAMaskPath = String(tokens.PASS_A_CHARACTER_MASK_PATH ?? "").trim();
  const passBMaskPath =
    String(tokens.PASS_B_CHARACTER_MASK_PATH ?? passAMaskPath).trim() || passAMaskPath;
  const poseGuideMode = String(tokens.STORYBOARD_POSE_GUIDE_MODE ?? "").trim() || (poseGuidePath ? "pose_map" : "none");
  const actionRefPath = String(tokens.STORYBOARD_ACTION_REF_PATH ?? "").trim();
  const workflowLabel = isStableStoryboardWorkflowPreset(workflow)
    ? "stable_pose_ipadapter"
    : isStoryboardComposerWorkflow(workflow)
      ? "storyboard_composer"
      : isFisherNextsceneWorkflow(workflow)
        ? "nextscene_fisher"
      : "custom_storyboard";
  const poseSummary =
    passAPoseGuidePath && passBPoseGuidePath && passAPoseGuidePath === passBPoseGuidePath
      ? `${poseGuideMode}:${summarizeStoryboardDebugSource(passAPoseGuidePath)}`
      : `passA=${summarizeStoryboardDebugSource(passAPoseGuidePath)} | passB=${summarizeStoryboardDebugSource(passBPoseGuidePath)}`;
  const maskSummary =
    passAMaskPath && passBMaskPath && passAMaskPath === passBMaskPath
      ? summarizeStoryboardDebugSource(passAMaskPath)
      : passAMaskPath || passBMaskPath
        ? `passA=${summarizeStoryboardDebugSource(passAMaskPath)} | passB=${summarizeStoryboardDebugSource(passBMaskPath)}`
        : "";
  const primaryCharacterSummary = [
    String(tokens.CHAR1_PRIMARY_PATH ?? "").trim()
      ? `char1=${summarizeStoryboardDebugSource(String(tokens.CHAR1_PRIMARY_PATH ?? ""))}@${String(tokens.CHAR1_PRIMARY_WEIGHT ?? "-")}`
      : "",
    String(tokens.CHAR2_PRIMARY_PATH ?? "").trim()
      ? `char2=${summarizeStoryboardDebugSource(String(tokens.CHAR2_PRIMARY_PATH ?? ""))}@${String(tokens.CHAR2_PRIMARY_WEIGHT ?? "-")}`
      : ""
  ]
    .filter(Boolean)
    .join(" | ");
  const stagedSummary = summarizeStoryboardDebugEntries(stagedCharacterImages, "filename");
  const rawSummary = summarizeStoryboardDebugEntries(imageReferenceSources, "source");
  const lines = [
    `workflow=${workflowLabel}; frame_seed=${frameSeedMode}:${summarizeStoryboardDebugSource(frameImagePath)}; scene=${summarizeStoryboardDebugSource(sceneRefPath)}; pose=${poseSummary}${maskSummary ? `; mask=${maskSummary}` : ""}${actionRefPath ? `; action_ref=${summarizeStoryboardDebugSource(actionRefPath)}` : ""}`
  ];
  if (primaryCharacterSummary) {
    lines.push(`primary_refs=${primaryCharacterSummary}`);
  }
  if (stagedSummary) {
    lines.push(`staged_refs=${stagedSummary}`);
  }
  if (rawSummary) {
    lines.push(`source_refs=${rawSummary}`);
  }
  return lines;
}

type StableStoryboardCharacterPassSlot = {
  slotKey: "char1" | "char2";
  name: string;
  primaryPath: string;
  frontPath: string;
  sidePath: string;
  backPath: string;
  secondaryPath: string;
  facePath: string;
  detailPath: string;
  primaryWeight: number;
  poseFigure: StoryboardPoseGuideFigure;
  sourcePoseFigure: StoryboardPoseGuideFigure;
};

type StableStoryboardSingleCharacterPassPlan = {
  renderWidth: number;
  renderHeight: number;
  poseFigure: StoryboardPoseGuideFigure;
};

function measureStableStoryboardPoseFigureBounds(
  figure: StoryboardPoseGuideFigure
): {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
  width: number;
  height: number;
} {
  const geometry = computeStoryboardPoseFigureGeometry(
    figure.centerX,
    figure.floorY,
    figure.bodyHeight,
    figure.action,
    poseFigureUsesMirror(figure)
  );
  const points = [
    geometry.head,
    geometry.neck,
    geometry.pelvis,
    geometry.leftShoulder,
    geometry.rightShoulder,
    geometry.leftHip,
    geometry.rightHip,
    geometry.leftElbow,
    geometry.rightElbow,
    geometry.leftWrist,
    geometry.rightWrist,
    geometry.leftKnee,
    geometry.rightKnee,
    geometry.leftAnkle,
    geometry.rightAnkle
  ];
  const sidePadding = Math.max(18, Math.round(figure.bodyHeight * 0.16));
  const topPadding = Math.max(22, Math.round(figure.bodyHeight * 0.16));
  const bottomPadding = Math.max(12, Math.round(figure.bodyHeight * 0.06));
  const minX = Math.min(...points.map((point) => point.x)) - sidePadding;
  const minY = Math.min(...points.map((point) => point.y)) - topPadding;
  const maxX = Math.max(...points.map((point) => point.x)) + sidePadding;
  const maxY = Math.max(...points.map((point) => point.y)) + bottomPadding;
  return {
    minX,
    minY,
    maxX,
    maxY,
    width: Math.max(1, maxX - minX),
    height: Math.max(1, maxY - minY)
  };
}

function resolveStableStoryboardSingleCharacterPassPlan(args: {
  poseFigure: StoryboardPoseGuideFigure;
  isSdxlStoryboardModel: boolean;
}): StableStoryboardSingleCharacterPassPlan {
  const { poseFigure, isSdxlStoryboardModel } = args;
  const measuredBounds = measureStableStoryboardPoseFigureBounds({
    ...poseFigure,
    centerX: poseFigure.bodyHeight,
    floorY: poseFigure.bodyHeight * 1.2
  });
  const widthToBodyRatio = measuredBounds.width / Math.max(1, poseFigure.bodyHeight);
  const heightToBodyRatio = measuredBounds.height / Math.max(1, poseFigure.bodyHeight);
  const renderHeight = isSdxlStoryboardModel ? 1280 : 1152;
  const maxRenderWidth = isSdxlStoryboardModel ? 1024 : 960;
  const desiredAspect = Math.max(0.62, Math.min(0.86, widthToBodyRatio / Math.max(0.1, heightToBodyRatio) + 0.2));
  const renderWidth = snapRenderSize(
    Math.max(640, Math.min(maxRenderWidth, Math.round(renderHeight * desiredAspect)))
  );
  const widthLimitedBodyHeight = (renderWidth * 0.72) / Math.max(0.1, widthToBodyRatio);
  const heightLimitedBodyHeight = (renderHeight * 0.8) / Math.max(0.1, heightToBodyRatio);
  const localBodyHeight = Math.max(448, Math.min(widthLimitedBodyHeight, heightLimitedBodyHeight));
  return {
    renderWidth,
    renderHeight,
    poseFigure: {
      ...poseFigure,
      centerX: renderWidth / 2,
      floorY: renderHeight * 0.91,
      bodyHeight: localBodyHeight
    }
  };
}

function resolveStableStoryboardPassARenderSize(
  tokens: Record<string, string>,
  storyboardModel: string,
  characterCount: number
): {
  renderWidth: number;
  renderHeight: number;
  passAWidth: number;
  passAHeight: number;
} {
  const renderWidth = Math.max(64, Number.parseInt(String(tokens.RENDER_WIDTH ?? "1024"), 10) || 1024);
  const renderHeight = Math.max(64, Number.parseInt(String(tokens.RENDER_HEIGHT ?? "576"), 10) || 576);
  const shotScale = inferStoryboardCompositeScaleFromCorpus(
    compactTextParts(tokens.SHOT_TITLE, tokens.STORY_PROMPT, tokens.NOTES, tokens.DIALOGUE).toLowerCase()
  );
  const isSdxlStoryboardModel = looksLikeSdxlCheckpoint(storyboardModel);
  const passARenderScaleDefault =
    characterCount >= 2
      ? shotScale === "wide"
        ? 1.18
        : 1.14
      : shotScale === "close"
        ? 1.08
        : 1.12;
  const passARenderScale = Math.min(isSdxlStoryboardModel ? 1.3 : 1.24, Math.max(1, passARenderScaleDefault));
  const passAMaxSide = isSdxlStoryboardModel ? 1536 : 1280;
  const passARequestedWidth = Math.max(renderWidth, Math.round(renderWidth * passARenderScale));
  const passARequestedHeight = Math.max(renderHeight, Math.round(renderHeight * passARenderScale));
  const passAResizeFactor = Math.min(1, passAMaxSide / Math.max(passARequestedWidth, passARequestedHeight));
  return {
    renderWidth,
    renderHeight,
    passAWidth: snapRenderSize(passARequestedWidth * passAResizeFactor),
    passAHeight: snapRenderSize(passARequestedHeight * passAResizeFactor)
  };
}

function scaleStoryboardPoseFigure(
  figure: StoryboardPoseGuideFigure,
  scaleX: number,
  scaleY: number
): StoryboardPoseGuideFigure {
  return {
    ...figure,
    centerX: figure.centerX * scaleX,
    floorY: figure.floorY * scaleY,
    bodyHeight: figure.bodyHeight * scaleY
  };
}

async function writeStableStoryboardSingleFigurePoseGuide(args: {
  inputDir: string;
  shotId: string;
  fileSuffix: string;
  renderWidth: number;
  renderHeight: number;
  poseFigure: StoryboardPoseGuideFigure;
  sourcePoseGuidePath?: string;
  sourcePoseFigure?: StoryboardPoseGuideFigure;
  sourcePoseRenderWidth?: number;
  sourcePoseRenderHeight?: number;
}): Promise<{ localPath: string; inputName: string }> {
  const {
    inputDir,
    shotId,
    fileSuffix,
    renderWidth,
    renderHeight,
    poseFigure,
    sourcePoseGuidePath,
    sourcePoseFigure,
    sourcePoseRenderWidth,
    sourcePoseRenderHeight
  } = args;
  const canvas = document.createElement("canvas");
  canvas.width = renderWidth;
  canvas.height = renderHeight;
  const context = canvas.getContext("2d");
  if (!context) {
    throw new Error(`稳定分镜生成 pose 图失败：${shotId}/${fileSuffix}`);
  }
  context.fillStyle = "black";
  context.fillRect(0, 0, renderWidth, renderHeight);
  let usedSharedPoseGuide = false;
  if (sourcePoseGuidePath?.trim() && sourcePoseFigure) {
    const sourceImage = await loadReferenceImageElement(sourcePoseGuidePath);
    const sourceWidth = sourceImage?.naturalWidth || sourceImage?.width || 0;
    const sourceHeight = sourceImage?.naturalHeight || sourceImage?.height || 0;
    if (sourceImage && sourceWidth > 0 && sourceHeight > 0) {
      const normalizedSourceFigure =
        sourcePoseRenderWidth && sourcePoseRenderHeight
          ? scaleStoryboardPoseFigure(
              sourcePoseFigure,
              sourceWidth / Math.max(1, sourcePoseRenderWidth),
              sourceHeight / Math.max(1, sourcePoseRenderHeight)
            )
          : sourcePoseFigure;
      const expectedLocalBounds = measureStableStoryboardPoseFigureBounds(poseFigure);
      const sourceBounds = measureStableStoryboardPoseFigureBounds(normalizedSourceFigure);
      const sourceCanvas = document.createElement("canvas");
      sourceCanvas.width = sourceWidth;
      sourceCanvas.height = sourceHeight;
      const sourceContext = sourceCanvas.getContext("2d");
      if (sourceContext) {
        sourceContext.fillStyle = "black";
        sourceContext.fillRect(0, 0, sourceWidth, sourceHeight);
        sourceContext.drawImage(sourceImage, 0, 0, sourceWidth, sourceHeight);
      }
      const sharedPoseAnalysis = sourceContext ? analyzeCanvasVisibleInkComponents(sourceCanvas) : null;
      const selectedComponent = sharedPoseAnalysis
        ? pickStableStoryboardSharedPoseGuideComponent({
            analysis: sharedPoseAnalysis,
            expectedBounds: sourceBounds
          })
        : null;
      const selectedBounds = selectedComponent ?? {
        ...sourceBounds,
        centerX: normalizedSourceFigure.centerX,
        centerY: (sourceBounds.minY + sourceBounds.maxY) / 2
      };
      const paddingX = Math.max(26, Math.round(selectedBounds.width * 0.26));
      const paddingTop = Math.max(28, Math.round(selectedBounds.height * 0.2));
      const paddingBottom = Math.max(20, Math.round(selectedBounds.height * 0.16));
      const cropX = Math.max(0, Math.round(selectedBounds.minX - paddingX));
      const cropY = Math.max(0, Math.round(selectedBounds.minY - paddingTop));
      const cropWidth = Math.min(sourceWidth - cropX, Math.max(1, Math.round(selectedBounds.width + paddingX * 2)));
      const cropHeight = Math.min(
        sourceHeight - cropY,
        Math.max(1, Math.round(selectedBounds.height + paddingTop + paddingBottom))
      );
      const desiredScale = poseFigure.bodyHeight / Math.max(1, selectedBounds.height);
      const scale = Math.max(
        0.1,
        Math.min(desiredScale, (renderWidth * 0.82) / Math.max(1, cropWidth), (renderHeight * 0.88) / Math.max(1, cropHeight))
      );
      const drawWidth = cropWidth * scale;
      const drawHeight = cropHeight * scale;
      const drawX = poseFigure.centerX - (selectedBounds.centerX - cropX) * scale;
      const drawY = poseFigure.floorY - (selectedBounds.maxY + 1 - cropY) * scale;
      const previewCanvas = document.createElement("canvas");
      previewCanvas.width = renderWidth;
      previewCanvas.height = renderHeight;
      const previewContext = previewCanvas.getContext("2d");
      if (previewContext) {
        previewContext.fillStyle = "black";
        previewContext.fillRect(0, 0, renderWidth, renderHeight);
        previewContext.imageSmoothingEnabled = true;
        previewContext.imageSmoothingQuality = "high";
        previewContext.drawImage(sourceImage, cropX, cropY, cropWidth, cropHeight, drawX, drawY, drawWidth, drawHeight);
        const sanitizedPreview =
          retainLargestVisibleInkComponentCanvas(previewCanvas) ??
          sanitizeStableStoryboardSingleFigurePoseGuideCanvas({
            source: previewCanvas,
            poseFigure
          }) ??
          previewCanvas;
        if (
          isStableStoryboardSharedPoseGuideAcceptable({
            canvas: sanitizedPreview,
            expectedBounds: expectedLocalBounds
          })
        ) {
          context.imageSmoothingEnabled = true;
          context.imageSmoothingQuality = "high";
          context.drawImage(sanitizedPreview, 0, 0);
          usedSharedPoseGuide = true;
        }
      }
    }
  }
  if (!usedSharedPoseGuide) {
    buildStoryboardPoseFigure(
      context,
      poseFigure.centerX,
      poseFigure.floorY,
      poseFigure.bodyHeight,
      poseFigure.action,
      poseFigureUsesMirror(poseFigure)
    );
  }

  const safeShotId = sanitizePathSegment(shotId || "shot");
  const filePath = `${inputDir}/shot_${safeShotId}_${fileSuffix}.png`;
  return writeCanvasToLocalPng(filePath, canvas);
  const result = await invokeDesktopCommand<{ filePath: string }>("write_base64_file", {
    filePath,
    base64Data: canvas.toDataURL("image/png").replace(/^data:[^,]+,/, "")
  });
  const localPath = result.filePath?.trim() ?? "";
  const inputName = localPath ? localPath.split("/").pop() ?? localPath.split("\\").pop() ?? localPath : "";
  if (!localPath || !inputName) {
    throw new Error(`稳定分镜写入 pose 图失败：${shotId}/${fileSuffix}`);
  }
  return { localPath, inputName };
}

function buildStableStoryboardSingleFigureGenerationMask(args: {
  width: number;
  height: number;
  poseFigure: StoryboardPoseGuideFigure;
}): HTMLCanvasElement | null {
  const { width, height, poseFigure } = args;
  if (width <= 0 || height <= 0) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  if (!context) return null;
  context.fillStyle = "black";
  context.fillRect(0, 0, width, height);
  buildStoryboardCharacterMaskFigure(
    context,
    poseFigure.centerX,
    poseFigure.floorY,
    poseFigure.bodyHeight * 1.1,
    poseFigure.action,
    poseFigureUsesMirror(poseFigure)
  );
  buildStoryboardCharacterEdgeContactMaskFigure(
    context,
    poseFigure.centerX,
    poseFigure.floorY,
    poseFigure.bodyHeight * 1.04,
    poseFigure.action,
    poseFigureUsesMirror(poseFigure)
  );
  return canvas;
}

async function writeStableStoryboardSingleCharacterInitPlateFromPoseFigure(args: {
  inputDir: string;
  shotId: string;
  slotKey: string;
  renderWidth: number;
  renderHeight: number;
  characterRefPath: string;
  poseFigure: StoryboardPoseGuideFigure;
}): Promise<{ localPath: string; inputName: string }> {
  const { inputDir, shotId, slotKey, renderWidth, renderHeight, characterRefPath, poseFigure } = args;
  const cutout = await buildCharacterCutoutCanvas(characterRefPath);
  const palette = resolveStoryboardPoseHumanPalette(cutout, slotKey === "char2" ? 1 : 0);

  const canvas = document.createElement("canvas");
  canvas.width = renderWidth;
  canvas.height = renderHeight;
  const context = canvas.getContext("2d");
  if (!context) {
    throw new Error(`稳定分镜人物底板生成失败，缺少画布上下文：${shotId}/${slotKey}`);
  }
  context.fillStyle = "rgb(244, 241, 236)";
  context.fillRect(0, 0, renderWidth, renderHeight);
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  drawStoryboardReadableHumanFigure({
    context,
    poseFigure,
    palette,
    mode: "plate"
  });

  const safeShotId = sanitizePathSegment(shotId || "shot");
  return writeCanvasToLocalPng(`${inputDir}/shot_${safeShotId}_${slotKey}_init_plate.png`, canvas);
}

